def evaluate_rpn(expression: str) -> int:
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token in "+-*/":
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                result = a + b
            elif token == '-':
                result = a - b
            elif token == '*':
                result = a * b
            elif token == '/':
                # Division truncates toward zero
                result = int(a / b)
            stack.append(result)
        else:
            # Convert token to integer and push to stack
            stack.append(int(token))

    return stack[0]

