def max_non_overlapping_intervals(events):
    # Sort intervals based on their end times
    events.sort(key=lambda x: x[1])

    count = 0
    last_end = -float('inf')

    for start, end in events:
        if start >= last_end:
            count += 1
            last_end = end

    return count

def max_floors(N, H, C, B):
    # Create a dictionary to store the minimum cost for each unique height
    height_cost = {}
    for height, cost in zip(H, C):
        if height not in height_cost or cost < height_cost[height]:
            height_cost[height] = cost

    # Extract the unique heights and their minimum costs
    unique_heights = list(height_cost.items())

    # Sort by cost to try and select the cheapest ones first
    unique_heights.sort(key=lambda x: x[1])

    total_cost = 0
    count = 0

    for height, cost in unique_heights:
        if total_cost + cost <= B:
            total_cost += cost
            count += 1
        else:
            break

    return count

