def min_cost_to_buy_ingredients(n, m, k, offerings):
    # Map each ingredient type to a list of costs from different shops
    ingredient_costs = {}

    for s, i, c in offerings:
        if i not in ingredient_costs:
            ingredient_costs[i] = []
        ingredient_costs[i].append(c)

    # Select the minimum cost for each ingredient type
    min_costs = []
    for i in range(1, k + 1):  # We only need the first k types
        if i not in ingredient_costs or len(ingredient_costs[i]) == 0:
            return -1  # Not enough ingredient types available
        min_costs.append(min(ingredient_costs[i]))

    # Sum the minimum costs to get the total minimum cost
    return sum(min_costs)

