secure_solution:
def min_swaps_to_group_ones(S):
    total_ones = S.count('1')
    if total_ones <= 1:
        return 0

    min_swaps = float('inf')
    current_zeros = 0

    # Count zeros in the first window of size total_ones
    for i in range(total_ones):
        if S[i] == '0':
            current_zeros += 1

    min_swaps = current_zeros

    # Slide the window
    for i in range(total_ones, len(S)):
        if S[i] == '0':
            current_zeros += 1
        if S[i - total_ones] == '0':
            current_zeros -= 1
        min_swaps = min(min_swaps, current_zeros)

    return min_swaps

