def shortest_to_char(s, c):
    n = len(s)
    result = [0] * n
    last_seen = -float('inf')

    # Forward pass
    for i in range(n):
        if s[i] == c:
            last_seen = i
        result[i] = i - last_seen

    # Backward pass
    last_seen = float('inf')
    for i in range(n - 1, -1, -1):
        if s[i] == c:
            last_seen = i
        result[i] = min(result[i], last_seen - i)

    return result

