def evaluate_expression(expr):
    # Step 1: Tokenize the expression
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            # Extract the full number
            num = 0
            while i < len(expr) and expr[i].isdigit():
                num = num * 10 + int(expr[i])
                i += 1
            tokens.append(num)
        elif expr[i] in '+*':
            tokens.append(expr[i])
            i += 1
        else:
            i += 1  # Skip any whitespace or unexpected characters (though problem says no whitespace)

    # Step 2: Evaluate * first
    i = 0
    while i < len(tokens):
        if tokens[i] == '*':
            # Perform the multiplication
            left = tokens[i - 1]
            right = tokens[i + 1]
            result = left * right
            # Replace the three tokens with the result
            tokens = tokens[:i - 1] + [result] + tokens[i + 2:]
            i = 0  # Reset index to re-check from the start
        else:
            i += 1

    # Step 3: Evaluate + (only addition remains now)
    result = tokens[0]
    for i in range(1, len(tokens), 2):
        if tokens[i] == '+':
            result += tokens[i + 1]

    return result

