def findPairs(arr, s):
    seen = set()
    result = []
    for num in arr:
        complement = s - num
        if complement in seen:
            # Ensure unique pairs and maintain order
            if num <= complement:
                result.append([num, complement])
            else:
                result.append([complement, num])
        seen.add(num)

    # Remove duplicates and sort
    seen_pairs = set()
    unique_result = []
    for pair in result:
        if tuple(pair) not in seen_pairs:
            seen_pairs.add(tuple(pair))
            unique_result.append(pair)

    # Sort the final result
    unique_result.sort()
    return unique_result

def count_unique_pairs(nums, target):
    seen = set()
    unique_pairs = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            # Use a tuple in sorted order to ensure uniqueness
            pair = tuple(sorted((num, complement)))
            unique_pairs.add(pair)
        seen.add(num)

    return len(unique_pairs)

