def find_two_subarrays_with_sum_k(n, k, arr):
    # Helper function to find subarray indices with sum k
    def find_subarray_with_sum_k(arr, target):
        prefix_sums = {}
        current_sum = 0
        for i, num in enumerate(arr):
            current_sum += num
            if current_sum == target:
                return (0, i)  # from start to i
            if (current_sum - target) in prefix_sums:
                return (prefix_sums[current_sum - target] + 1, i)
            prefix_sums[current_sum] = i
        return None

    # Try all possible positions for the first subarray
    for i in range(n):
        # Try to find a subarray from i to end
        subarray = arr[i:]
        result = find_subarray_with_sum_k(subarray, k)
        if result is not None:
            # Extract indices in original array
            start, end = result
            first_subarray_start = i + start
            first_subarray_end = i + end
            # Check if second subarray can be found before the first
            if find_subarray_with_sum_k(arr[:first_subarray_start], k) is not None:
                return "YES"
            # Check if second subarray can be found after the first
            if find_subarray_with_sum_k(arr[first_subarray_end + 1:], k) is not None:
                return "YES"
    return "NO"

