from typing import List, Tuple

def advanced_knapsack(items: List[Tuple[int, int]], capacity: int) -> int:
    if not items or capacity == 0:
        return 0

    # Separate items with zero weight
    zero_weight_value = 0
    non_zero_items = []

    for value, weight in items:
        if weight == 0:
            zero_weight_value += value
        else:
            non_zero_items.append((value, weight))

    # Handle the basic case where all items have zero weight
    if not non_zero_items:
        return zero_weight_value

    # DP for the standard 0/1 knapsack problem
    n = len(non_zero_items)
    dp = [0] * (capacity + 1)

    for i in range(n):
        value, weight = non_zero_items[i]
        for w in range(capacity, weight - 1, -1):
            dp[w] = max(dp[w], dp[w - weight] + value)

    return dp[capacity] + zero_weight_value

