def make_unique_variables(variable_names: List[str]) -> List[str]:
    name_count = defaultdict(int)
    result = []

    for name in variable_names:
        if name_count[name] == 0:
            result.append(name)
        else:
            result.append(f"{name}{name_count[name]}")
        name_count[name] += 1

    return result

