def unique_paths(grid):
    m = len(grid)
    n = len(grid[0])

    # Initialize a DP table with the same dimensions as the grid
    dp = [[0] * n for _ in range(m)]

    # Starting point
    dp[0][0] = 1

    # Fill the DP table
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue  # Skip the starting point
            # Check if we can come from the top
            if i > 0 and grid[i][j] >= grid[i - 1][j]:
                dp[i][j] += dp[i - 1][j]
            # Check if we can come from the left
            if j > 0 and grid[i][j] >= grid[i][j - 1]:
                dp[i][j] += dp[i][j - 1]

    return dp[m - 1][n - 1]

