secure_solution:
def encrypt_message(message, shift):
    encrypted = ""
    for char in message:
        if char.isalpha():
            # Shift letters (lowercase)
            shifted = ord(char) + shift
            if shifted > ord('z'):
                shifted -= 26
            encrypted += chr(shifted)
        elif char.isdigit():
            # Shift digits with wrap-around from 9 to 0
            shifted = (int(char) + shift) % 10
            encrypted += str(shifted)
        else:
            # Keep spaces unchanged
            encrypted += char
    return encrypted

