def find_max_beauty_subarray(n, a):
    max_beauty = -float('inf')
    result_l = 0
    result_r = 0

    for i in range(n):
        beauty = 2 * a[i]
        if beauty > max_beauty:
            max_beauty = beauty
            result_l = i
            result_r = i
        elif beauty == max_beauty:
            # In case of tie, pick the one with smaller start index
            if i < result_l:
                result_l = i
                result_r = i

    return result_l, result_r

