def find_fibonacci_subsequence(low: int, high: int) -> list[int]:
    # Handle edge cases
    if low > high or (low <= 0 and high <= 0):
        return []

    # Initialize the first two Fibonacci numbers
    fib_numbers = []
    a, b = 0, 1

    # Generate Fibonacci numbers and check the range
    while a <= high:
        if a >= low:
            fib_numbers.append(a)
        a, b = b, a + b

    return fib_numbers

def max_subarray_sum_and_length(arr):
    if not arr:
        return 0, 0  # Return 0 sum and 0 length if array is empty

    max_sum = current_sum = arr[0]
    start = end = 0
    temp_start = 0

    for i in range(1, len(arr)):
        if current_sum + arr[i] > arr[i]:
            current_sum += arr[i]
        else:
            current_sum = arr[i]
            temp_start = i

        if current_sum > max_sum:
            max_sum = current_sum
            start = temp_start
            end = i

    return max_sum, end - start + 1

