def is_arithmetic_progression_possible(n, a0, d):
    if n == 1:
        # Only one number. Check if it's in the progression
        if d == 0:
            return "YES", ""
        else:
            return "YES", ""

    # Calculate total sum of 1 to n
    total = n * (n + 1) // 2

    # Special case if d == 0
    if d == 0:
        if total == a0:
            # Create a dummy result
            result = "YES\n"
            result += "\n".join([f"{i} + {i+1} = {i + i + 1}" for i in range(1, n)])
            return result
        else:
            return "NO"

    # Find if `total` is in the arithmetic progression a0, a0 + d, a0 + 2d, ...
    # The condition is: (total - a0) % d == 0 and (total - a0) // d >= 0
    if d != 0:
        if (total - a0) % d == 0 and (total - a0) // d >= 0:
            # Create output
            steps = []
            for i in range(1, n):
                step = f"{i} + {i + 1} = {i + i + 1}"
                steps.append(step)
            output = "YES\n" + "\n".join(steps)
            return output
        else:
            return "NO"
    else:
        return "NO"

