def string_transform(s, rules):
    # Convert the string into a list for easier manipulation
    s_list = list(s)

    # Apply each rule in the order they appear in the list
    for old_char, new_char in rules:
        # Iterate through the list and replace old_char with new_char
        for i in range(len(s_list)):
            if s_list[i] == old_char:
                s_list[i] = new_char

    # Join the list back into a string and return it
    return ''.join(s_list)

