def numSpecial(matrix):
    if not matrix or not matrix[0]:
        return 0

    rows = len(matrix)
    cols = len(matrix[0])

    # Step 1: Compute row sums and column sums
    row_sums = [sum(row) for row in matrix]
    col_sums = [sum(col) for col in zip(*matrix)]

    # Step 2: Count special cells
    count = 0
    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == 1 and row_sums[i] == 1 and col_sums[j] == 1:
                count += 1

    return count

