def smallest_number_with_digit_sum(n):
    if n == 0:
        return 0
    # The smallest number is formed by having the largest digits at the end
    m = ""
    # Start with the remainder when dividing n by 9
    first_digit = n % 9
    if first_digit == 0:
        first_digit = 9  # Special case when n is a multiple of 9
    m += str(first_digit)
    # Add remaining 9s
    remaining = n - first_digit
    m += '9' * (remaining // 9)
    return int(m)

