def limited_repetition_elements(lst, N):
    """
    Returns a new list containing each number from the original list at most N times,
    preserving the original order of appearance.

    Time Complexity: O(n), where n is the length of the input list.
    Space Complexity: O(n), for the output list and hash table.
    """
    if N == 0:
        return []

    freq = {}
    result = []

    for num in lst:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

        if freq[num] <= N:
            result.append(num)

    return result

