from collections import deque

def shortest_path(m, n, grid):
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return -1  # Start or end is blocked

    visited = [[False] * n for _ in range(m)]
    queue = deque()
    queue.append((0, 0, 0))  # (row, col, steps)
    visited[0][0] = True

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    while queue:
        row, col, steps = queue.popleft()
        if row == m - 1 and col == n - 1:
            return steps

        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 0 and not visited[nr][nc]:
                visited[nr][nc] = True
                queue.append((nr, nc, steps + 1))

    return -1

def text_editor(operations):
    document = []  # List to store characters of the document
    results = []   # List to store the results of PRINTKth operations

    for op in operations:
        if op.startswith("INSERT"):
            c = op.split()[1]
            document.append(c)
        elif op == "DELETE":
            if document:
                document.pop()
        elif op.startswith("PRINTKth"):
            k = int(op.split()[1])
            if 1 <= k <= len(document):
                results.append(document[k - 1])
            else:
                results.append("")

    return results

