def highest_possible_sum(n, T, power_levels):
    # Initialize dp array with size T+1, starting with -infinity
    # dp[i] = max sum we can reach exactly to i
    dp = [-1] * (T + 1)
    dp[0] = 0  # Base case: sum of 0 is achievable with no gems

    for power in power_levels:
        for i in range(T, power - 1, -1):
            if dp[i - power] != -1:
                dp[i] = max(dp[i], dp[i - power] + power)

    # Find the maximum possible sum <= T
    return max([i for i in range(T + 1) if dp[i] != -1])

