def min_jumps_to_reach_height(n, H, jumps):
    # Initialize dp array with infinity (a large number like H+1)
    dp = [float('inf')] * (H + 1)
    dp[0] = 0  # Base case: 0 jumps needed to reach height 0

    for i in range(1, H + 1):
