def min_cost_with_layover(flights, src, dst):
    from collections import defaultdict

    # Build adjacency list: map from city to list of (destination, cost)
    graph = defaultdict(list)
    for from_city, to_city, price in flights:
        graph[from_city].append((to_city, price))

    min_cost = float('inf')

    # Check for direct flight
    for to_city, price in graph[src]:
        if to_city == dst:
            min_cost = min(min_cost, price)

    # Check for flights with one layover
    for intermediate, price1 in graph[src]:
        for to_city, price2 in graph[intermediate]:
            if to_city == dst:
                total_price = price1 + price2
                min_cost = min(min_cost, total_price)

    return min_cost if min_cost != float('inf') else -1

