secure_solution:
def minimize_donation_difference(n, donations):
    total_sum = sum(donations)
    target = total_sum // 2

    # Use a set to track achievable sums
    achievable_sums = set()
    achievable_sums.add(0)

    for donation in donations:
        new_sums = set()
        for s in achievable_sums:
            new_sum = s + donation
            if new_sum <= target:
                new_sums.add(new_sum)
        achievable_sums.update(new_sums)

    # Find the maximum achievable sum that is <= target
    closest_sum = max(achievable_sums)
    return abs(total_sum - 2 * closest_sum)

