    # Convert the essential skills string to a set for easy comparison
    required_skills = set(essential_skills)

    # Helper function to check if a combination of employees covers all required skills
    def has_all_skills(selected):
        combined_skills = set()
        for employee in selected:
            combined_skills.update(employee)
        return required_skills.issubset(combined_skills)

    # Try all combinations of employees
    from itertools import combinations

    for r in range(1, n + 1):
