def min_difference(n, chocolates):
    total = sum(chocolates)
    target = total // 2

    # dp[i] will be True if a subset with sum i can be formed
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum of 0 is always possible

    for choco in chocolates:
        for i in range(target, choco - 1, -1):
            if dp[i - choco]:
                dp[i] = True

    # Find the maximum subset sum <= target
    max_sum = 0
    for i in range(target, -1, -1):
        if dp[i]:
            max_sum = i
            break

    return abs(total - 2 * max_sum)

