secure_solution:
def is_anagram(s1: str, s2: str) -> bool:
    # If the lengths are different, they cannot be anagrams
    if len(s1) != len(s2):
        return False

    # Initialize a fixed-size array for 26 lowercase letters
    char_count = [0] * 26

    # Count characters in s1
    for char in s1:
        index = ord(char) - ord('a')
        char_count[index] += 1

    # Subtract characters in s2
    for char in s2:
        index = ord(char) - ord('a')
        char_count[index] -= 1

    # If all counts are zero, they are anagrams
    for count in char_count:
        if count != 0:
            return False

    return True

import string

def check_palindrome_or_anagram(s):
    # Function to preprocess the string: remove non-alphabetic characters and convert to lowercase
    def preprocess(s):
        return ''.join(char.lower() for char in s if char.isalpha())

    processed = preprocess(s)

    # Check if it's a palindrome
    if processed == processed[::-1]:
        return "Palindrome"

    # Check if it's an anagram of a palindrome
    # For a string to be an anagram of a palindrome:
    # - At most one character can have an odd count (for odd-length strings)
    from collections import Counter
    counts = Counter(processed)
    odd_count = sum(1 for count in counts.values() if count % 2 != 0)

    if odd_count <= 1:
        return "Anagram of Palindrome"
    else:
        return "Neither"

