        user_id, amount = entry.split(':')
        amount = int(amount)
        if user_id in user_totals:
            user_totals[user_id] += amount
        else:
            user_totals[user_id] = amount

    # Filter users who have processed more than $10,000
    high_spenders = {user: total for user, total in user_totals.items() if total > 10000}

