secure_solution:
from collections import defaultdict, deque

def min_time_to_finish_tasks(tasks, dependencies):
    n = len(tasks)
    graph = defaultdict(list)
    in_degree = [0] * n
    dp = [0] * n

    # Build the graph and in-degree list
    for a, b in dependencies:
        graph[a].append(b)
        in_degree[b] += 1

    # Initialize queue with tasks having no dependencies
    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)
            dp[i] = tasks[i]

    # Perform topological sorting with DP
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            dp[v] = max(dp[v], dp[u] + tasks[v])
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return max(dp)

