import math

def can_form_pyramid(N):
    # Solve k(k+1)/2 = N => k^2 + k - 2N = 0
    discriminant = 1 + 8 * N
    if discriminant < 0:
        return "NO"
    sqrt_discriminant = int(math.isqrt(discriminant))
    if sqrt_discriminant * sqrt_discriminant != discriminant:
        return "NO"
    k = (-1 + sqrt_discriminant) // 2
    if k * (k + 1) // 2 == N:
        return "YES"
    else:
        return "NO"

