def find_minimum_tour_distance(n, m, roads):
    import sys
    sys.setrecursionlimit(10000)

    # Initialize distance matrix with infinity
    INF = float('inf')
    dist = [[INF] * (n + 1) for _ in range(n + 1)]

    # Set distance from city to itself as 0
    for i in range(1, n + 1):
        dist[i][i] = 0

    # Populate initial distances from the roads
    for u, v, w in roads:
        dist[u][v] = min(dist[u][v], w)
        dist[v][u] = min(dist[v][u], w)

    # Floyd-Warshall to find all-pairs shortest paths
    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # DP table: dp[mask][u] = minimum distance for visiting cities in mask, ending at city u
    dp = [[INF] * (n + 1) for _ in range(1 << n)]

    # Initialize DP with starting from city 1
    for i in range(1, n + 1):
        dp[1 << (i - 1)][i] = dist[1][i]

    # Iterate over all possible states (masks)
    for mask in range(1 << n):
        for u in range(1, n + 1):
            if not (mask & (1 << (u - 1))):
                continue  # u not in the current mask
            for v in range(1, n + 1):
                if mask & (1 << (v - 1)):
                    continue  # v already visited
                new_mask = mask | (1 << (v - 1))
                dp[new_mask][v] = min(dp[new_mask][v], dp[mask][u] + dist[u][v])

    # Find the minimum cycle starting and ending at city 1
    full_mask = (1 << n) - 1
    result = INF
    for u in range(1, n + 1):
        result = min(result, dp[full_mask][u] + dist[u][1])

    return result

