import heapq
from collections import deque, Counter

def rearrangeFlowers(s: str, k: int) -> str:
    if k == 0:
        return s  # No restriction

    count = Counter(s)
    max_heap = []
    for char, freq in count.items():
        heapq.heappush(max_heap, (-freq, char))  # Max heap using negative frequencies

    result = []
    queue = deque()  # To hold (char, next_available_index)

    while max_heap or queue:
        # Get the most frequent character that is available
        if not max_heap:
            return ""  # Not possible to rearrange
        freq, char = heapq.heappop(max_heap)
        result.append(char)
        freq += 1  # Decrease the frequency (it's now one less)

        # If there is a previous flower that can be placed now, add it back to the heap
        if queue and queue[0][0] <= len(result) - 1:
            prev_freq, prev_char = queue.popleft()
            heapq.heappush(max_heap, (prev_freq, prev_char))

        # If the current flower still has remaining count, add it to the queue
        if freq != 0:
            queue.append((freq, char))

    return ''.join(result)

