def is_beautiful_sequence(n, a):
    if n <= 2:
        return "YES"  # Any 2 elements can form a beautiful sequence

    a.sort()
    possible_diffs = set()

    # Try building sequence using difference between first and last element
    for i in range(1, min(5, n)):
        diff = a[i] - a[0]
        if diff == 0:
            continue  # Skip zero difference to avoid repetition
        possible_diffs.add(diff)

    for diff in possible_diffs:
        sequence = [a[0]]
        current = a[0]
        found = True
        for _ in range(n - 1):
            next_val = current + diff
            if next_val in a:
                a.remove(next_val)
                current = next_val
            else:
                found = False
                break
        if found:
            return "YES"

    return "NO"

