    n = len(grid[0])

    if k > m or k > n:
        return -1  # Cannot fit a k x k subgrid

    # Step 1: Create the prefix sum matrix
    prefix = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m):
        for j in range(n):
            prefix[i + 1][j + 1] = grid[i][j] + prefix[i][j + 1] + prefix[i + 1][j] - prefix[i][j]

    max_sum = 0

