            # Coordinates of the bottom-right corner of the subgrid in prefix sum matrix
            x1, y1 = i + k, j + k
            # Sum of subgrid using prefix sum
            current_sum = prefix[x1][y1] - prefix[i][y1] - prefix[x1][j] + prefix[i][j]
            if current_sum > max_sum:
