def two_sum_pairs(arr, target):
    seen = set()
    pairs = set()

    for num in arr:
        complement = target - num
        if complement in seen:
            # Ensure the pair is in sorted order
            pair = tuple(sorted((num, complement)))
            pairs.add(pair)
        seen.add(num)

    # Convert the set to a sorted list of tuples
    return sorted(pairs)

