    open_paren = 0
    required_add = 0

    for char in s:
        if char == '(':
            open_paren += 1
        elif char == ')':
            if open_paren > 0:
                open_paren -= 1
            else:
                required_add += 1  # Need to add '(' to balance this ')'

    # After processing the string, add closing parentheses for remaining open ones
    required_add += open_paren

