import bisect

def min_trees_to_cut(n, heights):
    # This list will store the smallest possible tail of all increasing subsequences
    # with length i+1
    lnds = []

    for h in heights:
        # Use bisect_right to find the insertion point for h in lnds
        idx = bisect.bisect_right(lnds, h)
        if idx == len(lnds):
            lnds.append(h)
        else:
            lnds[idx] = h

    # The length of lnds is the length of the longest non-decreasing subsequence
    return n - len(lnds)

