def find3Numbers(array, target_sum):
    n = len(array)
    array.sort()  # Sort the array to use two-pointer technique

    for i in range(n - 2):
        left = i + 1
        right = n - 1

        while left < right:
            current_sum = array[i] + array[left] + array[right]

            if current_sum == target_sum:
                return True
            elif current_sum < target_sum:
                left += 1
            else:
                right -= 1

    return False

