def can_transform_by_reversing_substring(s, t):
    if len(s) != len(t):
        return False

    if s == t:
        return True

    start = 0
    end = len(s) - 1

    # Find the first mismatch
    while start < len(s) and s[start] == t[start]:
        start += 1

    # Find the last mismatch
    while end >= 0 and s[end] == t[end]:
        end -= 1

    # Reverse the substring of s from start to end and compare with t
    reversed_substring = s[:start] + s[start:end+1][::-1] + s[end+1:]
    return reversed_substring == t

