def longest_subarray_sum(nums, target):
    prefix_sum = 0
    sum_indices = {0: -1}  # Map from prefix_sum to the earliest index it was seen
    max_length = -1

    for i, num in enumerate(nums):
        prefix_sum += num
        if (prefix_sum - target) in sum_indices:
            # A subarray ending at index i sums to target
            max_length = max(max_length, i - sum_indices[prefix_sum - target])
        # Store the earliest index for the current prefix_sum
        if prefix_sum not in sum_indices:
            sum_indices[prefix_sum] = i

    return max_length if max_length != 0 else -1

