def maximize_weight(n, W, P, items):
    # Separate perishable and non-perishable items
    perishable = []
    non_perishable = []

    for w, p, _ in items:
        if p == 1:
            perishable.append(w)
        else:
            non_perishable.append(w)

    # Let's use a 2D DP table: dp[i][j] = max weight using i perishable items and j total weight
    dp = [[0] * (W + 1) for _ in range(P + 1)]

    # Fill DP table
    for w in non_perishable:
        for i in range(P + 1):
            for j in range(W, w - 1, -1):
                if dp[i][j - w] + w > dp[i][j]:
                    dp[i][j] = dp[i][j - w] + w

    for w in perishable:
        for i in range(1, P + 1):
            for j in range(W, w - 1, -1):
                if dp[i - 1][j - w] + w > dp[i][j]:
                    dp[i][j] = dp[i - 1][j - w] + w

    # The answer is the maximum value in the dp[P][*] row
    return max(dp[P])

