def can_partition(nums):
    total = sum(nums)
    if total % 2 != 0:
        return False  # If total is odd, partition is not possible

    target = total // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum of 0 is always possible

    for num in nums:
        for i in range(target, num - 1, -1):
            if dp[i - num]:
                dp[i] = True

    return dp[target]

