def judge_circle(moves: str) -> bool:
    # Step 1: Check for invalid characters (not in "RLUD")
    for move in moves:
        if move not in ("R", "L", "U", "D"):
            return False

    # Step 2: Track net movement in horizontal (x) and vertical (y) directions
    x, y = 0, 0
    for move in moves:
        if move == 'R':
            x += 1
        elif move == 'L':
            x -= 1
        elif move == 'U':
            y += 1
        elif move == 'D':
            y -= 1

    # Step 3: Return True if robot is back at origin (0,0)
    return x == 0 and y == 0

