from typing import List

def min_chunks_required(files: List[int], chunk_size: int) -> int:
    if not files or chunk_size <= 0:
        return 0

    total_chunks = 0
    for file_size in files:
        # Calculate the number of chunks needed for this file
        chunks_needed = (file_size + chunk_size - 1) // chunk_size
        total_chunks += chunks_needed

    return total_chunks

from collections import deque

def shortest_subarray_with_sum_greater_than_x(nums, x):
    n = len(nums)
    prefix_sums = [0] * (n + 1)
    for i in range(n):
        prefix_sums[i + 1] = prefix_sums[i] + nums[i]

    dq = deque()
    min_length = float('inf')

    for i in range(n + 1):
        while dq and prefix_sums[i] - prefix_sums[dq[0]] > x:
            min_length = min(min_length, i - dq.popleft())
        while dq and prefix_sums[i] <= prefix_sums[dq[-1]]:
            dq.pop()
        dq.append(i)

    return min_length if min_length != float('inf') else -1

