from collections import Counter

def longest_word(words, letters):
    # Count the frequency of each letter in the `letters` string
    letter_count = Counter(letters)

    max_length = 0
    result = ""

    for word in words:
        # Count the frequency of each letter in the current word
        word_count = Counter(word)

        # Check if the word can be constructed using the available letters
        can_construct = True
        for letter, count in word_count.items():
            if letter_count.get(letter, 0) < count:
                can_construct = False
                break

        if can_construct:
            if len(word) > max_length:
                max_length = len(word)
                result = word

    return result

