def count_paths(n, m, k, edges, start, end):
    MOD = 10**9 + 7

    # Build the graph (adjacency list)
    graph = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)  # for topological sort

    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    # Step 1: Topological sort using Kahn's Algorithm
    from collections import deque
    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    topo_order = []
    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Step 2: Dynamic Programming
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[start][0] = 1  # Starting at 'start' with 0 edges

    for u in topo_order:
        if u == end:
            continue  # No need to propagate from end
        for j in range(k):
            if dp[u][j] == 0:
                continue
            for v in graph[u]:
                if j + 1 <= k:
                    dp[v][j + 1] = (dp[v][j + 1] + dp[u][j]) % MOD

    # Sum all paths to 'end' using up to k edges
    result = sum(dp[end][j] for j in range(k + 1)) % MOD
    return result

