def min_deletions_to_palindrome(s):
    n = len(s)
    # Reverse the string
    s_rev = s[::-1]

    # Create a 2D table for DP
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if s[i - 1] == s_rev[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # LPS length = dp[n][n]
    lps_length = dp[n][n]
    return n - lps_length

import math

def calculate_side(opposite, adjacent, hypotenuse):
    """
    Given the lengths of two sides of a right-angled triangle, returns the length of the third side.
    If one of the sides' lengths is unknown, it is represented by None.

    :param opposite: (float) length of the side opposite the right angle, or None if unknown.
    :param adjacent: (float) length of the side adjacent to the right angle, or None if unknown.
    :param hypotenuse: (float) length of the hypotenuse side, or None if unknown.

    :return: the length of the unknown side (float).
             raises ValueError if:
                - more than one side is None
                - the supplied lengths do not form a valid right-angled triangle
    """
    # Check if more than one parameter is None
    none_count = sum(1 for x in [opposite, adjacent, hypotenuse] if x is None)
    if none_count > 1:
        raise ValueError("More than one side is unknown. Only one side should be None.")

    # Check if any known side is negative
    for side, name in zip([opposite, adjacent, hypotenuse], ["opposite", "adjacent", "hypotenuse"]):
        if side is not None and side < 0:
            raise ValueError(f"{name} side length must be non-negative.")

    # Determine which side to calculate
    if opposite is None:
        # Opposite = sqrt(hypotenuse^2 - adjacent^2)
        if hypotenuse is None or adjacent is None:
            raise ValueError("Hypotenuse and Adjacent sides must be known to calculate the opposite side.")
        if hypotenuse < adjacent:
            raise ValueError("Hypotenuse must be greater than the adjacent side for a valid triangle.")
        result = math.sqrt(hypotenuse ** 2 - adjacent ** 2)
    elif adjacent is None:
        # Adjacent = sqrt(hypotenuse^2 - opposite^2)
        if hypotenuse is None or opposite is None:
            raise ValueError("Hypotenuse and Opposite sides must be known to calculate the adjacent side.")
        if hypotenuse < opposite:
            raise ValueError("Hypotenuse must be greater than the opposite side for a valid triangle.")
        result = math.sqrt(hypotenuse ** 2 - opposite ** 2)
    elif hypotenuse is None:
        # Hypotenuse = sqrt(opposite^2 + adjacent^2)
        if opposite is None or adjacent is None:
            raise ValueError("Opposite and Adjacent sides must be known to calculate the hypotenuse.")
        result = math.sqrt(opposite ** 2 + adjacent ** 2)
    else:
        # All sides are provided, check for correctness
        if not math.isclose(opposite ** 2 + adjacent ** 2, hypotenuse ** 2, rel_tol=1e-9):
            raise ValueError("The given sides do not form a valid right-angled triangle.")
        return 0.0  # All sides are known, no calculation needed

    # Round the result to two decimal places
    return round(result, 2)

