def calculate_sales_stats(orders):
    """
    Calculate and format cumulative sales statistics for a given list of orders.

    Parameters:
        orders (list of dict): List where each item is a dictionary representing an order.

    Returns:
        dict: A dictionary with total_sales, average_order_value, and order_count.
    """
    if not isinstance(orders, list):
        return {
            "total_sales": "$0.00",
            "average_order_value": "$0.00",
            "order_count": 0
        }

    total_sales = 0
    order_count = 0

    for order in orders:
        if not isinstance(order, dict):
            continue  # Skip invalid order

        # Validate required fields
        if "id" not in order or "total_amount" not in order:
            continue  # Skip order with missing fields

        id_value = order["id"]
        total_amount = order["total_amount"]

        # Validate and process total_amount
        if isinstance(total_amount, (int, float)):
            total_sales += float(total_amount)
            order_count += 1
        elif isinstance(total_amount, str):
            try:
                total_sales += float(total_amount)
                order_count += 1
            except ValueError:
                # Skip if conversion to float fails
                pass

    if order_count == 0:
        return {
            "total_sales": "$0.00",
            "average_order_value": "$0.00",
            "order_count": 0
        }

    average_order_value = total_sales / order_count

    # Format values with two decimal places and currency format
    total_sales_str = "${:.2f}".format(total_sales)
    average_order_value_str = "${:.2f}".format(average_order_value)

    return {
        "total_sales": total_sales_str,
        "average_order_value": average_order_value_str,
        "order_count": order_count
    }

