import string

def is_message_valid(s: str, k: int) -> str:
    # Define allowed characters: spaces, digits, and punctuation
    allowed = set(string.whitespace + string.digits + string.punctuation)

    max_unchecked = 0
    current_unchecked = 0

    for char in s:
        if char not in allowed:
            current_unchecked += 1
            max_unchecked = max(max_unchecked, current_unchecked)
        else:
            current_unchecked = 0

    return "VALID" if max_unchecked <= k else "INVALID"

