    if len(s) != len(t):
        return False

    s_to_t = {}
    t_to_s = {}

    for char_s, char_t in zip(s, t):
        if char_s in s_to_t:
            if s_to_t[char_s] != char_t:
                return False
        else:
            if char_t in t_to_s:
                return False
            s_to_t[char_s] = char_t
            t_to_s[char_t] = char_s

    return True

