import sys
import heapq

def shortest_path(n, m, roads):
    # Build the adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v, w in roads:
        adj[u].append((v, w))
        adj[v].append((u, w))  # Since roads are bidirectional

    # Initialize distance array with infinity
    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[1] = 0  # Starting from town 1 (capital)

    # Priority queue: (distance, node)
    pq = [(0, 1)]

    while pq:
        current_dist, u = heapq.heappop(pq)
        if current_dist > dist[u]:
            continue  # Skip outdated entries
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    # Format the output
    result = []
    for i in range(1, n + 1):
        if dist[i] == INF:
            result.append(-1)
        else:
            result.append(dist[i])
    return result

