def longest_common_prefix(strs):
    if not strs:
        return ""

    # Find the minimum length string to limit the prefix check
    min_len = min(len(s) for s in strs)

    # Iterate through each character position up to the minimum length
    for i in range(min_len):
        # Get the current character from the first string
        current_char = strs[0][i]

        # Check if this character is present at the same position in all other strings
        for s in strs[1:]:
            if s[i] != current_char:
                return strs[0][:i]  # Return the prefix up to the previous character

    return strs[0][:min_len]  # All characters matched up to the min length

