from collections import deque

def find_course_order(num_courses: int, prerequisites: list[tuple[int, int]]) -> list[int]:
    # Build adjacency list and in-degree map
    graph = {i: [] for i in range(num_courses)}
    in_degree = {i: 0 for i in range(num_courses)}

    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    # Initialize queue with nodes of in-degree 0
    queue = deque([course for course in in_degree if in_degree[course] == 0])
    result = []

    while queue:
        course = queue.popleft()
        result.append(course)
        for neighbor in graph[course]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If the result has all courses, return it; else, a cycle exists
    return result if len(result) == num_courses else []

