def contains_nearby_almost_duplicate(nums: List[int], k: int, t: int) -> bool:
    if k < 0 or t < 0:
        return False  # Invalid input as per constraints

    buckets = {}
    bucket_size = t + 1  # We need to avoid division by zero, so ensure bucket_size > 0

    for i, num in enumerate(nums):
        bucket_id = num // bucket_size

        # Check if the current number is in the bucket
        if bucket_id in buckets:
            return True

        # Check adjacent buckets for possible match
        if (bucket_id - 1) in buckets and abs(num - buckets[bucket_id - 1]) <= t:
            return True
        if (bucket_id + 1) in buckets and abs(num - buckets[bucket_id + 1]) <= t:
            return True

        # Add the current number to the bucket
        buckets[bucket_id] = num

        # Remove the element that is out of the window (index > k)
        if i >= k:
            remove_bucket_id = nums[i - k] // bucket_size
            del buckets[remove_bucket_id]

    return False

