def longest_valid_string(words, k):
    # Step 1: Get unique words
    unique_words = list(set(words))

    # Step 2: If there are fewer than k unique words, return 0
    if len(unique_words) < k:
        return 0

    # Step 3: Sort the unique words by descending length
    unique_words.sort(key=lambda x: -len(x))

    # Step 4: Take the first k words and sum their lengths
    return sum(len(word) for word in unique_words[:k])

