secure_solution:
def count_sentences(s: str, dictionaries: set) -> int:
    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1  # One way to split an empty string

    # Preprocess to set for O(1) lookups
    word_set = set(dictionaries)

    for i in range(1, n + 1):
        for j in range(i):
            if s[j:i] in word_set:
                dp[i] += dp[j]

    return dp[n]

