    total_score = 0
    for level_scores in scores:
        total_score += max(level_scores)
    return total_score

def find_pairs(lst, k):
    seen = set()
    result = set()

    for num in lst:
        complement = k - num
        if complement in seen:
            # Ensure the tuple is ordered with a <= b
            pair = tuple(sorted((num, complement)))
            result.add(pair)
        seen.add(num)

    return list(result)

