import sys

def count_rectangles(points):
    y_to_x = defaultdict(set)

    for x, y in points:
        y_to_x[y].add(x)

    x_pair_count = defaultdict(int)
    rectangles = 0

    for y, x_coords in y_to_x.items():
        x_list = list(x_coords)
        for i in range(len(x_list)):
            for j in range(i + 1, len(x_list)):
                x1, x2 = x_list[i], x_list[j]
                if x1 < x2:
                    pair = (x1, x2)
                else:
                    pair = (x2, x1)
                x_pair_count[pair] += 1
                if x_pair_count[pair] >= 2:
                    rectangles += 1

    return rectangles

