import heapq

def max_possible_difference(arr, k):
    if not arr or k == 0:
        return max(arr) - min(arr) if arr else 0

    arr.sort()
    min_heap = []
    for height in arr:
        heapq.heappush(min_heap, height)

    # We will cut the tallest trees to match the shortest ones, if we can
    for i in range(len(arr) - 1, 0, -1):
        if k <= 0:
            break
        # Try to reduce the tallest tree to the height of the shortest
        tallest = arr[i]
        shortest = min_heap[0]
        if tallest > shortest:
            diff = tallest - shortest
            if diff <= k:
                # Cut this tree down to the shortest
                k -= diff
                heapq.heappop(min_heap)
                heapq.heappush(min_heap, tallest)  # Actually, the tallest becomes the new shortest
            else:
                # Cannot cut this tree to match the current shortest
                break

    return arr[-1] - min_heap[0]

