def number_of_arithmetic_slices(nums):
    if len(nums) < 3:
        return 0

    count = 0
    current_diff = nums[1] - nums[0]
    length = 2  # length of the current arithmetic slice

    for i in range(2, len(nums)):
        new_diff = nums[i] - nums[i - 1]

        if new_diff == current_diff:
            length += 1
        else:
            # Calculate the number of arithmetic slices for the current segment
            if length >= 2:
                count += (length - 1) * (length - 2) // 2
            current_diff = new_diff
            length = 2  # Reset the length for the new segment

    # Handle the last segment
    if length >= 2:
        count += (length - 1) * (length - 2) // 2

    return count

