def can_partition(nums, target):
    # Check if the total sum of nums is equal to 2 * target
    if sum(nums) != 2 * target:
        return False

    # Use dynamic programming to check if a subset with sum equal to target exists
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: subset with sum 0 is always possible

    for num in nums:
        for i in range(target, num - 1, -1):
            if dp[i - num]:
                dp[i] = True

    return dp[target]

