def min_total_cost(s, cost, k):
    # Pair each character with its cost
    char_cost_pairs = list(zip(s, cost))

    # Sort the pairs in descending order of cost
    char_cost_pairs.sort(key=lambda x: -x[1])

    total_cost = 0
    removed = 0

    for char, c in char_cost_pairs:
        if removed < k:
            removed += 1
        else:
            total_cost += c

    return total_cost

