def num_distinct_paths(grid):
    rows, cols = len(grid), len(grid[0])
    dp = [[0] * cols for _ in range(rows)]

    # Initialize the starting cell
    if grid[0][0] == 0:
        dp[0][0] = 1
    else:
        return 0  # No path if start cell is an obstacle

    # Fill the DP table
    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                continue  # Skip the starting cell
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                top = dp[i-1][j] if i > 0 else 0
                left = dp[i][j-1] if j > 0 else 0
                dp[i][j] = top + left

    return dp[rows-1][cols-1]

