def min_insertions_to_balance_parentheses(s):
    insertions = 0
    left = 0  # number of unmatched opening parentheses

    for char in s:
        if char == '(':
            left += 1
        else:  # char == ')'
            if left == 0:
                # No unmatched '(' to match this ')', need to insert one
                insertions += 1
            else:
                left -= 1

    # Add the number of unmatched '(', each needs a corresponding ')'
    insertions += left

    return insertions

