def max_orderliness_after_flip(arr):
    n = len(arr)
    original = 0

    # Step 1: Count original orderliness
    for i in range(n - 1):
        if arr[i] < arr[i + 1]:
            original += 1

    # Step 2: Try flipping each segment [i, j] and calculate the gain
    # For this, simulate a sliding window-based gain calculation
    max_gain = 0

    # For each index, simulate flipping a segment ending at that index
    for i in range(n):
        # Start with i and expand to the right
        for j in range(i, n):
            # For small n, we can simulate the flip
            # For optimization, break early when no gain is possible
            new_arr = arr[:i] + arr[i:j+1][::-1] + arr[j+1:]
            count = 0
            for k in range(n - 1):
                if new_arr[k] < new_arr[k + 1]:
                    count += 1
            max_gain = max(max_gain, count - original)

    return original + max_gain

