def max_parcels(W, D, parcels):
    def backtrack(index, total_weight, total_dimension, count):
        nonlocal max_count
        if index == len(parcels):
            if count > max_count:
                max_count = count
            return

        # Prune if the current path cannot beat the best known solution
        if total_weight + parcels[index][0] <= W and total_dimension + parcels[index][1] <= D:
            # Take the parcel
            backtrack(index + 1, total_weight + parcels[index][0], total_dimension + parcels[index][1], count + 1)

        # Skip the parcel
        backtrack(index + 1, total_weight, total_dimension, count)

    max_count = 0
    backtrack(0, 0, 0, 0)
    return max_count

