def min_removals_to_sort(n, task_ids):
    # Find the length of the Longest Increasing Subsequence (LIS)
    def length_of_lis(nums):
        import bisect
        lis = []
        for num in nums:
            idx = bisect.bisect_left(lis, num)
            if idx == len(lis):
                lis.append(num)
            else:
                lis[idx] = num
        return len(lis)

    lis_length = length_of_lis(task_ids)
    return n - lis_length

