def find_closest(nums, target):
    if not nums:
        raise ValueError("The list 'nums' is empty.")

    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return nums[mid]
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    # After the loop, left is the insertion point
    if left == 0:
        return nums[0]
    if left == len(nums):
        return nums[-1]

    before = nums[left - 1]
    after = nums[left]

    if target - before <= after - target:
        return before
    else:
        return after

