from typing import List, Tuple

def find_pairs(numbers: List[int], targetSum: int) -> List[Tuple[int, int]]:
    seen = set()
    result = set()

    for num in numbers:
        complement = targetSum - num
        if complement in seen:
            # Ensure the pair is sorted in increasing order
            pair = tuple(sorted((num, complement)))
            result.add(pair)
        seen.add(num)

    # Convert the set to a sorted list (lexicographical order)
    return sorted(result)

