secure_solution:
def reverse_words_in_string(s):
    # Split the string into words and spaces
    tokens = []
    i = 0
    n = len(s)

    while i < n:
        if s[i].isspace():
            # Collect consecutive spaces
            j = i
            while j < n and s[j].isspace():
                j += 1
            tokens.append(' ' * (j - i))
            i = j
        else:
            # Collect a word
            j = i
            while j < n and not s[j].isspace():
                j += 1
            tokens.append(s[i:j])
            i = j

    # Reverse the words, preserving spaces
    words = []
    spaces = []
    for token in tokens:
        if token.isspace():
            spaces.append(token)
        else:
            words.append(token)

    # Reconstruct the string with reversed words and original spaces
    result = []
    word_index = 0
    space_index = 0

    for token in tokens:
        if token.isspace():
            result.append(spaces[space_index])
            space_index += 1
        else:
            result.append(words[-(word_index + 1)])
            word_index += 1

    return ''.join(result)

