def collatz_sequence_length(n: int) -> int:
    memo = {}  # Dictionary to store computed sequence lengths

    def helper(n):
        if n in memo:
            return memo[n]
        if n == 1:
            return 0  # Base case: 1 has 0 steps remaining to reach 1
        if n % 2 == 0:
            next_n = n // 2
        else:
            next_n = 3 * n + 1
        steps = 1 + helper(next_n)
        memo[n] = steps
        return steps

    return helper(n)

