def shortest_common_supersequence(a, b):
    # Step 1: Compute LCS using dynamic programming
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Step 2: Use LCS to construct the shortest common supersequence
    i, j = m, n
    result = []

    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            result.append(a[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            result.append(a[i - 1])
            i -= 1
        else:
            result.append(b[j - 1])
            j -= 1

    # Add remaining characters from a or b
    while i > 0:
        result.append(a[i - 1])
        i -= 1
    while j > 0:
        result.append(b[j - 1])
        j -= 1

    return ''.join(reversed(result))

