def min_permutation_sum(n, k, arr):
    # Step 1: Sort the array
    arr.sort()

    # Step 2: Check if each consecutive difference is <= k
    for i in range(1, n):
        if abs(arr[i] - arr[i - 1]) > k:
            return -1

    # Step 3: Calculate sum of absolute differences between consecutive elements
    total_sum = sum(abs(arr[i] - arr[i - 1]) for i in range(1, n))

    return total_sum

