def schedule_tasks(graph: Dict[int, List[int]]) -> List[int]:
    # Step 1: Build in-degree map and adjacency list
    in_degree = {node: 0 for node in graph}
    adj_list = {node: [] for node in graph}

    for node, neighbors in graph.items():
        for neighbor in neighbors:
            adj_list[node].append(neighbor)
            in_degree[neighbor] += 1

    # Step 2: Initialize queue with nodes having in-degree 0
    queue = deque([node for node in in_degree if in_degree[node] == 0])
    result = []

    # Step 3: Process nodes
    while queue:
        node = queue.popleft()
        result.append(node)

        for neighbor in adj_list[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Step 4: Check for cycle
    if len(result) != len(in_degree):
        raise ValueError("Cycle detected")

    return result

