def longest_non_losing_sequence(margins):
    max_length = 0
    current_length = 0
    start_index = 0
    end_index = 0

    for i in range(len(margins)):
        if margins[i] >= 0:
            current_length += 1
            if current_length > max_length:
                max_length = current_length
                start_index = i - current_length + 1
                end_index = i
