def summarize_logs(file_path: str, severity_level: str = None) -> dict:
    """
    Read a log file and summarize the frequency of different action types,
    optionally filtering by minimum severity level.

    Parameters:
    - file_path (str): Path to the log file.
    - severity_level (str, optional): Minimum severity level (INFO, WARNING, ERROR).
      Defaults to None, meaning all entries are included.

    Returns:
    - dict: A dictionary with action types as keys and their counts as values.
    """
    # Map severity levels to their priority (higher is more severe)
    SEVERITY_PRIORITY = {"INFO": 0, "WARNING": 1, "ERROR": 2}

    action_summary = {}

    try:
        with open(file_path, 'r') as file:
            for line in file:
                # Skip empty lines
                if not line.strip():
                    continue

                # Extract severity and action
                if line.startswith("[") and "]" in line:
                    severity_part = line.split("]", 1)[0][1:].strip()
                    action_part = line.split("]", 1)[1].strip()

                    # Check if severity is valid
                    if severity_part in SEVERITY_PRIORITY:
                        # If a minimum severity is provided, check if the entry meets it
                        if severity_level is None or SEVERITY_PRIORITY[severity_part] >= SEVERITY_PRIORITY[severity_level]:
                            # Count the action
                            action_summary[action_part] = action_summary.get(action_part, 0) + 1
                    # Handle malformed log entries
                    else:
                        continue
                else:
                    # Skip malformed log entries
                    continue
    except FileNotFoundError:
        print(f"Error: File not found at {file_path}")
        return {}
    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

    return action_summary

