def sort_diagonally(mat: List[List[int]]) -> List[List[int]]:
    m, n = len(mat), len(mat[0])
    diagonals = {}

    # Step 1: Collect all diagonals
    for i in range(m):
        for j in range(n):
            diff = i - j
            if diff not in diagonals:
                diagonals[diff] = []
            diagonals[diff].append(mat[i][j])

    # Step 2: Sort each diagonal and place back into the matrix
    for diff in diagonals:
        sorted_diag = sorted(diagonals[diff])
        k = 0  # index for the sorted diagonal
        i, j = 0, 0
        while i < m and j < n:
            if i - j == diff:
                mat[i][j] = sorted_diag[k]
                k += 1
            if i == m - 1:
                i = 0
                j += 1
            else:
                i += 1

    return mat

