def encrypt_message(s, k):
    result = []
    for char in s:
        # Shift the character by k positions backwards in the alphabet
        # ord(char) gives ASCII value of the character
        # ord('a') is 97, so we subtract k and wrap around using modulo 26
        shifted = (ord(char) - ord('a') - k) % 26 + ord('a')
        result.append(chr(shifted))
    return ''.join(result)

