secure_solution:
def maxCharFrequency(n, s, q, queries):
    # Step 1: Precompute prefix sums for each character (a-z)
    # prefix[i][c] will store the number of times character c appears in s[0..i-1]
    prefix = [[0] * 26 for _ in range(n + 1)]

    for i in range(n):
        for c in range(26):
            prefix[i + 1][c] = prefix[i][c]
        prefix[i + 1][ord(s[i]) - ord('a')] += 1

    # Step 2: Process each query and determine the maximum frequency
    result = []
    for i in range(0, q * 2, 2):
        l = queries[i]
        r = queries[i + 1]

        max_freq = 0
        for c in range(26):
            count = prefix[r + 1][c] - prefix[l][c]
            if count > max_freq:
                max_freq = count
        result.append(max_freq)

    return result

