def int_divide(n: int) -> int:
    # Create DP table of size (n+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: There's 1 way to partition 0, using no numbers
    for j in range(n + 1):
        dp[0][j] = 1

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if j > i:
                dp[i][j] = dp[i][i]
            else:
                dp[i][j] = dp[i - j][j] + dp[i][j - 1]

    return dp[n][n]

