def min_moves_to_sort(arr):
    from bisect import bisect_left

    n = len(arr)
    sorted_arr = sorted(arr)

    # Greedily find the longest sequence of elements in arr that appear in the same order as in sorted_arr
    # We will use this to find the maximum number of elements that are already in their correct relative positions

    # Make a list to store indices of positions in sorted array
    # Map each value in arr to its position in the sorted array
    # To handle duplicates properly, we use bisect_left to find the correct position
    index_map = {}
    for i, val in enumerate(sorted_arr):
        if val not in index_map:
            index_map[val] = i
        else:
            index_map[val] = i  # keep the same index for duplicates

    # Now, find the length of the longest increasing subsequence of these indices
    lis = []
    for val in arr:
        idx = index_map[val]
        # Use binary search to replace the first element in lis that is >= idx
        pos = bisect_left(lis, idx)
        if pos == len(lis):
            lis.append(idx)
        else:
            lis[pos] = idx

    return n - len(lis)

