def longest_subsequence_with_limit(arr: list, limit: int) -> list:
    # Sort the array in ascending order
    arr.sort()

    result = []
    current_sum = 0

    for num in arr:
        if current_sum + num <= limit:
            result.append(num)
            current_sum += num
        else:
            break  # No more elements can be added without exceeding the limit

    return result

