def max_valid_events(events, duration):
    # Filter out events that are not valid (duration < required duration)
    valid_events = []
    for start, end in events:
        if end - start >= duration:
            valid_events.append((start, end))

    # Sort valid events by end time to allow greedy selection
    valid_events.sort(key=lambda x: x[1])

    count = 0
    last_end = -float('inf')

    for start, end in valid_events:
        if start >= last_end:
            count += 1
            last_end = end

    return count

