from typing import List

def robust_interpolation_search(array: List[int], search_key: int) -> int:
    if not array:
        return -1  # Empty array

    low, high = 0, len(array) - 1

    # Ensure that the search key is within the range of the array
    if search_key < array[low] or search_key > array[high]:
        return -1

    while low <= high and array[low] <= search_key <= array[high]:
        # Avoid division by zero in case of repeated elements
        if array[low] == array[high]:
            if array[low] == search_key:
                return low  # All elements are the same and equal to the search key
            else:
                return -1

        # Interpolation formula
        pos = low + ((search_key - array[low]) * (high - low)) // (array[high] - array[low])

        if array[pos] == search_key:
            # Return first occurrence
            while pos > low and array[pos - 1] == search_key:
                pos -= 1
            return pos
        elif array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1

