import heapq

def trapRainWater(heightMap):
    if not heightMap or not heightMap[0]:
        return 0

    m, n = len(heightMap), len(heightMap[0])
    visited = [[False for _ in range(n)] for _ in range(m)]
    heap = []

    # Push all boundary cells into the heap
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(heap, (heightMap[i][j], i, j))
                visited[i][j] = True

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    trapped_water = 0

    while heap:
        height, x, y = heapq.heappop(heap)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                # The water level at this cell is determined by the min height from which it was reached
                # Water can be trapped if the neighbor's height is lower than the current effective height
                if heightMap[nx][ny] < height:
                    trapped_water += height - heightMap[nx][ny]
                # Push the neighbor with the effective height (height or its own height)
                heapq.heappush(heap, (max(height, heightMap[nx][ny]), nx, ny))

    return trapped_water

def max_packages_delivered(n, m, towns, packages):
    from collections import defaultdict

    # Create a dictionary to map town ID to its weight limit
    town_limits = {}
    for town in towns:
        tid, limit = town
        town_limits[tid] = limit

    # Group packages by town ID and sort each group by weight
    town_packages = defaultdict(list)
    for package in packages:
        pid, weight, tid = package
        town_packages[tid].append(weight)

    # Sort each town's packages by weight to prioritize smaller packages
    for tid in town_packages:
        town_packages[tid].sort()

    total_delivered = 0

    # Try to deliver packages for each town
    for tid in town_packages:
        current_weight = 0
        packages_for_town = town_packages[tid]
        limit = town_limits[tid]
        for weight in packages_for_town:
            if current_weight + weight <= limit:
                current_weight += weight
                total_delivered += 1
            else:
                break  # Can't deliver this or any heavier package

    return total_delivered

