def min_diff_pair(arr):
    if len(arr) < 2:
        return None  # Not enough elements to form a pair

    # Sort the array
    arr.sort()

    min_diff = float('inf')
    best_pair = None

    # Compare adjacent elements to find the minimum difference
    for i in range(len(arr) - 1):
        a, b = arr[i], arr[i + 1]
        diff = b - a

        # Update best pair based on conditions
        if diff < min_diff:
            min_diff = diff
            best_pair = (a, b)
        elif diff == min_diff:
            # Tie-break: compare sums
            current_sum = a + b
            best_sum = best_pair[0] + best_pair[1]
            if current_sum < best_sum:
                best_pair = (a, b)
            elif current_sum == best_sum:
                # Tie-break: compare first elements
                if a < best_pair[0]:
                    best_pair = (a, b)

    return best_pair

def removeOuterParentheses(s):
    result = []
    balance = 0  # Tracks the balance of parentheses
    start = 0    # Start index of the current primitive substring

    for i, char in enumerate(s):
        if char == '(':
            balance += 1
        else:
            balance -= 1

        # When balance reaches 0, we have completed a primitive substring
        if balance == 0:
            # Exclude the outermost parentheses and add the inner characters
            result.append(s[start + 1:i])
            start = i + 1  # Move to the next potential primitive substring

    return ''.join(result)

