def min_completion_time(tasks):
    total_sum = sum(tasks)
    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True

    for task in tasks:
        for j in range(target, task - 1, -1):
            if dp[j - task]:
                dp[j] = True

    # Find the maximum subset sum <= target
    max_subset_sum = 0
    for i in range(target, -1, -1):
        if dp[i]:
            max_subset_sum = i
            break

    return max(total_sum - max_subset_sum, max_subset_sum)

