from typing import List

def longest_subsequence_with_sum(arr: List[int], target: int) -> List[int]:
    prefix_sum = 0
    prefix_map = {0: -1}  # maps prefix_sum to its earliest index
    max_len = 0
    start_index = -1

    for i, num in enumerate(arr):
        prefix_sum += num
        if (prefix_sum - target) in prefix_map:
            prev_index = prefix_map[prefix_sum - target]
            current_len = i - prev_index
            if current_len > max_len:
                max_len = current_len
                start_index = prev_index + 1
        # Only store the first occurrence of each prefix_sum
        if prefix_sum not in prefix_map:
            prefix_map[prefix_sum] = i

    if max_len == 0:
        return []
    return arr[start_index:start_index + max_len]

