def min_distance_dp(word1: str, word2: str) -> int:
    n, m = len(word1), len(word2)

    # Use a 1D DP array to store the LCS lengths
    dp = [0] * (m + 1)

    for i in range(1, n + 1):
        prev = 0  # This will store the diagonal value (dp[j-1] from the previous row)
        for j in range(1, m + 1):
            temp = dp[j]  # Save current value before overwriting
            if word1[i - 1] == word2[j - 1]:
                dp[j] = prev + 1
            else:
                dp[j] = max(dp[j], dp[j - 1])
            prev = temp  # Move to the next diagonal value

    lcs_length = dp[m]
    return (n - lcs_length) + (m - lcs_length)

