        # If there are odd elements, we must remove one of them
        # Try to remove the smallest odd number (to preserve as many elements as possible)
        if len(odd_numbers) == 0:
            return len(arr)
        else:
            # At least one odd number exists, remove the smallest one
            return len(arr) - 1

