def find_pairs(arr, target_sum):
    seen = set()
    result = set()

    for num in arr:
        complement = target_sum - num
        if complement in seen:
            # Ensure the smaller number comes first to avoid duplicates like (a, b) and (b, a)
            pair = tuple(sorted((num, complement)))
            result.add(pair)
        seen.add(num)

    # Convert set of tuples to a list of lists and sort the result
    return sorted([list(pair) for pair in result])

def nextGreaterElement(nums1, nums2):
    next_greater = {}
    stack = []

    for num in nums2:
        while stack and num > stack[-1]:
            next_greater[stack.pop()] = num
        stack.append(num)

    # For numbers in nums1 that have no greater element in nums2, return -1
    return [next_greater.get(num, -1) for num in nums1]

