def max_good_houses(n, k, houses):
    if k == 0:
        return houses.count('G')

    # Count the number of 'G's in the entire string
    total_good = houses.count('G')

    # If k == n, we can repair all houses
    if k == n:
        return n

    # Calculate the number of 'B's in the first window of size k
    current_bad = 0
    for i in range(k):
        if houses[i] == 'B':
            current_bad += 1

    max_bad = current_bad

    # Slide the window
    for i in range(k, n):
        if houses[i] == 'B':
            current_bad += 1
        if houses[i - k] == 'B':
            current_bad -= 1
        max_bad = max(max_bad, current_bad)

    # Result: total good + max number of bad houses that can be replaced
    return total_good + max_bad

