def largest_square_subgrid(N, M, grid):
    # Initialize a DP table with the same size as the grid
    dp = [[0] * M for _ in range(N)]
    max_side = 0  # To keep track of the largest square side

    # Initialize the first row and first column
    for i in range(N):
        dp[i][0] = 1 if grid[i][0] == '.' else 0
        if dp[i][0] > max_side:
            max_side = dp[i][0]

