def word_wrap(text: str, max_width: int) -> List[str]:
    words = text.split()
    lines = []
    current_line = ""

    for word in words:
        # If current line is empty, add the word
        if not current_line:
            current_line = word
        else:
            # Check if the word fits in the current line
            if len(current_line) + 1 + len(word) <= max_width:
                current_line += " " + word
            else:
                # If not, finalize the current line and start a new one
                lines.append(current_line)
                current_line = word
    # Append the last line
