def largest_square_no_tree(n, m, k, trees):
    # Initialize the park grid with all 0s
    park = [[0 for _ in range(m)] for _ in range(n)]

    # Mark the tree positions
    for r, c in trees:
        park[r][c] = 1

    # Initialize DP matrix
    dp = [[0 for _ in range(m)] for _ in range(n)]
    max_side = 0

    for i in range(n):
        for j in range(m):
            if park[i][j] == 0:
                # If current cell has no tree, compute dp[i][j]
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])
            else:
                dp[i][j] = 0  # Tree found, cannot form a square

    # Area is side length squared
    return max_side * max_side

