    # Function to check if a string is a palindrome
    def is_palindrome(s):
        return s == s[::-1]

    # Count the number of mismatched character pairs
    mismatch_count = 0
    for i in range(M // 2):
        if T[i] != T[M - 1 - i]:
            mismatch_count += 1

    # If there is exactly one mismatch, we can change one character to make it a palindrome
    if mismatch_count == 1:
        return "YES"
    # If there are no mismatches, we can change one character (e.g., to the same character) to keep it a palindrome
    elif mismatch_count == 0:
        return "YES"
    else:
        return "NO"

