def find_and_remove(s, k):
    # Convert string to a list for easy modification
    s_list = list(s)
    # Find the first occurrence of k
    index = s_list.index(k) if k in s_list else -1

    if index != -1:
        # Remove the first occurrence of k
        del s_list[index]
        # Convert back to string
        new_s = ''.join(s_list)
    else:
        new_s = s

    return (index, new_s)

