def can_split_into_equal_sum_subarrays(arr):
    total_sum = sum(arr)

    # If total sum is odd, it's impossible to split into two equal parts
    if total_sum % 2 != 0:
        return "NO"

    target = total_sum // 2
    current_sum = 0

    for num in arr:
        current_sum += num
        if current_sum == target:
            return "YES"

    return "NO"

