def longest_common_subsequence(n, m, strand1, strand2):
    # Create a 2D array to store lengths of longest common subsequence.
    # dp[i][j] will store the length of LCS of strand1[0..i-1] and strand2[0..j-1]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Fill dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if strand1[i - 1] == strand2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The result is in dp[n][m]
    return dp[n][m]

