secure_solution:
def count_anagram_pairs(lst):
    from collections import defaultdict

    anagram_counts = defaultdict(int)

    # Count the frequency of each unique anagram
    for word in lst:
        sorted_word = ''.join(sorted(word))
        anagram_counts[sorted_word] += 1

    # Calculate total number of unique anagram pairs
    total_pairs = 0
    for count in anagram_counts.values():
        if count >= 2:
            total_pairs += count * (count - 1) // 2

    return total_pairs

