def is_balanced(s: str) -> str:
    # Define a mapping of closing brackets to their corresponding opening brackets
    brackets_map = {')': '(', '}': '{', ']': '['}

    # Use a stack to keep track of opening brackets
    stack = []

    for char in s:
        if char in brackets_map.values():
            # If the character is an opening bracket, push it onto the stack
            stack.append(char)
        elif char in brackets_map:
            # If the character is a closing bracket
            if not stack or stack[-1] != brackets_map[char]:
                # If the stack is empty or the top of the stack doesn't match
                return "NO"
            stack.pop()  # Pop the matching opening bracket from the stack

    # If the stack is empty, all brackets were matched properly
    return "YES" if not stack else "NO"

