def similarity_score(dna_seq1: str, dna_seq2: str) -> float:
    # Check if both sequences are non-empty
    if not dna_seq1 or not dna_seq2:
        raise ValueError("DNA sequences must be non-empty")

    # Check if both sequences have the same length
    if len(dna_seq1) != len(dna_seq2):
        raise ValueError("DNA sequences must be of the same length")

    # Check if all characters in both sequences are valid nucleotides
    valid_nucleotides = {'A', 'C', 'G', 'T'}
    for seq in [dna_seq1, dna_seq2]:
        if not all(char in valid_nucleotides for char in seq):
            raise ValueError("DNA sequences can only contain the characters 'A', 'C', 'G', and 'T'")

    # Calculate the number of matching positions
    matches = sum(1 for a, b in zip(dna_seq1, dna_seq2) if a == b)

    # Calculate the similarity score
    total_positions = len(dna_seq1)
    score = matches / total_positions

    return score

