secure_solution:
def switch_pairs_in_stack(stack: list) -> list:
    # Create a new list to represent the modified stack
    result = []

    # Iterate over the stack in pairs
    for i in range(0, len(stack), 2):
        # If it's the last element and the stack length is odd, leave it unchanged
        if i + 1 >= len(stack):
            result.append(stack[i])
        else:
            # Swap the pair and add to result
            result.append(stack[i + 1])
            result.append(stack[i])

    return result

