def find_closest_submatrix_sum(matrix):
    m = len(matrix)
    n = len(matrix[0])

    # Create a prefix sum matrix
    prefix = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m):
        for j in range(n):
            prefix[i + 1][j + 1] = matrix[i][j] + prefix[i][j + 1] + prefix[i + 1][j] - prefix[i][j]

    closest_sum = float('inf')

    # Iterate over all submatrix dimensions
    for top in range(m):
        for left in range(n):
            for bottom in range(top, m):
                for right in range(left, n):
                    current_sum = prefix[bottom + 1][right + 1] - prefix[top][right + 1] - prefix[bottom + 1][left] + prefix[top][left]
                    if abs(current_sum) < abs(closest_sum):
                        closest_sum = current_sum
                    # Optional: early break if we reach a sum of exactly zero
                    if closest_sum == 0:
                        return 0

    return closest_sum

