def min_operations_to_transform(n, m, S1, S2, k):
    # Initialize DP table
    dp = [[float('inf')] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0  # No cost to transform empty string to empty string

    # Fill DP table
    for i in range(n + 1):
        for j in range(m + 1):
            # If i == 0, only insertions are allowed
            if i == 0:
                dp[i][j] = j  # Insert j characters
                continue
            # If j == 0, only deletions are allowed
            if j == 0:
                dp[i][j] = i  # Delete i characters
                continue
            # Standard case (insert, delete, replace)
            dp[i][j] = min(
                dp[i][j - 1] + 1,       # Insert
                dp[i - 1][j] + 1,       # Delete
                dp[i - 1][j - 1] + (S1[i - 1] != S2[j - 1])  # Replace
            )

            # Try group operations (up to k characters at once)
            for l in range(1, min(k, i, j) + 1):
                cost = 0
                match = True
                for p in range(l):
                    if S1[i - 1 - p] != S2[j - 1 - p]:
                        cost += 1
                # We can perform one operation on l characters
                if i - l >= 0 and j - l >= 0:
                    dp[i][j] = min(dp[i][j], dp[i - l][j - l] + 1)
                # Or, perform a replace on l characters (if all characters in a group are different)
                if i - l >= 0 and j - l >= 0:
                    dp[i][j] = min(dp[i][j], dp[i - l][j - l] + cost)

    return dp[n][m]

