def can_partition(nums):
    total_sum = sum(nums)
    if total_sum % 2 != 0:
        return "NO"

    target = total_sum // 2
    n = len(nums)

    # Create a 2D DP table
    dp = [[False] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = True  # Base case: zero elements can sum to zero

    for i in range(1, n + 1):
        num = nums[i - 1]
        for j in range(target + 1):
            if dp[i - 1][j]:
                dp[i][j] = True
                if j + num <= target:
                    dp[i][j + num] = True

    return "YES" if dp[n][target] else "NO"

