def longest_beautiful_substring(s, n):
    if n == 0 or n > 26:
        return 0

    from collections import defaultdict

    char_count = defaultdict(int)
    max_length = 0
    left = 0
    distinct = 0

    for right in range(len(s)):
        char = s[right]
        char_count[char] += 1
        if char_count[char] == 1:
            distinct += 1

        while distinct > n:
            left_char = s[left]
            char_count[left_char] -= 1
            if char_count[left_char] == 0:
                distinct -= 1
            left += 1

        if distinct == n:
            max_length = max(max_length, right - left + 1)

    return max_length

