from typing import List, Tuple

def can_distribute(t: int, instances: List[Tuple[int, List[int]]]) -> List[str]:
    result = []
    for n, arr in instances:
        count = Counter(arr)
        max_freq = max(count.values())
        if max_freq <= (n + 1) // 2:
            result.append("YES")
        else:
            result.append("NO")
    return result

