def max_unique_stones(N, X, type_values):
    # Sort the type values in ascending order
    type_values.sort()

    total = 0
    count = 0

    for value in type_values:
        if total + value <= X:
            total += value
            count += 1
        else:
            break

    return count

def min_travel_cost(n, cost):
    # Initialize DP table: dp[mask][u] = minimum cost to reach city u with visited cities in mask
    dp = [[float('inf')] * n for _ in range(1 << n)]

    # Start at city 0 with only city 0 visited
    dp[1 << 0][0] = 0

    for mask in range(1 << n):
        for u in range(n):
            if not (mask & (1 << u)):
                continue  # Skip if city u is not in the current mask
            for v in range(n):
                if mask & (1 << v):
                    continue  # Skip if city v is already visited
                new_mask = mask | (1 << v)
                dp[new_mask][v] = min(dp[new_mask][v], dp[mask][u] + cost[u][v])

    # We need to return to city 0 after visiting all cities
    full_mask = (1 << n) - 1
    return min(dp[full_mask][u] + cost[u][0] for u in range(n))

