from collections import deque, Counter

def rearrange_array(arr, k):
    count = Counter(x % k for x in arr)

    # We'll use two deques to alternate elements
    q1 = deque()
    q2 = deque()

    # Fill the queues with elements based on their remainders
    for num in arr:
        rem = num % k
        if count[rem] > 1:
            if q1 and q1[-1] % k != rem:
                q1.append(num)
            elif q2 and q2[-1] % k != rem:
                q2.append(num)
            else:
                # If we can't place in either queue, the arrangement is not possible
                return []
        else:
            # If frequency is 1, we can just place it anywhere
            if not q1:
                q1.append(num)
            elif not q2:
                q2.append(num)
            else:
                if q1[-1] % k != rem:
                    q1.append(num)
                elif q2[-1] % k != rem:
                    q2.append(num)
                else:
                    return []

    # Now, interleave the two queues
    result = []
    while q1 or q2:
        if q1:
            result.append(q1.popleft())
        if q2:
            result.append(q2.popleft())

    # Final validation: check if any two adjacent elements have sum divisible by k
    for i in range(len(result) - 1):
        if (result[i] + result[i + 1]) % k == 0:
            return []

    return result

