from typing import List
import math

def optimized_jump_search(arr: List[int], target: int) -> int:
    n = len(arr)
    step = int(math.sqrt(n))  # Optimal jump size is around sqrt(n)

    # Jump through blocks of size 'step'
    prev = 0
    while arr[min(step, n) - 1] < target:
        prev = step
        step += int(math.sqrt(n))
        if prev >= n:
            return -1

    # Perform a linear search in the identified block
    while arr[prev] < target:
        prev += 1
        if prev == min(step, n):
            return -1

    # Check if the target is found
    if arr[prev] == target:
        return prev
    else:
        return -1

def find_triplets(arr, target):
    arr.sort()
    n = len(arr)
    result = []

    for i in range(n - 2):
        if i > 0 and arr[i] == arr[i - 1]:
            continue  # Skip duplicate elements for the first number

        left = i + 1
        right = n - 1

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]

            if current_sum == target:
                result.append([arr[i], arr[left], arr[right]])
                # Skip duplicates for the second number
                while left < right and arr[left] == arr[left + 1]:
                    left += 1
                # Skip duplicates for the third number
                while left < right and arr[right] == arr[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return result

