import heapq

def k_largest_elements(arr, k):
    if k == 0:
        return []

    # Use a min-heap of size k to keep track of the k largest elements
    min_heap = []

    for num in arr:
        heapq.heappush(min_heap, num)
        if len(min_heap) > k:
            heapq.heappop(min_heap)

    # The heap contains the k largest elements, but in min-heap order (smallest at top)
    # So we need to reverse the sorted result to get ascending order
    return sorted(min_heap)

