def longest_zero_sum_sublist_length(arr):
    prefix_sum = 0
    sum_indices = {0: -1}  # To handle the case where the sublist starts from index 0
    max_length = 0

    for i, num in enumerate(arr):
        prefix_sum += num
        if prefix_sum in sum_indices:
            # Calculate the length of the sublist
            max_length = max(max_length, i - sum_indices[prefix_sum])
        else:
            sum_indices[prefix_sum] = i

    return max_length

def has_repeated_substring(s: str) -> bool:
    n = len(s)
    if n == 0:
        return False

    # Construct the prefix array for KMP
    prefix = [0] * n
    for i in range(1, n):
        j = prefix[i - 1]
        while j > 0 and s[i] != s[j]:
            j = prefix[j - 1]
        if s[i] == s[j]:
            j += 1
        prefix[i] = j

    # Check if the string can be formed by repeating a substring
    return prefix[-1] > 0 and n % (n - prefix[-1]) == 0

