def find_valley_points(grid: list[list[int]]) -> list[tuple[int, int]]:
    if not grid or not grid[0]:
        return []

    rows, cols = len(grid), len(grid[0])
    valley_points = []

    # Define the four possible directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for i in range(rows):
        for j in range(cols):
            current_value = grid[i][j]
            is_valley = True

            # Check all four neighbors
            for dx, dy in directions:
                ni, nj = i + dx, j + dy
                if 0 <= ni < rows and 0 <= nj < cols:
                    if grid[ni][nj] <= current_value:
                        is_valley = False
                        break
                else:
                    # Skip if out of bounds (no neighbor in that direction)
                    continue

            if is_valley:
                valley_points.append((i, j))

    return valley_points

