secure_solution:
def is_almost_palindrome(n, s):
    # Compare characters from both ends toward the center
    left = 0
    right = n - 1
    changes = 0

    while left < right:
        if s[left] != s[right]:
            changes += 1
            if changes > 1:
                return "NO"
            # Move the pointer that has the different character
            if s[left] == s[right - 1]:
                right -= 1
            elif s[left + 1] == s[right]:
                left += 1
            else:
                # No way to make it a palindrome with one change
                return "NO"
        else:
            left += 1
            right -= 1

    return "YES"

