def max_contiguous_subarrays(nums):
    seen = set()
    count = 0
    for num in nums:
        if num in seen:
            # Reached a duplicate, so split here
            count += 1
            seen = set()
        seen.add(num)
    # Don't forget the last subarray
    if seen:
        count += 1
    return count

