def longest_palindrome_length(s):
    from collections import Counter

    count = Counter(s)
    length = 0
    odd_found = False

    for char_freq in count.values():
        if char_freq % 2 == 0:
            length += char_freq
        else:
            length += char_freq - 1
            odd_found = True

    # If there's any character with an odd count, we can use one in the middle
    if odd_found:
        length += 1

    return length

