def max_items_within_budget(arr, budget):
    # Sort the array in ascending order
    arr.sort()

    count = 0
    total_cost = 0

    # Iterate through the sorted array and keep adding items as long as the budget allows
    for cost in arr:
        if total_cost + cost <= budget:
            total_cost += cost
            count += 1
        else:
            break  # Can't afford this item, so we stop

    return count

