def max_sum_submatrix(matrix, n, k):
    # Create a prefix sum matrix with an extra row and column for easier calculation
    prefix = [[0] * (n + 1) for _ in range(n + 1)]

    # Compute prefix sums
    for i in range(n):
        for j in range(n):
            prefix[i+1][j+1] = matrix[i][j] + prefix[i][j+1] + prefix[i+1][j] - prefix[i][j]

    max_sum = float('-inf')

    # Iterate over all possible top-left corners of k x k submatrices
    for i in range(n - k + 1):
        for j in range(n - k + 1):
            # Calculate the sum of the k x k submatrix using the prefix sum
            current_sum = prefix[i + k][j + k] - prefix[i][j + k] - prefix[i + k][j] + prefix[i][j]
            if current_sum > max_sum:
                max_sum = current_sum

    return max_sum

