from collections import deque

def min_jumps_to_reach_end(buildings, k):
    n = len(buildings)
    if n == 0:
        return -1
    if n == 1:
        return 0

    visited = set()
    queue = deque()
    queue.append((0, 0))  # (index, jumps)
    visited.add(0)

    while queue:
        index, jumps = queue.popleft()
        # Try to jump from index to j
        for j in range(index + 1, min(index + k + 1, n)):
            if buildings[j] >= buildings[index] and j not in visited:
                if j == n - 1:
                    return jumps + 1
                visited.add(j)
                queue.append((j, jumps + 1))
    return -1

