def can_partition(nums):
    total_sum = sum(nums)

    # If total sum is odd, partition is not possible
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    n = len(nums)

    # Use a 1D DP array to store whether a subset with sum i is possible
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum of 0 is always possible

    for num in nums:
        # Iterate backwards to ensure we don't reuse the same element multiple times
        for i in range(target, num - 1, -1):
            if dp[i - num]:
                dp[i] = True

    return dp[target]

