def minimum_difference(nums):
    total_sum = sum(nums)
    target = total_sum // 2
    possible_sums = {0}

    for num in nums:
        new_sums = set()
        for s in possible_sums:
            new_sums.add(s)
            new_sums.add(s + num)
        possible_sums = new_sums

    # Find the subset sum closest to target
    closest = min(possible_sums, key=lambda x: abs(x - target))
    return total_sum - 2 * closest

