from collections import defaultdict

def find_isomer_pairs(molecules):
    # A dictionary to map sorted strings (canonical form) to list of indices
    isomer_map = defaultdict(list)

    for idx, molecule in enumerate(molecules):
        # Sort the characters of the molecule to get its canonical form
        canonical = ''.join(sorted(molecule))
        isomer_map[canonical].append(idx + 1)  # Using 1-based index

    # Collect all pairs of indices that are isomers
    result = []
    for group in isomer_map.values():
        if len(group) >= 2:
            # Generate all pairs from the group
            for i in range(len(group)):
                for j in range(i + 1, len(group)):
                    result.append((group[i], group[j]))

    # If no isomer pairs, return -1
    if not result:
        return -1
    else:
        return result

