def min_madals(T):
    # Initialize dp array with infinity
    dp = [float('inf')] * (T + 1)
    dp[0] = 0  # Base case: 0 amount requires 0 coins

    # Precompute all square numbers up to T
    squares = []
    j = 1
    while j * j <= T:
        squares.append(j * j)
        j += 1

    # Dynamic programming to find minimum coins
    for i in range(1, T + 1):
        for s in squares:
            if s <= i:
                dp[i] = min(dp[i], dp[i - s] + 1)

    return dp[T]

