from collections import deque

def min_steps(forest):
    if not forest or not forest[0]:
        return -1

    rows, cols = len(forest), len(forest[0])
    start = (0, 0)
    end = (rows - 1, cols - 1)

    # Check if start or end is blocked
    if forest[start[0]][start[1]] == 0 or forest[end[0]][end[1]] == 0:
        return -1

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS initialization
    queue = deque([(start[0], start[1], 0)])  # (row, col, steps)
    visited = set()
    visited.add((start[0], start[1]))

    while queue:
        r, c, steps = queue.popleft()

        # Check if reached the bottom-right corner
        if (r, c) == end:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            # Check if the new position is within grid bounds, walkable, and not visited
            if 0 <= nr < rows and 0 <= nc < cols:
                if forest[nr][nc] == 1 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc, steps + 1))

    # If end is not reachable
    return -1

