def trap_rain_water(arr):
    if not arr or len(arr) < 3:
        return 0

    left = 0
    right = len(arr) - 1
    max_left = arr[left]
    max_right = arr[right]
    water_trapped = 0

    while left < right:
        if arr[left] < arr[right]:
            if arr[left] >= max_left:
                max_left = arr[left]
            else:
                water_trapped += max_left - arr[left]
            left += 1
        else:
            if arr[right] >= max_right:
                max_right = arr[right]
            else:
                water_trapped += max_right - arr[right]
            right -= 1

    return water_trapped

