def fibonacci_sum(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 1

    # Initialize the first two Fibonacci numbers
    a, b = 0, 1
    total = a + b  # Sum of the first two numbers

    # Compute the next Fibonacci numbers and keep adding to the total
    for _ in range(2, n):
        c = a + b
        total += c
        a, b = b, c

    return total

