secure_solution:
def distance_between_characters(s: str) -> str:
    if len(s) <= 1:
        return ""

    result = []
    for i in range(1, len(s)):
        # Calculate the position of each character manually
        # 'a' is 1, so we subtract ord('a') and add 1
        prev_pos = ord(s[i - 1]) - ord('a') + 1
        curr_pos = ord(s[i]) - ord('a') + 1
        diff = abs(curr_pos - prev_pos)
        result.append(str(diff))

    return " ".join(result)

