def can_assign_tasks(n, m, tasks, drivers):
    # Sort tasks in descending order
    tasks.sort(reverse=True)
    # Sort drivers in ascending order
    drivers.sort()

    # Try to assign each task to the first driver who can accommodate it
    for task in tasks:
        assigned = False
        for i in range(len(drivers)):
            if drivers[i] >= task:
                drivers[i] -= task  # Assign the task to this driver
                assigned = True
                break
        if not assigned:
            return "NO"
    return "YES"

