from typing import List

def count_increasing_triplets(nums: List[int]) -> int:
    n = len(nums)
    if n < 3:
        return 0

    # left[i] = number of elements before i that are smaller than nums[i]
    left = [0] * n

    # right[i] = number of elements after i that are greater than nums[i]
    right = [0] * n

    # Compute left[i]
    for i in range(n):
        count = 0
        for j in range(i):
            if nums[j] < nums[i]:
                count += 1
        left[i] = count

    # Compute right[i]
    for i in range(n):
        count = 0
        for j in range(i + 1, n):
            if nums[j] > nums[i]:
                count += 1
        right[i] = count

    # Count the number of triplets
    total_triplets = 0
    for i in range(n):
        total_triplets += left[i] * right[i]

    return total_triplets

