def longest_same_parity_subsequence(T, test_cases):
    results = []

    for case in test_cases:
        N, sequence = case
        max_length = 1  # At least one element in the subsequence
        current_length = 1

        for i in range(1, N):
            # Check if current and previous element have the same parity
            if (sequence[i] % 2) == (sequence[i - 1] % 2):
                current_length += 1
                max_length = max(max_length, current_length)
            else:
                current_length = 1  # Reset the counter if parity changes

        results.append(max_length)

    return results

