def calculate_trapped_water(elevations):
    if not elevations or len(elevations) < 3:
        return 0

    left, right = 0, len(elevations) - 1
    max_left = max_right = 0
    trapped_water = 0

    while left < right:
        if elevations[left] < elevations[right]:
            if elevations[left] > max_left:
                max_left = elevations[left]
            else:
                trapped_water += max_left - elevations[left]
            left += 1
        else:
            if elevations[right] > max_right:
                max_right = elevations[right]
            else:
                trapped_water += max_right - elevations[right]
            right -= 1

    return trapped_water

