from collections import Counter

def min_changes_to_anagram(s, t):
    if len(s) != len(t):
        return -1

    count_s = Counter(s)
    count_t = Counter(t)

    # Calculate the total number of changes needed
    changes = 0
    for char in count_s:
        changes += abs(count_s[char] - count_t.get(char, 0))
    for char in count_t:
        if char not in count_s:
            changes += count_t[char]

    return changes // 2  # Each change affects two characters

