    output = set()

    for num in arr:
        complement = k - num
        if complement in seen:
            # Ensure the pair is sorted (non-decreasing order)
            pair = tuple(sorted((num, complement)))
            output.add(pair)
        seen.add(num)

    # Convert the set to a sorted list of tuples
    return sorted(output)

