secure_solution:
def cocktail_shaker_sort_and_deduplicate(arr: list) -> list:
    n = len(arr)
    if n == 0:
        return []

    # Cocktail Shaker Sort Implementation
    swapped = True
    start = 0
    end = n - 1

    while swapped:
        swapped = False

        # Forward pass (left to right)
        for i in range(start, end):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                swapped = True

        if not swapped:
            break

        swapped = False
        end -= 1

        # Backward pass (right to left)
        for i in range(end, start, -1):
            if arr[i] < arr[i - 1]:
                arr[i], arr[i - 1] = arr[i - 1], arr[i]
                swapped = True

        start += 1

    # Remove duplicates while maintaining order of first occurrences
    result = []
    seen = []

    for num in arr:
        if num not in seen:
            seen.append(num)
            result.append(num)

    return result

