from collections import deque

def min_moves_to_reach_bottom_right(n, m, warehouse):
    if warehouse[0][0] == '#' or warehouse[n-1][m-1] == '#':
        return -1  # Start or end is blocked

    visited = [[False] * m for _ in range(n)]
    queue = deque([(0, 0, 0)])  # (row, col, moves)
    visited[0][0] = True

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    while queue:
        r, c, moves = queue.popleft()

        if r == n - 1 and c == m - 1:
            return moves

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc] and warehouse[nr][nc] == '.':
                visited[nr][nc] = True
                queue.append((nr, nc, moves + 1))

    return -1

