def closest_sum_to_target(difficulties, target):
    # Initialize a set to keep track of all achievable sums
    achievable_sums = {0}

    for difficulty in difficulties:
        # We only consider sums up to target to avoid unnecessary computations
        new_sums = set()
        for s in achievable_sums:
            new_sum = s + difficulty
            if new_sum <= target:
                new_sums.add(new_sum)
        # Update the set of achievable sums
        achievable_sums.update(new_sums)

    # Find the sum in achievable_sums that is closest to the target
    closest = min(achievable_sums, key=lambda x: (abs(x - target), x))

    return closest

