def count_waterproof_buildings(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Left pass: longest non-decreasing subarray ending at i
    left = [1] * n
    for i in range(1, n):
        if heights[i] >= heights[i - 1]:
            left[i] = left[i - 1] + 1

    # Right pass: longest non-increasing subarray starting at i
    right = [1] * n
    for i in range(n - 2, -1, -1):
        if heights[i] >= heights[i + 1]:
            right[i] = right[i + 1] + 1

    # Count buildings which are at the peak of a "valley" or are in a non-decreasing or non-increasing sequence
    count = 0
    for i in range(n):
        if left[i] + right[i] - 1 >= 1:
            count += 1

    return count

