def longest_subsequence_with_diff_two(nums):
    # Dictionary to keep track of the length of the longest subsequence ending at each number
    dp = {}

    for num in nums:
        # If num - 2 exists in the dictionary, we can extend that subsequence
        # Otherwise, the subsequence starts at num with length 1
        dp[num] = dp.get(num - 2, 0) + 1

    # Return the maximum value in dp, or 0 if the dictionary is empty
    return max(dp.values()) if dp else 0

