def highest_product_of_three(numbers):
    if len(numbers) < 3:
        return None

    # Sort the list
    numbers.sort()

    # The highest product can be either:
    # 1. The product of the three largest numbers
    # 2. The product of the two smallest (possibly negative) and the largest number
    return max(
        numbers[-1] * numbers[-2] * numbers[-3],
        numbers[0] * numbers[1] * numbers[-1]
    )

def max_bracelet_value(n, W, bracelets):
    # Initialize a DP array where dp[w] represents the maximum value achievable with weight w
    dp = [0] * (W + 1)

    # Iterate over each bracelet
    for weight, value in bracelets:
        # Traverse the DP array in reverse to avoid using the same item multiple times
        for w in range(W, weight - 1, -1):
            dp[w] = max(dp[w], dp[w - weight] + value)

    # The answer is the maximum value achievable with weight up to W
    return dp[W]

