def max_participants_with_tshirts(N, P, d, t_shirt_sizes, preferred_sizes):
    # Count the number of T-shirts available for each size
    from collections import Counter
    tshirt_count = Counter(t_shirt_sizes)

    # Total participants that can get a t-shirt
    result = 0

    for preferred_size in preferred_sizes:
        # Find all t-shirt sizes that are in range [preferred_size - d, preferred_size + d]
        for size in tshirt_count:
            if abs(size - preferred_size) <= d:
                if tshirt_count[size] > 0:
                    tshirt_count[size] -= 1
                    result += 1
                    break  # Assign the first available t-shirt to the participant
    return result

