from typing import List

def find_medians(nums: List[int]) -> List[float]:
    # Input validation
    if not isinstance(nums, list):
        raise ValueError("The numbers should be a list of integers.")

    for num in nums:
        if not isinstance(num, int):
            raise ValueError("The numbers should be a list of integers.")
        if not (-100000 <= num <= 100000):
            raise ValueError("The numbers should be between -100000 and 100000.")

    if not nums:
        return []

    medians = []
    left_half = []  # max-heap (using negative values)
    right_half = []  # min-heap

    for num in nums:
        # Insert into the appropriate heap
        if not left_half or num <= -left_half[0]:
            heapq.heappush(left_half, -num)
        else:
            heapq.heappush(right_half, num)

        # Rebalance heaps
        if len(left_half) > len(right_half) + 1:
            moved = -heapq.heappop(left_half)
            heapq.heappush(right_half, moved)
        elif len(right_half) > len(left_half):
            moved = heapq.heappop(right_half)
            heapq.heappush(left_half, -moved)

        # Calculate the median
        if len(left_half) == len(right_half):
            median = (-left_half[0] + right_half[0]) / 2
        else:
            median = -left_half[0]

        medians.append(float(median))

    return medians

