def longest_zero_sum_subarray(arr):
    sum_indices = {}
    max_length = 0
    current_sum = 0

    for i, num in enumerate(arr):
        current_sum += num

        if current_sum == 0:
            max_length = i + 1  # whole subarray from index 0 to i is zero sum
        elif current_sum in sum_indices:
            # Subarray from index sum_indices[current_sum] + 1 to i has a sum of zero
            max_length = max(max_length, i - sum_indices[current_sum])
        else:
            sum_indices[current_sum] = i

