from typing import List

def custom_interpolation_search(arr: List[int], key: int) -> int:
    if not arr:
        return -1

    low = 0
    high = len(arr) - 1

    while low <= high and arr[low] <= key <= arr[high]:
        # Avoid division by zero when all elements are the same
        if arr[low] == arr[high]:
            if arr[low] == key:
                return low
            else:
                return -1

        # Estimate the position using interpolation formula
        pos = low + ((key - arr[low]) * (high - low)) // (arr[high] - arr[low])

        # Check if the key is found
        if arr[pos] == key:
            return pos
        elif arr[pos] < key:
            low = pos + 1
        else:
            high = pos - 1

    return -1

