from typing import List

def canPartition(nums: List[int]) -> bool:
    total_sum = sum(nums)

    # If the total sum is odd, cannot partition into two equal subsets
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    dp_set = set()
    dp_set.add(0)

    for num in nums:
        temp = set()
        for s in dp_set:
            new_sum = s + num
            if new_sum == target:
                return True
            if new_sum < target:
                temp.add(new_sum)
        dp_set.update(temp)

    return False

