from typing import List

def minCompletionTime(tasks: List[int]) -> int:
    # Sort tasks in descending order
    tasks.sort(reverse=True)

    # Initialize the two workers' loads
    worker1 = 0
    worker2 = 0

    # Assign tasks greedily
    for task in tasks:
        if worker1 <= worker2:
            worker1 += task
        else:
            worker2 += task

    # The completion time is the maximum of the two workers' loads
    return max(worker1, worker2)

