from typing import List

def count_paths(grid: List[List[int]]) -> int:
    n, m = len(grid), len(grid[0])

    # Create a dp table initialized with 0's
    dp = [[0] * m for _ in range(n)]

    # Starting point
    dp[0][0] = 1 if grid[0][0] == 0 else 0

    # Fill the first row
    for j in range(1, m):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]
        else:
            dp[0][j] = 0

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = 0

    # Fill the rest of the dp table
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0

    return dp[n-1][m-1]

