def minimum_swaps(n, arr):
    visited = [False] * n
    swaps = 0

    for i in range(n):
        if visited[i] or arr[i] == i + 1:
            continue

        cycle_size = 0
        j = i
        while not visited[j]:
            visited[j] = True
            next_j = arr[j] - 1
            j = next_j
            cycle_size += 1

        if cycle_size > 0:
            swaps += (cycle_size - 1)

    return swaps

