def min_insertions_to_make_palindrome(s):
    n = len(s)
    # Create a 2D DP table of size n x n
    dp = [[0] * n for _ in range(n)]

    # All single characters are palindromes of length 1
    for i in range(n):
        dp[i][i] = 1

    # Length of substring is from 2 to n
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = 2 + dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    # Length of LPS is dp[0][n - 1]
    lps_length = dp[0][n - 1]
    return n - lps_length

