from collections import defaultdict, deque

def min_time_to_complete_jobs(n, durations, m, dependencies):
    # Build the graph and in-degree count
    graph = defaultdict(list)
    in_degree = [0] * n

    for u, v in dependencies:
        graph[u - 1].append(v - 1)  # Convert to 0-based index
        in_degree[v - 1] += 1

    # Initialize the completion times with each job's own duration
    completion_time = [0] * n
    for i in range(n):
        completion_time[i] = durations[i]

    # Use Kahn's algorithm for topological sort
    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    while queue:
        u = queue.popleft()
        for v in graph[u]:
            # Update the completion time for v
            completion_time[v] = max(completion_time[v], completion_time[u] + durations[v])
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # The answer is the maximum completion time among all jobs
    return max(completion_time)

