def min_moves_to_rearrange_blocks(n, blocks):
    if n <= 1:
        return 0  # No adjacent blocks to compare

    moves = 0
    for i in range(1, n):
        if blocks[i] == blocks[i - 1]:
            # Find a color that is not the same as previous or next block
            current = blocks[i]
            prev = blocks[i - 1]
            next_color = blocks[i + 1] if i + 1 < n else ''

            # Choose a color different from current and previous and (if exists) next
            for color in ['R', 'G', 'B']:
                if color != current and color != prev and (i + 1 >= n or color != next_color):
                    blocks = blocks[:i] + color + blocks[i + 1:]
                    moves += 1
                    break

    return moves

