def knapsack_max_value(n, W, items):
    # Initialize dp array with size W+1 and all elements set to 0
    dp = [0] * (W + 1)

    # Iterate over each item
    for weight, value in items:
        # Traverse dp from W down to weight to prevent reusing the same item
        for w in range(W, weight - 1, -1):
            dp[w] = max(dp[w], dp[w - weight] + value)

    # The maximum value is in dp[W]
    return dp[W]

