def min_diff_between_teams(n, skills):
    total_sum = sum(skills)
    dp = [False] * (total_sum + 1)
    dp[0] = True

    for skill in skills:
        for j in range(total_sum, skill - 1, -1):
            if dp[j - skill]:
                dp[j] = True

    # Find the maximum sum <= total_sum / 2 that can be achieved
    max_sum = 0
    for i in range(total_sum // 2, -1, -1):
        if dp[i]:
            max_sum = i
            break

    return total_sum - 2 * max_sum

