def largest_contiguous_square(n, m, field):
    # Convert field into a 2D array of integers (1 for 'F', 0 for 'B')
    grid = [[1 if cell == 'F' else 0 for cell in row] for row in field]

    # Initialize dp table
    dp = [[0] * m for _ in range(n)]
