import heapq

def dijkstra_shortest_secure_path(n, roads, s, d):
    # Build the graph using only secure roads
    graph = [[] for _ in range(n + 1)]
    for u, v, t in roads:
        if t == 0:
            graph[u].append((v, 1))  # assuming roads have unit weight
            graph[v].append((u, 1))  # since the roads are bidirectional

    # Dijkstra's algorithm
    dist = [float('inf')] * (n + 1)
    dist[s] = 0
    priority_queue = [(0, s)]

    while priority_queue:
        current_dist, u = heapq.heappop(priority_queue)
        if current_dist > dist[u]:
            continue
        for v, weight in graph[u]:
            if dist[v] > dist[u] + weight:
                dist[v] = dist[u] + weight
                heapq.heappush(priority_queue, (dist[v], v))

    return dist[d] if dist[d] != float('inf') else -1

