import heapq

def max_after_operations(nums):
    heap = []
    results = []

    for num in nums:
        if num != -1:
            # Add operation: push the number to the heap
            heapq.heappush(heap, -num)  # Use negative for max-heap simulation
        else:
            # Remove operation: pop the largest element if the heap is not empty
            if heap:
                heapq.heappop(heap)

        # Get the current maximum or -1 if empty
        current_max = -heap[0] if heap else -1
        results.append(current_max)

    return results

from collections import deque

def min_cost_to_destination(n, grid):
    if grid[0][0] == '#' or grid[n-1][n-1] == '#':
        return -1  # Start or end is blocked

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    visited = [[False] * n for _ in range(n)]
    queue = deque()
    queue.append((0, 0, 0))  # (row, col, cost)
    visited[0][0] = True

    while queue:
        row, col, cost = queue.popleft()

        if row == n - 1 and col == n - 1:
            return cost

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < n and 0 <= new_col < n and not visited[new_row][new_col] and grid[new_row][new_col] == '.':
                visited[new_row][new_col] = True
                queue.append((new_row, new_col, cost + 1))

    return -1  # No path found

