def minimum_spanning_tree(n, W):
    from collections import defaultdict

    class UnionFind:
        def __init__(self, size):
            self.parent = list(range(size))

        def find(self, x):
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])  # Path compression
            return self.parent[x]

        def union(self, x, y):
            rootX = self.find(x)
            rootY = self.find(y)
            if rootX != rootY:
                self.parent[rootY] = rootX
                return True
            return False

    # Step 1: Generate list of edges (excluding self-loop)
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((W[i][j], i, j))

    # Step 2: Sort edges by weight
    edges.sort()

    # Step 3: Initialize Union-Find
    uf = UnionFind(n)
    total_weight = 0
    edge_count = 0

    # Step 4: Use Kruskal's algorithm
    for weight, u, v in edges:
        if uf.union(u, v):
            total_weight += weight
            edge_count += 1
            if edge_count == n - 1:
                break  # MST is complete

    return total_weight

