from typing import List

def longest_increasing_subsequence(arr: List[int]) -> int:
    """
    Returns the length of the longest increasing subsequence in the given list of integers.

    Parameters:
    arr (List[int]): The input list of integers.

    Returns:
    int: The length of the longest increasing subsequence.
    """
    if not arr:
        return 0

    n = len(arr)
    dp = [1] * n  # dp[i] will store the length of the longest increasing subsequence ending at index i

    for i in range(n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

