def valid_mountain_array(nums):
    n = len(nums)
    if n < 3:
        return False  # A mountain array must have at least 3 elements

    # Find the peak
    i = 0
    while i < n - 1 and nums[i] < nums[i + 1]:
        i += 1

    # Peak cannot be at the first or last element
    if i == 0 or i == n - 1:
        return False

    # Check if the rest of the array is strictly decreasing
    while i < n - 1:
        if nums[i] <= nums[i + 1]:
            return False
        i += 1

    return True

