def find_cheapest_price(flights, src, dst, K):
    n = 100  # Number of cities can be up to 100 as per the constraints
    # Initialize cost to reach each city as infinity
    cost = [float('inf')] * n
    cost[src] = 0  # Starting city has 0 cost

    # We iterate K+1 times since we are allowed up to K stops (i.e., K+1 flights)
    for _ in range(K + 1):
        temp_cost = cost[:]  # Make a copy for this iteration
        for start, end, price in flights:
            if cost[start] != float('inf') and cost[start] + price < temp_cost[end]:
                temp_cost[end] = cost[start] + price
        cost = temp_cost  # Update the cost for the next iteration

    return cost[dst] if cost[dst] != float('inf') else -1

