def max_consecutive_ones(n, s):
    max_length = 0
    left = 0
    zero_count = 0

    for right in range(n):
        if s[right] == '0':
            zero_count += 1

        # If there are more than one '0's, move the left pointer to the right
        while zero_count > 1:
            if s[left] == '0':
                zero_count -= 1
            left += 1

        # Update the maximum window size
        max_length = max(max_length, right - left + 1)

    return max_length

