def is_scramble(s1, s2):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(s1, s2):
        if s1 == s2:
            return True
        if sorted(s1) != sorted(s2):
            return False
        n = len(s1)
        for i in range(1, n):
            if (dp(s1[:i], s2[:i]) and dp(s1[i:], s2[i:])) or \
               (dp(s1[:i], s2[-i:]) and dp(s1[i:], s2[:-i])):
                return True
        return False

    return "YES" if dp(s1, s2) else "NO"

