from collections import deque

def min_steps(obstacles, startRow, startCol, endRow, endCol):
    if obstacles[startRow][startCol] == 1 or obstacles[endRow][endCol] == 1:
        return -1  # start or end is blocked

    rows, cols = len(obstacles), len(obstacles[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    visited = [[False] * cols for _ in range(rows)]
    queue = deque([(startRow, startCol, 0)])  # (row, col, steps)
    visited[startRow][startCol] = True

    while queue:
        r, c, steps = queue.popleft()
        if r == endRow and c == endCol:
            return steps
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and obstacles[nr][nc] == 0:
                visited[nr][nc] = True
                queue.append((nr, nc, steps + 1))

    return -1  # no path found

