def is_merged_string(s: str, part1: str, part2: str) -> bool:
    m, n = len(part1), len(part2)
    if m + n != len(s):
        return False

    # dp[i][j] will be True if s[0..i+j-1] can be formed by
    # part1[0..i-1] and part2[0..j-1]
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    # Initialize first row and column
    for i in range(1, m + 1):
        dp[i][0] = dp[i-1][0] and part1[i-1] == s[i-1]
    for j in range(1, n + 1):
        dp[0][j] = dp[0][j-1] and part2[j-1] == s[j-1]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            idx = i + j - 1
            if part1[i-1] == s[idx] and dp[i-1][j]:
                dp[i][j] = True
            if part2[j-1] == s[idx] and dp[i][j-1]:
                dp[i][j] = True

    return dp[m][n]

