    nums.sort()

    # The maximum product is the maximum of:
    # 1. Product of the three largest numbers
    # 2. Product of the two smallest (possibly negative) numbers and the largest number
    return max(
        nums[-1] * nums[-2] * nums[-3],
        nums[0] * nums[1] * nums[-1]
    )

