def find_longest_subsequence(numbers: list) -> int:
    # Input validation
    if not isinstance(numbers, list):
        raise ValueError("Input must be a list of integers")

    for num in numbers:
        if not isinstance(num, int):
            raise ValueError("Input must be a list of integers")

    # Edge case: empty list
    if not numbers:
        return 0

    # Sliding window approach with a dictionary to keep track of counts
    from collections import defaultdict

    count_map = defaultdict(int)
    left = 0
    max_length = 0

    for right in range(len(numbers)):
        count_map[numbers[right]] += 1

        # If more than 3 distinct elements, move left pointer
        while len(count_map) > 3:
            count_map[numbers[left]] -= 1
            if count_map[numbers[left]] == 0:
                del count_map[numbers[left]]
            left += 1

        # Update the maximum length of valid subsequence
        max_length = max(max_length, right - left + 1)

    return max_length

