def number_of_paths(n, m, blocked_positions):
    # Convert 1-based indexing to 0-based for easier matrix handling
    blocked_set = set((a - 1, b - 1) for a, b in blocked_positions)

    # Check if start or end is blocked
    if (0, 0) in blocked_set or (n - 1, m - 1) in blocked_set:
        return 0

    # Create a DP table initialized with 0s
    dp = [[0] * m for _ in range(n)]

    # Start point is always reachable
    dp[0][0] = 1

    # Fill the DP table
    for i in range(n):
        for j in range(m):
            if (i, j) in blocked_set:
                dp[i][j] = 0
                continue
            # If not on the first row, add the value from the top
            if i > 0:
                dp[i][j] += dp[i - 1][j]
            # If not on the first column, add the value from the left
            if j > 0:
                dp[i][j] += dp[i][j - 1]

    return dp[n - 1][m - 1]

