import heapq

def min_people_required(nums, x):
    if not nums:
        return 0

    # Sort the tasks in descending order to handle longest tasks first
    nums.sort(reverse=True)

    # Min-heap to track the current load of each person
    heap = []

    for time in nums:
        if not heap:
            # No people available, add a new person
            heapq.heappush(heap, time)
        else:
            # Try to assign to the person with the least load
            if heap[0] + time <= x:
                heapq.heappush(heap, heap[0] + time)
                heapq.heappop(heap)  # Remove the old load
            else:
                # Assign to a new person
                heapq.heappush(heap, time)

    return len(heap)

