def reorder_log_files(logs):
    def is_letter_log(log):
        # Split the log into parts
        _, *rest = log.split()
        # Check if the first non-identifier part is a letter
        return rest[0].isalpha()

    # Separate letter-logs and digit-logs
    letter_logs = []
    digit_logs = []

    for log in logs:
        if is_letter_log(log):
            letter_logs.append(log)
        else:
            digit_logs.append(log)

    # Sort letter-logs by content, then by identifier
    letter_logs.sort(key=lambda x: (x.split()[1:], x.split()[0]))

    # Concatenate the sorted letter-logs and original digit-logs
    return letter_logs + digit_logs

