def count_ways_to_reach_top(n, m):
    # dp[i] will store the number of ways to reach step i
    dp = [0] * (n + 1)
    dp[0] = 1  # Base case: one way to be at step 0 (start)

    for i in range(1, n + 1):
        # Sum up the number of ways to reach i from steps i - 1, i - 2, ..., i - m
        for j in range(1, m + 1):
            if i - j >= 0:
                dp[i] += dp[i - j]

    return dp[n]

