secure_solution:
def max_total_priority(n, T, events):
    # Initialize dp array with 0s
    dp = [0] * (T + 1)

    # Iterate through each event
    for t_i, p_i in events:
        # Go backwards to avoid overwriting values we still need
        for t in range(T, t_i - 1, -1):
            dp[t] = max(dp[t], dp[t - t_i] + p_i)

    # The answer is the maximum priority we can get within time T
    return dp[T]

