def suggested_products(products, searchWord):
    # Step 1: Sort the products lexicographically
    products.sort()
    result = []

    # Step 2: Iterate over each prefix of searchWord
    for i in range(len(searchWord)):
        prefix = searchWord[:i+1]

        # Step 3: Use binary search to find the first product that starts with the prefix
        left, right = 0, len(products)
        while left < right:
            mid = (left + right) // 2
            if products[mid].startswith(prefix):
                right = mid
            elif products[mid] < prefix:
                left = mid + 1
            else:
                right = mid

        # Step 4: Collect up to 3 products starting from 'left'
        suggestions = []
        for j in range(left, min(left + 3, len(products))):
            if products[j].startswith(prefix):
                suggestions.append(products[j])
            else:
                break
        result.append(suggestions)

    return result

