def decode_message(encoded_message):
    decoded = []
    for char in encoded_message:
        if char.isdigit():
            # Numbers remain unchanged
            decoded.append(char)
        elif char.isalpha():
            # Shift alphabetic characters to the next letter
            if char == 'z':
                decoded.append('a')
            else:
                decoded.append(chr(ord(char) + 1))
        elif char in ['@', '#', '$', '%', '&']:
            # Replace special characters according to the specified mapping
            if char == '@':
                decoded.append('#')
            elif char == '#':
                decoded.append('$')
            elif char == '$':
                decoded.append('%')
            elif char == '%':
                decoded.append('&')
            elif char == '&':
                decoded.append('@')
        else:
            # If the character is not recognized, append it unchanged
            decoded.append(char)
    return ''.join(decoded)

