def count_ways_to_collect_fruits(T, cases):
    MOD = 10**9 + 7
    results = []

    for case in cases:
        N, S, F = case
        dp = [0] * (S + 1)
        dp[0] = 1  # One way to make sum 0: take nothing

        for f in F:
            for i in range(S, f - 1, -1):
                dp[i] = (dp[i] + dp[i - f]) % MOD

        results.append(dp[S])

    return results

