def maximum_difference(nums):
    if len(nums) < 2:
        return -1

    min_val = nums[0]
    max_diff = -1

    for num in nums[1:]:
        max_diff = max(max_diff, num - min_val)
        min_val = min(min_val, num)

    return max_diff if max_diff > 0 else -1

def extended_gcd(num1: int, num2: int) -> (int, int, int):
    if num2 == 0:
        return (1, 0, num1)
    else:
        s_prev, t_prev, g = extended_gcd(num2, num1 % num2)
        s = t_prev
        t = s_prev - (num1 // num2) * t_prev
        return (s, t, g)

