from collections import Counter

def min_replacements_to_anagram(s, t):
    if len(s) != len(t):
        return -1

    count_s = Counter(s)
    count_t = Counter(t)

    # Calculate the number of replacements
    replacements = 0
    for char in count_s:
        if char in count_t:
            replacements += abs(count_s[char] - count_t[char])
        else:
            replacements += count_s[char]

    # We need to account for characters in t that are not in s
    for char in count_t:
        if char not in count_s:
            replacements += count_t[char]

    # Since each replacement fixes two characters' discrepancy
    return replacements // 2

