def calculate_phi(n: int) -> int:
    """
    This function takes a single integer n (1 <= n <= 10^6) as input and returns the count of integers between 1 and n inclusive that are coprime with n.
    """
    if n == 0:
        return 0
    if n == 1:
        return 1

    result = n
    i = 2
    while i * i <= n:
        if n % i == 0:
            while n % i == 0:
                n //= i
            result -= result // i
        i += 1
    if n > 1:
        result -= result // n
    return result

