def length_of_longest_arithmetic_subsequence(nums):
    if len(nums) < 2:
        return len(nums)

    n = len(nums)
    dp = [{} for _ in range(n)]  # dp[i] is a dictionary mapping difference to length of sequence

    max_len = 1  # At least one element is a valid subsequence

    for i in range(n):
        for j in range(i):
            diff = nums[i] - nums[j]
            # Get the length of the sequence ending at j with the same difference
            count = dp[j].get(diff, 1)  # if no such sequence, count starts at 1
            dp[i][diff] = max(dp[i].get(diff, 1), count + 1)
            max_len = max(max_len, dp[i][diff])

