from collections import deque

def shortest_subarray_with_sum_at_least_k(arr, k):
    n = len(arr)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + arr[i]

    dq = deque()
    min_len = float('inf')

    for i in range(n + 1):
        while dq and prefix_sum[i] - prefix_sum[dq[0]] >= k:
            min_len = min(min_len, i - dq.popleft())
        while dq and prefix_sum[i] <= prefix_sum[dq[-1]]:
            dq.pop()
        dq.append(i)

    return min_len if min_len != float('inf') else -1

def edit_distance_optimized(A: str, B: str) -> int:
    m, n = len(A), len(B)
    # Ensure we use the smaller of the two strings to minimize space
    if m < n:
        A, B = B, A
        m, n = n, m

    # Initialize the previous row (DP[i][0])
    prev = list(range(n + 1))

    for i in range(1, m + 1):
        curr = [i]  # edit distance to transform first i chars of A to empty string
        for j in range(1, n + 1):
            # Check if characters are the same
            if A[i - 1] == B[j - 1]:
                curr.append(prev[j - 1])  # No operation needed
            else:
                # Take the minimum of insert, delete, or substitute
                curr.append(1 + min(prev[j], curr[j - 1], prev[j - 1]))
        prev = curr  # Move to the next row

    return prev[n]

