from typing import List

def count_paths_with_obstacles(grid: List[List[int]]) -> int:
    n = len(grid)

    # If start or end cell is blocked, return 0
    if grid[0][0] == 1 or grid[n-1][n-1] == 1:
        return 0

    # Initialize a DP table with the same size as the grid
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = 1  # Starting point

    # Fill the first row
    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]
        else:
            dp[0][j] = 0  # Obstacle, so no path can go through

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = 0  # Obstacle, so no path can go through

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Obstacle, so no path through this cell

    return dp[n-1][n-1]

