def follows_pattern(s: str, sub1: str, sub2: str) -> bool:
    # Find the first occurrence of sub1
    first_index = s.find(sub1)
    if first_index == -1:
        return False

    # Find the first occurrence of sub2 after the end of sub1
    second_index = s.find(sub2, first_index + len(sub1))
    if second_index == -1:
        return False

    return True

