def findMedian(nums):
    nums.sort()
    n = len(nums)
    if n % 2 == 1:
        # Odd number of elements: return the middle element
        return nums[n // 2]
    else:
        # Even number of elements: return average of the two middle elements
        return (nums[(n // 2) - 1] + nums[n // 2]) / 2

from typing import List

def all_pairs_shortest_path(adjacency_matrix: List[List[float]]) -> List[List[float]]:
    n = len(adjacency_matrix)
    # Initialize the distance matrix
    dist = [row[:] for row in adjacency_matrix]

    # Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                # Check if the path i -> k -> j is shorter than current path i -> j
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist

