from collections import deque

def findTaskOrder(n, dependency):
    # Step 1: Build adjacency list and in-degree count
    graph = [[] for _ in range(n)]
    in_degree = [0] * n

    for a, b in dependency:
        graph[a].append(b)
        in_degree[b] += 1

    # Step 2: Initialize queue with nodes with in-degree 0
    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    order = []

    # Step 3: Process nodes in topological order
    while queue:
        node = queue.popleft()
        order.append(node)

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Step 4: Check if all nodes were processed (no cycle)
    if len(order) == n:
        return order
    else:
        return []

