def unique_paths_with_obstacles(m, n, obstacles):
    # Convert the obstacles list to a set of tuples for fast lookup
    obstacle_set = set(obstacles)

    # Initialize a DP table with 0s
    dp = [[0] * n for _ in range(m)]

    # Start point is (0, 0), so if it's not an obstacle, it has 1 path
    if (0, 0) not in obstacle_set:
        dp[0][0] = 1

    # Fill the first row
    for j in range(1, n):
        if (0, j) not in obstacle_set:
            dp[0][j] = dp[0][j - 1]

    # Fill the first column
    for i in range(1, m):
        if (i, 0) not in obstacle_set:
            dp[i][0] = dp[i - 1][0]

    # Fill the rest of the DP table
    for i in range(1, m):
        for j in range(1, n):
            if (i, j) not in obstacle_set:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]

    return dp[m - 1][n - 1]

