def minimum_cost_to_connect_houses(n, m, connections):
    # Sort connections by cost
    connections.sort(key=lambda x: x[2])

    # Initialize DSU (Union-Find) data structure
    parent = list(range(n + 1))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]  # Path compression
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            return False  # Already connected
        parent[root_v] = root_u  # Union by attaching root_v to root_u
        return True

    total_cost = 0
    edges_used = 0

    for u, v, w in connections:
        if union(u, v):
            total_cost += w
            edges_used += 1
            if edges_used == n - 1:
                break  # MST has n-1 edges

    # Check if all nodes are connected
    root = find(1)
    for i in range(2, n + 1):
        if find(i) != root:
            return -1  # Not all nodes are connected

    return total_cost

