def min_moves_to_find_threshold(K: int, N: int) -> int:
    # dp[k][m] will store the maximum floors that can be checked with k eggs and m moves
    dp = [[0] * (N + 1) for _ in range(K + 1)]

    # Base case: 0 moves => 0 floors can be checked
    for k in range(K + 1):
        dp[k][0] = 0

    # Base case: 1 egg => m moves allow checking m floors
    for m in range(1, N + 1):
        dp[1][m] = m

    # Fill the DP table
    for k in range(2, K + 1):
        for m in range(1, N + 1):
            dp[k][m] = dp[k-1][m-1] + dp[k][m-1] + 1

    # Find the minimum number of moves m such that dp[K][m] >= N
    for m in range(1, N + 1):
        if dp[K][m] >= N:
            return m

    return N

