def count_pairs_with_sum(arr, target):
    seen = set()
    pairs = set()

    for num in arr:
        complement = target - num
        if complement in seen:
            # Create a sorted tuple to ensure (a, b) and (b, a) are considered the same
            pair = tuple(sorted((num, complement)))
            pairs.add(pair)
        seen.add(num)

    return len(pairs)

