    if not isinstance(description, str):
        raise TypeError("Description must be a string.")

    # Convert the description to lowercase for case-insensitive matching
    description_lower = description.lower()

    # Predefined dictionary of categories and keywords
    categories = {
        "grocery": ["walmart", "supermarket", "groceries"],
        "utilities": ["electric", "water", "gas", "utility"],
        "entertainment": ["movie", "netflix", "amusement"],
        "restaurant": ["restaurant", "dining", "cafe"],
        "transportation": ["taxi", "uber", "bus", "fuel"],
        "healthcare": ["hospital", "pharmacy", "doctor"]
    }

    # Match keywords in the description with the categories
    for category, keywords in categories.items():
        for keyword in keywords:
            if keyword in description_lower:
                return category

    # If no keyword matches, return "Miscellaneous"
    return "miscellaneous"

