def can_form_by_removing_one_char(s, t):
    # If the lengths differ by more than 1, it's not possible
    if len(s) - len(t) != 1:
        return False

    i = j = 0
    n, m = len(s), len(t)

    while i < n and j < m:
        if s[i] == t[j]:
            i += 1
            j += 1
        else:
            # Skip one character in s
            i += 1

    # If we reached the end of t, then it's possible
    return j == m

