def max_treasure(T, test_cases):
    results = []

    for case in test_cases:
        N, grid = case
        dp = [[0] * N for _ in range(N)]

        # Initialize the starting point
        dp[0][0] = grid[0][0]

        # Fill first row
        for j in range(1, N):
            dp[0][j] = dp[0][j - 1] + grid[0][j]

        # Fill first column
        for i in range(1, N):
            dp[i][0] = dp[i - 1][0] + grid[i][0]

        # Fill the rest of the dp table
        for i in range(1, N):
            for j in range(1, N):
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + grid[i][j]

        results.append(dp[N - 1][N - 1])

    return results

