def find_path(grid):
    if grid[0][0] == 0 or grid[-1][-1] == 0:
        return False

    rows, cols = len(grid), len(grid[0])
    visited = set()
    stack = [(0, 0)]

    while stack:
        x, y = stack.pop()

        if (x, y) == (rows - 1, cols - 1):
            return True

        for dx, dy in ((0, 1), (1, 0)):
            nx, ny = x + dx, y + dy

            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 1 and (nx, ny) not in visited:
                visited.add((nx, ny))
                stack.append((nx, ny))

    return False

