from typing import List

def calculate_trimmed_mean(data: List[int], percentage: float) -> float:
    if not data or percentage >= 100:
        return 0.0

    n = len(data)
    trim_amount = int(n * (percentage / 100))

    if trim_amount * 2 >= n:
        return 0.0

    data_sorted = sorted(data)
    trimmed_data = data_sorted[trim_amount : n - trim_amount]

    if not trimmed_data:
        return 0.0

    return sum(trimmed_data) / len(trimmed_data)

