def search_in_rotated_array(array: List[int], target: int) -> int:
    low, high = 0, len(array) - 1

    while low <= high:
        mid = (low + high) // 2

        if array[mid] == target:
            return mid

        # Check if left half is sorted
        if array[low] <= array[mid]:
            if array[low] <= target < array[mid]:
                high = mid - 1
            else:
                low = mid + 1
        else:
            if array[mid] < target <= array[high]:
                low = mid + 1
            else:
                high = mid - 1

    return -1

