def longest_balanced_subsequence(s):
    from collections import defaultdict

    # Initialize the count differences
    a_t_diff = 0  # A - T
    c_g_diff = 0  # C - G

    # Map to store the first index for each (a_t_diff, c_g_diff) pair
    first_occurrence = defaultdict(lambda: -1)

    # Initial state: (0, 0) at index -1
    first_occurrence[(0, 0)] = -1

    max_length = 0

    for i, ch in enumerate(s):
        if ch == 'A':
            a_t_diff += 1
        elif ch == 'T':
            a_t_diff -= 1
        elif ch == 'C':
            c_g_diff += 1
        elif ch == 'G':
            c_g_diff -= 1

        # Check if the difference pair has been seen before
        if (a_t_diff, c_g_diff) in first_occurrence:
            # If yes, calculate the length of the subsequence
            start_index = first_occurrence[(a_t_diff, c_g_diff)]
            current_length = i - start_index
            if current_length > max_length:
                max_length = current_length
        else:
            # Store the first occurrence of this difference pair
            first_occurrence[(a_t_diff, c_g_diff)] = i

    return max_length

