def find_missing_numbers(arr: List[int]) -> List[int]:
    n = len(arr)

    # First pass: Mark the indices of the numbers that are present
    for num in arr:
        index = abs(num) - 1
        if arr[index] > 0:
            arr[index] = -arr[index]

    # Second pass: Collect the indices that are still positive
    missing = []
    for i in range(n):
        if arr[i] > 0:
            missing.append(i + 1)

    return missing

