def is_path_exists(grid):
    n = len(grid)
    m = len(grid[0])

    # Check if the start or end cell is '0'
    if grid[0][0] == '0' or grid[n-1][m-1] == '0':
        return "No"

    # Directions: right and down
    directions = [(0, 1), (1, 0)]

    # Use a visited matrix to prevent revisiting cells
    visited = [[False for _ in range(m)] for _ in range(n)]

    def dfs(i, j):
        if i == n - 1 and j == m - 1:
            return True
        visited[i][j] = True
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and not visited[ni][nj] and grid[ni][nj] == '1':
                if dfs(ni, nj):
                    return True
        return False

    return "Yes" if dfs(0, 0) else "No"

