secure_solution:
def next_bigger(num: int) -> int:
    digits = list(str(num))
    n = len(digits)

    # Step 1: Find the first digit that can be swapped
    pivot = -1
    for i in range(n - 2, -1, -1):
        if digits[i] < digits[i + 1]:
            pivot = i
            break

    if pivot == -1:
        return -1  # No next permutation exists

    # Step 2: Find the smallest digit greater than digits[pivot] to the right of pivot
    for i in range(n - 1, pivot, -1):
        if digits[i] > digits[pivot]:
            # Step 3: Swap
            digits[i], digits[pivot] = digits[pivot], digits[i]
            break

    # Step 4: Reverse the digits after pivot to get the smallest number
    digits[pivot + 1:] = digits[pivot + 1:][::-1]

    # Step 5: Convert back to integer and return
    return int(''.join(digits))

