def min_absolute_difference(ages):
    total_sum = sum(ages)
    target = total_sum // 2
    possible_sums = {0}

    for age in ages:
        new_sums = set()
        for s in possible_sums:
            new_sums.add(s + age)
        possible_sums.update(new_sums)

    # Find the subset sum closest to the target
    closest = min(possible_sums, key=lambda x: abs(x - target))
    return abs(total_sum - 2 * closest)

