secure_solution:
def is_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)

    # Initialize a 2D DP table with (m+1) rows and (n+1) columns
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # Base case: An empty string matches an empty pattern
    dp[0][0] = True

    # Handle patterns with '*' at the beginning
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                # Use * to match zero instances
                dp[i][j] = dp[i][j - 2]
                # Use * to match one or more instances
                if p[j - 2] == s[i - 1] or p[j - 2] == '.':
                    dp[i][j] |= dp[i - 1][j]
            else:
                # Check if current characters match or match with '.'
                if p[j - 1] == s[i - 1] or p[j - 1] == '.':
                    dp[i][j] = dp[i - 1][j - 1]

    return dp[m][n]

