import re

def sanitizeMessage(message, spamWords):
    # Create a regex pattern to match any of the spam words as whole words
    pattern = r'\b(' + '|'.join(re.escape(word) for word in spamWords) + r')\b'

    # Define a function to replace matched words with the same number of asterisks
    def replace_with_asterisks(match):
        return '*' * len(match.group(0))

    # Use re.sub with the pattern and the replacement function
    sanitized_message = re.sub(pattern, replace_with_asterisks, message)

    return sanitized_message

from functools import lru_cache

def is_scrambled(s1, s2):
    @lru_cache(maxsize=None)
    def helper(s1, s2):
        if s1 == s2:
            return True
        if len(s1) != len(s2):
            return False

        # Check if character counts differ
        if sorted(s1) != sorted(s2):
            return False

        n = len(s1)
        for i in range(1, n):
            # Case 1: No swap
            if helper(s1[:i], s2[:i]) and helper(s1[i:], s2[i:]):
                return True
            # Case 2: Swap
            if helper(s1[:i], s2[n-i:]) and helper(s1[i:], s2[:n-i]):
                return True
        return False

    return helper(s1, s2)

