from typing import List

def longest_even_sum_subarray(arr: List[int]) -> int:
    prefix_mod = 0
    first_occurrence = {0: -1}  # Store index of first occurrence of prefix_mod
    max_length = 0

    for i, num in enumerate(arr):
        prefix_mod = (prefix_mod + num) % 2
        if prefix_mod in first_occurrence:
