def smallestProductNumber(N):
    if N == 1:
        return 1

    digits = []

    # Try to factor N into digits 9 down to 2
    for i in range(9, 1, -1):
        while N % i == 0:
            digits.append(i)
            N //= i

    if N != 1:
        return -1  # If after factorization, N is not 1, it's not possible

    # Reverse to get the smallest number (digits should be in ascending order)
    digits.sort()
    return int("".join(map(str, digits)))

