from typing import List

def ternary_search(left: int, right: int, key: int, arr: List[int]) -> int:
    # Check for a valid range
    if left > right or left < 0 or right >= len(arr):
        return -1

    while left <= right:
        # Calculate two midpoints
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3

        # Check if key matches either midpoint
        if arr[mid1] == key:
            return mid1
        if arr[mid2] == key:
            return mid2

        # Adjust the search range
        if key < arr[mid1]:
            right = mid1 - 1
        elif key > arr[mid2]:
            left = mid2 + 1
        else:
            left = mid1 + 1
            right = mid2 - 1

    # Key not found
    return -1

