def infix_to_postfix(expression):
    output = []
    stack = []
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    associativity = {'+': 'left', '-': 'left', '*': 'left', '/': 'left'}

    i = 0
    while i < len(expression):
        char = expression[i]

        if char.isdigit():
            # If the character is a digit, add it to output
            output.append(char)
            i += 1
        elif char == '(':
            # Push '(' to stack
            stack.append(char)
            i += 1
        elif char == ')':
            # Pop from stack to output until '(' is encountered
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()  # Pop the '('
            i += 1
        else:
            # It's an operator
            while stack and stack[-1] != '(' and \
                ((precedence[stack[-1]] > precedence[char]) or
                 (precedence[stack[-1]] == precedence[char] and associativity[char] == 'left')):
                output.append(stack.pop())
            stack.append(char)
            i += 1

    # Pop any remaining operators in the stack
    while stack:
        output.append(stack.pop())

    return ''.join(output)

