def max_coins(n, grid):
    # Initialize a DP array
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = grid[0][0]

    # Fill the first row
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill the first column
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the dp array
    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = grid[i][j] + max(dp[i-1][j], dp[i][j-1])

    return dp[n-1][n-1]

