from typing import List, Tuple

def max_knapsack_value(items: List[Tuple[int, int]], capacity: int) -> int:
    # Edge case: if capacity is 0 or no items, return 0
    if capacity == 0 or not items:
        return 0

    # Initialize dp array
    dp = [0] * (capacity + 1)

    # Process each item
    for value, weight in items:
        # Process from high to low to avoid using the same item multiple times
        for w in range(capacity, weight - 1, -1):
            dp[w] = max(dp[w], dp[w - weight] + value)

    # The maximum value is the maximum in the dp array
    return max(dp)

