def get_divisors(n: int) -> List[int]:
    """Get all divisors of a number n."""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

def optimized_find_order(a: int, n: int) -> int:
    """
    Optimized version of find_order to calculate the order of `a` modulo `n`.

    Parameters:
    a (int): the base integer such that gcd(a, n) = 1.
    n (int): the modulus integer.

    Returns:
    int: the smallest positive integer `k` such that `a^k % n == 1`, or -1 if no such `k` exists.
    """
    if math.gcd(a, n) != 1:
        return -1

    # Handle the edge case when a == 1
    if a == 1:
        return 1

    def mod_pow(base: int, exp: int, mod: int) -> int:
        """Efficient modular exponentiation using binary exponentiation."""
        result = 1
        base = base % mod
        while exp > 0:
            if exp % 2 == 1:
                result = (result * base) % mod
            base = (base * base) % mod
            exp = exp // 2
        return result

    # Compute Euler's totient function φ(n)
    def eulers_totient(n: int) -> int:
        result = n
        i = 2
        while i * i <= n:
            if n % i == 0:
                while n % i == 0:
                    n //= i
                result -= result // i
            i += 1
        if n > 1:
            result -= result // n
        return result

    phi = eulers_totient(n)
    divisors = get_divisors(phi)

    # Try each divisor of φ(n) to find the smallest k such that a^k % n == 1
    for k in sorted(divisors):
        if mod_pow(a, k, n) == 1:
            return k

    return -1

