def min_intervals_to_cover_peaks(prices):
    n = len(prices)
    if n < 3:
        return 0  # Not enough elements to have a local peak

    peaks = []
    for i in range(1, n - 1):
        if prices[i - 1] < prices[i] and prices[i] > prices[i + 1]:
            peaks.append(i)

    if not peaks:
        return 0  # No local peaks

    # Greedy selection of non-overlapping intervals
    count = 0
    i = 0
    while i < len(peaks):
        # Start the interval at the current peak, extend to the next non-overlapping peak
        count += 1
        j = i + 1
        while j < len(peaks) and peaks[j] < peaks[i] + 1:
            j += 1
        i = j

    return count

