    # Greedy selection of non-overlapping intervals
    count = 0
    i = 0
    while i < len(peaks):
        # Start the interval at the current peak, extend to the next non-overlapping peak
        count += 1
        j = i + 1
        while j < len(peaks) and peaks[j] < peaks[i] + 1:
            j += 1
        i = j

    return count

