def move_zeros(arr):
    # Initialize a pointer to track the position where non-zero elements should be placed
    non_zero_pos = 0

    # First pass: move all non-zero elements to the front
    for i in range(len(arr)):
        # Check if the current element is not zero (and also not a boolean False, which is considered 0 in integer context)
        if arr[i] != 0 or isinstance(arr[i], bool):
            arr[non_zero_pos], arr[i] = arr[i], arr[non_zero_pos]
            non_zero_pos += 1

    # Second pass: fill the remaining positions with zeros
    for i in range(non_zero_pos, len(arr)):
        arr[i] = 0

    return arr

