def total_series_resistance(resistances: list) -> float:
    """
    Calculate the total resistance of resistors connected in series.

    Args:
        resistances (list of float): A list of non-negative resistance values in Ohms.

    Returns:
        float: The total resistance in Ohms.

    Raises:
        ValueError: If the list contains non-numeric elements or negative values.
    """
    # Check if resistances is a list and not empty
    if not isinstance(resistances, list):
        raise ValueError("Input must be a list")

    if len(resistances) == 0:
        raise ValueError("List cannot be empty")

    # Validate each resistance value
    for r in resistances:
        if not isinstance(r, (int, float)):
            raise ValueError("All elements in the list must be numeric")
        if r < 0:
            raise ValueError("Resistance values must be non-negative")

    # Calculate total resistance
    return float(sum(resistances))

