from collections import defaultdict, deque

def max_score_in_dag(n, m, k, values, edges):
    # Build the adjacency list
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)

    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    # Topological sort using Kahn's algorithm
    topo_order = []
    queue = deque()

    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Initialize DP table
    # dp[i][j] = max score ending at node i with exactly j nodes visited
    dp = [[-float('inf')] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dp[i][1] = values[i - 1]  # Starting at each node with just one node visited

    # Process nodes in topological order
    for u in topo_order:
        for v in graph[u]:
            for l in range(1, k):
                if dp[u][l] != -float('inf'):
                    if dp[v][l + 1] < dp[u][l] + values[v - 1]:
                        dp[v][l + 1] = dp[u][l] + values[v - 1]

    # The answer is the maximum score of visiting exactly k nodes
    max_score = max(dp[i][k] for i in range(1, n + 1))
    return max_score

