    # Process nodes in topological order
    for u in topo_order:
        for v in graph[u]:
            for l in range(1, k):
                if dp[u][l] != -float('inf'):
                    if dp[v][l + 1] < dp[u][l] + values[v - 1]:
                        dp[v][l + 1] = dp[u][l] + values[v - 1]

    # The answer is the maximum score of visiting exactly k nodes
    max_score = max(dp[i][k] for i in range(1, n + 1))
    return max_score

