def is_scramble(s1, s2):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i1, i2, length):
        # Base case: if the substrings are identical
        if s1[i1:i1+length] == s2[i2:i2+length]:
            return True

        # If the character counts are different, can't be scramble
        if sorted(s1[i1:i1+length]) != sorted(s2[i2:i2+length]):
            return False

        # Try all possible splits
        for k in range(1, length):
            # Case 1: left part of s1 matches left part of s2, right part matches right part
            if dp(i1, i2, k) and dp(i1 + k, i2 + k, length - k):
                return True
            # Case 2: left part of s1 matches right part of s2, right part matches left part of s2
            if dp(i1, i2 + length - k, k) and dp(i1 + k, i2, length - k):
                return True

        return False

    return dp(0, 0, len(s1))

