def find_zero_sum_subarray(n, arr):
    prefix_sum = 0
    prefix_map = {}

    for i in range(n):
        prefix_sum += arr[i]

        if prefix_sum == 0:
            # Subarray from index 0 to current index has sum 0
            return 0, i

        if prefix_sum in prefix_map:
            # We found a prefix sum that was seen before
            # The subarray is from prefix_map[prefix_sum] + 1 to current index i
            return prefix_map[prefix_sum] + 1, i

        # Store the first occurrence of prefix_sum
        prefix_map[prefix_sum] = i

    return -1

