def break_palindrome(s):
    # If the string has only one character, it's impossible to break the palindrome
    if len(s) == 1:
        return ""

    # Convert the string to a list for easier manipulation
    s_list = list(s)

    # Try to break the palindrome by changing the first character that is not 'a' to 'a'
    for i in range(len(s_list) // 2):
        if s_list[i] != 'a':
            s_list[i] = 'a'
            return ''.join(s_list)

    # If all characters in the first half are 'a', change the last character to 'b'
    # This ensures we break the palindrome and keep it lexicographically smallest
    s_list[-1] = 'b'
    return ''.join(s_list)

