def min_coins(n, m, denominations):
    # Initialize a list to store the minimum number of coins needed for each amount up to m
    # We use m + 1 to cover all amounts up to m
    dp = [float('inf')] * (m + 1)
    dp[0] = 0  # Base case: 0 coins needed to make amount 0

    for amount in range(1, m + 1):
        for coin in denominations:
            if coin <= amount:
                dp[amount] = min(dp[amount], dp[amount - coin] + 1)

    return dp[m] if dp[m] != float('inf') else -1

