def longest_balanced_subarray(n, arr, x, y):
    from collections import defaultdict

    count_diff = 0
    diff_map = defaultdict(int)
    diff_map[0] = -1  # Initialize with 0 difference at index -1
    max_length = 0

    for i in range(n):
        if arr[i] == x:
            count_diff += 1
        elif arr[i] == y:
            count_diff -= 1

        if count_diff in diff_map:
            max_length = max(max_length, i - diff_map[count_diff])
        else:
            diff_map[count_diff] = i

    return max_length

