def min_moves_to_identical(arr1, arr2):
    # Check if the set of elements is the same
    if set(arr1) != set(arr2):
        return -1

    # Use two pointers to find the LCS (Longest Common Subsequence)
    i = j = 0
    lcs_length = 0

    while i < len(arr1) and j < len(arr2):
        if arr1[i] == arr2[j]:
            lcs_length += 1
            i += 1
            j += 1
        elif arr1[i] < arr2[j]:
            i += 1
        else:
            j += 1

    # Minimum moves = total elements - 2 * LCS
    return len(arr1) + len(arr2) - 2 * lcs_length

