from collections import defaultdict, deque

def topological_sort_with_dependencies(graph):
    # Step 1: Build in-degree map and adjacency list
    in_degree = defaultdict(int)
    adjacency = defaultdict(list)

    # Map tasks to their direct dependencies
    direct_dependencies = {}

    for task, dependents in graph.items():
        direct_dependencies[task] = len(dependents)
        for dependent in dependents:
            in_degree[dependent] += 1
            adjacency[task].append(dependent)

    # Step 2: Get all nodes in the graph
    all_tasks = set(graph.keys())
    for dependent in in_degree:
        if dependent not in all_tasks:
            all_tasks.add(dependent)

    # Step 3: Initialize queue with nodes having zero in-degree
    queue = deque([task for task in all_tasks if in_degree[task] == 0 and task in graph])

    # Step 4: Topological sort
    result = []

    while queue:
        task = queue.popleft()
        # Add the task and its original direct dependencies to the result
        result.append((task, direct_dependencies.get(task, 0)))

        for neighbor in adjacency[task]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Step 5: Check for cycles
    if len(result) != len(all_tasks):
        raise ValueError("cycle detected")

    return result

