def removeKDuplicates(s, k):
    stack = []  # Each element is a tuple (char, count)

    for char in s:
        if stack and stack[-1][0] == char:
            stack[-1] = (char, stack[-1][1] + 1)
            if stack[-1][1] == k:
                stack.pop()
        else:
            stack.append((char, 1))

    # Reconstruct the final string from the stack
    result = []
    for char, count in stack:
        result.append(char * count)

    return ''.join(result)

