def unique_paths(grid):
    M, N = len(grid), len(grid[0])
    dp = [[0] * N for _ in range(M)]

    # Initialize the starting point
    if grid[0][0] == 0:
        dp[0][0] = 1
    else:
        return 0  # No path if the starting cell is blocked

    # Fill the first row
    for j in range(1, N):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j - 1]
        else:
            dp[0][j] = 0

    # Fill the first column
    for i in range(1, M):
        if grid[i][0] == 0:
            dp[i][0] = dp[i - 1][0]
        else:
            dp[i][0] = 0

    # Fill the rest of the dp table
    for i in range(1, M):
        for j in range(1, N):
            if grid[i][j] == 0:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
            else:
                dp[i][j] = 0

    return dp[M - 1][N - 1]

