def max_sum_subarray_length_m(arr, n, m):
    if m > n or m <= 0:
        return 0  # Based on problem constraints M <= N, so this is just a safeguard

    current_sum = sum(arr[:m])
    max_sum = current_sum

    for i in range(m, n):
        current_sum += arr[i] - arr[i - m]
        max_sum = max(max_sum, current_sum)

    return max_sum

