def min_difference(n, skill_array):
    total_sum = sum(skill_array)
    half_size = n // 2
    min_diff = float('inf')

    def backtrack(start, current_team, current_sum, team_size):
        nonlocal min_diff
        if team_size == half_size:
            remaining_sum = total_sum - current_sum
            min_diff = min(min_diff, abs(current_sum - remaining_sum))
            return
        for i in range(start, len(skill_array)):
            if team_size + 1 <= half_size:
                backtrack(i + 1, current_team + [skill_array[i]], current_sum + skill_array[i], team_size + 1)
            else:
                break

    backtrack(0, [], 0, 0)
    return min_diff

