import math

def count_ways_to_sum(n):
    count = 0
    max_k = int(math.sqrt(2 * n))  # Maximum possible value of k
    for k in range(2, max_k + 1):
        numerator = n - k * (k - 1) // 2
        if numerator > 0 and numerator % k == 0:
            count += 1
    return count

