def highest_product_of_three(nums):
    if len(nums) < 3:
        raise ValueError("Array must have at least three numbers")

    # Sort the array
    nums.sort()

    # Two possibilities for the highest product:
    # 1. Product of the three largest numbers
    # 2. Product of the two smallest (most negative) and the largest number
    return max(
        nums[-1] * nums[-2] * nums[-3],
        nums[0] * nums[1] * nums[-1]
    )

