def minimum_fare(n, fares, x, y):
    if x == y:
        return 0  # No need to travel if start and end are the same

    # Calculate the fare in clockwise direction: from x to y
    if x < y:
        clockwise = sum(fares[x-1:y-1])
    else:
        clockwise = sum(fares[x-1:] + fares[:y-1])

    # Calculate the fare in counter-clockwise direction: from y to x
    if y < x:
        counter_clockwise = sum(fares[y-1:x-1])
    else:
        counter_clockwise = sum(fares[y-1:] + fares[:x-1])

    return min(clockwise, counter_clockwise)

