secure_solution:
def count_paths(matrix):
    MOD = 10**9 + 7
    n = len(matrix)
    m = len(matrix[0])

    # Initialize a DP table
    dp = [[0] * m for _ in range(n)]

    # If the starting cell is blocked
    if matrix[0][0] == 0:
        return 0

    # Starting point
    dp[0][0] = 1

    # Fill first row
    for j in range(1, m):
        if matrix[0][j] == 1:
            dp[0][j] = dp[0][j - 1]
        else:
            break  # Obstacle, no further path in this row

    # Fill first column
    for i in range(1, n):
        if matrix[i][0] == 1:
            dp[i][0] = dp[i - 1][0]
        else:
            break  # Obstacle, no further path in this column

    # Fill the rest of the dp table
    for i in range(1, n):
        for j in range(1, m):
            if matrix[i][j] == 1:
                dp[i][j] = (dp[i - 1][j] + dp[i][j - 1]) % MOD
            else:
                dp[i][j] = 0  # Obstacle, no path through this cell

    return dp[n - 1][m - 1]

