def can_convert_with_k_modifications(s1, s2, k):
    m, n = len(s1), len(s2)

    # If the difference in lengths is greater than k, it's impossible to convert
    if abs(m - n) > k:
        return False

    # Create a DP table with (m+1) rows and (n+1) columns
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the first row and column
    for i in range(m + 1):
        dp[i][0] = i  # Deletions from s1
    for j in range(n + 1):
        dp[0][j] = j  # Insertions into s1

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # No modification needed
            else:
                # Minimum of insert, delete, or replace
                dp[i][j] = 1 + min(dp[i - 1][j],    # Delete from s1
                                   dp[i][j - 1],    # Insert into s1
                                   dp[i - 1][j - 1]) # Replace in s1

    return dp[m][n] <= k

