def min_chars_to_remove_for_palindrome(s: str) -> int:
    n = len(s)
    # Create a DP table to store the length of the longest palindromic subsequence
    dp = [[0] * n for _ in range(n)]

    # A single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the DP table
    for length in range(2, n + 1):  # length of the substring
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = 2 + dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    # The length of the LPS is dp[0][n - 1]
    lps_length = dp[0][n - 1]
    return n - lps_length

