def max_non_adjacent_sum(arr):
    if not arr:
        return 0
    if len(arr) == 1:
        return arr[0]

    # Initialize previous two values
    prev_prev = arr[0]  # max sum up to i-2
    prev = max(arr[0], arr[1])  # max sum up to i-1

    for i in range(2, len(arr)):
        current = max(prev, prev_prev + arr[i])
        prev_prev, prev = prev, current

    return prev

