def combination_iter(n: int, r: int) -> int:
    # Edge cases
    if r > n or r < 0:
        return 0
    if r == 0 or r == n:
        return 1

    # Use a single list to store the current row of Pascal's Triangle
    # We compute up to the nth row, but only need the rth element
    dp = [0] * (r + 1)
    dp[0] = 1  # C(k, 0) = 1 for all k

    for i in range(1, n + 1):
        # Update the dp array in reverse to avoid overwriting values we still need
        for j in range(min(i, r), 0, -1):
            dp[j] = dp[j] + dp[j - 1]

    return dp[r]

