    user_sessions = {}
    user_stack = {}  # To track login times for each user

    for user_id, action, timestamp in logs:
        if action == 'login':
            user_stack[user_id] = timestamp
        elif action == 'logout':
            if user_id in user_stack:
                login_time = user_stack.pop(user_id)
                session_time = timestamp - login_time
                if user_id in user_sessions:
