secure_solution:
def find_digit_product_number(P):
    if P == 1:
        return 1

    digits = []

    # Decompose P into digits from 9 to 2
    for i in range(9, 1, -1):
        while P % i == 0:
            digits.append(i)
            P //= i

    if P != 1:
        return -1  # P cannot be decomposed into factors of 2-9

    # Sort the digits to get the smallest number
    digits.sort()
    return int(''.join(map(str, digits)))

