def min_diff(n, preferences):
    if n % 2 != 0:
        return "Unbalanced"

    total_preferences = sum(len(prefs) for prefs in preferences)
    target = total_preferences // 2
    half_size = n // 2

    # dp[i][j] = max number of preferences we can get using the first i participants for j people
    dp = [[-1] * (half_size + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        prefs = preferences[i - 1]
        count = len(prefs)
        for j in range(half_size + 1):
            if dp[i - 1][j] != -1:
                # Option 1: do not take this participant
                dp[i][j] = max(dp[i][j], dp[i - 1][j])
                # Option 2: take this participant
                if j + 1 <= half_size:
                    dp[i][j + 1] = max(dp[i][j + 1], dp[i - 1][j] + count)

    # Find the closest value to target that we can achieve
    min_diff = float('inf')
    for j in range(half_size + 1):
        if dp[n][j] != -1:
            diff = abs(dp[n][j] - target)
            if diff < min_diff:
                min_diff = diff

    return min_diff

