def max_subarray_length(arr, x):
    prefix_sum = 0
    sum_indices = {0: -1}  # To handle the case where the subarray starts from index 0
    max_length = 0

    for i, num in enumerate(arr):
        prefix_sum += num
        if (prefix_sum - x) in sum_indices:
            max_length = max(max_length, i - sum_indices[prefix_sum - x])
        if prefix_sum not in sum_indices:
            sum_indices[prefix_sum] = i

    return max_length

