from typing import List, Tuple

def validate_task_order(order: str, constraints: List[Tuple[str, str]]) -> bool:
    # Split the order string into individual tasks
    tasks = order.split("->")

    # Create a dictionary to map each task to its index in the order
    task_index = {task: idx for idx, task in enumerate(tasks)}

    # Check each constraint
    for a, b in constraints:
        if a not in task_index or b not in task_index:
            # If either task is not in the order, the constraint cannot be satisfied
            return False
        if task_index[a] >= task_index[b]:
            # If a is not before b in the order, violate the constraint
            return False

    return True

