    @lru_cache(maxsize=None)
    def can_form(i: int, j: int, k: int) -> bool:
        # If we've reached the end of s, it's valid
        if k == len(s):
            return True

        # Try to take the next character from part1
        if i < len(part1) and part1[i] == s[k]:
            if can_form(i + 1, j, k + 1):
                return True

        # Try to take the next character from part2
        if j < len(part2) and part2[j] == s[k]:
            if can_form(i, j + 1, k + 1):
                return True

        return False

    return can_form(0, 0, 0)

