from typing import List

def longest_arith_seq_length(arr: List[int]) -> int:
    if len(arr) <= 2:
        return len(arr)

    # dp[i] is a dictionary where key is the difference and value is the length of the subsequence
    dp = [{} for _ in range(len(arr))]
    max_length = 2  # Minimum length of a subsequence is 2 with two elements

    for i in range(len(arr)):
        for j in range(i):
            diff = arr[i] - arr[j]
            # If the difference has been seen before with j, then extend that sequence
            count = dp[j].get(diff, 1) + 1
            dp[i][diff] = max(dp[i].get(diff, 1), count)
            max_length = max(max_length, dp[i][diff])

    return max_length

def can_be_symmetric(grid):
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # For the grid to be symmetric along the main diagonal,
    # it must be a square grid (n == m)
    if n != m:
        return "NO"

    # Check symmetry along the main diagonal (i, j) vs (j, i)
    for i in range(n):
        for j in range(i + 1, n):  # Only check upper triangle
            if grid[i][j] != grid[j][i]:
                return "NO"

    return "YES"

