def canPartition(nums):
    total_sum = sum(nums)

    # If the total sum is odd, partition is not possible
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    n = len(nums)

    # Use a set to keep track of achievable sums
    achievable_sums = {0}

    for num in nums:
        # For each achievable sum, add the current number to it
        # and update the set of achievable sums
        new_sums = set()
        for s in achievable_sums:
            new_sum = s + num
            if new_sum <= target:
                new_sums.add(new_sum)
        achievable_sums.update(new_sums)

    return target in achievable_sums

