def max_subsegment(n, a):
    max_sum = float('-inf')
    current_sum = 0
    start = 0
    min_length = n  # initially assume the whole array is the subsegment
    result_start = 0

    for i in range(n):
        if current_sum + a[i] > a[i]:
            current_sum += a[i]
        else:
            current_sum = a[i]
            start = i

        # Update the result based on the current subsegment
        if current_sum > max_sum:
            max_sum = current_sum
            min_length = i - start + 1
            result_start = start
        elif current_sum == max_sum:
            length = i - start + 1
            if length < min_length:
                min_length = length
                result_start = start
            elif length == min_length and start < result_start:
                result_start = start

    return min_length, result_start + 1  # convert to 1-based indexing

