def three_sum(arr, k):
    n = len(arr)
    arr.sort()  # Sorting the array to use two-pointer technique

    for i in range(n - 2):
        left = i + 1
        right = n - 1

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]

            if current_sum == k:
                return True
            elif current_sum < k:
                left += 1
            else:
                right -= 1

    return False

