def can_partition_to_equal_subsets(n, difficulties):
    total_sum = sum(difficulties)

    # If total sum is odd, partition is not possible
    if total_sum % 2 != 0:
        return "NO"

    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum of 0 is always possible

    for difficulty in difficulties:
        for j in range(target, difficulty - 1, -1):
            if dp[j - difficulty]:
                dp[j] = True

    return "YES" if dp[target] else "NO"

