def count_cinephile_pairs(arr):
    # Count the frequency of each number of movies watched
    freq = Counter(arr)

    # Calculate the number of unique pairs for each group
    total_pairs = 0
    for count in freq.values():
        if count >= 2:
            total_pairs += count * (count - 1) // 2

    return total_pairs

