from typing import List, Tuple

def two_sum(array: List[int], target: int) -> Tuple[int, int]:
    """
    Find two indices in the array such that the corresponding values add up to the target.
    Returns a tuple of the indices, or None if no such pair exists.
    """
    num_map = {}  # Map from value to its index

    for index, num in enumerate(array):
        complement = target - num
        if complement in num_map:
            return (num_map[complement], index)
        num_map[num] = index  # Store the current number and its index

    return None  # If no solution is found

