def longest_valid_subsequence(dna_sequence):
    max_length = 0
    start = 0  # Start of the sliding window

    for end in range(len(dna_sequence)):
        # If the character is 'G', move the start to end + 1 to skip this 'G'
        if dna_sequence[end] == 'G':
            start = end + 1

        # Update the maximum length of the valid subsequence
        max_length = max(max_length, end - start + 1)

    return max_length

