def iterative_binomial_coefficient(n: int, k: int) -> int:
    if k < 0 or k > n:
        raise ValueError("k must be between 0 and n inclusive")

    # Use symmetry to reduce the number of iterations
    k = min(k, n - k)

    result = 1
    for i in range(1, k + 1):
        # Compute the numerator and denominator for current term and multiply to the result
        result = result * (n - k + i) // i

    return result

