def convert_to_zigzag(s, n):
    if n == 1 or n >= len(s):
        return s

    # Create a list of strings for each row
    rows = [''] * n
    current_row = 0
    going_down = False

    for char in s:
        rows[current_row] += char
        # Change direction when reaching the top or bottom row
        if current_row == 0 or current_row == n - 1:
            going_down = not going_down
        current_row += 1 if going_down else -1

    # Join all rows to get the final zigzag string
    return ''.join(rows)

def is_magic_square(grid):
    # Check if the grid is 3x3
    if len(grid) != 3 or any(len(row) != 3 for row in grid):
        return False

    # Calculate the target sum (sum of first row)
    target_sum = sum(grid[0])

    # Check rows
    for row in grid:
        if sum(row) != target_sum:
            return False

    # Check columns
    for col in range(3):
        if sum(grid[row][col] for row in range(3)) != target_sum:
            return False

    # Check main diagonal (top-left to bottom-right)
    if sum(grid[i][i] for i in range(3)) != target_sum:
        return False

    # Check anti-diagonal (top-right to bottom-left)
    if sum(grid[i][2 - i] for i in range(3)) != target_sum:
        return False

    return True

