def is_permutation_of_substring(s, p):
    len_s, len_p = len(s), len(p)

    if len_p > len_s:
        return False

    # Create a count dictionary for p
    p_count = {}
    for ch in p:
        p_count[ch] = p_count.get(ch, 0) + 1

    # Initialize the count for the first window in s
    s_window_count = {}
    for i in range(len_p):
        ch = s[i]
        s_window_count[ch] = s_window_count.get(ch, 0) + 1

    # Check if the first window is a permutation of p
    if s_window_count == p_count:
        return True

    # Slide the window
    for i in range(len_p, len_s):
        left_char = s[i - len_p]
        right_char = s[i]

        # Remove left character from window count
        s_window_count[left_char] -= 1
        if s_window_count[left_char] == 0:
            del s_window_count[left_char]

        # Add new right character to window count
        s_window_count[right_char] = s_window_count.get(right_char, 0) + 1

        # Check if current window is a permutation of p
        if s_window_count == p_count:
            return True

    return False

