import heapq

def furthest_building(heights, ladder_length, bricks, ladder):
    max_heap = []  # To store the largest height differences
    n = len(heights)

    for i in range(1, n):
        diff = heights[i] - heights[i - 1]
        if diff <= 0:
            continue  # No need for ladder or bricks to go down

        # Use the ladder if we can
        if ladder > 0:
            heapq.heappush(max_heap, diff)
            ladder -= 1
        else:
            # Use bricks if possible
            if bricks >= diff:
                bricks -= diff
            else:
                # Can't move further
                return i - 1

    # If we went through all buildings
    return n - 1

