def closest_pair(arr, x):
    left = 0
    right = len(arr) - 1
    closest_sum = float('inf')
    closest_pair = []

    while left < right:
        current_sum = arr[left] + arr[right]

        # Update closest pair if current_sum is closer to x
        if abs(current_sum - x) < abs(closest_sum - x):
            closest_sum = current_sum
            closest_pair = [arr[left], arr[right]]
        # If the sum is equal to x, this is the best possible pair
        elif abs(current_sum - x) == abs(closest_sum - x):
            if arr[left] + arr[right] < closest_sum:
                closest_sum = current_sum
                closest_pair = [arr[left], arr[right]]

        # Move the pointers
        if current_sum < x:
            left += 1
        else:
            right -= 1

    return closest_pair

