def is_magic_number(n: int) -> bool:
    # Handle the case where n is negative
    n = abs(n)

    # Function to sum the digits of a number
    def digit_sum(num):
        if num < 10:
            return num
        total = 0
        while num > 0:
            total += num % 10
            num //= 10
        return digit_sum(total)  # Recursively sum until a single digit is obtained

    return digit_sum(n) == 1

