secure_solution:
def longestPalindromicSubsequence(s: str) -> int:
    n = len(s)
    # Reverse the string
    s_rev = s[::-1]

    # Create a 2D DP table of size (n+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if s[i - 1] == s_rev[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n][n]

