def can_form_palindrome(s: str) -> bool:
    from collections import Counter

    # Count the frequency of each character
    char_counts = Counter(s)

    # Track the number of characters with odd counts
    odd_count = 0

    for count in char_counts.values():
        if count % 2 != 0:
            odd_count += 1

    # For a string to be rearranged into a palindrome:
    # - If length is even, no character can have an odd count
    # - If length is odd, only one character can have an odd count
    if len(s) % 2 == 0:
        return odd_count == 0
    else:
        return odd_count == 1

