def min_insertions_to_make_palindrome(s: str) -> int:
    n = len(s)

    # Create a DP table where dp[i][j] represents the length of LPS in the substring s[i:j+1]
    dp = [[0] * n for _ in range(n)]

    # All single characters are palindromes of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the table for substrings of length 2 to n
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = 2 + dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    # Minimum insertions = length of string - length of LPS
    return n - dp[0][n - 1]

