    target = total_sum // 2
    n = len(bookThicknesses)

    # Initialize a set to store possible sums
    possible_sums = {0}

    for thickness in bookThicknesses:
        new_sums = set()
        for s in possible_sums:
            new_sum = s + thickness
            if new_sum <= target:
                new_sums.add(new_sum)
        possible_sums.update(new_sums)

    return target in possible_sums

