    # Sort items in descending order to try the heaviest first
    items.sort(reverse=True)

    # Try to place each item on the first possible shelf
    for item in items:
        placed = False
        for i in range(len(shelves)):
            if shelves[i] >= item:
                shelves[i] -= item
                placed = True
                break
        if not placed:
            return "NO"
    return "YES"

