def largest_subarray_with_sum_k(arr, k):
    prefix_sum = 0
    prefix_sum_map = {}
    max_length = 0

    for i, num in enumerate(arr):
        prefix_sum += num

        # If prefix_sum == k, then the subarray from index 0 to i has sum k
        if prefix_sum == k:
            max_length = i + 1

        # Check if (prefix_sum - k) exists in the map
        # If so, then the subarray from the index after the stored index to current index has sum k
        if (prefix_sum - k) in prefix_sum_map:
            length = i - prefix_sum_map[prefix_sum - k]
            if length > max_length:
                max_length = length

        # Store the first occurrence of this prefix_sum
        if prefix_sum not in prefix_sum_map:
            prefix_sum_map[prefix_sum] = i

    return max_length

