def max_consecutive_ones(s):
    max_length = 0
    left = 0
    flip_count = 0

    for right in range(len(s)):
        if s[right] == '0':
            flip_count += 1

        # If more than one flip is needed, move the left pointer
        while flip_count > 1:
            if s[left] == '0':
                flip_count -= 1
            left += 1

        # Update the maximum window size
        max_length = max(max_length, right - left + 1)

    return max_length

