import heapq

def trap_rain_water(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False for _ in range(n)] for _ in range(m)]
    heap = []

    # Push all border cells into the heap
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(heap, (grid[i][j], i, j))
                visited[i][j] = True

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    total_water = 0

    while heap:
        height, row, col = heapq.heappop(heap)
        for dx, dy in directions:
            x, y = row + dx, col + dy
            if 0 <= x < m and 0 <= y < n and not visited[x][y]:
                visited[x][y] = True
                # Water can be trapped if the neighbor's height is lower than the current boundary height
                if grid[x][y] < height:
                    total_water += height - grid[x][y]
                # Add the neighbor to the heap with its height (or the boundary height, if it's higher)
                heapq.heappush(heap, (max(grid[x][y], height), x, y))

    return total_water

