from datetime import datetime

def is_valid_log_entry(timestamp, log_level, message):
    # Check log level is valid
    if log_level not in ["INFO", "WARNING", "ERROR"]:
        return "Invalid"

    # Check message length is between 1 and 100
    if not (1 <= len(message) <= 100):
        return "Invalid"

    # Check timestamp format and validity
    try:
        # The format we expect
        datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return "Invalid"

    # If all checks pass
    return "Valid"

