from typing import List

def min_cost(cost: List[List[int]]) -> int:
    n = len(cost)
    # dp[i] will store the minimum cost to reach station n-1 from station i
    dp = [float('inf')] * n
    dp[n-1] = 0  # Cost to reach destination from itself is 0

    # Traverse from the end to begin
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if cost[i][j] + dp[j] < dp[i]:
                dp[i] = cost[i][j] + dp[j]

    return dp[0]

