def max_product_length(arr):
    from collections import defaultdict

    # Map to store the maximum length of strings for each bitmask
    bit_len_map = defaultdict(int)

    # Convert each string to a bitmask and record the maximum length for each bitset
    for s in arr:
        mask = 0
        for ch in s:
            mask |= 1 << (ord(ch) - ord('a'))
        bit_len_map[mask] = max(bit_len_map[mask], len(s))

    max_product = 0

    # Check all pairs of bitmasks
    for mask1, len1 in bit_len_map.items():
        for mask2, len2 in bit_len_map.items():
            if mask1 != mask2 and (mask1 & mask2) == 0:
                max_product = max(max_product, len1 * len2)

    return max_product

