    dp = [0] * (T + 1)

    # Iterate over all possible durations from 1 to T
    for t in range(1, T + 1):
        # For each game, check if adding it gives better excitement
        for e, d in games:
            if d <= t:
                dp[t] = max(dp[t], dp[t - d] + e)

