def organize_events(events):
    # Step 1: Identify the order of first occurrence of each event type
    first_occurrence_order = []
    seen = set()
    for event in events:
        if event not in seen:
            seen.add(event)
            first_occurrence_order.append(event)

    # Step 2: Group events by their type
    event_groups = {}
    for event in events:
        if event not in event_groups:
            event_groups[event] = []
        event_groups[event].append(event)

    # Step 3: Construct the result based on the first occurrence order
    result = []
    for event_type in first_occurrence_order:
        result.append(''.join(event_groups[event_type]))

    return ''.join(result)

