def max_sum_submatrix(matrix, k, l):
    if not matrix or k <= 0 or l <= 0:
        return 0

    m, n = len(matrix), len(matrix[0])

    # If k or l is larger than the matrix dimensions, return 0
    if k > m or l > n:
        return 0

    # Step 1: Precompute cumulative sums for each row
    row_sums = [[0] * (n + 1) for _ in range(m)]
    for i in range(m):
        for j in range(n):
            row_sums[i][j + 1] = row_sums[i][j] + matrix[i][j]

    max_sum = float('-inf')

    # Step 2: Use sliding window on columns
    for i in range(m - k + 1):
        # Use sliding window on columns
        col_sums = [0] * (n + 1)
        for j in range(n):
            # Update column sums for the current set of rows
            for x in range(i, i + k):
                col_sums[j + 1] += row_sums[x][j + 1] - row_sums[x][j]

        # Now, apply sliding window on the column sums
        for j in range(n - l + 1):
            current_sum = sum(col_sums[j + 1 : j + l + 1])
            max_sum = max(max_sum, current_sum)

    return max_sum

