def longest_even_odd_subarray_length(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Map to store the first occurrence of prefix sum
    prefix_sum_map = {}
    # Initialize with sum 0 at index -1
    prefix_sum_map[0] = -1

    current_sum = 0
    max_length = 0

    for i in range(n):
        # Treat even numbers as +1, odd as -1
        current_sum += 1 if arr[i] % 2 == 0 else -1

        # If this prefix sum has been seen before, calculate subarray length
        if current_sum in prefix_sum_map:
            max_length = max(max_length, i - prefix_sum_map[current_sum])
        else:
            # Store first occurrence of this prefix sum
            prefix_sum_map[current_sum] = i

    return max_length

