from collections import defaultdict

def max_subgroups(players, k):
    rank_counts = defaultdict(int)

    # Parse the input and count the frequency of each rank
    for player in players:
        _, rank = player.split('_')
        rank_counts[int(rank)] += 1

    # We can only form a subgroup if we have at least one player for each rank from 1 to k
    if any(rank_counts.get(i, 0) == 0 for i in range(1, k + 1)):
        return 0

    # The maximum number of subgroups is limited by the minimum count of the ranks 1..k
    return min(rank_counts[i] for i in range(1, k + 1))

