def max_possible_sum(n, arr):
    if n == 0:
        return 0

    total = 0
    current_val = arr[0]
    count = 1

    for i in range(1, n):
        if arr[i] == current_val:
            count += 1
        else:
            total += current_val * count
            current_val = arr[i]
            count = 1

    # Add the last group
    total += current_val * count

    return total

