def is_well_balanced(n, s):
    # Initialize counts for 'A', 'B', 'C'
    count_a = 0
    count_b = 0
    count_c = 0

    # Iterate through the string and check each prefix
    for char in s:
        if char == 'A':
            count_a += 1
        elif char == 'B':
            count_b += 1
        else:
            count_c += 1

        # Check the max and min counts among the three
        max_count = max(count_a, count_b, count_c)
        min_count = min(count_a, count_b, count_c)

        # If the difference between max and min counts is more than 1, it's not well-balanced
        if max_count - min_count > 1:
            return "NO"

    return "YES"

