def is_valid_password(password):
    # Define the required special characters
    special_chars = "!@#$%^&*()"

    # Check length
    if len(password) < 8 or len(password) > 20:
        return False

    # Flags to check presence of required character types
    has_lowercase = False
    has_uppercase = False
    has_digit = False
    has_special = False

    for char in password:
        if char.islower():
            has_lowercase = True
        elif char.isupper():
            has_uppercase = True
        elif char.isdigit():
            has_digit = True
        elif char in special_chars:
            has_special = True

    # Check if all required character types are present
    return has_lowercase and has_uppercase and has_digit and has_special

