def max_skyscraper_sum(heights):
    if not heights:
        return 0
    if len(heights) == 1:
        return heights[0]

    # Using two variables to save space
    prev_prev = heights[0]  # dp[i-2]
    prev = max(heights[0], heights[1])  # dp[i-1]

    for i in range(2, len(heights)):
        current = max(prev, prev_prev + heights[i])
        prev_prev, prev = prev, current

    return prev

