from typing import List

def min_swaps(packages: List[int]) -> int:
    n = len(packages)
    visited = [False] * n
    swaps = 0

    for i in range(n):
        if not visited[i]:
            cycle_size = 0
            j = i
            while not visited[j]:
                visited[j] = True
                j = packages[j] - 1  # packages[j] is the value and should be at index packages[j] - 1
                cycle_size += 1
            if cycle_size > 0:
                swaps += (cycle_size - 1)

    return swaps

