def is_zigzag(lst):
    # A list with fewer than two elements is trivially a zigzag
    if len(lst) < 2:
        return True

    # Initialize the previous direction as 'none' (no comparison yet)
    prev_direction = None

    for i in range(1, len(lst)):
        current = lst[i]
        prev = lst[i - 1]

        # Determine the direction of the current comparison
        if current > prev:
            current_direction = 'up'
        elif current < prev:
            current_direction = 'down'
        else:
            # If equal, it's not a zigzag
            return False

        # Check if the current direction is the same as the previous one
        if current_direction == prev_direction:
            return False

        # Update the previous direction
        prev_direction = current_direction

    return True

