def min_turns_needed(test_cases):
    results = []
    for case in test_cases:
        n, a = case
        if n == 0:
            results.append(0)
            continue
        turns = 1  # At least one turn
        current_color = a[0]
        for i in range(1, n):
            if a[i] != current_color:
                turns += 1
                current_color = a[i]
        results.append(turns)
    return results

