def enhanced_gnome_sort(arr: List[int]) -> List[int]:
    if not arr or len(arr) == 1:
        return arr.copy()

    # Preprocessing step: identify and skip already sorted segments
    n = len(arr)
    i = 1
    # Find the first unsorted segment
    while i < n and arr[i] >= arr[i - 1]:
        i += 1

    # If the entire array is already sorted, return it
    if i == n:
        return arr.copy()

    # Start from the first unsorted position
    current = i

    while current < n:
        if current == 0 or arr[current] >= arr[current - 1]:
            current += 1
        else:
            # Swap elements
            arr[current], arr[current - 1] = arr[current - 1], arr[current]
            current -= 1

    return arr

