def rearrangeArray(arr):
    left = 0
    right = len(arr) - 1

    while left < right:
        # Move left pointer until an odd number is found
        while left < right and arr[left] % 2 == 0:
            left += 1

        # Move right pointer until an even number is found
        while left < right and arr[right] % 2 == 1:
            right -= 1

        # Swap the elements if left < right
        if left < right:
            arr[left], arr[right] = arr[right], arr[left]
            left += 1
            right -= 1

