def longest_ones(s, k):
    left = 0
    max_length = 0
    zero_count = 0

    for right in range(len(s)):
        if s[right] == '0':
            zero_count += 1

        # If the number of zeros exceeds k, move the left pointer to the right
        while zero_count > k:
            if s[left] == '0':
                zero_count -= 1
            left += 1

        # Update the maximum length of the window
        max_length = max(max_length, right - left + 1)

    return max_length

def three_sum(arr, x):
