    n = len(arr)

    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == x:
                return [arr[i], arr[left], arr[right]]
            elif current_sum < x:
                left += 1
            else:
                right -= 1
    return []

