def smallest_string_after_swaps(n, k, s):
    s = list(s)
    for i in range(n):
        # Find the smallest character in the range [i, i + k + 1] that can be moved to position i
        min_char = s[i]
        min_index = i
        for j in range(i + 1, min(i + k + 1, n)):
            if s[j] < min_char:
                min_char = s[j]
                min_index = j
        # Move the smallest character to position i
        for j in range(min_index, i, -1):
            s[j], s[j - 1] = s[j - 1], s[j]
            k -= 1
            if k == 0:
                break
        if k == 0:
            break
    return ''.join(s)

