def longest_prefix_suffix(s: str) -> str:
    n = len(s)
    pi = [0] * n  # Prefix function array

    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j

    # The longest prefix which is also a suffix has length pi[-1]
    return s[:pi[-1]]

def min_moves_to_equal_grid(grid):
    # Flatten the grid to find the maximum value
    max_val = max(max(row) for row in grid)

    # Calculate the total number of moves
    moves = 0
    for row in grid:
        for val in row:
            moves += max_val - val

    return moves

