from collections import defaultdict, deque

def minimum_weeks_to_complete(n, t, prerequisites):
    # Build adjacency list and in-degree count
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)

    for i in range(1, n + 1):
        k_i, *prereqs = prerequisites[i - 1]  # prerequisites[i - 1] corresponds to module i
        for p in prereqs:
            graph[p].append(i)
            in_degree[i] += 1

    # Initialize DP array
    dp = [0] * (n + 1)  # dp[i] = minimum weeks to complete module i

    # Kahn's algorithm (Topological sort)
    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)
            dp[i] = 1  # Base case: module with no prerequisites takes 1 week

    while queue:
        current = queue.popleft()
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            dp[neighbor] = max(dp[neighbor], dp[current] + 1)
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return dp[t]

