def can_partition(nums):
    total_sum = sum(nums)

    # If the total sum is odd, partition is not possible
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    n = len(nums)

    # Initialize a 1D DP array of size (target + 1)
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum of 0 is always possible

    # Dynamic programming to find subset with sum equal to target
    for num in nums:
        for j in range(target, num - 1, -1):
            if dp[j - num]:
                dp[j] = True

    return dp[target]

