def min_falling_path_sum(grid):
    rows, cols = len(grid), len(grid[0])

    # Start from the second row (index 1)
    for i in range(1, rows):
        for j in range(cols):
            # Get the minimum value from the three possible previous positions
            min_prev = float('inf')
            for dj in [-1, 0, 1]:
                prev_j = j + dj
                if 0 <= prev_j < cols:
                    min_prev = min(min_prev, grid[i-1][prev_j])
            # Update the current cell's cost
            grid[i][j] += min_prev

    # The answer is the minimum value in the last row
    return min(grid[-1])

