def is_isomorphic(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False

    # Dictionaries to store mappings from s to t and t to s
    s_to_t = {}
    t_to_s = {}

    for char_s, char_t in zip(s, t):
        # Check if the mapping from s to t is consistent
        if char_s in s_to_t:
            if s_to_t[char_s] != char_t:
                return False
        else:
            # Check if the character in t is already mapped to another character in s
            if char_t in t_to_s:
                return False
            # Create mappings
            s_to_t[char_s] = char_t
            t_to_s[char_t] = char_s

    return True

