def min_deletions_to_palindrome(s: str) -> int:
    n = len(s)
    # Create a 2D DP table with dimensions (n x n)
    dp = [[0] * n for _ in range(n)]

    # All single characters are palindromes of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the DP table
    for length in range(2, n + 1):  # length of the substring
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    # Length of the longest palindromic subsequence
    lps_length = dp[0][n - 1]
    return n - lps_length

