def has_contiguous_subarray(n, k, t, arr):
    # Calculate the sum of the first window of size k
    current_sum = sum(arr[:k])

    # If the first window meets the condition, return "YES"
    if current_sum >= t:
        return "YES"

    # Slide the window across the array
    for i in range(k, n):
        current_sum += arr[i] - arr[i - k]
        if current_sum >= t:
            return "YES"

    # If no window meets the condition, return "NO"
    return "NO"

