from functools import lru_cache

def count_increasing_paths(matrix):
    n = len(matrix)
    m = len(matrix[0])

    @lru_cache(maxsize=None)
    def dp(i, j):
        # Base case: if we're at the bottom-right cell, there's exactly one path (the cell itself)
        if i == n - 1 and j == m - 1:
            return 1

        total = 0

        # Move right if possible
        if j + 1 < m and matrix[i][j] < matrix[i][j + 1]:
            total += dp(i, j + 1)

        # Move down if possible
        if i + 1 < n and matrix[i][j] < matrix[i + 1][j]:
            total += dp(i + 1, j)

        return total

    return dp(0, 0)

