def max_gates_in_use(n, airplanes):
    # Initialize an array to track gate changes
    gate_changes = [0] * 25  # For hours 0 to 23

    for a, d, g in airplanes:
        gate_changes[a] += 1
        if d + 1 < 24:
            gate_changes[d + 1] -= 1

    # Compute the prefix sum to get gates in use at each hour
    current_gates = 0
    max_gates = 0
    for i in range(24):
        current_gates += gate_changes[i]
        if current_gates > max_gates:
            max_gates = current_gates

    return max_gates

