from typing import List

def max_non_consecutive_power(consumptions: List[int]) -> int:
    if not consumptions:
        return 0
    if len(consumptions) == 1:
        return consumptions[0]

    # Initialize the first two values
    prev_prev = consumptions[0]
    prev = max(consumptions[0], consumptions[1])

    for i in range(2, len(consumptions)):
        current = max(prev, consumptions[i] + prev_prev)
        prev_prev, prev = prev, current

    return prev

