def correct_corrupted_element(n, sequence):
    # Determine the correct common difference `d` based on the first few elements
    # Assume the first two elements are correct
    d = sequence[1] - sequence[0]

    # Check if the third element follows the AP
    if sequence[2] == sequence[1] + d:
        # If yes, then the pattern is consistent, and we check the rest
        for i in range(3, n):
            if sequence[i] != sequence[i - 1] + d:
                return (i, sequence[i - 1] + d)
    else:
        # The third element is wrong, so recalibrate `d` based on the second and third elements
        d = sequence[2] - sequence[1]
        # Check if the first three elements can form a consistent AP
        if sequence[0] + d == sequence[1]:
            # Now go through the rest of the sequence
            for i in range(3, n):
                if sequence[i] != sequence[i - 1] + d:
                    return (i, sequence[i - 1] + d)
        else:
            # The first element may be the wrong one
            # Try recalculating d between first and third elements
            d = sequence[2] - sequence[0]
            if sequence[1] != sequence[0] + d:
                return (1, sequence[0] + d)

    # If the above isn't triggered, the corrupted element must be at the end
    return (n - 1, sequence[n - 2] + d)

