secure_solution:
def longest_bitonic_subsequence(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Step 1: Longest Increasing Subsequence (LIS) ending at each index
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Step 2: Longest Decreasing Subsequence (LDS) starting from each index
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Step 3: Find the maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        max_bitonic = max(max_bitonic, inc[i] + dec[i] - 1)

    return max_bitonic

