def unique_paths_with_obstacles(m, n, grid):
    # Edge case: if start or end is blocked
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0

    # Initialize DP table
    dp = [[0 for _ in range(n)] for _ in range(m)]
    dp[0][0] = 1  # starting position

    # Fill first row
    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]
        else:
            dp[0][j] = 0  # blockage

    # Fill first column
    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = 0  # blockage

    # Fill the rest of the grid
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # blockage

    return dp[m-1][n-1]

