from collections import deque

def can_route_packet(edges: List[Tuple[int, int, int]], start: int, end: int, packet_size: int) -> bool:
    # Build adjacency list
    graph = {}
    for u, v, b in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, b))
        graph[v].append((u, b))  # The graph is undirected

    # Use BFS to find if end is reachable from start using only edges with bandwidth >= packet_size
    visited = set()
    queue = deque([start])
    visited.add(start)

    while queue:
        node = queue.popleft()
        if node == end:
            return True
        for neighbor, bandwidth in graph.get(node, []):
            if bandwidth >= packet_size and neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return False

