from collections import defaultdict

def arrange_paintings(n, k, importance_levels):
    if n == 1:
        return importance_levels

    remainder_groups = defaultdict(list)
    for a in importance_levels:
        rem = a % k
        remainder_groups[rem].append(a)

    # Check if the number of elements in any remainder group is more than n // 2
    for rem, lst in remainder_groups.items():
        if len(lst) > n // 2:
            return -1

    # Try to construct the arrangement by alternating remainders
    result = []
    used = set()

    while len(result) < n:
        placed = False
        for rem in range(k):
            if rem in used:
                continue
            for a in remainder_groups[rem]:
                if not result or (result[-1] + a) % k != 0:
                    result.append(a)
                    used.add(rem)
                    placed = True
                    break
            if placed:
                break
        if not placed:
            # Try to find another element that can be placed
            for rem in range(k):
                for a in remainder_groups[rem]:
                    if not result or (result[-1] + a) % k != 0:
                        result.append(a)
                        used.add(rem)
                        placed = True
                        break
                if placed:
                    break
        if not placed:
            return -1

    return result

