from typing import List

def ternary_search(left: int, right: int, key: int, arr: List[int]) -> int:
    while left <= right:
        # Calculate midpoints
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3

        # Check if key is at mid1 or mid2
        if arr[mid1] == key:
            return mid1
        if arr[mid2] == key:
            return mid2

        # Adjust search range based on comparison
        if key < arr[mid1]:
            right = mid1 - 1
        elif key > arr[mid2]:
            left = mid2 + 1
        else:
            left = mid1 + 1
            right = mid2 - 1

    return -1  # Key not found

