def max_sum_of_interactions(n, k, interactions):
    if k == 0 or k > n:
        return (0, 0)

    # Initial sum of the first k elements
    current_sum = sum(interactions[:k])
    max_sum = current_sum
    count = 1

    # Slide the window
    for i in range(k, n):
        current_sum += interactions[i] - interactions[i - k]
        if current_sum > max_sum:
            max_sum = current_sum
            count = 1
        elif current_sum == max_sum:
            count += 1

    return (max_sum, count)

