from typing import List, Tuple

def matrix_region_sum(matrix: List[List[int]], queries: List[Tuple[int, int, int, int]]) -> List[int]:
    if not matrix or not queries:
        return []

    rows, cols = len(matrix), len(matrix[0])

    # Step 1: Construct prefix sum matrix
    prefix = [[0] * (cols + 1) for _ in range(rows + 1)]

    for i in range(rows):
        for j in range(cols):
            prefix[i+1][j+1] = matrix[i][j] + prefix[i][j+1] + prefix[i+1][j] - prefix[i][j]

    # Step 2: Process each query using prefix sum matrix
    result = []
    for row1, col1, row2, col2 in queries:
        sum_submatrix = prefix[row2+1][col2+1] - prefix[row1][col2+1] - prefix[row2+1][col1] + prefix[row1][col1]
        result.append(sum_submatrix)

    return result

