class TrieNode:
    def __init__(self):
        self.children = [None, None]  # 0 and 1 for binary representation

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, number):
        node = self.root
        for i in range(31, -1, -1):  # Using 32 bits for integers
            bit = (number >> i) & 1
            if not node.children[bit]:
                node.children[bit] = TrieNode()
            node = node.children[bit]

    def query(self, number):
        node = self.root
        max_xor = 0
        for i in range(31, -1, -1):
            bit = (number >> i) & 1
            toggled_bit = 1 - bit
            if node.children[toggled_bit]:
                max_xor |= (1 << i)
                node = node.children[toggled_bit]
            else:
                node = node.children[bit] if node.children[bit] else node
        return max_xor

def findMaximumXORSubarray(arr):
    trie = Trie()
    max_xor = 0
    prefix_xor = 0
    trie.insert(0)  # Insert 0 to handle subarrays starting from index 0

    for num in arr:
        prefix_xor ^= num
        max_xor = max(max_xor, trie.query(prefix_xor))
        trie.insert(prefix_xor)

    return max_xor

