import os

def analyze_text_file(file_path: str, top_n: int) -> dict:
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            text = file.read().lower()  # Convert to lowercase for uniformity
            words = text.translate(str.maketrans('', '', string.punctuation)).split()  # Remove punctuation and split into words
            total_words = len(words)
            word_frequency = Counter(words)

            # Get the top N most common words
            top_common_words = word_frequency.most_common(top_n)

            return {
                "total_words": total_words,
                "word_frequency": dict(word_frequency),
                "top_common_words": top_common_words
            }
    except FileNotFoundError:
        return {
            "total_words": 0,
            "word_frequency": {},
            "top_common_words": [],
            "error": "File not found or cannot be read."
        }
    except Exception as e:
        return {
            "total_words": 0,
            "word_frequency": {},
            "top_common_words": [],
            "error": str(e)
        }

