def max_courses(costs, budget):
    # Sort the costs in ascending order
    costs.sort()

    count = 0
    total_cost = 0

    for cost in costs:
        if total_cost + cost <= budget:
            total_cost += cost
            count += 1
        else:
            break  # Can't afford this course, so we stop

    return count

