from itertools import permutations

def is_divisible_by_8(s):
    if len(s) == 1:
        return "YES" if s == '0' or s == '8' else "NO"

    # Get the frequency of each digit in the string
    from collections import Counter
    freq = Counter(s)

    # If length is 2, check all 2-digit combinations
    if len(s) == 2:
        for p in permutations(s):
            num = int(''.join(p))
            if num % 8 == 0:
                return "YES"
        return "NO"

    # For longer strings, check all 3-digit combinations
    # We can use permutations with replacement if a digit repeats
    digits = list(s)
    used = [False] * len(digits)

    def backtrack(start, path):
        if len(path) == 3:
            num = int(''.join(path))
            if num % 8 == 0:
                return True
            return False
        for i in range(len(digits)):
            if used[i]:
                continue
            used[i] = True
            path.append(digits[i])
            if backtrack(i + 1, path):
                return True
            path.pop()
            used[i] = False
        return False

    return "YES" if backtrack(0, []) else "NO"

