def min_difference(n, points):
    total_sum = sum(points)
    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True

    for point in points:
        for j in range(target, point - 1, -1):
            if dp[j - point]:
                dp[j] = True

    # Find the maximum sum less than or equal to target that can be formed
    closest_sum = 0
    for i in range(target, -1, -1):
        if dp[i]:
            closest_sum = i
            break

    return abs(total_sum - 2 * closest_sum)

