def maximum_tower_height(n, heights):
    evens = sorted([h for h in heights if h % 2 == 0], reverse=True)
    odds = sorted([h for h in heights if h % 2 == 1], reverse=True)

    # Compute prefix sums for evens and odds
    prefix_evens = [0]
    for h in evens:
        prefix_evens.append(prefix_evens[-1] + h)

    prefix_odds = [0]
    for h in odds:
        prefix_odds.append(prefix_odds[-1] + h)

    # Try all valid combinations of even and odd blocks with at most one switch
    max_height = 0

    # Case 1: All evens
    max_height = max(max_height, prefix_evens[-1])

    # Case 2: All odds
    max_height = max(max_height, prefix_odds[-1])

    # Case 3: Evens followed by some odds
    for i in range(len(prefix_evens)):
        for j in range(len(prefix_odds)):
            if i == 0 and j == 0:
                continue  # Avoid considering 0+0
            max_height = max(max_height, prefix_evens[i] + prefix_odds[j])

    # Case 4: Odds followed by some evens
    for i in range(len(prefix_odds)):
        for j in range(len(prefix_evens)):
            if i == 0 and j == 0:
                continue  # Avoid considering 0+0
            max_height = max(max_height, prefix_odds[i] + prefix_evens[j])

    return max_height

