def max_solar_panel_efficiency(grid):
    import sys
    sys.setrecursionlimit(10000)

    n = len(grid)
    m = len(grid[0])

    max_tree = max(max(row) for row in grid)

    def largest_rectangle_area(heights):
        # This is the standard largest rectangle in histogram algorithm
        stack = []
        max_area = 0
        heights.append(0)  # Append a 0 to trigger remaining elements in the stack
        for i, h in enumerate(heights):
            while stack and heights[stack[-1]] > h:
                height = heights[stack.pop()]
                width = i if not stack else i - stack[-1] - 1
                max_area = max(max_area, height * width)
            stack.append(i)
        return max_area

    # Binary search on the value to find max efficiency
    low = 0
    high = max_tree
    max_efficiency = 0

    while low <= high:
        mid = (low + high) // 2
        # Create a matrix where value >= mid becomes 1, else 0
        temp = []
        for row in grid:
            temp_row = [1 if val >= mid else 0 for val in row]
            temp.append(temp_row)

        # For each row, calculate the largest rectangle in histogram using the temp matrix
        for i in range(n):
            # Update the histogram for the current row
            if i == 0:
                heights = temp[i]
            else:
                for j in range(m):
                    if temp[i][j] == 1:
                        heights[j] += 1
                    else:
                        heights[j] = 0
            # Calculate max area using the largest_rectangle_area function
            area = largest_rectangle_area(heights.copy())
            if area > 0:
                max_efficiency = mid
                break
        if max_efficiency >= mid:
            low = mid + 1
        else:
            high = mid - 1

    return max_efficiency

