def check_distinct_subarray(arr, m):
    from collections import defaultdict

    n = len(arr)
    if m > n:
        return "No"

    count = defaultdict(int)
    unique_count = 0

    # Initialize the first window
    for i in range(m):
        count[arr[i]] += 1
        if count[arr[i]] == 1:
            unique_count += 1

    if unique_count == m:
        return "Yes"

    # Slide the window
    for i in range(m, n):
        # Remove the element exiting the window
        out_elem = arr[i - m]
        count[out_elem] -= 1
        if count[out_elem] == 0:
            unique_count -= 1

        # Add the new element entering the window
        in_elem = arr[i]
        count[in_elem] += 1
        if count[in_elem] == 1:
            unique_count += 1

        if unique_count == m:
            return "Yes"

    return "No"

