def count_ways_to_reach_end(n, m, grid):
    # Create a DP table initialized with 0s
    dp = [[0 for _ in range(m)] for _ in range(n)]

    # Start point: (0,0)
    if grid[0][0] == '*':
        return 0
    dp[0][0] = 1

    # Fill first row
    for j in range(1, m):
        if grid[0][j] == '*':
            dp[0][j] = 0
        else:
            dp[0][j] = dp[0][j - 1]

    # Fill first column
    for i in range(1, n):
        if grid[i][0] == '*':
            dp[i][0] = 0
        else:
            dp[i][0] = dp[i - 1][0]

    # Fill rest of the table
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == '*':
                dp[i][j] = 0
            else:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]

    return dp[n - 1][m - 1]

