def optimal_value_packing(items, capacity):
    # Initialize dp array with size (capacity + 1) and all values set to 0
    dp = [0] * (capacity + 1)

    for value, weight in items:
        # Update dp in reverse order to avoid reusing the same item
        for w in range(capacity, weight - 1, -1):
            dp[w] = max(dp[w], dp[w - weight] + value)

    return dp[capacity]

