def max_histogram_area(heights):
    n = len(heights)
    left = [0] * n  # nearest smaller to the left
    right = [n] * n  # nearest smaller to the right

    stack = []

    # Fill left array
    for i in range(n):
        while stack and heights[stack[-1]] >= heights[i]:
            stack.pop()
        if stack:
            left[i] = stack[-1] + 1  # +1 to make it 1-based index width
        else:
            left[i] = 0
        stack.append(i)

    stack = []

    # Fill right array
    for i in range(n - 1, -1, -1):
        while stack and heights[stack[-1]] >= heights[i]:
            stack.pop()
        if stack:
            right[i] = stack[-1] - 1  # -1 to make it 1-based index width
        else:
            right[i] = n - 1
        stack.append(i)

    # Calculate maximum area
    max_area = 0
    for i in range(n):
        width = right[i] - left[i] + 1
        area = heights[i] * width
        max_area = max(max_area, area)

    return max_area

