    while start < end:
        if s[start] != s[end]:
            return False
        start += 1
        end -= 1
    return True

def min_palindromic_substrings(s):
    n = len(s)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0  # Base case: empty string needs 0 substrings

    for i in range(1, n + 1):
        for j in range(i):
            if is_palindrome(s, j, i - 1):
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[n]

