def longest_subarray_with_distinct_elements(arr):
    if not arr:
        return 0

    seen = {}
    left = 0
    max_length = 0

    for right in range(len(arr)):
        current = arr[right]

        # If the element is seen and is within the current window, move the left pointer
        if current in seen and seen[current] >= left:
            left = seen[current] + 1

        # Update the last seen index of the current element
        seen[current] = right

        # Update the maximum length of the subarray with distinct elements
        max_length = max(max_length, right - left + 1)

    return max_length

