def canAchieveFavoriteCandies(candies, favorite):
    # Initialize a set to keep track of achievable sums
    achievable = {0}

    # Iterate through each candy count and update the set of achievable sums
    for candy in candies:
        new_sums = set()
        for s in achievable:
            new_sums.add(s + candy)
        achievable.update(new_sums)

    # Check for each favorite number if it is achievable
    result = [fave in achievable for fave in favorite]

    return result

