secure_solution:
def topological_sort(tasks: dict) -> list:
    """
    Perform a topological sort on the given task dependency graph.

    :param tasks: dict, a dictionary representing the task dependency graph
    :return: list, a topologically sorted order of tasks
    """
    # Step 1: Build in-degree dictionary
    in_degree = {task: 0 for task in tasks}
    graph = {task: [] for task in tasks}

    # Build the graph and compute in-degrees
    for task, dependents in tasks.items():
        for dependent in dependents:
            graph[task].append(dependent)
            in_degree[dependent] += 1

    # Step 2: Initialize queue with tasks having zero in-degree
    from collections import deque
    queue = deque([task for task in in_degree if in_degree[task] == 0])

    # Step 3: Process the queue
    result = []
    while queue:
        current_task = queue.popleft()
        result.append(current_task)
        for dependent in graph[current_task]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                queue.append(dependent)

    # Step 4: Check for cycles
    if len(result) != len(tasks):
        return []

    return result

