def min_visible_blocks(heights):
    if not heights:
        return 0  # Edge case: empty list

    # Sort the heights to facilitate block creation
    heights.sort()

    blocks = 1  # At least one block needed
    current_block_height = heights[0]

    for height in heights[1:]:
        # If current height is more than 1 greater than current block height, start new block
        if height > current_block_height + 1:
            blocks += 1
            current_block_height = height

    return blocks

