from collections import deque

def shortest_subarray_with_sum_at_least_x(arr: list[int], x: int) -> int:
    n = len(arr)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + arr[i]

    dq = deque()
    min_len = float('inf')

    for j in range(n + 1):
        while dq and prefix[j] - prefix[dq[0]] >= x:
            i = dq.popleft()
            min_len = min(min_len, j - i)

        while dq and prefix[j] <= prefix[dq[-1]]:
            dq.pop()

        dq.append(j)

    return min_len if min_len != float('inf') else -1

