    if n == 0:
        return 0

    count = 1  # At least one subarray
    trend = None  # Can be 'increasing', 'decreasing', or None (for the first element)

    for i in range(1, n):
        if a[i] > a[i - 1]:
            current_trend = 'increasing'
        elif a[i] < a[i - 1]:
            current_trend = 'decreasing'
        else:
            # Equal elements break both trends
            current_trend = None

        if trend is None:
            trend = current_trend
        else:
            if trend != current_trend:
                # Trend changed, so we need to split here
                count += 1
                trend = current_trend

    return count

