def min_max_completion_time(n, tasks):
    total_sum = sum(tasks)
    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True

    for duration in tasks:
        for i in range(target, duration - 1, -1):
            if dp[i - duration]:
                dp[i] = True

    max_subset_sum = 0
    for i in range(target, -1, -1):
        if dp[i]:
            max_subset_sum = i
            break

    return max(max_subset_sum, total_sum - max_subset_sum)

