def count_partitions(n):
    # dp[i] will store the number of ways to partition i
    dp = [0] * (n + 1)
    dp[0] = 1  # Base case: one way to partition 0 (using no numbers)

    # Iterate through each possible summand (starting from 1 to n)
    for k in range(1, n + 1):
        # Update dp for all values from k to n
        for i in range(k, n + 1):
            dp[i] += dp[i - k]

    return dp[n]

