import heapq
from typing import List

def trap_snow(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    heap = []

    # Initialize the heap with the boundary cells
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(heap, (grid[i][j], i, j))
                visited[i][j] = True

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    trapped_snow = 0

    while heap:
        height, x, y = heapq.heappop(heap)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                # The minimum height that can trap water at (nx, ny)
                if grid[nx][ny] < height:
                    trapped_snow += height - grid[nx][ny]
                # Push the neighboring cell with its elevation
                heapq.heappush(heap, (max(grid[nx][ny], height), nx, ny))

    return trapped_snow

def travelling_salesman(n, D):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def tsp(mask, current):
        if mask == (1 << n) - 1:
            return D[current][0]  # Return to the starting city (0)

        min_dist = float('inf')
        for next_city in range(n):
            if not (mask & (1 << next_city)):
                new_mask = mask | (1 << next_city)
                min_dist = min(min_dist, D[current][next_city] + tsp(new_mask, next_city))
        return min_dist

    return tsp(1 << 0, 0)  # Start from city 0 with only city 0 visited

