def card_game(n, cards):
    # Sort the cards in descending order
    cards.sort(reverse=True)

    # Initialize the sums for Alice and Bob
    alice_sum = 0
    bob_sum = 0

    # Alternate turns between Alice and Bob
    for i in range(n):
        if i % 2 == 0:
            alice_sum += cards[i]
        else:
            bob_sum += cards[i]

    return alice_sum, bob_sum

