secure_solution:
def max_signal_strength(n, d, signals):
    # Edge case when d == n
    if d == n:
        return sum(signals)

    # Initial sum of the first window
    current_sum = sum(signals[:d])
    max_sum = current_sum

    # Slide the window
    for i in range(d, n):
        current_sum += signals[i] - signals[i - d]
        max_sum = max(max_sum, current_sum)

    return max_sum

