def odd_sum_subsequences_count(n, sequence):
    count = 0

    # Iterate through all possible subsequences using bitmasking
    for mask in range(1, 1 << n):  # from 1 to 2^n - 1
        total = 0
        for i in range(n):
            if mask & (1 << i):
                total += sequence[i]
        if total % 2 == 1:
            count += 1

    return count

