def knapsack(n, W, items):
    # Initialize a set containing only 0 (starting with no weight)
    achievable_weights = {0}

    for w, v in items:
        # Temporarily store new achievable weights
        new_weights = set()

        # For each weight we have achieved so far, try adding the current item
        for weight in achievable_weights:
            new_weight = weight + w
            if new_weight <= W:
                new_weights.add(new_weight)

        # Merge new weights with existing achievable weights
        achievable_weights.update(new_weights)

    # Now, we need to find the maximum value corresponding to each weight
    # So we need to track the maximum value for each weight
    # Let's convert the set to a list and sort it
    sorted_weights = sorted(achievable_weights)

    # Track the value corresponding to each weight
    value_map = {0: 0}

    for w, v in items:
        # Create a copy to avoid modifying the set while iterating
        new_values = value_map.copy()
        for weight in sorted_weights:
            if weight in value_map:
                new_weight = weight + w
                if new_weight <= W and new_weight not in new_values:
                    new_values[new_weight] = value_map[weight] + v
        value_map = new_values

    return max(value_map.values())

