def count_paths_through_labyrinth(R, C, grid):
    # Initialize a DP table with the same dimensions as the grid
    dp = [[0 for _ in range(C)] for _ in range(R)]

    # Start point: if it's not an obstacle, there's one way to be there (start)
    if grid[0][0] == '.':
        dp[0][0] = 1
    else:
        return 0  # No path if start is blocked

    # Fill the first row
    for j in range(1, C):
        if grid[0][j] == '.':
            dp[0][j] = dp[0][j - 1]
        else:
            dp[0][j] = 0  # Obstacle, no path

    # Fill the first column
    for i in range(1, R):
        if grid[i][0] == '.':
            dp[i][0] = dp[i - 1][0]
        else:
            dp[i][0] = 0  # Obstacle, no path

    # Fill the rest of the DP table
    for i in range(1, R):
        for j in range(1, C):
            if grid[i][j] == '.':
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
            else:
                dp[i][j] = 0  # Obstacle, no path

    return dp[R - 1][C - 1]

