def maximize_resources(resources):
    if not resources:
        return 0
    n = len(resources)
    if n == 1:
        return resources[0]
    if n == 2:
        return max(resources)

    # Initialize the previous two values
    prev_prev = resources[0]
    prev = max(resources[0], resources[1])

    for i in range(2, n):
        current = max(prev, prev_prev + resources[i])
        prev_prev, prev = prev, current

    return prev

