def is_symmetric(mosaic):
    N = len(mosaic)

    # Check horizontal symmetry: each row should be mirrored around the horizontal axis
    for i in range(N // 2):
        if mosaic[i] != mosaic[N - 1 - i]:
            return "Not symmetric"

    # Check vertical symmetry: each column should be mirrored around the vertical axis
    for i in range(N):
        for j in range(N // 2):
            if mosaic[i][j] != mosaic[i][N - 1 - j]:
                return "Not symmetric"

    return "Symmetric"

