from typing import List

def wiggle_sort(nums: List[int]) -> None:
    """
    Reorders the elements of nums in-place to satisfy the wiggle sort pattern:
    nums[0] < nums[1] > nums[2] < nums[3] > ...

    Parameters:
    nums (List[int]): The list of integers to be sorted.
    """
    n = len(nums)
    for i in range(1, n):
        # For even index i, we need nums[i-1] < nums[i]
        if i % 2 == 1:
            if nums[i] < nums[i - 1]:
                nums[i], nums[i - 1] = nums[i - 1], nums[i]
        # For odd index i, we need nums[i-1] > nums[i]
        else:
            if nums[i] > nums[i - 1]:
                nums[i], nums[i - 1] = nums[i - 1], nums[i]

