def encode_decode(message: str, key1: str, key2: str, encode: bool) -> str:
    # Check that key1 and key2 have the same length and contain unique characters
    if len(key1) != len(key2):
        raise ValueError("key1 and key2 must be of the same length.")

    if len(set(key1)) != len(key1) or len(set(key2)) != len(key2):
        raise ValueError("key1 and key2 must contain only unique characters.")

    # Create a mapping dictionary
    mapping = {key1[i]: key2[i] for i in range(len(key1))}

    # If encoding, use the mapping directly
    # If decoding, reverse the mapping (key2 -> key1)
    if encode:
        result = ''.join([mapping[char] if char in mapping else char for char in message])
    else:
        reverse_mapping = {key2[i]: key1[i] for i in range(len(key2))}
        result = ''.join([reverse_mapping[char] if char in reverse_mapping else char for char in message])

    return result

