def min_weight_path_with_k_edges(n, m, k, edges, a, b):
    import sys
    import heapq

    # Initialize DP array: dp[steps][node] = min weight
    INF = float('inf')
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][a] = 0  # Starting point

    # Build adjacency list
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))  # Undirected graph

    # Dynamic Programming
    for step in range(1, k + 1):
        for u in range(1, n + 1):
            if dp[step - 1][u] == INF:
                continue
            for v, weight in graph[u]:
                if dp[step][v] > dp[step - 1][u] + weight:
                    dp[step][v] = dp[step - 1][u] + weight

    result = dp[k][b]
    return result if result != INF else -1

