from typing import List, Tuple

def entropy_sort(arr: List[int]) -> Tuple[List[int], int]:
    # Define a helper function to compute the entropy of a list
    def calculate_entropy(sorted_arr: List[int]) -> int:
        return sum(abs(sorted_arr[i] - sorted_arr[i + 1]) for i in range(len(sorted_arr) - 1))

    # Sort in ascending order
    sorted_asc = sorted(arr)
    entropy_asc = calculate_entropy(sorted_asc)

    # Sort in descending order
    sorted_desc = sorted(arr, reverse=True)
    entropy_desc = calculate_entropy(sorted_desc)

    # Choose the sorted list with the minimum entropy
    if entropy_asc <= entropy_desc:
        return (sorted_asc, entropy_asc)
    else:
        return (sorted_desc, entropy_desc)

