def can_rotate_to_avoid_uniform_k_subarray(N, K, A):
    if K == 1:
        # All elements are single-element subarrays; if any element is unique, the answer is "Yes"
        return "Yes"

    for shift in range(K):
        rotated = A[shift:] + A[:shift]
        has_bad_subarray = False

        # Use a sliding window to check for subarrays with all elements equal
        for i in range(N - K + 1):
            subarray = rotated[i:i + K]
            if all(x == subarray[0] for x in subarray):
                has_bad_subarray = True
