def longest_palindromic_subsequence(n, pearls):
    # Create a reversed version of the pearls list
    reversed_pearls = pearls[::-1]

    # Initialize a 2D DP table with (n+1) rows and (n+1) columns
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if pearls[i - 1] == reversed_pearls[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
