def decode_string(s: str) -> str:
    stack = []
    current_string = ""
    current_number = 0

    for char in s:
        if char.isdigit():
            current_number = current_number * 10 + int(char)
        elif char == "[":
            stack.append((current_string, current_number))
            current_string = ""
            current_number = 0
        elif char == "]":
            popped_string, popped_number = stack.pop()
            current_string = popped_string + popped_number * current_string
        else:
            current_string += char

    return current_string

