def count_paths(grid: List[List[int]]) -> int:
    m, n = len(grid), len(grid[0])

    # If starting or ending cell is an obstacle, return 0
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0

    # Initialize DP table
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1  # Starting point

    # Fill first row
    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]
        else:
            dp[0][j] = 0  # Obstacle, no path

    # Fill first column
    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = 0  # Obstacle, no path

    # Fill rest of the DP table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Obstacle, no path

    return dp[m-1][n-1]

