secure_solution:
def cocktail_shaker_sort(arr: [int]) -> [int]:
    n = len(arr)
    if n <= 1:
        return arr  # already sorted

    swapped = True
    start = 0
    end = n - 1

    while swapped:
        swapped = False

        # Forward pass (left to right)
        for i in range(start, end):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                swapped = True

        if not swapped:
            break  # if no swaps, list is sorted

        swapped = False
        end -= 1  # reduce end as the last element is now in place

        # Backward pass (right to left)
        for i in range(end, start, -1):
            if arr[i] < arr[i - 1]:
                arr[i], arr[i - 1] = arr[i - 1], arr[i]
                swapped = True

        start += 1  # increase start as the first element is now in place

    return arr

