from collections import defaultdict, deque

def find_longest_path(n, m, edges):
    # Build adjacency list and in-degree count
    graph = defaultdict(list)
    in_degree = [0] * n

    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    # Step 1: Topological Sort using Kahn's algorithm
    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    # Step 2: Initialize dp array
    dp = [0] * n

    # Step 3: Process nodes in topological order
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            dp[v] = max(dp[v], dp[u] + 1)
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # The longest path is the maximum value in dp
    return max(dp)

