from typing import Dict, Tuple, List
import sys

def bellman_ford_with_path(graph: Dict[str, Dict[str, int]], source: str, destination: str) -> Tuple[bool, List[str]]:
    # Step 1: Initialize distances and predecessors
    nodes = list(graph.keys())
    dist = {node: sys.maxsize for node in nodes}
    dist[source] = 0
    predecessors = {node: None for node in nodes}

    # Step 2: Relax edges |V| - 1 times
    for _ in range(len(nodes) - 1):
        updated = False
        for u in nodes:
            for v, weight in graph[u].items():
                if dist[v] > dist[u] + weight:
                    dist[v] = dist[u] + weight
                    predecessors[v] = u
                    updated = True
        if not updated:
            break

    # Step 3: Check for negative-weight cycles
    has_negative_cycle = False
    for u in nodes:
        for v, weight in graph[u].items():
            if dist[v] > dist[u] + weight:
                has_negative_cycle = True
                break
        if has_negative_cycle:
            break

    # Step 4: Reconstruct path if no negative cycle and path exists
    if has_negative_cycle:
        return (False, [])

    path = []
    current = destination
    while current is not None:
        path.append(current)
        current = predecessors[current]

    # Reverse path to get from source to destination
    path = path[::-1]

    # Check if the destination is reachable
    if dist[destination] == sys.maxsize:
        return (True, [])

    return (True, path)

