def shortest_common_supersequence(text1, text2):
    # Step 1: Compute the Longest Common Subsequence (LCS)
    m, n = len(text1), len(text2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i - 1] == text2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Step 2: Use LCS to build the shortest common supersequence
    i, j = m, n
    result = []

    while i > 0 and j > 0:
        if text1[i - 1] == text2[j - 1]:
            result.append(text1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            result.append(text1[i - 1])
            i -= 1
        else:
            result.append(text2[j - 1])
            j -= 1

    # Append remaining characters of text1 or text2
    while i > 0:
        result.append(text1[i - 1])
        i -= 1
    while j > 0:
        result.append(text2[j - 1])
        j -= 1

    # Reverse to get the correct order
    return ''.join(reversed(result))

