def max_non_overlapping_meetings(meetings):
    if not meetings:
        return 0

    # Sort meetings based on their end times
    meetings.sort(key=lambda x: x[1])

    count = 1
    last_end = meetings[0][1]

    for start, end in meetings[1:]:
        if start >= last_end:
            count += 1
            last_end = end

    return count

def is_merge(s: str, part1: str, part2: str) -> bool:
    # Check if the combined length of part1 and part2 matches s
    if len(part1) + len(part2) != len(s):
        return False

    # Handle base case: empty string
    if len(s) == 0:
        return True

