def count_paths(n, m, blocked_cells):
    MOD = 10**9 + 7  # To prevent integer overflow for large grids

    # Create a grid to mark blocked cells
    blocked = set(blocked_cells)

    # If start or end is blocked, return 0
    if (1, 1) in blocked or (n, m) in blocked:
        return 0

    # Initialize a DP table with dimensions (n+1) x (m+1)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[1][1] = 1  # Starting point

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if (i, j) in blocked:
                dp[i][j] = 0
            else:
                if i > 1:
                    dp[i][j] += dp[i - 1][j]
                if j > 1:
                    dp[i][j] += dp[i][j - 1]
                dp[i][j] %= MOD

    return dp[n][m]

