secure_solution:
def findTwoUniqueNumbers(arr, n):
    # Step 1: XOR all the elements
    xor_all = 0
    for num in arr:
        xor_all ^= num

    # Step 2: Find the rightmost set bit
    rightmost_bit = xor_all & -xor_all

    # Step 3: Partition the array into two groups and find the unique numbers
    num1, num2 = 0, 0
    for num in arr:
        if num & rightmost_bit:
            num1 ^= num
        else:
            num2 ^= num

    # Step 4: Return the result in ascending order
    return [min(num1, num2), max(num1, num2)]

