def find_cycle_groups(n, roads):
    visited = [False] * n
    cycle_count = 0

    for i in range(n):
        if not visited[i]:
            current = i
            path = []
            while True:
                if visited[current]:
                    # Check if current is in the current path
                    if current in path:
                        idx = path.index(current)
                        cycle = path[idx:]
                        cycle_count += 1
                    break
                visited[current] = True
                path.append(current)
                current = roads[current] - 1  # Convert to 0-based index

    return cycle_count

def numOfSubarrays(arr, k, threshold):
    n = len(arr)
    required_sum = threshold * k
    current_sum = sum(arr[:k])
    count = 0

    if current_sum >= required_sum:
        count += 1

    for i in range(k, n):
        current_sum += arr[i] - arr[i - k]
        if current_sum >= required_sum:
            count += 1

    return count

