    # Create a list to store the result
    result = []

    # Arrays to keep track of used indices
    used1 = [False] * len(arr1)
    used2 = [False] * len(arr2)

    # Try to form valid pairs using backtracking
    def backtrack():
        # If all elements are used, return True
        if all(used1) and all(used2):
            return True

        # Try pairing each unused element in arr1 with each unused element in arr2
        for i in range(len(arr1)):
            if used1[i]:
