                if (arr1[i] + arr2[j]) % k == 0:
                    used1[i] = True
                    used2[j] = True
                    result.append([arr1[i], arr2[j]])
                    if backtrack():
                        return True
                    # Backtrack
                    result.pop()
                    used1[i] = False
                    used2[j] = False
        return False

    if backtrack():
        return result
    else:
        return None

