def perfect_squares(n):
    if n == 0:
        return 0

    # Precompute perfect squares less than or equal to n
    max_square = int(n**0.5)
    squares = [i*i for i in range(1, max_square + 1)]

    # Initialize dp array with large values
    dp = [float('inf')] * (n + 1)
    dp[0] = 0  # Base case: 0 requires 0 perfect squares

    # Fill dp array
    for i in range(1, n + 1):
        for s in squares:
            if i >= s:
                dp[i] = min(dp[i], dp[i - s] + 1)

    return dp[n]

def find_triplet(arr, target):
    arr.sort()
    n = len(arr)

    for i in range(n - 2):
        left = i + 1
        right = n - 1

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return False

