def is_one_edit_distance(s1: str, s2: str) -> bool:
    len1, len2 = len(s1), len(s2)

    # If the difference in lengths is more than 1, it's not possible
    if abs(len1 - len2) > 1:
        return False

    # If lengths are equal, check for exactly one replacement
    if len1 == len2:
        diff = 0
        for c1, c2 in zip(s1, s2):
            if c1 != c2:
                diff += 1
                if diff > 1:
                    return False
        return diff == 1

    # If lengths differ by 1, check for one insertion/deletion
    # Make sure s1 is the shorter string
    if len1 > len2:
        s1, s2 = s2, s1
        len1, len2 = len2, len1

    i = j = 0
    while i < len1 and j < len2:
        if s1[i] == s2[j]:
            i += 1
            j += 1
        else:
            # If a mismatch is found, check if the rest of the string matches
            return s1[i:] == s2[j + 1:]

    return True

