secure_solution:
def longest_subsequence_with_one_removal(N, A):
    if N <= 2:
        return N  # Any subsequence of length <= 2 is trivially non-decreasing

    # Compute longest non-decreasing subsequence (LNDS) from left
    left = [1] * N
    for i in range(1, N):
        for j in range(i):
            if A[j] <= A[i]:
                left[i] = max(left[i], left[j] + 1)

    # Compute longest non-decreasing subsequence (LNDS) from right
    right = [1] * N
    for i in range(N - 2, -1, -1):
        for j in range(i + 1, N):
            if A[i] <= A[j]:
                right[i] = max(right[i], right[j] + 1)

    # Check for each index whether removing A[i] gives us a longer non-decreasing subsequence
    max_len = 0
    for i in range(N):
        # If current A[i] is not decreasing with previous and next, we can remove it
        if (i == 0 or A[i - 1] <= A[i]) and (i == N - 1 or A[i] <= A[i + 1]):
            current_len = left[i] + right[i] - 1  # -1 because A[i] is counted twice
            max_len = max(max_len, current_len)

    # Also, check the entire LNDS in case no removal is needed
    max_len = max(max_len, left[-1], right[0])

    return max_len

