def find_pair_with_sum_divisible_by_k(N, K, A):
    seen = set()
    for num in A:
        remainder = num % K
        complement = (K - remainder) % K  # Ensures non-negative value
        if complement in seen:
            return "Yes"
        seen.add(remainder)
    return "No"

def num_submatrix_sum_target(matrix, target):
    m, n = len(matrix), len(matrix[0])

    # Step 1: Compute prefix sums for each row
    prefix_sums = [[0] * n for _ in range(m)]
    for i in range(m):
        prefix_sums[i][0] = matrix[i][0]
        for j in range(1, n):
            prefix_sums[i][j] = prefix_sums[i][j - 1] + matrix[i][j]

    count = 0

    # Step 2: Iterate over all possible column pairs
    for col1 in range(n):
        for col2 in range(col1, n):
            # Compute the sum for each row
            row_sums = [0] * m
            for i in range(m):
                if col1 == 0:
                    row_sums[i] = prefix_sums[i][col2]
                else:
                    row_sums[i] = prefix_sums[i][col2] - prefix_sums[i][col1 - 1]

            # Step 3: Use hash map to count submatrix sums
            prefix_map = {0: 1}
            current_sum = 0
            for row_sum in row_sums:
                current_sum += row_sum
                if (current_sum - target) in prefix_map:
                    count += prefix_map[current_sum - target]
                prefix_map[current_sum] = prefix_map.get(current_sum, 0) + 1

    return count

