def find_subarray_with_minimum_maximum_element(arr, k):
    n = len(arr)
    max_deque = deque()
    min_max = float('inf')
    result_start = 0

    for i in range(n):
        # Remove indices that are out of the current window
        while max_deque and max_deque[0] < i - k + 1:
            max_deque.popleft()

        # Remove elements that are less than the current element
        while max_deque and arr[max_deque[-1]] <= arr[i]:
            max_deque.pop()

        max_deque.append(i)

        # Once we have processed at least k elements
        if i >= k - 1:
            current_max = arr[max_deque[0]]
            # Update if we found a smaller max
            if current_max < min_max:
                min_max = current_max
                result_start = i - k + 1

    # Convert to 1-based indexing
    return (result_start + 1, result_start + k)

