def int_divide(n: int) -> int:
    # Initialize a 2D DP table with (n+1) rows and (n+1) columns
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: There's one way to partition 0 (using zero parts)
    for j in range(n + 1):
        dp[0][j] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            # Case 1: do not use j as part of the partition
            dp[i][j] = dp[i][j - 1]
            # Case 2: use j as part of the partition (only if i >= j)
            if i >= j:
                dp[i][j] += dp[i - j][j]

    return dp[n][n]

