def count_cookie_arrangements(N):
    MOD = 10**9 + 7
    if N == 0:
        return 0
    if N == 1:
        return 2

    a, b = 1, 1  # a[1], b[1]
    for _ in range(2, N + 1):
        new_a = (a + b) % MOD
        new_b = a % MOD
        a, b = new_a, new_b

    return (a + b) % MOD

