from typing import List

def max_contiguous_subsequence_sum(arr: List[int]) -> int:
    if not arr:
        return 0

    max_current = max_global = arr[0]

    for num in arr[1:]:
        max_current = max(num, max_current + num)
        max_global = max(max_global, max_current)

    return max_global

