from collections import deque

def min_hours_to_ripe_all(grid):
    n = len(grid)
    visited = [[False] * n for _ in range(n)]
    queue = deque()

    # Initialize the queue with all initially ripe crops
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                visited[i][j] = True
                queue.append((i, j))

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    hours = 0
    count = 0  # Number of cells processed

    while queue:
        for _ in range(len(queue)):  # Process all nodes at the current level
            x, y = queue.popleft()
            count += 1
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                    visited[nx][ny] = True
                    queue.append((nx, ny))
        if queue:
            hours += 1

    if count == n * n:
        return hours
    else:
        return -1

