def min_swaps_to_sort(arr):
    # Create a sorted version of the array
    sorted_arr = sorted(arr)

    # Map each value to its index in the sorted array
    # Use a dictionary that maps values to their sorted indices
    value_to_index = {}
    for idx, val in enumerate(sorted_arr):
        if val not in value_to_index:
            value_to_index[val] = idx

    # Build the permutation of indices
    n = len(arr)
    perm = [value_to_index[val] for val in arr]

    # Track visited elements to avoid reprocessing
    visited = [False] * n
    swaps = 0

    for i in range(n):
        if not visited[i]:
            cycle_size = 0
            j = i
            while not visited[j]:
                visited[j] = True
                j = perm[j]
                cycle_size += 1
            if cycle_size > 0:
                swaps += (cycle_size - 1)

    return swaps

