def can_form_palindrome(s):
    """
    Determines if the characters in the string can be rearranged to form a palindrome.

    A string can form a palindrome if at most one character has an odd frequency.
    """
    char_count = {}
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1
            if odd_count > 1:
                return False

    return True

