def maximum_total_cost(n, m, grid):
    # Initialize a DP table of size n x m
    dp = [[0] * m for _ in range(n)]

    # Starting point
    dp[0][0] = grid[0][0]

    # Fill the first row
    for j in range(1, m):
        dp[0][j] = dp[0][j - 1] + grid[0][j]

    # Fill the first column
    for i in range(1, n):
        dp[i][0] = dp[i - 1][0] + grid[i][0]

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + grid[i][j]

    return dp[n - 1][m - 1]

