secure_solution:
def calculate_rewards(S, T1, T2, R1, R2, R3):
    if S <= 0:
        return 0

    reward = 0

    # First segment: up to T1
    if S <= T1:
        reward += S * R1
    else:
        reward += T1 * R1
        remaining = S - T1

        # Second segment: between T1 and T2
        if remaining <= T2 - T1:
            reward += remaining * R2
        else:
            reward += (T2 - T1) * R2
            remaining = S - T2

            # Third segment: beyond T2
            reward += remaining * R3

    return reward

