def find_passenger_with_highest_points(t, transactions):
    # Dictionary to keep track of each passenger's total points
    passenger_points = {}
    # Dictionary to keep track of the first occurrence of each passenger's highest points
    first_occurrence = {}

    for transaction in transactions:
        name, change = transaction
        change = int(change)

        # Update the passenger's current points
        if name in passenger_points:
            passenger_points[name] += change
        else:
            passenger_points[name] = change

        # Check if this passenger's current points are the highest so far
        current_max = max(passenger_points.values())
        if passenger_points[name] == current_max:
            # If this is the first time this passenger achieved this max, record the time
            if name not in first_occurrence:
                first_occurrence[name] = len(passenger_points)  # This represents the order of occurrence

    # Find the passenger with the highest points, and in case of tie, the one who reached it first
    max_points = max(passenger_points.values())
    candidates = [name for name, points in passenger_points.items() if points == max_points]

    # Return the candidate who reached max points first
    return min(candidates, key=lambda x: first_occurrence[x])

