from typing import List

def maximum_rent(rent_values: List[int]) -> int:
    if not rent_values:
        return 0
    if len(rent_values) == 1:
        return rent_values[0]

    # Initialize previous two maximum rents
    prev_prev = rent_values[0]
    prev = max(rent_values[0], rent_values[1])

    for i in range(2, len(rent_values)):
        current = max(prev, prev_prev + rent_values[i])
        prev_prev, prev = prev, current

    return prev

