def largest_rectangle_area(arr):
    if not arr:
        return 0

    stack = []  # This stack will store indices
    max_area = 0
    n = len(arr)

    for i in range(n):
        while stack and arr[i] < arr[stack[-1]]:
            height = arr[stack.pop()]
            if not stack:
                width = i
            else:
                width = i - stack[-1] - 1
            max_area = max(max_area, height * width)
        stack.append(i)

    # After all bars are processed, pop remaining bars from stack
    while stack:
        height = arr[stack.pop()]
        if not stack:
            width = n
        else:
            width = n - stack[-1] - 1
        max_area = max(max_area, height * width)

    return max_area

