def max_flowers(n, m, grid):
    # Initialize dp with the same size as grid
    dp = [[0] * m for _ in range(n)]

    # Starting cell
    dp[0][0] = grid[0][0]

    # Fill first row
    for j in range(1, m):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill first column
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill rest of the dp table
    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = grid[i][j] + max(dp[i-1][j], dp[i][j-1])

    return dp[n-1][m-1]

