def min_clusters(n, k, deliveries):
    if any(d > k for d in deliveries):
        return -1

    clusters = 0
    current_sum = 0

    for delivery in deliveries:
        if current_sum + delivery > k:
            clusters += 1
            current_sum = delivery
        else:
            current_sum += delivery

    # Account for the last cluster
    if current_sum > 0:
