def min_bracket_move(s: str) -> int:
    balance = 0
    moves = 0

    for char in s:
        if char == '(':
            balance += 1
        else:
            balance -= 1

        # If balance is negative, we need an opening bracket
        if balance < 0:
            moves += 1
            balance += 1  # This is the added '('

    # After processing the string, any positive balance means we need closing brackets
    moves += balance

    return moves

