from itertools import combinations

def max_performance(skills: List[int]) -> Tuple[int, int]:
    # Sort the skills in descending order to easily find the top 3 values
    skills.sort(reverse=True)

    # Calculate the maximum performance score
    max_score = sum(skills[:3])

    # Count how many distinct teams have this max score
    count = 0
    for team in combinations(skills, 3):
        if sum(team) == max_score:
            count += 1

    return (max_score, count)

