from typing import List

def findLongestConsecutiveSubsequence(numbers: List[int]) -> int:
    if not numbers:
        return 0

    unique_numbers = set(numbers)
    sorted_unique = sorted(unique_numbers)

    max_length = 1
    current_length = 1

    for i in range(1, len(sorted_unique)):
        if sorted_unique[i] == sorted_unique[i - 1] + 1:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

