def fast_modular_exponentiation(base: int, exponent: int, modulus: int) -> int:
    if modulus == 1:
        return 0  # Everything modulo 1 is 0

    # Handle the case where exponent is 0
    if exponent == 0:
        return 1 % modulus

    # Ensure we handle negative exponents by raising an error
    if exponent < 0:
        raise ValueError("Exponent must be non-negative for this implementation.")

    result = 1
    base = base % modulus  # Reduce base modulo modulus first

    while exponent > 0:
        # If exponent is odd, multiply the result by the current base
        if exponent % 2 == 1:
            result = (result * base) % modulus

        # Square the base and halve the exponent
        base = (base * base) % modulus
        exponent = exponent // 2

    return result

