def lexicographically_smallest_string(text):
    # Initialize the result with the original string
    result = list(text)

    # Iterate through the string to find the best character to remove
    for i in range(len(text) - 1):
        # If the current character is greater than the next one, remove the current character
        if text[i] > text[i + 1]:
            # Remove the current character and break
            result.pop(i)
            break

    # If we didn't break, the string is non-decreasing, so remove the last character
    else:
        result.pop()

    return ''.join(result)

