def minimum_moves(eggs: int, floors: int) -> int:
    # Initialize a 2D DP table
    dp = [[0] * (floors + 1) for _ in range(eggs + 1)]

    # Fill base cases
    for e in range(eggs + 1):
        dp[e][0] = 0  # 0 floors, no moves needed

    for f in range(1, floors + 1):
        dp[1][f] = f  # 1 egg: need to check every floor

    # Fill the DP table for more than 1 egg
    for e in range(2, eggs + 1):
        for f in range(1, floors + 1):
            dp[e][f] = float('inf')
            for k in range(1, f + 1):
                dp[e][f] = min(dp[e][f], 1 + max(dp[e - 1][k - 1], dp[e][f - k]))

    return dp[eggs][floors]

