from collections import deque

def min_steps_to_reach(grid):
    m, n = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Find all teleporters
    teleporters = []
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2:
                teleporters.append((i, j))

    visited = set()
    queue = deque()

    # Start from top-left corner
    if grid[0][0] != 1:
        queue.append((0, 0, 0))  # (row, col, steps)
        visited.add((0, 0))

    while queue:
        r, c, steps = queue.popleft()

        # If we reached bottom-right corner
        if r == m - 1 and c == n - 1:
            return steps

        # Move in 4 directions
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in visited:
                if grid[nr][nc] != 1:
                    visited.add((nr, nc))
                    queue.append((nr, nc, steps + 1))

        # If we are on a teleporter, teleport to all other teleporters
        if grid[r][c] == 2:
            for tr, tc in teleporters:
                if (tr, tc) not in visited:
                    visited.add((tr, tc))
                    queue.append((tr, tc, steps + 1))

    return -1

