from typing import List

def min_removals_to_non_decreasing(heights: List[int]) -> int:
    n = len(heights)
    if n == 0:
        return 0

    # dp[i] = length of the longest non-decreasing subsequence ending at index i
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            if heights[j] <= heights[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    # Length of the longest non-decreasing subsequence
    max_length = max(dp)

    # Minimum number of removals = total students - longest non-decreasing subsequence
    return n - max_length

def unique_paths_with_obstacles(grid):
    m = len(grid)
    n = len(grid[0])

    # Initialize a DP table with the same dimensions as grid
    dp = [[0 for _ in range(n)] for _ in range(m)]

    # Start point is blocked
    if grid[0][0] == -1:
        return 0

    # First row: can only come from the left
    for i in range(n):
        if grid[0][i] == -1:
            break
        dp[0][i] = 1

    # First column: can only come from above
    for i in range(m):
        if grid[i][0] == -1:
            break
        dp[i][0] = 1

    # Fill the DP table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == -1:
