def convert_grayscale_to_ascii(pixels, width, height):
    # Define the mapping from pixel values to symbols
    symbol_map = {
        range(0, 64): '.',
        range(64, 128): '+',
        range(128, 192): '@',
        range(192, 256): '#'
    }

    # Create the ASCII image
    ascii_image = []
    for row in range(height):
        start = row * width
        end = start + width
        row_pixels = pixels[start:end]

        # Map each pixel to its corresponding symbol
        row_symbols = []
        for pixel in row_pixels:
            for range_key, symbol in symbol_map.items():
                if pixel in range_key:
                    row_symbols.append(symbol)
                    break

        # Join with space separators
        ascii_image.append(' '.join(row_symbols))

    # Join rows with newlines
    return '\n'.join(ascii_image)

