def longest_subarray_with_sum_k(nums, k):
    prefix_sum = 0
    sum_indices = {0: -1}  # To handle cases where subarray starts from index 0
    max_length = 0

    for i, num in enumerate(nums):
        prefix_sum += num

        # Check if we have seen (prefix_sum - k) before
        if (prefix_sum - k) in sum_indices:
            max_length = max(max_length, i - sum_indices[prefix_sum - k])

        # Store the first occurrence of prefix_sum
        if prefix_sum not in sum_indices:
            sum_indices[prefix_sum] = i

    return max_length

