def max_gift_bags(costs_list, budget):
    if not costs_list or budget <= 0:
        return 0

    # Sort the costs in ascending order
    costs_list.sort()

    count = 0
    remaining_budget = budget

    for cost in costs_list:
        if remaining_budget >= cost:
            # Use as many of this item as possible
            count += remaining_budget // cost
            remaining_budget %= cost
        else:
            # Cannot use this item
            break

    return count

