def max_coins_value(n, C, coin_values):
    # Initialize a DP array where dp[i] represents the maximum value that can be achieved with a capacity of i
    dp = [0] * (C + 1)

    # Iterate through each coin
    for value in coin_values:
        # Traverse the DP array from C down to value to avoid reusing the same coin
        for capacity in range(C, value - 1, -1):
            dp[capacity] = max(dp[capacity], dp[capacity - value] + value)

    # The maximum value that can be achieved without exceeding the capacity C
    return dp[C]

