def stack_sequence_operations(operations: str) -> list:
    stack = []
    result = []
    ops = operations.split()

    i = 0
    while i < len(ops):
        if ops[i] == "PUSH":
            # Ensure that the next item is a valid integer
            if i + 1 < len(ops):
                try:
                    value = int(ops[i + 1])
                    stack.append(value)
                    i += 2
                except ValueError:
                    # Invalid value after PUSH, though per problem statement this should not happen
                    i += 1
            else:
                i += 1
        elif ops[i] == "POP":
            if stack:
                stack.pop()
            else:
                result.append(-1)
            i += 1
        elif ops[i] == "TOP":
            if stack:
                result.append(stack[-1])
            else:
                result.append(-1)
            i += 1
        else:
            # Invalid operation, though per problem statement this should not happen
            i += 1

    return result

