from collections import deque

def min_time_to_reach_end(heights, k):
    n = len(heights)
    if n == 0:
        return -1

    visited = [[False] * (k + 1) for _ in range(n)]  # [position][remaining_jumps]
    queue = deque([(0, 0, k)])  # (position, time, remaining_jumps)

    while queue:
        i, time, jumps = queue.popleft()

        if i == n - 1:
            return time

        # Move right to i+1 if possible
        if i + 1 < n and heights[i + 1] <= heights[i]:
            if not visited[i + 1][jumps]:
                visited[i + 1][jumps] = True
                queue.append((i + 1, time + 1, jumps))

        # Jump to any position in [i - k, i + k] if possible
        for j in range(max(0, i - k), min(n - 1, i + k) + 1):
            if j == i:
                continue  # already at current position
            if heights[j] <= heights[i]:
                if not visited[j][jumps - 1]:
                    visited[j][jumps - 1] = True
                    queue.append((j, time + 1, jumps - 1))

    return -1

