def integer_partitions(n: int) -> int:
    # Initialize a 2D list to store the number of partitions
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: There is one way to partition 0 (using no numbers)
    for j in range(n + 1):
        dp[0][j] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i >= j:
                dp[i][j] = dp[i][j - 1] + dp[i - j][j]
            else:
                dp[i][j] = dp[i][j - 1]

    return dp[n][n]

