secure_solution:
def can_split_array(arr):
    total_sum = sum(arr)

    # If total sum is odd, it's impossible to split into two equal parts
    if total_sum % 2 != 0:
        return "NO"

    target = total_sum // 2
    current_sum = 0

    for num in arr:
        current_sum += num
        if current_sum == target:
            return "YES"
        # Early exit if current_sum exceeds half of total_sum
        elif current_sum > target:
            break

    return "NO"

