secure_solution:
def rob(nums, k):
    n = len(nums)
    if n == 0:
        return 0

    dp = [0] * n
    dp[0] = nums[0]

    for i in range(1, n):
        # Option 1: Skip the current house
        option1 = dp[i - 1]
        # Option 2: Rob the current house (if previous k houses are skipped)
        if i - k - 1 >= 0:
            option2 = nums[i] + dp[i - k - 1]
        else:
            option2 = nums[i]  # if i - k - 1 < 0, we can take nums[i] directly
        dp[i] = max(option1, option2)

    return dp[-1]

