def LongestSubstringWithKDistinct(s: str, k: int) -> tuple:
    if k == 0:
        return ("", 0)

    n = len(s)
    left = 0
    max_length = 0
    start = 0
    char_map = {}

    for right in range(n):
        # Add the current character to the map
        char_map[s[right]] = char_map.get(s[right], 0) + 1

        # If the number of distinct characters exceeds k, shrink the window from the left
        while len(char_map) > k:
            char_map[s[left]] -= 1
            if char_map[s[left]] == 0:
                del char_map[s[left]]
            left += 1

        # Update the maximum length and starting index of the longest substring found so far
        if right - left + 1 > max_length:
            max_length = right - left + 1
            start = left

    return (s[start:start + max_length], max_length)

