def find_overall_winner(m, p, race_results):
    # Initialize a dictionary to track each participant's total score and their best individual position
    participants = {i: {'score': 0, 'best_position': 0} for i in range(1, p + 1)}

    # Process each race result
    for race in race_results:
        # For each position in the race, assign points to the participant
        for position, participant in enumerate(race, start=1):
            participants[participant]['score'] += position
            # Update best position if this is the highest so far (note: lower position number is better)
            if position < participants[participant]['best_position'] or participants[participant]['best_position'] == 0:
                participants[participant]['best_position'] = position

    # Find the participant with the lowest total score
    winner = min(participants.items(), key=lambda x: (x[1]['score'], -x[1]['best_position']))

