def max_noodle_pairs(lengths, m):
    lengths.sort()
    count = 0
    left, right = 0, len(lengths) - 1

    while left < right:
        if lengths[left] + lengths[right] >= m:
            count += 1
            left += 1
            right -= 1
        else:
            left += 1

    return count

