from typing import List

def min_partition_difference(nums: List[int]) -> List[int]:
    total_sum = sum(nums)
    target = total_sum // 2  # We try to get as close to half the total sum as possible

    # Create a boolean DP array where dp[i] is True if a subset with sum i can be formed
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum of 0 can always be formed

    for num in nums:
        for i in range(target, num - 1, -1):
            if dp[i - num]:
                dp[i] = True

    # Find the largest sum <= target that can be formed
    max_subset_sum = 0
    for i in range(target, -1, -1):
        if dp[i]:
            max_subset_sum = i
            break

    # The other subset sum is total_sum - max_subset_sum
    return [max_subset_sum, total_sum - max_subset_sum]

