def shortest_subarray_to_sort(arr):
    n = len(arr)
    if n <= 1:
        return 0

    # Step 1: Find the first index where the order breaks
    start = 0
    while start < n - 1 and arr[start] <= arr[start + 1]:
        start += 1
    if start == n - 1:
        return 0  # Array is already sorted

    # Step 2: Find the last index where the order breaks
    end = n - 1
    while end > 0 and arr[end] >= arr[end - 1]:
        end -= 1

    # Step 3: Find min and max in the unsorted subarray
    min_sub = min(arr[start:end + 1])
    max_sub = max(arr[start:end + 1])

    # Step 4: Expand the subarray to include out-of-order elements
    while start > 0 and arr[start - 1] > min_sub:
        start -= 1
    while end < n - 1 and arr[end + 1] < max_sub:
        end += 1

    return end - start + 1

