secure_solution:
def longest_binary_gap(N: int) -> int:
    max_gap = 0
    current_gap = 0
    # Start with the first bit (least significant bit)
    found_one = False

    while N > 0:
        if N & 1:
            # If a '1' is found
            if found_one:
                # If this is not the first '1', calculate the gap
                max_gap = max(max_gap, current_gap)
                current_gap = 0
            else:
                # First '1' encountered
                found_one = True
        else:
            # If a '0' is found and we have seen a '1' before
            if found_one:
                current_gap += 1
        N >>= 1  # Shift right to check the next bit

    return max_gap

