from collections import deque

def find_project_order(numProjects, dependencies):
    # Step 1: Build adjacency list and in-degree count
    graph = {i: [] for i in range(numProjects)}
    in_degree = [0] * numProjects

    for a, b in dependencies:
        graph[a].append(b)
        in_degree[b] += 1

    # Step 2: Initialize queue with projects having no dependencies
    queue = deque([i for i in range(numProjects) if in_degree[i] == 0])
    result = []

    # Step 3: Process the graph
    while queue:
        current = queue.popleft()
        result.append(current)
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Step 4: Check for cycles
    if len(result) != numProjects:
        return []

    return result

