from typing import List

def can_partition(weights: List[int]) -> bool:
    total_sum = sum(weights)

    # If total sum is odd, partition is not possible
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    dp = set()
    dp.add(0)

    for weight in weights:
        new_sums = set()
        for s in dp:
            new_sum = s + weight
            if new_sum <= target:
                new_sums.add(new_sum)
        dp.update(new_sums)

        # Early exit if we can reach the target sum
        if target in dp:
            return True

    return target in dp

