def max_coins(n, m, grid):
    # Initialize DP table
    dp = [[0] * m for _ in range(n)]

    # Base case: the first row
    for j in range(m):
        dp[0][j] = grid[0][j]

    # Fill the DP table
    for i in range(1, n):
        for j in range(m):
            max_prev = dp[i - 1][j]  # Directly above
            if j > 0:
                max_prev = max(max_prev, dp[i - 1][j - 1])  # Left above
            if j < m - 1:
                max_prev = max(max_prev, dp[i - 1][j + 1])  # Right above
            dp[i][j] = grid[i][j] + max_prev

    # The answer is the maximum value in the last row
    return max(dp[n - 1])

