def remove_duplicate_letters(s):
    last_occurrence = {c: i for i, c in enumerate(s)}
    stack = []
    seen = set()

    for i, c in enumerate(s):
        if c in seen:
            continue
        while stack and c < stack[-1] and last_occurrence[stack[-1]] > i:
            removed = stack.pop()
            seen.remove(removed)
        stack.append(c)
        seen.add(c)

    return ''.join(stack)

