def unique_paths_with_obstacles(grid):
    m = len(grid)
    n = len(grid[0]) if m > 0 else 0

    # Initialize a DP table with the same dimensions as the grid
    dp = [[0 for _ in range(n)] for _ in range(m)]

    # Start point: if it's an obstacle, return 0
    if grid[0][0] == 1:
        return 0

    # First row and first column
    for i in range(m):
        if grid[i][0] == 1:
            break
        dp[i][0] = 1

    for j in range(n):
        if grid[0][j] == 1:
            break
        dp[0][j] = 1

    # Fill the DP table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

