def longest_mountain(arr):
    n = len(arr)
    if n < 3:
        return 0

    up = [0] * n
    down = [0] * n

    # Count up slopes
    for i in range(1, n):
        if arr[i] > arr[i - 1]:
            up[i] = up[i - 1] + 1
        else:
            up[i] = 0

    # Count down slopes
    for i in range(n - 2, -1, -1):
        if arr[i] > arr[i + 1]:
            down[i] = down[i + 1] + 1
        else:
            down[i] = 0

    # Calculate the longest mountain
    max_length = 0
    for i in range(n):
        if up[i] > 0 and down[i] > 0:
            max_length = max(max_length, up[i] + down[i] + 1)

    return max_length

