def min_cost_to_adjust_trees(n, A, B, heights):
    # We will use a DP table where dp[i][h] is the minimum cost to adjust the first i trees
    # such that the i-th tree has height h.
    # Since the heights can be between 0 and 100 + n (worst case), we define a suitable range.
    max_height = max(heights) + n  # A little buffer
    dp = [[float('inf')] * (max_height + 1) for _ in range(n)]

    # Initialize the first tree
    for h in range(max_height + 1):
        cost = abs(h - heights[0]) * A if h >= heights[0] else abs(h - heights[0]) * B
        dp[0][h] = cost

    for i in range(1, n):
        for prev_h in range(max_height + 1):
            for curr_h in range(max_height + 1):
                if curr_h == prev_h:
                    continue  # Skip the same height as the previous tree
                cost = abs(curr_h - heights[i]) * A if curr_h >= heights[i] else abs(curr_h - heights[i]) * B
                dp[i][curr_h] = min(dp[i][curr_h], dp[i - 1][prev_h] + cost)

    # The answer is the minimum value in the last row of the DP table
    return min(dp[n - 1])

