def largest_square_same_height(grid):
    if not grid or not grid[0]:
        return 0

    n, m = len(grid), len(grid[0])
    dp = [[1] * m for _ in range(n)]
    max_size = 1  # At least 1x1 square is possible

    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == grid[i-1][j] == grid[i][j-1] == grid[i-1][j-1]:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_size = max(max_size, dp[i][j])
            else:
                # If heights are not equal, we can't form a square, so set to 1 if all current cell is same
                # and only check if current cell is same as top, left and top-left
                if grid[i][j] == grid[i-1][j] and grid[i][j] == grid[i][j-1] and grid[i][j] == grid[i-1][j-1]:
                    dp[i][j] = 2
                    max_size = max(max_size, 2)
                else:
