def max_weight_with_two_trucks(n, total_weight, capacities):
    capacities.sort()
    max_weight = 0
    left = 0
    right = n - 1

    while left < right:
        current_sum = capacities[left] + capacities[right]
        if current_sum <= total_weight:
            max_weight = max(max_weight, current_sum)
            left += 1
        else:
            right -= 1

    return max_weight

