def is_valid_extended(s: str) -> bool:
    # Dictionary to map closing brackets to their corresponding opening brackets
    bracket_map = {')': '(', '}': '{', ']': '['}

    # Stack to keep track of opening brackets
    stack = []

    for char in s:
        if char in bracket_map:
            # If there's a closing bracket, check if there's a matching opening bracket in the stack
            if stack and stack[-1] == bracket_map[char]:
                stack.pop()
            else:
                return False
        elif char in bracket_map.values():
            # If it's an opening bracket, push it onto the stack
            stack.append(char)

    # After processing the string, the stack should be empty if all brackets are properly closed
    return not stack

