def longest_subsequence(n, k, arr):
    dp = {}
    max_length = 0

    for num in arr:
        # The longest subsequence ending at num is 1 (just num itself)
        # Or it's the length ending at (num - k) + 1
        prev_length = dp.get(num - k, 0)
        dp[num] = prev_length + 1
        max_length = max(max_length, dp[num])

    return max_length

