def search_in_a_sorted_matrix(mat: List[List[int]], key: int) -> Tuple[int, int]:
    if not mat or not mat[0]:
        return (-1, -1)

    rows, cols = len(mat), len(mat[0])
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        current = mat[row][col]
        if current == key:
            return (row + 1, col + 1)  # Convert to 1-based indexing
        elif current > key:
            col -= 1  # Move left
        else:
            row += 1  # Move down

    return (-1, -1)

