def find_shortest_word(paragraph):
    # Split the paragraph into words, using split() which handles multiple spaces
    words = paragraph.split()

    # Initialize the shortest word as the first word
    shortest_word = words[0]

    # Iterate through the words to find the shortest one
    for word in words[1:]:
        if len(word) < len(shortest_word):
            shortest_word = word

    return shortest_word

