def max_rectangle_area(heights: list[int]) -> int:
    """Returns the maximum area of the rectangle that can be formed between two heights in the given array."""
    if len(heights) < 2:
        return 0

    max_area = 0
    left, right = 0, len(heights) - 1

    while left < right:
        height = min(heights[left], heights[right])
        width = right - left
        max_area = max(max_area, height * width)

        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1

    return max_area

