secure_solution:
def count_partitions(n):
    # dp[i][j] = number of ways to partition i using integers up to j
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: There's 1 way to partition 0
    for j in range(n + 1):
        dp[0][j] = 1

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            # If j > i, we can't use j to form i, so copy the value from j-1
            if j > i:
                dp[i][j] = dp[i][j-1]
            else:
                # Otherwise, include partitions that include j and those that exclude j
                dp[i][j] = dp[i][j-1] + dp[i-j][j]

    return dp[n][n]

