def balance_parentheses(lst: List[str]) -> List[int]:
    result = []
    for s in lst:
        open_count = 0
        imbalance = 0
        for char in s:
            if char == '(':
                open_count += 1
            elif char == ')':
                if open_count > 0:
                    open_count -= 1
                else:
                    imbalance += 1
        # Add the remaining unmatched open parentheses
        imbalance += open_count
        result.append(imbalance)
    return result

