def find_optimal_gas_station_location(nums):
    if not nums:
        return 0.0  # or any default value if nums is empty

    max_gap = 0
    best_gap_start = nums[0]

    for i in range(1, len(nums)):
        gap = nums[i] - nums[i - 1]
        if gap > max_gap:
            max_gap = gap
            best_gap_start = nums[i - 1]

    # Place the station at the midpoint of the largest gap
    optimal_position = best_gap_start + max_gap / 2
    return optimal_position

