def find_three_sum(arr, target):
    # Sort the array
    arr.sort()

    # Iterate through each element as the first element of the triplet
    for i in range(len(arr) - 2):
        # Use two-pointer approach for the remaining part of the array
        left = i + 1
        right = len(arr) - 1

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]

            if current_sum == target:
                # Return the triplet as a tuple
                return (arr[i], arr[left], arr[right])
            elif current_sum < target:
                # Move the left pointer to the right to increase the sum
                left += 1
            else:
                # Move the right pointer to the left to decrease the sum
                right -= 1

    # If no triplet is found, return None
    return None

