def find_cheapest_price(n, flights, src, dst, k):
    # Initialize cost array
    cost = [float('inf')] * n
    cost[src] = 0

    # Bellman-Ford with restriction on number of stops
    for i in range(k + 1):
        temp_cost = cost.copy()
        updated = False

        for u, v, w in flights:
            if cost[u] != float('inf') and cost[u] + w < temp_cost[v]:
                temp_cost[v] = cost[u] + w
                updated = True

        if not updated:
            break  # No more updates, can exit early

        cost = temp_cost

    return cost[dst] if cost[dst] != float('inf') else -1

