secure_solution:
def integer_decomposition(n: int) -> int:
    # Initialize a 2D DP table with (n+1) rows and (n+1) columns
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: there is exactly 1 way to partition 0
    for j in range(n + 1):
        dp[0][j] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            # If the current number is less than j, we are not using j in the partition
            if i < j:
                dp[i][j] = dp[i][j - 1]
            else:
                # If it is >= j, we can use j in the partition
                dp[i][j] = dp[i][j - 1] + dp[i - j][j]

    # The result is the number of partitions of n using numbers up to n
    return dp[n][n]

