from typing import List

def diagonal_sum(matrix: List[List[int]]) -> int:
    # Input validation
    if not isinstance(matrix, list):
        raise ValueError("Invalid input: matrix must be a list of lists containing integers")

    for row in matrix:
        if not isinstance(row, list) or not all(isinstance(x, int) for x in row):
            raise ValueError("Invalid input: matrix must be a list of lists containing integers")

    n = len(matrix)
    for row in matrix:
        if len(row) != n:
            raise ValueError("Invalid input: matrix must be square")

    # Compute primary and secondary diagonal sums
    primary_sum = 0
    secondary_sum = 0

    for i in range(n):
        primary_sum += matrix[i][i]
        secondary_sum += matrix[i][n - 1 - i]

    # If the matrix has odd dimensions, the center element (common to both diagonals) was counted twice
    if n % 2 == 1:
        # Subtract the center element once from the total sum since it was included twice
        center_value = matrix[n // 2][n // 2]
        total_sum = primary_sum + secondary_sum - center_value
    else:
        total_sum = primary_sum + secondary_sum

    return total_sum

