def largest_subgrid_with_boxes(matrix):
    if not matrix or not matrix[0]:
        return 0

    n, m = len(matrix), len(matrix[0])
    max_area = 0
    heights = [0] * m

    for i in range(n):
        # Update heights for the current row
        for j in range(m):
            if matrix[i][j] == 1:
                heights[j] += 1
            else:
                heights[j] = 0

        # Calculate largest rectangle in histogram for the current row
