def min_abs_sum_diff(nums):
    n = len(nums)
    total_sum = sum(nums)
    min_diff = float('inf')

    # Try all possible non-empty subsets using bitmasking
    for mask in range(1, 1 << n):  # from 1 to 2^n - 1 (exclude empty set)
        subset_sum = 0
        for i in range(n):
            if mask & (1 << i):
                subset_sum += nums[i]
        complement_sum = total_sum - subset_sum
        diff = abs(subset_sum - complement_sum)
        if diff < min_diff:
            min_diff = diff
    return min_diff

