def max_data_transport(n, m, k, portals, s, t):
    # Initialize DP table: dp[jumps][node] = max capacity to reach node with j jumps
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    dp[0][s] = float('inf')  # Starting node has infinite capacity at 0 jumps

    # Build an adjacency list from the portals
    graph = [[] for _ in range(n + 1)]
    for u, v, c in portals:
        graph[u].append((v, c))

    # DP iteration
    for jumps in range(k):
        for u in range(1, n + 1):
            if dp[jumps][u] == 0:
                continue  # No way to reach this node with 'jumps' jumps
            for v, capacity in graph[u]:
                # Min of current capacity and portal capacity
                new_capacity = min(dp[jumps][u], capacity)
                if new_capacity > dp[jumps + 1][v]:
                    dp[jumps + 1][v] = new_capacity

    # The answer is the maximum capacity to reach 't' in at most 'k' jumps
    result = max(dp[i][t] for i in range(k + 1))
    return result if result != 0 else 0  # Return 0 if not reachable

