def combination_iter(n: int, r: int) -> int:
    if r > n or r < 0:
        return 0
    if r == 0 or r == n:
        return 1

    # Initialize a 1D DP array of size r + 1
    dp = [0] * (r + 1)
    dp[0] = 1  # Base case: nC0 = 1

    for i in range(1, n + 1):
        # Traverse from r down to 1 to reuse computed values
        for j in range(min(i, r), 0, -1):
            dp[j] = dp[j] + dp[j - 1]

    return dp[r]

