from typing import List

def max_benefit(B: int, C: List[int], V: List[int]) -> int:
    dp = [0] * (B + 1)

    for i in range(len(C)):
        cost = C[i]
        benefit = V[i]
        for b in range(B, cost - 1, -1):
            dp[b] = max(dp[b], dp[b - cost] + benefit)

    return dp[B]

