def min_operations_deletion(word1: str, word2: str) -> int:
    # Get lengths of the two strings
    m, n = len(word1), len(word2)

    # Create a DP table with (m+1) rows and (n+1) columns
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # LCS length is at dp[m][n]
    lcs_length = dp[m][n]

    # Minimum deletions required
    return (m - lcs_length) + (n - lcs_length)

