    results = []
    for n, a in test_cases:
        max_sum = 0
        for i in range(n):
            # Calculate the sum of a[i] and a[i+1], with wrap-around for the last element
            neighbor = a[(i + 1) % n]
            current_sum = a[i] + neighbor
            if current_sum > max_sum:
                max_sum = current_sum
        results.append(max_sum)
