def hailstone_analysis(n: int) -> (int, int, list):
    sequence = []
    max_value = n
    length = 0

    while n != 1:
        sequence.append(n)
        length += 1

        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1

        if n > max_value:
            max_value = n

    # Append the final 1 to the sequence
    sequence.append(1)
    length += 1

    return (length, max_value, sequence)

