def unique_paths_with_obstacles(n, m, grid):
    # Initialize DP table
    dp = [[0] * m for _ in range(n)]

    # Starting point
    if grid[0][0] == '#':
        return 0
    dp[0][0] = 1

    # Fill the first row
    for j in range(1, m):
        if grid[0][j] == '#':
            break
        dp[0][j] = dp[0][j-1]

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == '#':
            break
        dp[i][0] = dp[i-1][0]

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
