def max_subarray_sum(n, k, heights):
    # Compute prefix sum
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + heights[i]

    max_sum = 0
    for i in range(1, n + 1):
        # Consider subarrays ending at i with lengths from 1 to k
        start = max(0, i - k)
        current_sum = prefix[i] - prefix[start]
        if current_sum > max_sum:
            max_sum = current_sum

    return max_sum

