def find_max_participants(n, m, scores):
    # Initialize a list to store the total points for each participant
    total_points = [0] * n

    # Calculate the total points for each participant
    for i in range(m):
        for j in range(n):
            total_points[j] += scores[i][j]

    # Find the maximum score
    max_score = max(total_points)

    # Find all participants with the max score (1-based index)
    max_participants = [i + 1 for i, score in enumerate(total_points) if score == max_score]

    # Return the sorted list of participant indices
    return sorted(max_participants)

