def find_highest_average(nums: list[int], k: int) -> float:
    if k == 0 or k > len(nums):
        raise ValueError("k must be between 1 and the length of nums")

    # Calculate the sum of the first k elements
    current_sum = sum(nums[:k])
    max_sum = current_sum

    # Slide the window across the array
    for i in range(k, len(nums)):
        current_sum += nums[i] - nums[i - k]
        if current_sum > max_sum:
            max_sum = current_sum

    # Return the average of the maximum sum
    return max_sum / k

def count_distinct_subsequences(s: str, t: str) -> int:
    n, m = len(s), len(t)

    # Initialize a 2D DP table with (n+1) rows and (m+1) columns.
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: empty string 't' can be formed in one way
    for i in range(n + 1):
        dp[i][0] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s[i - 1] == t[j - 1]:
                # Use the current character of s
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                # Do not use the current character of s
                dp[i][j] = dp[i - 1][j]

    return dp[n][m]

