from typing import List

def interpolation_search(array: List[int], search_key: int) -> int:
    """
    Perform interpolation search on a sorted list to find the index of the search_key.

    :param array: List of integers sorted in non-decreasing order.
    :param search_key: An integer value to search for within the array.
    :returns: Index of the search_key if found; otherwise, -1.
    """
    if not array:
        return -1  # Empty array case

    low = 0
    high = len(array) - 1

    while low <= high and array[low] <= search_key <= array[high]:
        # Avoid division by zero
        if array[low] == array[high]:
            if array[low] == search_key:
                return low  # All elements are same and equal to search_key
            else:
                return -1  # All elements are same but not equal to search_key

        # Calculate the probable position using interpolation formula
        pos = low + ((search_key - array[low]) * (high - low)) // (array[high] - array[low])

        # Ensure pos is within the bounds of the array
        pos = max(min(pos, high), low)

        if array[pos] == search_key:
            return pos
        elif array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1  # search_key not found

