def max_candy_robbed(n, candies):
    if n == 0:
        return 0
    prev_prev = 0  # dp[i-2]
    prev = 0       # dp[i-1]

    for candy in candies:
        current = max(prev, prev_prev + candy)
        prev_prev, prev = prev, current

    return prev

