import bisect

def min_students_to_delete(heights):
    # List to store the smallest possible tail of all increasing subsequences
    tails = []

    for height in heights:
        # Find the index where this height can be placed in tails
        # to maintain non-decreasing order
        idx = bisect.bisect_left(tails, height)
        if idx == len(tails):
            # If it's larger than all elements, append it
            tails.append(height)
        else:
            # Otherwise, replace the element at idx with height
            tails[idx] = height

    # The length of the longest non-decreasing subsequence is len(tails)
    return len(heights) - len(tails)

