from typing import List

def findLongestSubarray(arr: List[int]) -> int:
    count_map = {}
    count = 0
    max_length = 0

    for i, num in enumerate(arr):
        # Treat 0 as -1
        count += 1 if num == 1 else -1

        if count == 0:
            # If count is 0, the subarray from start to current index has equal 0s and 1s
            max_length = i + 1
        elif count in count_map:
            # If count has been seen before, calculate subarray length
            max_length = max(max_length, i - count_map[count])
        else:
            # Store the first occurrence of this count
            count_map[count] = i

    return max_length

