def atbash_cipher(s: str) -> str:
    result = []
    for c in s:
        if 'A' <= c <= 'Z':
            # Map uppercase letters
            result.append(chr(90 - (ord(c) - 65)))
        elif 'a' <= c <= 'z':
            # Map lowercase letters
            result.append(chr(122 - (ord(c) - 97)))
        else:
            # Leave other characters unchanged
            result.append(c)
    return ''.join(result)

