secure_solution:
def count(coins, value):
    # If the target value is 0, there is exactly one way to make it (using no coins)
    if value == 0:
        return 1

    # Initialize a dp array where dp[i] will store the number of ways to make amount i
    dp = [0] * (value + 1)
    dp[0] = 1  # Base case: 1 way to make 0

    # Iterate through each coin
    for coin in coins:
        # Update dp for all amounts >= coin
        for i in range(coin, value + 1):
            dp[i] += dp[i - coin]

    return dp[value]

