from collections import deque

def min_time_to_burn_all_cells(n, m, t, starting_points, grid):
    # Convert grid to 0-based indexing
    grid = [list(row) for row in grid]

    # Initialize distance matrix with -1 (unvisited)
    dist = [[-1 for _ in range(m)] for _ in range(n)]

    # Queue for BFS
    q = deque()

    # Convert starting points to 0-based and add to queue
    for x, y in starting_points:
        x -= 1
        y -= 1
        if grid[x][y] == '.':
            dist[x][y] = 0
            q.append((x, y))

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Perform BFS
    while q:
        x, y = q.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                if grid[nx][ny] == '.' and dist[nx][ny] == -1:
                    dist[nx][ny] = dist[x][y] + 1
                    q.append((nx, ny))

    # Check if all empty cells are reachable
    max_time = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and dist[i][j] == -1:
                return -1
            if dist[i][j] > max_time:
                max_time = dist[i][j]

    return max_time

