def smallest_lexicographical_rotation(sequence):
    n = len(sequence)
    min_rotation = sequence[:]  # Start with the original sequence as the minimum

    for i in range(1, n):
        # Generate rotation by i positions to the right
        rotation = sequence[-i:] + sequence[:-i]
        # Compare lexicographically and keep the smallest
        if rotation < min_rotation:
            min_rotation = rotation

    return min_rotation

def optimize_borrowing(borrower_pref: list[list[int]], available_books: list[bool]) -> list[int]:
    n = len(borrower_pref)
    m = len(available_books)
    result = [-1] * n  # -1 indicates the borrower hasn't been assigned a book
    book_availability = available_books.copy()  # Keep track of whether a book is assigned or not

    for borrower_idx, preferences in enumerate(borrower_pref):
        for book_idx in preferences:
            if book_availability[book_idx] and book_idx < len(book_availability):
                result[borrower_idx] = book_idx
                book_availability[book_idx] = False  # Mark book as assigned
                break  # Move to next borrower

    return result

