secure_solution:
def num_of_qualifying_subarrays(scores, k, threshold):
    count = 0
    n = len(scores)

    # Iterate through all possible starting indices of subarrays of length k
    for i in range(n - k + 1):
        subarray = scores[i:i + k]
        average = sum(subarray) / k
        if average >= threshold:
            count += 1

    return count

