def maximum_product_of_three(nums):
    nums.sort()
    # Possible maximum products:
    # 1. Product of three largest numbers
    # 2. Product of two smallest (most negative) and one largest
    return max(
        nums[-1] * nums[-2] * nums[-3],
        nums[0] * nums[1] * nums[-1]
    )

