def subarray_sum_exists(array, target):
    prefix_sum = 0
    sum_indices = {0: -1}  # Initialize with sum 0 at index -1 to handle subarrays starting from index 0

    for index, value in enumerate(array):
        prefix_sum += value
        if (prefix_sum - target) in sum_indices:
