def max_points(m, D, tasks):
    # Initialize dp array where dp[w] is the max points with total difficulty w
    dp = [0] * (D + 1)

    for points, difficulty in tasks:
        # Traverse from high difficulty to low to avoid reusing the same task multiple times
        for w in range(D, difficulty - 1, -1):
            dp[w] = max(dp[w], dp[w - difficulty] + points)

    # The answer is the max points achievable with difficulty <= D
    return max(dp)

