secure_solution:
def find_smallest_suffix(n, types, pattern):
    # Check if the pattern is longer than the types
    if len(pattern) > len(types):
        return "-1"

    # Two pointers to track the current position in pattern and types
    i, j = 0, 0
    # Try to find the pattern as a subsequence in the entire types string
    while i < len(types) and j < len(pattern):
        if types[i] == pattern[j]:
            j += 1
        i += 1

    # If we matched the entire pattern, then the smallest possible suffix is types[i - len(pattern):]
    if j == len(pattern):
        return types[i - len(pattern):]

    # Otherwise, we need to check for every suffix of types
    for start in range(len(types) - len(pattern), -1, -1):
        i, j = 0, 0
        while i < len(types) - start and j < len(pattern):
            if types[start + i] == pattern[j]:
                j += 1
            i += 1
        if j == len(pattern):
            return types[start:]

    return "-1"

