def string_frequency(s, n):
    from collections import defaultdict

    # Count frequency of each character
    freq = defaultdict(int)
    for ch in s:
        freq[ch] += 1

    # Process characters in lexicographical order
    result = []
    for ch in sorted(freq.keys()):
        # Keep only the first n occurrences of ch
        count = 0
        for c in s:
            if c == ch:
                if count < n:
                    result.append(c)
                    count += 1
                else:
                    break  # We've added n occurrences already

    return ''.join(result)

