def filter_products_by_discount(products, min_discount, max_discount):
    # Step 1: Calculate the final price for each product and filter based on discount range
    filtered_products = []
    for product in products:
        discount = product["discount"]
        if min_discount <= discount <= max_discount:
            final_price = product["price"] * (1 - discount / 100)
            filtered_products.append({
                "name": product["name"],
                "final_price": final_price
            })

    # Step 2: Sort the filtered products by their final price in ascending order
    filtered_products.sort(key=lambda x: x["final_price"])

    # Step 3: Extract and return the product names
    return [product["name"] for product in filtered_products]

