def longest_bitonic_subsequence(arr):
    n = len(arr)

    # lis[i] = length of LIS ending at i
    lis = [1] * n

    # Compute LIS values
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # lds[i] = length of LDS starting at i
    lds = [1] * n

    # Compute LDS values
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Calculate the maximum bitonic subsequence length
    max_bitonic_length = 0
    for i in range(n):
        max_bitonic_length = max(max_bitonic_length, lis[i] + lds[i] - 1)

    return max_bitonic_length

