from collections import deque

def min_moves_to_reach(n, grid):
    # Find the starting position 'S'
    start = None
    end = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1  # Invalid grid (missing 'S' or 'E')

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS initialization
    queue = deque()
    queue.append((start[0], start[1], 0))  # (row, col, moves)
    visited = set()
    visited.add((start[0], start[1]))

    while queue:
        row, col, moves = queue.popleft()

        # If we reached the end point 'E'
        if (row, col) == end:
            return moves

        # Explore neighbors
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            # Check if new position is within bounds and not visited, and not an obstacle
            if (0 <= new_row < n and 0 <= new_col < n and
                (new_row, new_col) not in visited and
                grid[new_row][new_col] != '#'):
                visited.add((new_row, new_col))
                queue.append((new_row, new_col, moves + 1))

    # If 'E' is unreachable
    return -1

