from typing import List

def find_unique_elements(nums: List[int]) -> List[int]:
    if not nums:
        return []

    # Step 1: XOR all elements to get the XOR of the two unique elements
    xor_result = 0
    for num in nums:
        xor_result ^= num

    # Step 2: Find an isolated bit (a bit that is set in xor_result)
    # Use the rightmost set bit
    isolated_bit = 1
    while (xor_result & isolated_bit) == 0:
        isolated_bit <<= 1

    # Step 3: Divide the array into two groups and XOR to get the unique elements
    unique1 = 0
    unique2 = 0
    for num in nums:
        if num & isolated_bit:
            unique1 ^= num
        else:
            unique2 ^= num

    return [unique1, unique2]

