def min_difference_subsequence(n, k, a):
    a.sort()  # Sort the array
    min_diff = float('inf')  # Initialize with infinity

    # Use sliding window of size k
    for i in range(n - k + 1):
        current_diff = a[i + k - 1] - a[i]  # Difference between max and min in this window
