def count_paths(grid):
    m = len(grid)
    n = len(grid[0])

    # Initialize a DP table with the same dimensions as the grid
    dp = [[0 for _ in range(n)] for _ in range(m)]

    # The starting cell has 1 path to itself
    dp[0][0] = 1 if grid[0][0] == 1 else 0

    # Fill the first row (can only move right)
    for j in range(1, n):
        if grid[0][j] == 1:
            dp[0][j] = dp[0][j - 1]
        else:
            dp[0][j] = 0  # Obstacle, no path

    # Fill the first column (can only move down)
    for i in range(1, m):
        if grid[i][0] == 1:
            dp[i][0] = dp[i - 1][0]
        else:
            dp[i][0] = 0  # Obstacle, no path

    # Fill the rest of the DP table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 1:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
            else:
                dp[i][j] = 0  # Obstacle, no path

    return dp[m - 1][n - 1]

