def count_unique_strictly_increasing_subsequences(arr, k):
    n = len(arr)
    if k > n or k < 1:
        return 0

    # dp[i][j] will store the number of increasing subsequences of length i ending at index j
    dp = [[0] * n for _ in range(k + 1)]

    # Each single element is a subsequence of length 1
    for j in range(n):
        dp[1][j] = 1

    # Fill dp table
    for i in range(2, k + 1):
        for j in range(n):
            for l in range(j):
                if arr[l] < arr[j]:
                    dp[i][j] += dp[i - 1][l]

    # Sum up all subsequences of length k
    return sum(dp[k])

