def binary_exponentiation(a: int, n: int, mod: int = None) -> int:
    if n == 0:
        return 1 if mod is None else 1 % mod
    if a == 0:
        return 0

    result = 1
    a = a % mod if mod is not None else a

    while n > 0:
        if n % 2 == 1:
