from typing import List

def num_paths(city: List[List[int]]) -> int:
    n = len(city)
    m = len(city[0])

    # Initialize a DP table
    dp = [[0] * m for _ in range(n)]

    # Start at (0,0) if it is not a building
    if city[0][0] == 0:
        dp[0][0] = 1
    else:
        return 0  # Starting point is blocked

    # Fill the first row
    for j in range(1, m):
        if city[0][j] == 0:
            dp[0][j] = dp[0][j-1]
        else:
            break  # Once a building is encountered, all further cells in the row are inaccessible

    # Fill the first column
    for i in range(1, n):
        if city[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            break  # Once a building is encountered, all further cells in the column are inaccessible

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            if city[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Building, so no path through here

    return dp[n-1][m-1]

