from typing import List, Dict, Any
from collections import defaultdict

def aggregate_data(data: List[Dict[str, Any]], group_by: str, aggregate_by: str, operation: str) -> Dict[Any, float]:
    """
    Group the data by a specified key and aggregate the values of another key with a given operation.

    :param data: A list of dictionaries containing the data.
    :param group_by: The key to group by (e.g., "category").
    :param aggregate_by: The key to aggregate by (e.g., "value").
    :param operation: The aggregation operation to perform ("sum", "average", "min", "max").
    :return: A dictionary with the grouped key and the aggregated value.
    """
    if not data:
        return {}

    # Validate that `group_by` and `aggregate_by` exist in all entries
    for entry in data:
        if group_by not in entry:
            raise KeyError(f"Key '{group_by}' not found in one of the data entries.")
        if aggregate_by not in entry:
            raise KeyError(f"Key '{aggregate_by}' not found in one of the data entries.")

    # Validate the operation
    if operation not in ["sum", "average", "min", "max"]:
        raise ValueError(f"Unsupported operation: '{operation}'. Supported operations are 'sum', 'average', 'min', 'max'.")

    # Group the data by the `group_by` key
    grouped_data = defaultdict(list)
    for entry in data:
        key = entry[group_by]
        value = entry[aggregate_by]
        grouped_data[key].append(value)

    # Perform the aggregation based on the operation
    result = {}
    for key, values in grouped_data.items():
        if operation == "sum":
            result[key] = sum(values)
        elif operation == "average":
            result[key] = sum(values) / len(values)
        elif operation == "min":
            result[key] = min(values)
        elif operation == "max":
            result[key] = max(values)

    return result

