import math

def max_product_of_lengths(s, k):
    n = len(s)
    if k > n:
        return -1

    # Distribute n into k parts as evenly as possible
    quotient, remainder = divmod(n, k)
    # The product is (quotient + 1)^remainder * quotient^(k - remainder)
    return (quotient + 1) ** remainder * (quotient) ** (k - remainder)

