from collections import deque

def min_steps_to_traverse(hills):
    n = len(hills)
    if n == 1:
        return 0  # Already at the last hill

    visited = [False] * n
    queue = deque()
    queue.append((0, 0))  # (index, steps)
    visited[0] = True

    while queue:
        idx, steps = queue.popleft()

        # If we reached the last hill
        if idx == n - 1:
            return steps

        # Move to the next hill (adjacent)
        if idx + 1 < n and not visited[idx + 1]:
            visited[idx + 1] = True
            queue.append((idx + 1, steps + 1))

        # Jump over one hill (idx + 2)
        if idx + 2 < n and hills[idx + 2] >= hills[idx] and not visited[idx + 2]:
            visited[idx + 2] = True
            queue.append((idx + 2, steps + 1))

    return -1  # In case there is no path (though problem says there will be one)

