def int_partition(N: int) -> int:
    # Initialize a 2D list to store the number of partitions.
    # dp[i][j]: number of ways to partition i using numbers up to j.
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    # Base case: There is 1 way to partition 0 (using no numbers).
    for j in range(N + 1):
        dp[0][j] = 1

    # Fill the DP table
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            # If j > i, we can't use j in the partition of i
            if j > i:
                dp[i][j] = dp[i][j - 1]
            else:
                # The number of partitions without j plus the number with j
                dp[i][j] = dp[i][j - 1] + dp[i - j][j]

    return dp[N][N]

