def min_path_cost(n, m, edges):
    import sys
    sys.setrecursionlimit(10000)

    # Build adjacency list
    graph = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Step 1: Check if all nodes are reachable from node 1
    visited = [False] * (n + 1)
    stack = [1]
    visited[1] = True
    while stack:
        u = stack.pop()
        for v, _ in graph[u]:
            if not visited[v]:
                visited[v] = True
                stack.append(v)

    if sum(visited[1:]) < n:
        return -1

    # Step 2: Use Floyd-Warshall to find all-pairs shortest paths
    INF = float('inf')
    dist = [[INF] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dist[i][i] = 0

    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)

    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Step 3: TSP with dynamic programming
    from functools import lru_cache

    @lru_cache(None)
    def dp(mask, u):
        if mask == (1 << n) - 1:
            return dist[u][1]  # Return to node 1

        res = INF
        for v in range(1, n + 1):
            if not (mask & (1 << (v - 1))):
                res = min(res, dp(mask | (1 << (v - 1)), v) + dist[u][v])
        return res

    initial_mask = 1 << 0  # Node 1 is the starting point
    result = dp(initial_mask, 1)
    return result if result != INF else -1

