def count_anagram_pairs(words):
    from collections import defaultdict

    anagram_groups = defaultdict(int)

    for word in words:
        # Sort the characters of the word to create an anagram signature
        signature = ''.join(sorted(word))
        anagram_groups[signature] += 1

    # Count the number of pairs in each group
    total_pairs = 0
    for count in anagram_groups.values():
        if count >= 2:
            total_pairs += count * (count - 1) // 2

