def shuffle_count(N):
    def shuffle(deck):
        mid = (len(deck) + 1) // 2  # Split into two halves
        first_half = deck[:mid]
        second_half = deck[mid:]
        new_deck = []
        for i in range(max(len(first_half), len(second_half))):
            if i < len(first_half):
                new_deck.append(first_half[i])
            if i < len(second_half):
                new_deck.append(second_half[i])
        return new_deck

    original = list(range(1, N + 1))
    current = original.copy()
    count = 0

    while True:
        count += 1
        current = shuffle(current)
        if current == original:
            return count

