from typing import List, Tuple, Optional

def one_sparse(array: List[Tuple[int, str]]) -> Optional[int]:
    # Dictionary to track the net count of each number
    num_counts = {}

    for number, sign in array:
        if sign == '+':
            num_counts[number] = num_counts.get(number, 0) + 1
        else:  # sign == '-'
            num_counts[number] = num_counts.get(number, 0) - 1

    # Find the number with non-zero net count
    unique_num = None
    for key, value in num_counts.items():
        if value != 0:
            if unique_num is None:
                unique_num = key
            else:
                # More than one non-zero count, not 1-sparse
                return None

    return unique_num

