def max_crystals(n, m, grid):
    # Initialize a 1D DP array
    dp = [0] * m
    dp[0] = grid[0][0]  # Starting point

    # Fill the first row (left to right)
    for j in range(1, m):
        dp[j] = dp[j - 1] + grid[0][j]

    # Fill the rest of the rows
    for i in range(1, n):
        dp[0] += grid[i][0]  # First column
        for j in range(1, m):
            dp[j] = grid[i][j] + max(dp[j - 1], dp[j])

    return dp[-1]

