def min_path_cost(grid: list[list[int]]) -> int:
    # Get the dimensions of the grid
    n = len(grid)
    m = len(grid[0])

    # Start from the first cell
    for i in range(n):
        for j in range(m):
            if i == 0 and j == 0:
                continue  # Starting point, no cost to move into it
            elif i == 0:
                grid[i][j] += grid[i][j - 1]  # Only move from the left
            elif j == 0:
                grid[i][j] += grid[i - 1][j]  # Only move from above
            else:
                grid[i][j] += min(grid[i - 1][j], grid[i][j - 1])  # Take the minimum cost from above or left

    return grid[n - 1][m - 1]

