def count_good_buildings(heights):
    n = len(heights)

    # left[i] is True if all buildings to the left of i are shorter than heights[i]
    left = [False] * n
    max_so_far = -1
    for i in range(n):
        if heights[i] > max_so_far:
            left[i] = True
            max_so_far = heights[i]

    # right[i] is True if all buildings to the right of i are taller than heights[i]
    right = [False] * n
    min_so_far = float('inf')
    for i in range(n - 1, -1, -1):
        if heights[i] < min_so_far:
            right[i] = True
            min_so_far = heights[i]

    # Count how many buildings are good
    good_count = 0
    for i in range(n):
        if left[i] and right[i]:
            good_count += 1

    return good_count

from typing import List

def max_path_sum(grid: List[List[int]]) -> int:
    n = len(grid)
    m = len(grid[0])

    # Initialize the DP array with the first row
    dp = grid[0].copy()

    # Iterate over the grid starting from the second row
    for i in range(1, n):
        new_dp = [0] * m
        for j in range(m):
            # We can come from the cell directly above, or diagonally from the left or right
            max_prev = dp[j]
            if j > 0:
                max_prev = max(max_prev, dp[j - 1])
            if j < m - 1:
                max_prev = max(max_prev, dp[j + 1])
            new_dp[j] = grid[i][j] + max_prev
        dp = new_dp

    return max(dp)

