    prefix_sum = 0
    max_length = 0

    for i, num in enumerate(arr):
        prefix_sum += num

        # If the prefix_sum is equal to k, update max_length
        if prefix_sum == k:
            max_length = i + 1

        # Check if (prefix_sum - k) is in the map
        if (prefix_sum - k) in prefix_sum_map:
            length = i - prefix_sum_map[prefix_sum - k]
