def largest_factorial(n):
    if n < 1:
        return 1  # 0! = 1

    factorial = 1
    result = 1  # 0! = 1

    i = 1
    while True:
        factorial *= i
        if factorial > n:
            break
        result = factorial
        i += 1

    return result

