from typing import List

def largestPerimeter(nums: List[int]) -> int:
    nums.sort()  # Sort the array in non-decreasing order
    n = len(nums)

    # Start from the end to find the largest valid triangle
    for i in range(n - 1, 1, -1):
        a, b, c = nums[i - 2], nums[i - 1], nums[i]
        if a + b > c:
            return a + b + c

    return 0  # If no valid triangle is found

