from collections import deque

def min_moves(board):
    n = len(board)
    if board[0][0] == '#' or board[n-1][n-1] == '#':
        return -1  # Start or end is blocked

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    visited = [[False] * n for _ in range(n)]
    queue = deque([(0, 0, 0)])  # (row, col, moves)
    visited[0][0] = True

    while queue:
        row, col, moves = queue.popleft()

        if row == n - 1 and col == n - 1:
            return moves

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < n and 0 <= new_col < n and not visited[new_row][new_col] and board[new_row][new_col] == '.':
                visited[new_row][new_col] = True
                queue.append((new_row, new_col, moves + 1))

    return -1

