import heapq

def shortest_path(n, edges, start, end):
    # Build adjacency list
    graph = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))  # Since the graph is undirected

    # Initialize distances with infinity
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    heap = [(0, start)]  # (distance, node)

    while heap:
        current_dist, u = heapq.heappop(heap)
        if u == end:
            return current_dist
        if current_dist > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))

    return -1  # If end is unreachable from start

