def uniquePathsWithObstacles(grid, n, m):
    # Initialize a DP table with the same dimensions as the grid
    dp = [[0] * m for _ in range(n)]

    # If the start cell is blocked, return 0
    if grid[0][0] == 1:
        return 0

    # There is only one way to reach the start cell
    dp[0][0] = 1

    # Fill the first row
    for i in range(1, m):
        if grid[0][i] == 0:
            dp[0][i] = dp[0][i - 1]
        else:
            dp[0][i] = 0  # Obstacle, no way to reach this cell

    # Fill the first column
    for j in range(1, n):
        if grid[j][0] == 0:
            dp[j][0] = dp[j - 1][0]
        else:
            dp[j][0] = 0  # Obstacle, no way to reach this cell

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == 0:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
            else:
                dp[i][j] = 0  # Obstacle, no way to reach this cell

    return dp[n - 1][m - 1]

