def unique_paths(N, M, K, blocked):
    if N == 0 or M == 0:
        return 1 if (0, 0) not in blocked and (N, M) not in blocked else 0

    blocked_set = set(blocked)

    if (0, 0) in blocked_set or (N, M) in blocked_set:
        return 0

    # Use memoization (top-down DP)
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i, j):
        if (i, j) in blocked_set:
            return 0
        if i == 0 and j == 0:
            return 1
        total = 0
        if i > 0:
            total += dp(i - 1, j)
        if j > 0:
            total += dp(i, j - 1)
        return total

    return dp(N, M)

