from datetime import datetime

def average_session_duration(sessions):
    if not sessions:
        return 0.0

    total_duration_minutes = 0.0
    for session in sessions:
        start_time = datetime.fromisoformat(session['start_time'])
        end_time = datetime.fromisoformat(session['end_time'])

        duration = end_time - start_time
        total_duration_minutes += duration.total_seconds() / 60

    average = total_duration_minutes / len(sessions)
    return round(average, 2)

def min_path_sum(matrix):
    if not matrix or not matrix[0]:
        return -1

    m, n = len(matrix), len(matrix[0])
    # If the bottom-right cell is negative, it's impossible to meet the exit condition
    if matrix[-1][-1] <= 0:
        return -1

    # Initialize a DP table
    dp = [[0] * n for _ in range(m)]

    # First row and first column can only be reached by moving right or down, respectively
    dp[0][0] = matrix[0][0]
    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + matrix[i][0]
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + matrix[0][j]

    # Fill the rest of the DP table
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + matrix[i][j]

    return dp[-1][-1]

