def can_fulfill_all_requests(n, weight_limits, m, capacities):
    # Sort weight limits in ascending order
    weight_limits.sort()
    # Sort drone capacities in ascending order
    capacities.sort()

    # Try to match each weight limit with a drone
    drone_index = 0
    for weight in weight_limits:
        # Find the first drone that can handle the current weight
        while drone_index < m and capacities[drone_index] < weight:
            drone_index += 1
        if drone_index < m:
            drone_index += 1  # Mark this drone as used
        else:
            return "NO"  # No more drones can handle this request

    return "YES"

