def maxProfit(k, prices):
    n = len(prices)
    if n <= 1 or k == 0:
        return 0

    # If k is large enough to allow unlimited transactions
    if k >= n // 2:
        max_profit = 0
        for i in range(1, n):
            if prices[i] > prices[i - 1]:
                max_profit += prices[i] - prices[i - 1]
        return max_profit

    # DP array: dp[i] represents the maximum profit with at most i transactions
    dp = [[0] * n for _ in range(k + 1)]

    for i in range(1, k + 1):
        max_diff = -prices[0]
        for j in range(1, n):
            dp[i][j] = max(dp[i][j-1], prices[j] + max_diff)
            max_diff = max(max_diff, dp[i-1][j] - prices[j])

    return dp[k][n-1]

