def can_construct_from_k_rotations(s, k):
    if len(s) % k != 0:
        return False

    n = len(s)
    num_substrings = n // k

    # Get the first substring
    first_sub = s[:k]

    # Check if all other substrings are rotations of the first one
    for i in range(1, num_substrings):
        current_sub = s[i * k : (i + 1) * k]
        if not is_rotation(first_sub, current_sub):
            return False

    return True

def is_rotation(a, b):
    # Check if b is a rotation of a
    return len(a) == len(b) and b in a + a

def efficient_combination(n: int, r: int) -> int:
    # Handle edge cases
    if r > n or r < 0:
        return 0
    if r == 0 or r == n:
        return 1

    # Create a 2D list to store combinations: dp[i][j] = C(i, j)
    dp = [[0] * (r + 1) for _ in range(n + 1)]

    # Base case: C(i, 0) = 1
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the DP table using the recurrence
    for i in range(1, n + 1):
        for j in range(1, min(i, r) + 1):
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]

    return dp[n][r]

