def find_min_cyclic_rotation(s):
    min_rot = s  # Initialize with the original string
    n = len(s)

    # Generate all cyclic rotations and find the minimum
    for i in range(1, n):
        rotated = s[i:] + s[:i]
        if rotated < min_rot:
            min_rot = rotated

    return min_rot

