secure_solution:
def max_rainfall_span(rainfall, k):
    n = len(rainfall)
    if k > n:
        return -1  # This case is not possible as per the constraints

    current_sum = sum(rainfall[:k])
    max_sum = current_sum
    start_index = 0

    for i in range(k, n):
        current_sum += rainfall[i] - rainfall[i - k]
        if current_sum > max_sum:
            max_sum = current_sum
            start_index = i - k + 1

    return start_index

