        if i % 2 == 0:  # Even index (0-based), corresponds to 1st, 3rd, 5th positions (1-based)
            product_even *= lst[i]
        else:  # Odd index (0-based), corresponds to 2nd, 4th, 6th positions (1-based)
            sum_odd += lst[i]

    return product_even * sum_odd

