def max_magical_items(n, m, grid):
    # Initialize a 1D DP array with the first row
    dp = [0] * m
    dp[0] = grid[0][0]

    # Fill the first row
    for j in range(1, m):
        dp[j] = dp[j - 1] + grid[0][j]

    # Fill the rest of the rows
    for i in range(1, n):
        dp[0] += grid[i][0]  # Only one way to reach the first column
