from typing import List

def canBeSplit(nums: List[int]) -> bool:
    total_sum = sum(nums)

    # If total sum is odd, it's not possible to split into two equal subsets
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum of 0 is always possible

    for num in nums:
        for j in range(target, num - 1, -1):
            if dp[j - num]:
                dp[j] = True

    return dp[target]

