    # Remove all hyphens from the ISBN string
    cleaned_isbn = isbn.replace('-', '')

    # Check if the cleaned ISBN has exactly 10 characters
    if len(cleaned_isbn) != 10:
        return "Invalid"

    # Check if the first 9 characters are digits
    if not cleaned_isbn[:9].isdigit():
        return "Invalid"

    # Process the last character (can be a digit or 'X')
    try:
        # If it's a digit, convert to int
        last_char_value = int(cleaned_isbn[9])
    except ValueError:
        # If it's 'X', assign value 10
        if cleaned_isbn[9] == 'X':
            last_char_value = 10
        else:
            return "Invalid"  # Not a digit or 'X'

    # Calculate the weighted sum
    total = sum((i + 1) * int(cleaned_isbn[i]) for i in range(9))
    total += 10 * last_char_value

    # Check if the total is divisible by 11
    if total % 11 == 0:
        return "Valid"
    else:
        return "Invalid"

