def is_subarray_sum_greater_or_equal(n, k, x, a):
    # Extend the array to simulate circular nature
    extended_a = a + a

    # Initialize window sum
    current_sum = sum(extended_a[:k])
    if current_sum >= x:
        return "YES"

    # Slide the window
    for i in range(k, len(extended_a)):
        current_sum += extended_a[i] - extended_a[i - k]
        if current_sum >= x:
            return "YES"

    return "NO"

