from collections import defaultdict, deque

def find_task_order(tasks, dependencies):
    # Step 1: Build graph and in-degree count
    graph = defaultdict(list)
    in_degree = defaultdict(int)

    for a, b in dependencies:
        graph[a].append(b)
        in_degree[b] += 1

    # Step 2: Initialize queue with nodes having 0 in-degree
    queue = deque()
    for task in tasks:
        if in_degree.get(task, 0) == 0:
            queue.append(task)

    result = []

    # Step 3: Process nodes
    while queue:
        current = queue.popleft()
        result.append(current)

        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Step 4: Check for cycles (if result has fewer elements than tasks)
    if len(result) != len(tasks):
        return []  # There is a cycle

    return result

