def min_remove_to_make_valid(s):
    # Stack to keep track of indices of '('
    stack = []
    # Set to keep track of indices to remove
    to_remove = set()

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()  # Matched pair, so no need to remove
            else:
                to_remove.add(i)  # Unmatched ')', mark for removal

    # Any remaining '(' in stack are unmatched, mark for removal
    to_remove.update(stack)

    # Build the result string by skipping characters marked for removal
    return ''.join([c for i, c in enumerate(s) if i not in to_remove])

