import heapq

def min_processors_required(tasks):
    # Sort tasks by their start time
    tasks.sort()

    # Min-heap to keep track of the end times of the processors
    processors = []

    for start, end in tasks:
        if processors and processors[0] <= start:
            # We can reuse a processor
            heapq.heappop(processors)

        # Assign the task to a processor (add its end time to the heap)
        heapq.heappush(processors, end)

    return len(processors)

