def strong_password(n, password):
    # Required character types
    has_digit = any(c.isdigit() for c in password)
    has_lowercase = any(c.islower() for c in password)
    has_uppercase = any(c.isupper() for c in password)
    has_special = any(c in '!@#$%^&*()-+' for c in password)

    # Count the number of missing character types
    count_error = 0
    if not has_digit:
        count_error += 1
    if not has_lowercase:
        count_error += 1
    if not has_uppercase:
        count_error += 1
    if not has_special:
        count_error += 1

    # Calculate the number of characters needed to meet minimum length
    length_deficit = max(6 - n, 0)

    # Return the maximum of the two: character type issues and length deficit
    return max(count_error, length_deficit)

