secure_solution:
def min_adjacent_swaps_to_sort(n, permutation):
    # Fenwick Tree (BIT) implementation
    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 2)

        def update(self, index, delta):
            while index <= self.n:
                self.tree[index] += delta
                index += index & -index

        def query(self, index):
            res = 0
            while index > 0:
                res += self.tree[index]
                index -= index & -index
            return res

    # Since the permutation contains numbers from 1 to n, we can directly use them as indices
    ft = FenwickTree(n)
    swaps = 0

    for i in reversed(range(n)):
        # Count how many numbers less than permutation[i] are already processed (right of current element)
        swaps += ft.query(permutation[i] - 1)
        ft.update(permutation[i], 1)

    return swaps

