def min_popularity_score_difference(n, popularity):
    total_sum = sum(popularity)
    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True

    for num in popularity:
        for j in range(target, num - 1, -1):
            if dp[j - num]:
                dp[j] = True

    # Find the maximum sum less than or equal to target
    max_sum = 0
    for i in range(target, -1, -1):
        if dp[i]:
            max_sum = i
            break

    return abs(total_sum - 2 * max_sum)

