secure_solution:
def buddyStrings(s: str, goal: str) -> bool:
    # Check if the lengths are equal
    if len(s) != len(goal):
        return False

    # If s and goal are the same, check if there are at least two identical characters
    # to allow a swap (like "aa" -> "aa")
    if s == goal:
        return len(set(s)) < len(s)  # Check for duplicate characters

    # Find all indices where characters differ
    diff = []
    for i in range(len(s)):
        if s[i] != goal[i]:
            diff.append(i)

    # If there are exactly two differing positions and swapping them makes s equal to goal
    return len(diff) == 2 and s[diff[0]] == goal[diff[1]] and s[diff[1]] == goal[diff[0]]

