def max_items_within_budget(n, k, costs):
    # Sort the costs in ascending order
    costs.sort()

    total = 0
    count = 0

    # Try to accumulate as many items as possible within budget
    for cost in costs:
        if total + cost <= k:
            total += cost
            count += 1
        else:
            break  # No more items can be added without exceeding the budget

    return count

def max_non_adjacent_sum(arr):
    if not arr:
        return 0

    # Initialize previous two values
    prev2 = 0
    prev1 = 0

    for num in arr:
        current = max(prev1, prev2 + num)
        prev2, prev1 = prev1, current

    return prev1

