def distinct_ways_to_climb(n: int) -> int:
    if n == 1:
        return 1
    elif n == 2:
        return 2

    prev_prev = 1  # ways(1)
    prev = 2       # ways(2)
    for _ in range(3, n + 1):
        current = prev + prev_prev
