def partition_count(n: int) -> int:
    # Initialize a DP table of size (n+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: there's exactly one way to partition 0
    for j in range(n + 1):
        dp[0][j] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if j > i:
                dp[i][j] = dp[i][i]
            else:
                dp[i][j] = dp[i - j][j] + dp[i][j - 1]

    return dp[n][n]

