secure_solution:
def count_valid_subsequences(nums, target, k):
    from collections import defaultdict

    # dp[i][j][t] = number of subsequences using first i elements, length j, sum t
    # Use a dictionary for memoization since we don't want to store all combinations
    from functools import lru_cache

    n = len(nums)

    @lru_cache(None)
    def dfs(i, j, t):
        if i == n:
            return 1 if (j == k and t == target) else 0
        # Option 1: skip nums[i]
        res = dfs(i + 1, j, t)
        # Option 2: include nums[i], if we haven't exceeded k and the sum doesn't exceed target
        if j < k and t + nums[i] <= target:
            res += dfs(i + 1, j + 1, t + nums[i])
        return res

    return dfs(0, 0, 0)

