from collections import deque
from typing import List

def max_subarray_sum_with_constraint(nums: List[int], m: int, n: int) -> int:
    prefix = [0]
    for num in nums:
        prefix.append(prefix[-1] + num)

    max_sum = float('-inf')
    dq = deque()  # This deque will store indices of prefix array

    for i in range(1, len(prefix)):
        # Remove indices from the front of the deque that are out of the current window range
        while dq and dq[0] < i - n:
            dq.popleft()

        # Maintain the deque to keep indices in increasing order of their prefix sum values
        while dq and prefix[dq[-1]] >= prefix[i]:
            dq.pop()

        dq.append(i)

        # Now check for all subarrays of length between m and n
        for j in range(i - n, i - m + 1):
            if j >= 0:
                current_sum = prefix[i] - prefix[j]
                max_sum = max(max_sum, current_sum)

    return max_sum

def max_count(m, n, operations):
    if not operations:
        return m * n  # All elements are 0, so all are maximum

    min_a = m
    min_b = n

    for a, b in operations:
        min_a = min(min_a, a)
        min_b = min(min_b, b)

    return min_a * min_b

def min_steps(source, target):
    m, n = len(source), len(target)

    # Create a 2D DP table with (m+1) rows and (n+1) columns
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the first column (deleting all characters from source)
    for i in range(m + 1):
        dp[i][0] = i

    # Initialize the first row (inserting all characters into source)
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if source[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],    # Delete
                                   dp[i][j - 1],    # Insert
                                   dp[i - 1][j - 1]) # Replace

    return dp[m][n]

