def calculate_overall_grades(grades: List[List[int]]) -> List[float]:
    def compute_overall(assignment_grades: List[int]) -> float:
        if not assignment_grades:
            return 0.0
        if len(assignment_grades) == 1:
            return float(assignment_grades[0])
