    # Convert the input string to lowercase to ignore case differences
    input_string = input_string.lower()

    # Use a dictionary to count the frequency of each character
    freq = {}
    for char in input_string:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1

    # Count how many characters have an odd frequency
    odd_count = 0
    for count in freq.values():
        if count % 2 != 0:
            odd_count += 1

    # A string can be rearranged into a palindrome if at most one character has an odd count
    return odd_count <= 1

