def longest_zigzag_sequence(arr):
    if not arr:
        return 0

    n = len(arr)
    up = [1] * n  # up[i]: length of longest zigzag ending at i with a positive difference
    down = [1] * n  # down[i]: length of longest zigzag ending at i with a negative difference

    for i in range(n):
        for j in range(i):
            if arr[i] > arr[j]:
                up[i] = max(up[i], down[j] + 1)
            elif arr[i] < arr[j]:
                down[i] = max(down[i], up[j] + 1)

    return max(max(up), max(down))

