secure_solution:
def find_maximum_beauty(n, lights):
    if n == 0:
        return 0

    max_beauty = 1  # At least one color
    current_color = lights[0]
    count = 1

    for i in range(1, n):
        if lights[i] == current_color:
            count += 1
        else:
            # Change of color, we now have at least 2 distinct colors
            max_beauty = 2
            current_color = lights[i]
            count = 1

    return max_beauty

