def longestValidParentheses(s):
    stack = [-1]  # Initialize stack with base index
    max_length = 0

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                current_length = i - stack[-1]
                max_length = max(max_length, current_length)

    return max_length

