def max_avg_sales(transactions):
    max_avg = -1
    result_item = ""

    for item, sales in transactions.items():
        avg = sum(sales) / len(sales)
        if avg > max_avg or (avg == max_avg and item < result_item):
            max_avg = avg
            result_item = item

    return result_item

