def unique_paths_with_obstacles(grid: List[List[int]]) -> int:
    n, m = len(grid), len(grid[0])

    # If the start or end cell has an obstacle
    if grid[0][0] == 1 or grid[n-1][m-1] == 1:
        return 0

    # Initialize DP table
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1  # Starting point

    # Fill first row
    for j in range(1, m):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]
        else:
            dp[0][j] = 0  # Obstacle, no path

    # Fill first column
    for i in range(1, n):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = 0  # Obstacle, no path

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Obstacle, no path

