def minimum_energy_stops(floors):
    if not floors:
        return 0  # According to constraints, this won't happen

    total_energy = 0
    current_floor = floors[0]

    for next_floor in floors[1:]:
        total_energy += abs(next_floor - current_floor)
        current_floor = next_floor

    return total_energy

