def find_target_sum_ways(nums, target):
    total_sum = sum(nums)

    # If the target is greater than the total sum, it's impossible to get target
    if abs(target) > total_sum:
        return 0

    # We use a dictionary to store the number of ways to get each sum at each step
    dp = {0: 1}  # dp[sum] = number of ways to achieve that sum

    for num in nums:
        next_dp = {}
        for current_sum in dp:
            # Add the current number
            next_dp[current_sum + num] = next_dp.get(current_sum + num, 0) + dp[current_sum]
            # Subtract the current number
            next_dp[current_sum - num] = next_dp.get(current_sum - num, 0) + dp[current_sum]
        dp = next_dp

    return dp.get(target, 0)

