import math

def smallest_right_triangle(m, n):
    # Try the case where m and n are the two legs
    hypotenuse_sq = m**2 + n**2
    hypotenuse = int(math.isqrt(hypotenuse_sq))
    if hypotenuse * hypotenuse == hypotenuse_sq:
        return sorted([m, n, hypotenuse]) if m <= n else sorted([n, m, hypotenuse])

    # Try the case where m is the hypotenuse and n is a leg
    leg_sq = m**2 - n**2
    if leg_sq > 0:
        leg = int(math.isqrt(leg_sq))
        if leg * leg == leg_sq:
            return sorted([n, leg, m])

    # Try the case where n is the hypotenuse and m is a leg
    leg_sq = n**2 - m**2
    if leg_sq > 0:
        leg = int(math.isqrt(leg_sq))
        if leg * leg == leg_sq:
            return sorted([m, leg, n])

    return -1

