def max_increasing_subsequence_sum(n, a):
    # Initialize dp array with the same values as the input array
    dp = [num for num in a]

    # Iterate through each element in the array
    for i in range(n):
        # Check all previous elements
        for j in range(i):
            # If a[j] < a[i], we can extend the subsequence ending at j
            if a[j] < a[i]:
                dp[i] = max(dp[i], dp[j] + a[i])

    # The maximum value in dp array is the answer
    return max(dp)

