def longest_same_diff_subseq_length(n, arr):
    if n < 2:
        return 0  # As per the constraints, n ≥ 2, but just in case

    max_len = 1  # At least one element is present in any subsequence

    for i in range(n):
        for j in range(i + 1, n):
            # Calculate the absolute difference between first two elements
            diff = abs(arr[i] - arr[i + 1])
            current_len = 2  # Start with the first two elements
            valid = True

            # Check the rest of the subsequence from i to j
            for k in range(i + 1, j):
                if abs(arr[k] - arr[k + 1]) != diff:
                    valid = False
                    break
                current_len += 1

            if valid and current_len > max_len:
                max_len = current_len

    return max_len

