def power(x: int, y: int, mod: int = None) -> int:
    if y == 0:
        return 1  # x^0 is 1, even if x is 0
    if x == 0:
        return 0  # 0^y is 0 for y > 0

    result = 1
    x = x % mod if mod is not None else x  # Handle modulo for x if needed

    while y > 0:
        # If y is odd, multiply result with x
        if y % 2 == 1:
            result = (result * x) % mod if mod is not None else result * x

        # Square the base (x) and halve the exponent (y)
        x = (x * x) % mod if mod is not None else x * x
        y = y // 2

    return result

