def maxFrequencyCharacter(N, s):
    # Initialize frequency array for lowercase letters (a-z)
    freq = [0] * 26

    # Count the frequency of each character
    for char in s:
        index = ord(char) - ord('a')
        freq[index] += 1

    # Find the character with maximum frequency
    max_freq = -1
    result_char = 'z'  # Start with the highest lexicographical character

    for i in range(26):
        if freq[i] > max_freq:
            max_freq = freq[i]
            result_char = chr(i + ord('a'))
        elif freq[i] == max_freq:
            # If tied, choose the lexicographically smaller character
            if chr(i + ord('a')) < result_char:
                result_char = chr(i + ord('a'))

    return result_char

