import heapq

def furthest_building(heights, bricks, ladders):
    heap = []  # min-heap to keep track of the largest height differences

    for i in range(1, len(heights)):
        diff = heights[i] - heights[i - 1]
        if diff <= 0:
            continue  # No need for bricks or ladders if the next column is not taller

        # Use bricks or a ladder
        heapq.heappush(heap, diff)

        if len(heap) > ladders:
            # We need to use bricks for the smallest difference
            bricks -= heapq.heappop(heap)
            if bricks < 0:
                return i - 1  # Can't reach i-th column

    return len(heights) - 1  # Reached the last column

