def smallest_lexicographic_binary_string(t, test_cases):
    results = []
    for case in test_cases:
        count_0 = case.count('0')
        count_1 = case.count('1')
        if count_0 > 0 and count_1 > 0:
            # We can rearrange to all 0s followed by 1s
