def min_operations_to_non_decreasing(n, sequence):
    import bisect

    # We'll maintain a list to keep track of the smallest possible tail of increasing subsequences
    tails = []

    for num in sequence:
        # Use bisect_right to find the insertion point for num in tails
        # bisect_right returns the index where num can be inserted to maintain sorted order
        idx = bisect.bisect_right(tails, num)
        if idx == len(tails):
            tails.append(num)
        else:
            tails[idx] = num

    # The length of the longest non-decreasing subsequence is len(tails)
    return n - len(tails)

