def convert_temperature(value: float, from_scale: str, to_scale: str) -> float:
    # Convert scales to lowercase for case-insensitive comparison
    from_scale = from_scale.lower()
    to_scale = to_scale.lower()

    # Helper functions for the various conversions
    def celsius_to_fahrenheit(c):
        return (9 / 5) * c + 32

    def celsius_to_kelvin(c):
        return c + 273.15

    def fahrenheit_to_celsius(f):
        return (5 / 9) * (f - 32)

    def fahrenheit_to_kelvin(f):
        return (5 / 9) * (f - 32) + 273.15

    def kelvin_to_celsius(k):
        return k - 273.15

    def kelvin_to_fahrenheit(k):
        return (9 / 5) * (k - 273.15) + 32

    # Perform the conversion based on from_scale and to_scale
    if from_scale == to_scale:
        return value

    if from_scale == "celsius":
        if to_scale == "fahrenheit":
            return celsius_to_fahrenheit(value)
        elif to_scale == "kelvin":
            return celsius_to_kelvin(value)

    elif from_scale == "fahrenheit":
        if to_scale == "celsius":
            return fahrenheit_to_celsius(value)
        elif to_scale == "kelvin":
            return fahrenheit_to_kelvin(value)

    elif from_scale == "kelvin":
        if to_scale == "celsius":
            return kelvin_to_celsius(value)
        elif to_scale == "fahrenheit":
            return kelvin_to_fahrenheit(value)

    # If we get here, it means the from_scale or to_scale was not recognized (though problem says inputs are valid)
    raise ValueError("Invalid temperature scale provided.")

