def find_winner_team(k, n, task_results):
    # Initialize a list to hold total points for each team
    # Index 0 is unused since team IDs start from 1
    team_points = [0] * (k + 1)

    # Update points for each team
    for team_id, points in task_results:
        team_points[team_id] += points

    # Find the team with the highest points
    max_points = max(team_points)
    # Find the smallest team ID with max points
    for team_id in range(1, k + 1):
        if team_points[team_id] == max_points:
            return team_id

