def unique_paths_with_obstacles(obstacleGrid):
    m = len(obstacleGrid)
    n = len(obstacleGrid[0])

    # Initialize a 2D DP array
    dp = [[0] * n for _ in range(m)]

    # If the starting cell is not blocked
    if obstacleGrid[0][0] == 0:
        dp[0][0] = 1
    else:
        return 0  # No path if the start is blocked

    # Fill the first row
    for j in range(1, n):
        if obstacleGrid[0][j] == 0:
            dp[0][j] = dp[0][j - 1]
        else:
            dp[0][j] = 0  # Obstacle, cannot reach this cell

    # Fill the first column
    for i in range(1, m):
        if obstacleGrid[i][0] == 0:
            dp[i][0] = dp[i - 1][0]
        else:
            dp[i][0] = 0  # Obstacle, cannot reach this cell

    # Fill the rest of the DP table
    for i in range(1, m):
        for j in range(1, n):
            if obstacleGrid[i][j] == 0:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
            else:
                dp[i][j] = 0  # Obstacle, cannot reach this cell

    return dp[m - 1][n - 1]

