def custom_sequence_nth(a, b, c, n):
    # Handle the first three cases directly
    if n == 1:
        return a
    elif n == 2:
        return b
    elif n == 3:
        return c

    # Initialize the sequence with the first three numbers
    seq = [a, b, c]

    # Generate the sequence up to the nth number
    for i in range(3, n):
        next_val = seq[i-1] + seq[i-2] + seq[i-3]
        seq.append(next_val)

    return seq[-1]

