def longest_bitonic_subsequence(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Step 1: Longest Increasing Subsequence (LIS) ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Step 2: Longest Decreasing Subsequence (LDS) starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Step 3: Compute the maximum bitonic length
    max_bitonic = 0
    for i in range(n):
        max_bitonic = max(max_bitonic, lis[i] + lds[i] - 1)

    return max_bitonic

