def find_triplet_with_sum(nums, target):
    nums.sort()  # Sort the array
    n = len(nums)

    for i in range(n - 2):  # Iterate through each element as the first element of the triplet
        left = i + 1
        right = n - 1

        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]

            if current_sum == target:
                return [nums[i], nums[left], nums[right]]  # Return the triplet
            elif current_sum < target:
                left += 1  # Need a larger sum
            else:
                right -= 1  # Need a smaller sum

    return []  # If no triplet is found

