def max_weight_support(heights):
    left = 0
    right = len(heights) - 1
    max_weight = 0

    while left < right:
        current_weight = min(heights[left], heights[right]) * (right - left)
        max_weight = max(max_weight, current_weight)

        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1

    return max_weight

