secure_solution:
def max_value(n, D, prices):
    # Initialize a DP array where dp[i] represents the maximum value that can be achieved with i dollars
    dp = [0] * (D + 1)

    for price in prices:
        # Traverse the dp array in reverse to prevent reusing the same item
        for i in range(D, price - 1, -1):
            dp[i] = max(dp[i], dp[i - price] + price)

    # The maximum value Nils can buy without exceeding the gift card value
    return dp[D]

