def maxCoins(grid, n, m):
    # Initialize DP array with the first row
    dp = [grid[0][j] for j in range(m)]

    # Iterate over the grid starting from the second row
    for i in range(1, n):
        new_dp = [0] * m
        for j in range(m):
            # Check all possible positions from the previous row that can reach current position
            max_prev = 0
            for dj in [-1, 0, 1]:
                prev_j = j + dj
                if 0 <= prev_j < m:
                    max_prev = max(max_prev, dp[prev_j])
            new_dp[j] = grid[i][j] + max_prev
        dp = new_dp  # Update dp for the next iteration

    # The answer is the maximum value in the last row
    return max(dp)

