from collections import deque

def smallest_identifier(n):
    # Queue for BFS
    queue = deque(["1"])
    # Set to track visited numbers to avoid repetition
    visited = set()

    while queue:
        current = queue.popleft()
        if int(current) % n == 0:
            return current
        # Generate next numbers by appending '0' and '1'
        for digit in ['0', '1']:
            next_num = current + digit
            if next_num not in visited:
                visited.add(next_num)
                queue.append(next_num)

