from typing import List
from collections import defaultdict, deque

def minimum_time_required(num_tasks: int, task_durations: List[int], task_dependencies: List[List[int]]) -> int:
    # Build the graph
    graph = defaultdict(list)
    in_degree = [0] * num_tasks

    for i in range(num_tasks):
        for dep in task_dependencies[i]:
            graph[dep].append(i)
            in_degree[i] += 1

    # Initialize earliest completion time for each task
    earliest_completion = [0] * num_tasks

    # Topological sort using Kahn's algorithm
    queue = deque()
    for i in range(num_tasks):
        if in_degree[i] == 0:
            queue.append(i)

    while queue:
        current_task = queue.popleft()
        for neighbor in graph[current_task]:
            # Update the earliest completion time for the neighbor
            earliest_completion[neighbor] = max(earliest_completion[neighbor], earliest_completion[current_task] + task_durations[current_task])
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # The maximum earliest completion time is the total time to complete all tasks
    return max(earliest_completion[i] + task_durations[i] for i in range(num_tasks))

