def efficient_combination(n: int, r: int, memo=None) -> int:
    if memo is None:
        memo = {}

    # Base cases
    if r == 0 or r == n:
        return 1

    # If the result is already in memo, return it
    key = (n, r)
    if key in memo:
        return memo[key]

    # Recursive relation: nCr = n-1Cr-1 + n-1Cr
    result = efficient_combination(n - 1, r - 1, memo) + efficient_combination(n - 1, r, memo)

    # Save the result in the memo before returning
    memo[key] = result
    return result

