def min_operations_to_target(nums, target):
    nums.sort(reverse=True)  # Sort in descending order for greedy selection
    sum_so_far = 0
    operations = 0

    for num in nums:
        if sum_so_far + num > target:
            # We can only decrease the number to not overshoot target
            needed = target - sum_so_far
            operations += num - needed
            sum_so_far += needed
        else:
            sum_so_far += num

        if sum_so_far == target:
            return operations

    return -1

def fcfs_disk_scheduling(requests: list[int], head_start: int) -> tuple[list[int], int]:
    if not requests:
        return ([head_start], 0)

    order = [head_start]
    total_movements = 0
    current_position = head_start

    for request in requests:
        total_movements += abs(request - current_position)
        order.append(request)
        current_position = request

    return (order, total_movements)

