def largest_number_by_adjacent_swaps(S):
    s = list(S)  # Convert string to list for easier manipulation
    n = len(s)

    for i in range(n):
        # Find the index of the maximum digit from i to the end
        max_index = i
        for j in range(i + 1, n):
            if s[j] > s[max_index]:
                max_index = j

        # Swap the max digit to the front (i-th position)
        # by repeatedly swapping with adjacent digits
        while max_index > i:
            s[max_index], s[max_index - 1] = s[max_index - 1], s[max_index]
            max_index -= 1

    return ''.join(s)

