def can_transform(s1, s2):
    # If lengths are different, transformation is impossible
    if len(s1) != len(s2):
        return False

    # Count the frequency of characters in both strings
    from collections import Counter
    if Counter(s1) != Counter(s2):
        return False

    # Count the number of mismatched positions
    mismatch = 0
    for ch1, ch2 in zip(s1, s2):
        if ch1 != ch2:
            mismatch += 1
            if mismatch > 2:
                return False

    # If at most 2 mismatches, it can be fixed by moving one character
    return mismatch <= 2

