def min_add_to_make_valid(s):
    balance = 0
    additions = 0

    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1

        # If balance is negative, we need to add an opening parenthesis
        if balance < 0:
            additions += 1
            balance += 1  # balance it out

    # After the loop, balance represents unmatched opening parentheses
    additions += balance

    return additions

