def find_pairs(nums, target):
    seen = set()
    pairs = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            # Ensure the pair is sorted in ascending order
            pair = tuple(sorted((num, complement)))
            pairs.add(pair)
        seen.add(num)

    # Convert set to list and sort lexicographically
    return sorted(pairs)

