def is_subset_sum(arr, target):
    # Handle the special case where the target is 0
    if target == 0:
        return "YES"

    # Initialize a set to store all possible subset sums
    possible_sums = {0}

    for num in arr:
        # Update possible_sums by adding the current number to all existing sums
        new_sums = set()
        for s in possible_sums:
            new_sums.add(s + num)
        possible_sums.update(new_sums)

        # Early exit if the target is found
        if target in possible_sums:
            return "YES"

    return "NO"

