secure_solution:
def min_steps_to_reach_end(grid):
    rows, cols = len(grid), len(grid[0])

    # If the start or end cell is a mine, return -1
    if grid[0][0] == -1 or grid[rows - 1][cols - 1] == -1:
        return -1

    # Create a DP table to store the minimum steps to reach each cell
    dp = [[float('inf')] * cols for _ in range(rows)]
    dp[0][0] = 0  # Starting position

    # Fill the first row (only right moves)
    for j in range(1, cols):
        if grid[0][j] == -1:
            break
        dp[0][j] = dp[0][j - 1] + 1

    # Fill the first column (only down moves)
    for i in range(1, rows):
        if grid[i][0] == -1:
            break
        dp[i][0] = dp[i - 1][0] + 1

    # Fill the rest of the grid
    for i in range(1, rows):
        for j in range(1, cols):
            if grid[i][j] == -1:
                continue
            dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + 1

    return dp[rows - 1][cols - 1] if dp[rows - 1][cols - 1] != float('inf') else -1

