def count_overlapping_occurrences(s: str, subs: str) -> int:
    # Input validation
    if not isinstance(s, str) or not isinstance(subs, str):
        raise ValueError("Input must be a valid non-empty string")
    if len(s) == 0 or len(subs) == 0:
        raise ValueError("Input must be a valid non-empty string")

    # Special case: if the substring is longer than the string, return 0
    if len(subs) > len(s):
        return 0

    count = 0
    i = 0

    # Iterate through the string and count overlapping occurrences
    while i <= len(s) - len(subs):
        if s[i:i + len(subs)] == subs:
            count += 1
            i += 1  # Move by 1 to allow overlapping
        else:
            i += 1

    return count

