        raise ValueError("Current can not be negative")
    if voltage < 0 and voltage != 0:
        raise ValueError("Voltage can not be negative")
    if impedance < 0 and impedance != 0:
        raise ValueError("Impedance can not be negative")

    # Check that only one of the parameters is zero
    zero_count = sum(1 for value in [current, voltage, impedance] if value == 0)
    if zero_count != 1:
        raise ValueError("One and only one argument must be 0")

    # Determine which parameter is zero and calculate it
    if current == 0:
        result = voltage / impedance
        return {'current': result}
    elif voltage == 0:
        result = current * impedance
        return {'voltage': result}
    elif impedance == 0:
        result = voltage / current
        return {'impedance': result}
    else:
        raise ValueError("One and only one argument must be 0")

