    # Step 3: Generate all combinations of K bits from the set bits
    min_x = float('inf')
    for bits in itertools.combinations(set_bits, K):
        x = 0
        for bit in bits:
            x |= (1 << bit)
        if x < min_x:
            min_x = x

    return min_x if min_x != float('inf') else -1

