def count_possible_squads(n, k, a):
    # Initialize dp table (n x (k+1))
    dp = [[0] * (k + 1) for _ in range(n)]

    for i in range(n):
        # For each element a[i], we can start a subsequence of length 1
        dp[i][1] = 1
        for j in range(i):
            if a[j] < a[i]:
                for l in range(2, k + 1):
                    dp[i][l] += dp[j][l - 1]

    # Sum all dp[i][k] to get total number of valid squads
    return sum(dp[i][k] for i in range(n))

