def is_circular(s):
    # Check if the input is empty or contains invalid characters
    if not s or not all(c in {'U', 'D', 'L', 'R'} for c in s):
        return False

    x, y = 0, 0  # Starting position at (0, 0)

    # Apply each move
    for move in s:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

    # Check if we return to the origin
    return x == 0 and y == 0

