def count_paths_of_length_k(n, m, k, edges, u, v):
    from collections import defaultdict

    # Build adjacency list
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    count = 0

    def dfs(current, steps, visited):
        nonlocal count
        if steps == k:
            if current == v:
                count += 1
            return
        if steps > k:
            return
        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                dfs(neighbor, steps + 1, visited)
                visited.remove(neighbor)

    # Start DFS from u with initial steps = 0 and visited set containing u
    dfs(u, 0, {u})
    return count

