def packageCookies(cookies):
    if cookies < 12:
        return [0, 0, cookies]  # Not enough cookies to form even a partial box

    full_boxes = cookies // 20
    remaining_cookies = cookies % 20

    if remaining_cookies >= 12:
        partial_boxes = 1
        leftover_cookies = 0
    else:
        partial_boxes = 0
        leftover_cookies = remaining_cookies

    return [full_boxes, partial_boxes, leftover_cookies]

def min_energy_to_cross_grid(T, test_cases):
    results = []

    for case in test_cases:
        N, M, grid = case
        dp = [[0] * M for _ in range(N)]

        # Initialize first cell
        dp[0][0] = grid[0][0]

        # Fill first row
        for j in range(1, M):
            dp[0][j] = dp[0][j-1] + grid[0][j]

        # Fill first column
        for i in range(1, N):
            dp[i][0] = dp[i-1][0] + grid[i][0]

        # Fill the rest of the DP table
        for i in range(1, N):
            for j in range(1, M):
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

        results.append(dp[N-1][M-1])

    return results

