def longest_substring_with_m_b(m, s):
    left = 0
    max_len = 0
    b_count = 0

    for right in range(len(s)):
        if s[right] == 'b':
            b_count += 1

        # If the number of 'b's exceeds m, move the left pointer
        while b_count > m:
            if s[left] == 'b':
                b_count -= 1
            left += 1

        # Update the maximum length of the valid window
        max_len = max(max_len, right - left + 1)

    return max_len

def max_toys(n, m, toys, edges):
    from collections import defaultdict

    # Build adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Memoization dictionary
    memo = {}

    def dfs(node, visited):
        if node in memo:
            return memo[node]

        # Update visited set
        visited.add(node)
        max_toys_collected = toys[node - 1]  # node is 1-indexed

        for neighbor in graph[node]:
            if neighbor not in visited:
                # Try moving to the neighbor and get the max toys from there
                current_toys = dfs(neighbor, visited.copy()) + toys[node - 1]
                max_toys_collected = max(max_toys_collected, current_toys)

        memo[node] = max_toys_collected
        return max_toys_collected

    return dfs(1, set())

