from typing import List
from collections import defaultdict

def can_partition_into_pairs(arr: List[int], k: int) -> bool:
    if len(arr) % 2 != 0:
        return False  # Cannot form pairs if the list length is odd

    remainder_counts = defaultdict(int)

    for num in arr:
        remainder = num % k
        remainder_counts[remainder] += 1

    for r in remainder_counts:
        complement = (k - r) % k
        if r == complement:
            # For remainder 0 or k/2 (if k is even), ensure even count
            if remainder_counts[r] % 2 != 0:
                return False
        else:
            if remainder_counts[r] != remainder_counts[complement]:
                return False

    return True

