def find_point_on_route(xa, ya, segments, xb, yb):
    x, y = xa, ya
    total_distance = 0

    for direction, length in segments:
        # Check if the target point is on the current segment
        if direction == 'N':
            if x == xb and y <= yb <= y + length:
                return total_distance + (yb - y)
            y += length
        elif direction == 'S':
            if x == xb and y >= yb >= y - length:
                return total_distance + (y - yb)
            y -= length
        elif direction == 'E':
            if y == yb and x <= xb <= x + length:
                return total_distance + (xb - x)
            x += length
        elif direction == 'W':
            if y == yb and x >= xb >= x - length:
                return total_distance + (x - xb)
            x -= length

        total_distance += length

    # After all segments, check if the point is the final position
    if x == xb and y == yb:
        return total_distance

    return -1

