def process_queries(n, q, array, queries):
    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)

        def update(self, idx, delta):
            while idx <= self.n:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

    ft = FenwickTree(n)
    for i in range(n):
        ft.update(i + 1, array[i])

    result = []
    for query in queries:
        if query[0] == 1:
            # Update query: 1 i x
            i, x = query[1], query[2]
            delta = x - array[i - 1]
            array[i - 1] = x
            ft.update(i, delta)
        else:
            # Sum query: 2 l r
            l, r = query[1], query[2]
            total = ft.query(r) - ft.query(l - 1)
            result.append(total)

    return result

