def single_source_shortest_path(graph: dict, source: str) -> bool:
    # Step 1: Extract all nodes from the graph
    nodes = list(graph.keys())
    num_nodes = len(nodes)

    # Step 2: Initialize distances dictionary
    distances = {node: float('inf') for node in nodes}
    distances[source] = 0

    # Step 3: Relax edges for num_nodes - 1 times
    for _ in range(num_nodes - 1):
        updated = False
        for u in graph:
            for v, weight in graph[u].items():
                if distances[u] + weight < distances[v]:
                    distances[v] = distances[u] + weight
                    updated = True
        # Early stop if no changes in the last iteration
        if not updated:
            break

    # Step 4: Check for negative weight cycles
    for u in graph:
        for v, weight in graph[u].items():
            if distances[u] + weight < distances[v]:
                return False  # Negative weight cycle is reachable from source

    return True

