def largest_square_submatrix_area(matrix):
    n = len(matrix)
    if n == 0:
        return 0

    # Initialize dp matrix with the same size as the input matrix
    dp = [[0] * n for _ in range(n)]
    max_size = 0

    for i in range(n):
        for j in range(n):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_size = max(max_size, dp[i][j])
            else:
                dp[i][j] = 0

    return max_size * max_size

