secure_solution:
def can_partition(nums):
    total_sum = sum(nums)

    # If total sum is odd, it's impossible to partition into two equal subsets
    if total_sum % 2 != 0:
        return False

    target_sum = total_sum // 2
    possible_sums = set()
    possible_sums.add(0)

    for num in nums:
        temp = set()
        for s in possible_sums:
            new_sum = s + num
            if new_sum <= target_sum:
                temp.add(new_sum)
        possible_sums.update(temp)

    return target_sum in possible_sums

