def min_replacements(s, k):
    n = len(s)
    i = 0
    count = 0
    while i < n - 2:
        if s[i] == s[i + 1] == s[i + 2]:
            # We need to break this triplet
            count += 1
            i += k  # Skip to the end of the replaced window
        else:
            i += 1
    return count

