secure_solution:
def is_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)
    # Create a DP table with (m+1) rows and (n+1) columns
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True  # Empty pattern matches empty string

    # Handle patterns like "a*", "a*b*", etc., where * can match zero occurrences
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                # Check if '*' can match zero occurrences
                dp[i][j] = dp[i][j - 2]
                # Check if '*' can match one or more occurrences
                if p[j - 2] == s[i - 1] or p[j - 2] == '.':
                    dp[i][j] |= dp[i - 1][j]
            elif p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]

    return dp[m][n]

