def are_anagrams(a, b):
    # If the lengths are different, they can't be anagrams
    if len(a) != len(b):
        return False

    # Use a dictionary to count character frequencies
    char_count = {}

    # Count characters in string a
    for char in a:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Subtract character counts using string b
    for char in b:
        if char in char_count:
            char_count[char] -= 1
        else:
            # If a character in b is not in a, they aren't anagrams
            return False

    # Check if all character counts are zero
    for count in char_count.values():
        if count != 0:
            return False

    return True

