def find_anagram_pairs(words: List[str]) -> List[Tuple[str, str]]:
    anagram_groups = defaultdict(list)

    # Group words by their sorted character string
    for word in words:
        key = ''.join(sorted(word))
        anagram_groups[key].append(word)

    result = []

    # Generate all pairs for each group of anagrams
    for group in anagram_groups.values():
        if len(group) >= 2:
            # Generate all unique pairs and sort them lexicographically
            for i in range(len(group)):
                for j in range(i + 1, len(group)):
                    pair = tuple(sorted((group[i], group[j])))
                    result.append(pair)

    return result

