def min_steps_to_end(steps):
    n = len(steps)

    if n <= 1:
        return 0  # Already at the end

    jumps = 0
    current_end = 0
    farthest = 0

    for i in range(n - 1):
        farthest = max(farthest, i + steps[i])

        if i == current_end:
            jumps += 1
            current_end = farthest

            # If current_end >= n - 1, we've reached the end
            if current_end >= n - 1:
                return jumps

    return -1  # If we never reach the end

