def secure_key_exchange(base: int, exponent: int, mod: int) -> int:
    if mod == 1:
        return 0
    if exponent == 0:
        return 1 % mod  # 1 % mod is 1, unless mod is 1 which is already handled

    result = 1
    base = base % mod  # Reduce base modulo mod to simplify calculations

    while exponent > 0:
        # If exponent is odd, multiply result by the current base
        if exponent % 2 == 1:
            result = (result * base) % mod

        # Square the base and reduce modulo mod
        base = (base * base) % mod

        # Divide exponent by 2
        exponent = exponent // 2

    return result

