from typing import List, Tuple
from collections import defaultdict

def findPairs(nums: List[int], target: int) -> List[Tuple[int, int]]:
    seen = set()
    result = []
    num_counts = defaultdict(int)

    # Count occurrences of each number
    for num in nums:
        num_counts[num] += 1

    # Iterate through the list to find valid pairs
    for num in nums:
        complement = target - num
        if complement in num_counts:
            # Ensure we don't count the same pair twice
            if num < complement:
                if (num, complement) not in seen:
                    seen.add((num, complement))
                    result.append((num, complement))
            elif num == complement:
                if num_counts[num] >= 2 and (num, num) not in seen:
                    seen.add((num, num))
                    result.append((num, num))

    # Sort the result based on the first element of each pair
    result.sort()
    return result

