def optimized_cocktail_shaker_sort(arr: list[int]) -> list[int]:
    n = len(arr)
    if n <= 1:
        return arr  # Already sorted for empty or single-element lists

    start = 0
    end = n - 1

    while start < end:
        swapped = False

        # Left to right pass (same as bubble sort)
        for i in range(start, end):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                swapped = True
                end = i  # Shrink the end boundary since the last element is in place

        if not swapped:
            break  # If no swaps, array is sorted

        swapped = False

        # Right to left pass (reverse direction)
        for i in range(end - 1, start - 1, -1):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                swapped = True
                start = i  # Shrink the start boundary since the first element is in place

        if not swapped:
            break  # If no swaps, array is sorted

    return arr

