def sum_of_prefix_frequencies(n, sequence):
    from collections import defaultdict

    prefix_sums = []
    current_sum = 0
    freq = defaultdict(int)

    for num in sequence:
        current_sum += num
        prefix_sums.append(current_sum)

    # Count frequency of each prefix sum
    for ps in prefix_sums:
        freq[ps] += 1

    # Sum up the frequencies
    return sum(freq.values())

