import heapq

def trapRainWater(heightMap):
    if not heightMap or not heightMap[0]:
        return 0

    rows, cols = len(heightMap), len(heightMap[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    heap = []

    # Initialize the heap with the boundary cells
    for i in range(rows):
        for j in [0, cols - 1]:
            heapq.heappush(heap, (heightMap[i][j], i, j))
            visited[i][j] = True

    for j in range(1, cols - 1):
        for i in [0, rows - 1]:
            heapq.heappush(heap, (heightMap[i][j], i, j))
            visited[i][j] = True

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    trapped_water = 0

    while heap:
        height, row, col = heapq.heappop(heap)

        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                visited[nr][nc] = True
                # If the neighbor is lower, water can be trapped
                if heightMap[nr][nc] < height:
                    trapped_water += height - heightMap[nr][nc]
                # Add the neighbor to the heap with its own height
                heapq.heappush(heap, (max(height, heightMap[nr][nc]), nr, nc))

    return trapped_water

