def longest_bitonic_subsequence(nums):
    n = len(nums)

    # lis[i] = length of longest increasing subsequence ending at index i
    lis = [1] * n

    # lds[i] = length of longest decreasing subsequence starting at index i
    lds = [1] * n

    # Compute LIS for each index
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Compute LDS for each index
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if nums[j] < nums[i]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Calculate the maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        max_bitonic = max(max_bitonic, lis[i] + lds[i] - 1)

    return max_bitonic

