def max_sum_of_nodes(n, edges):
    from collections import defaultdict, deque

    # Build the tree as an adjacency list
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    # We will use DFS, and start from node 1 (or any arbitrary root)
    # We need to prevent revisiting the parent node
    visited = [False] * (n + 1)

    def dfs(node, parent):
        visited[node] = True
        max_sum = node
        for neighbor in tree[node]:
            if neighbor != parent and not visited[neighbor]:
                child_sum = dfs(neighbor, node)
                max_sum += child_sum
        return max_sum

    return dfs(1, -1)

