from typing import List, Tuple

def does_drone_visit(n: int, commands: str, queries: List[Tuple[int, int]]) -> List[bool]:
    # Initialize the drone's position at (0, 0)
    x, y = 0, 0
    visited = set()
    visited.add((x, y))  # Start position is visited

    # Simulate drone's movement and record visited positions
    for move in commands:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
        visited.add((x, y))

    # Check each query against the visited positions
    result = [pos in visited for pos in queries]
    return result

