def count_interesting_binary_strings(n):
    MOD = 10**9 + 7

    if n == 0:
        return 0
    if n == 1:
        return 2  # '0', '1'

    # Initialize a and b for n = 1
    a, b = 1, 1

    for i in range(2, n + 1):
        new_a = (a + b) % MOD
        new_b = a % MOD
        a, b = new_a, new_b

    return (a + b) % MOD

