import math

def min_cut_cost(n, l, rod_lengths, c):
    total_cuts = 0
    for length in rod_lengths:
        if length <= l:
            # No cut needed if the rod is already <= max allowed
            continue
        else:
            # Number of pieces = ceil(length / l)
            num_pieces = math.ceil(length / l)
            total_cuts += (num_pieces - 1)  # Each piece requires one cut fewer than the number of pieces
    return total_cuts * c

def find_anagrams(words):
    from collections import defaultdict

    anagram_counts = defaultdict(int)
    result = set()

    for word in words:
        # Create a sorted tuple of characters (this is the canonical form of an anagram)
        key = tuple(sorted(word))
        anagram_counts[key] += 1

    # Collect all words that are part of an anagram group with count > 1
    for word in words:
        key = tuple(sorted(word))
        if anagram_counts[key] > 1:
            result.add(word)

    return list(result)

