def find_two_odd_numbers(arr):
    # Step 1: XOR all elements to get XOR of the two odd numbers
    xor_result = 0
    for num in arr:
        xor_result ^= num

    # Step 2: Find a set bit (rightmost set bit)
    set_bit = xor_result & -xor_result  # Isolate the rightmost set bit

    # Step 3: Partition the array into two groups based on the set bit
    first, second = 0, 0
    for num in arr:
        if num & set_bit:
            first ^= num
        else:
            second ^= num

    # Step 4: Return the two numbers in ascending order
    return [min(first, second), max(first, second)]

