import heapq

def minimum_risk_path(n, m, roads, s, t):
    # Build adjacency list
    graph = [[] for _ in range(n + 1)]  # 1-indexed
    for u, v, w in roads:
        graph[u].append((v, w))

    # Dijkstra's algorithm
    dist = [float('inf')] * (n + 1)
    dist[s] = 0
    heap = [(0, s)]

    while heap:
        risk, u = heapq.heappop(heap)
        if u == t:
            break
        if risk > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))

    return dist[t] if dist[t] != float('inf') else -1

