def maximum_sum(arr, k, x):
    # Step 1: Filter the array to include only elements <= x
    filtered = [num for num in arr if num <= x]

    # Step 2: Check if we have at least k distinct elements
    if len(filtered) < k:
        return 0

    # Step 3: Sort the filtered list in descending order
    filtered.sort(reverse=True)

    # Step 4: Take the top k elements and sum them
    return sum(filtered[:k])

