def min_spells_needed(R, C, forest):
    rows_with_trees = set()
    cols_with_trees = set()

    for i in range(R):
        for j in range(C):
            if forest[i][j] == 'T':
                rows_with_trees.add(i)
                cols_with_trees.add(j)

    # If no trees are present, no spells needed
    if not rows_with_trees:
        return 0

    # Greedy approach:
    # Cast all necessary row spells
    row_spells = len(rows_with_trees)
    # For each column with a tree, check if it's covered by any of the rows we cast
    # If not, we need to cast a column spell
    columns_to_cast = 0
    for col in cols_with_trees:
        covered = False
        for row in rows_with_trees:
            if forest[row][col] == 'T':
                covered = True
                break
        if not covered:
            columns_to_cast += 1

    # Alternatively: cast all column spells and check if all rows are covered
    col_spells = len(cols_with_trees)
    rows_to_cast = 0
    for row in rows_with_trees:
        covered = False
        for col in cols_with_trees:
            if forest[row][col] == 'T':
                covered = True
                break
        if not covered:
            rows_to_cast += 1

    # Return the minimum of two options
    return min(row_spells + columns_to_cast, col_spells + rows_to_cast)

