def findMaxSkillSum(n, k, skills):
    dp = [False] * (k + 1)
    dp[0] = True  # Base case: sum of 0 is always possible

    max_sum = 0

    for skill in skills:
        # We iterate from k down to skill to avoid reusing the same element
        for i in range(k, skill - 1, -1):
            if dp[i - skill]:
                dp[i] = True
                if i > max_sum:
                    max_sum = i

    return max_sum

