def longest_alternating_subsequence(nums):
    if not nums:
        return 0

    n = len(nums)
    up = [1] * n
    down = [1] * n

    for i in range(1, n):
        for j in range(i):
            diff = nums[i] - nums[j]
            if diff > 0:
                up[i] = max(up[i], down[j] + 1)
            elif diff < 0:
                down[i] = max(down[i], up[j] + 1)

    return max(max(up), max(down))

