def count_combinations(badges, S):
    # Initialize a dictionary to keep track of the number of ways to make each sum
    dp = {0: 1}  # Base case: one way to make sum 0 (using no elements)

    for badge in badges:
        # Make a copy of the current dp dictionary to avoid overwriting during iteration
        current_dp = dp.copy()
        for sum_val in current_dp:
            new_sum = sum_val + badge
            if new_sum <= S:
                dp[new_sum] = dp.get(new_sum, 0) + current_dp[sum_val]

    return dp.get(S, 0)

