def unique_paths_in_grid(N, grid):
    # Convert grid to 0-based indexing and make it a 2D list
    grid = [list(row) for row in grid]

    # Initialize DP table
    dp = [[0 for _ in range(N)] for _ in range(N)]

    # Base case: starting cell
    if grid[0][0] == 0:
        dp[0][0] = 1
    else:
        return 0  # Starting point is blocked (though input guarantees this is not the case)

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue  # Already handled
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                top = dp[i-1][j] if i > 0 else 0
                left = dp[i][j-1] if j > 0 else 0
                dp[i][j] = top + left

    return dp[N-1][N-1]

