def minCostToPaintBuildings(cost):
    n = len(cost)
    if n == 0:
        return 0

    # Initialize DP array
    dp = [[0] * 3 for _ in range(n)]
    dp[0] = cost[0]  # Cost to paint the first building with each color

    for i in range(1, n):
        for j in range(3):
            # The current building can be painted with color j, so the previous building must be painted with a different color
            dp[i][j] = cost[i][j] + min(dp[i - 1][k] for k in range(3) if k != j)

    return min(dp[-1])

