secure_solution:
def minPalPartion(S):
    n = len(S)

    # Step 1: Precompute palindrome table
    is_pal = [[False] * n for _ in range(n)]

    for i in range(n):
        is_pal[i][i] = True  # single character is a palindrome

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if S[i] == S[j]:
                if length == 2:
                    is_pal[i][j] = True
                else:
                    is_pal[i][j] = is_pal[i + 1][j - 1]

    # Step 2: Dynamic Programming to find minimum cuts
    dp = [0] * n  # dp[i] = min cuts for S[0...i]

    for i in range(n):
        if is_pal[0][i]:
            dp[i] = 0  # whole substring is a palindrome, no cuts needed
        else:
            dp[i] = float('inf')
            for j in range(i):
                if is_pal[j + 1][i]:
                    dp[i] = min(dp[i], dp[j] + 1)

    return dp[n - 1]

