def find_group_with_max_hours(G, S, contributions):
    # Initialize a dictionary to keep track of total hours for each group
    group_hours = {group: 0 for group in range(1, G + 1)}

    # Process each contribution
    for contribution in contributions:
        name, group, hours = contribution
        group_hours[group] += hours

    # Find the group with the maximum hours
    max_hours = -1
    best_group = -1

    for group in range(1, G + 1):
        if group_hours[group] > max_hours or (group_hours[group] == max_hours and group < best_group):
            max_hours = group_hours[group]
            best_group = group

    return best_group

