secure_solution:
def maxProfit(k, prices):
    n = len(prices)
    if n <= 1 or k == 0:
        return 0

    # If k is very large, it’s equivalent to unlimited transactions
    if k >= n // 2:
        max_profit = 0
        for i in range(1, n):
            if prices[i] > prices[i - 1]:
                max_profit += prices[i] - prices[i - 1]
        return max_profit

    # dp[i][j]: max profit with at most i transactions on the first j days
    dp = [[0] * (n + 1) for _ in range(k + 1)]

    for i in range(1, k + 1):
        for j in range(1, n + 1):
            # If we do not buy on day j
            dp[i][j] = dp[i][j - 1]
            # If we buy on day j
            for l in range(1, j):
                dp[i][j] = max(dp[i][j], dp[i - 1][l - 1] + prices[j - 1] - prices[l - 1])

    return dp[k][n]

