def swap_operations(initial_string, operations):
    # Convert the string to a list for easier manipulation
    string_list = list(initial_string)

    # Perform each swap operation
    for p, q in operations:
        # Swap the characters at positions p and q
        string_list[p], string_list[q] = string_list[q], string_list[p]

    # Join the list back into a string and return
    return ''.join(string_list)

