def tsp(fuel_matrix):
    n = len(fuel_matrix)

    # Initialize DP table: dp[mask][i] = min fuel to reach planet i with visited mask
    dp = [[float('inf')] * n for _ in range(1 << n)]
    dp[1 << 0][0] = 0  # Starting at planet 1 (index 0)

    for mask in range(1 << n):
        for u in range(n):
            if not (mask & (1 << u)):
                continue  # If planet u is not in the current mask, skip
            for v in range(n):
                if mask & (1 << v):
                    continue  # If planet v is already in the mask, skip
                new_mask = mask | (1 << v)
                dp[new_mask][v] = min(dp[new_mask][v], dp[mask][u] + fuel_matrix[u][v])

    # Find the minimum cost to return to planet 1 (index 0) after visiting all planets
    full_mask = (1 << n) - 1
    result = min(dp[full_mask][u] + fuel_matrix[u][0] for u in range(n))

    return result

