from collections import defaultdict

def num_submatrix_sum_target(mat, target):
    m, n = len(mat), len(mat[0])

    # Step 1: Compute row-wise prefix sums
    prefix_sums = [[0] * n for _ in range(m)]
    for i in range(m):
        prefix_sums[i][0] = mat[i][0]
        for j in range(1, n):
            prefix_sums[i][j] = prefix_sums[i][j - 1] + mat[i][j]

    count = 0

    # Step 2: Iterate over all pairs of columns
    for col1 in range(n):
        for col2 in range(col1, n):
            # Calculate the cumulative sum for each row between col1 and col2
            row_sums = [0] * m
            for i in range(m):
                if col1 == 0:
                    row_sums[i] = prefix_sums[i][col2]
                else:
                    row_sums[i] = prefix_sums[i][col2] - prefix_sums[i][col1 - 1]

            # Step 3: Use hash map to count subarrays with target sum
            prefix_map = defaultdict(int)
            prefix_map[0] = 1
            current_sum = 0
            for s in row_sums:
                current_sum += s
                count += prefix_map[current_sum - target]
                prefix_map[current_sum] += 1

    return count

