secure_solution:
def minEditDistance(N, M, str1, str2):
    # Create a 2D DP table with (N+1) rows and (M+1) columns
    dp = [[0] * (M + 1) for _ in range(N + 1)]

    # Initialize the first row and column
    for i in range(N + 1):
        dp[i][0] = i  # Cost to delete all characters from str1
    for j in range(M + 1):
        dp[0][j] = j  # Cost to insert all characters into str1

    # Fill the DP table
    for i in range(1, N + 1):
        for j in range(1, M + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # No operation needed
            else:
                # Take the minimum of insert, delete, or replace
                dp[i][j] = 1 + min(
                    dp[i - 1][j],    # Delete
                    dp[i][j - 1],    # Insert
                    dp[i - 1][j - 1] # Replace
                )

    return dp[N][M]

