secure_solution:
def calculate_total_revenue(n, m, prices, discounts):
    # Initialize a dictionary to hold the best discount for each gadget
    best_discounts = {i: 0 for i in range(1, n + 1)}

    # Iterate over each discount and update the best discount for the corresponding gadget
    for gadget_id, discount in discounts:
        if discount > best_discounts[gadget_id]:
            best_discounts[gadget_id] = discount

    # Calculate the total revenue by applying the best discount to each gadget
    total_revenue = 0
    for i in range(n):
        gadget_id = i + 1
        original_price = prices[i]
        discount = best_discounts[gadget_id]
        total_revenue += original_price - discount

    return total_revenue

def max_songs(subscription, n, b, sizes, d=None):
    # Sort the songs by size to pick the smallest ones first
    sizes.sort()

    # Use a greedy approach to select as many songs as possible within the bandwidth
    total = 0
    count = 0
    for size in sizes:
        if total + size <= b:
            total += size
            count += 1
        else:
            break

    # If subscription is Standard, apply the daily song limit
    if subscription == "Standard":
        count = min(count, d)

    return count

