def knapsack(weights: list[int], values: list[int], capacity: int) -> int:
    n = len(weights)

    # Edge case: no items or zero capacity
    if n == 0 or capacity == 0:
        return 0

    # Initialize a DP table with (n+1) rows and (capacity+1) columns
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    # Fill the DP table
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            # If the current item's weight exceeds the capacity, skip it
            if weights[i - 1] > w:
                dp[i][w] = dp[i - 1][w]
            else:
                # Choose the maximum of including or excluding the current item
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - weights[i - 1]] + values[i - 1])

    return dp[n][capacity]

