from typing import List

def subset_sum_zero_exists(n: int, nums: List[int]) -> str:
    seen_sums = set()
    current_sum = 0

    # If the list contains 0, then a subset exists
    if 0 in nums:
        return "YES"

    seen_sums.add(current_sum)

    for num in nums:
        current_sum += num
        if current_sum == 0:
            return "YES"
        if current_sum in seen_sums:
            return "YES"
        seen_sums.add(current_sum)

    return "NO"

