def longest_palindromic_subsequence(s):
    n = len(s)
    s_reversed = s[::-1]

    # Create a 2D DP table
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if s[i - 1] == s_reversed[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n][n]

