def kth_smallest_pair_distance(arr, k):
    arr.sort()
    n = len(arr)

    def count_pairs_less_than_or_equal(mid):
        count = 0
        left = 0
        for right in range(n):
            while arr[right] - arr[left] > mid:
                left += 1
            count += right - left
        return count

    left, right = 0, arr[-1] - arr[0]

    while left < right:
        mid = (left + right) // 2
        if count_pairs_less_than_or_equal(mid) < k:
            left = mid + 1
        else:
            right = mid

    return left

