def count_paths(n, m, grid):
    MOD = 10**9 + 7

    # Initialize DP table
    dp = [[0] * m for _ in range(n)]

    # Starting point (0, 0)
    if grid[0][0] == '.':
        dp[0][0] = 1
    else:
        return 0  # No path if starting cell is blocked

    # Fill the first row
    for j in range(1, m):
        if grid[0][j] == '.':
            dp[0][j] = dp[0][j - 1]
        else:
            break  # Obstacle blocks further cells in this row

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == '.':
            dp[i][0] = dp[i - 1][0]
        else:
            break  # Obstacle blocks further cells in this column

    # Fill the rest of the grid
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == '.':
                dp[i][j] = (dp[i - 1][j] + dp[i][j - 1]) % MOD
            else:
                dp[i][j] = 0

    return dp[n - 1][m - 1]

