def max_non_overlapping_events(n, time_slots):
    # Sort the time slots by their end times
    time_slots.sort(key=lambda x: x[1])

    count = 0
    last_end = -1

    for start, end in time_slots:
        if start >= last_end:
            count += 1
            last_end = end

    return count

