def binomial_coefficient(n: int, k: int) -> int:
    if k == 0 or k == n:
        return 1

    # Use the symmetry property to reduce the number of computations
    k = min(k, n - k)

    # Initialize a 1D list to store the current row of Pascal's triangle
    dp = [1] * (k + 1)

    for i in range(1, n):
        # Update the dp array from right to left to avoid overwriting values we still need
        for j in range(min(i, k), 0, -1):
            dp[j] = dp[j] + dp[j - 1]

    return dp[k]

