def split_and_sum(number):
    if number == 1:
        return 1  # 1 is the only number whose product of digits is 1

    digits = []

    # Try dividing by digits from 9 down to 2 to get factors
    for i in range(9, 1, -1):
        while number % i == 0:
            digits.append(i)
            number //= i

    if number != 1:
        return -1  # There's a prime factor left that cannot be represented by digits

    # Sort the digits to form the smallest number
    digits.sort()
    return int(''.join(map(str, digits)))

