import heapq

def minMeetingRooms(intervals):
    if not intervals:
        return 0

    # Sort the intervals by start time
    intervals.sort(key=lambda x: x[0])

    # Min-heap to keep track of end times of events currently using rooms
    rooms = []

    for start, end in intervals:
        # If the earliest ending event has ended before the current one starts, reuse the room
        if rooms and rooms[0] <= start:
            heapq.heappop(rooms)

        # Add the current event's end time to the heap
        heapq.heappush(rooms, end)

    # The number of rooms needed is the size of the heap
    return len(rooms)

