secure_solution:
def find_friends_of_friends(network: dict, user_id: int) -> list:
    # Set to store unique friends of friends
    friends_of_friends = set()

    # Set to store direct friends of the user
    direct_friends = set(network.get(user_id, []))

    # Add the user themselves to the direct friends to exclude
    direct_friends.add(user_id)

    # Iterate through direct friends of the user
    for friend in network.get(user_id, []):
        # Get the friends of each direct friend
        for friend_of_friend in network.get(friend, []):
            # Add to friends_of_friends if it's not the user or their direct friend
            if friend_of_friend not in direct_friends:
                friends_of_friends.add(friend_of_friend)

    # Convert the set to a sorted list (for consistent ordering in assertions)
    return sorted(friends_of_friends)

