secure_solution:
def max_chocolates_stolen(n, chocolates):
    if n == 0:
        return 0
    if n == 1:
        return chocolates[0]

    # dp array where dp[i] represents the maximum chocolates that can be stolen up to house i
    dp = [0] * n
    dp[0] = chocolates[0]
    dp[1] = max(chocolates[0], chocolates[1])

    for i in range(2, n):
        dp[i] = max(dp[i - 1], dp[i - 2] + chocolates[i])

    return dp[-1]

