def minimum_gold_coins(n, happiness_levels):
    if n == 0:
        return 0

    coins = [1] * n  # All start with at least 1 coin

    # Left to right pass
    for i in range(1, n):
        if happiness_levels[i] > happiness_levels[i - 1]:
            coins[i] = coins[i - 1] + 1

    # Right to left pass
    for i in range(n - 2, -1, -1):
        if happiness_levels[i] > happiness_levels[i + 1]:
            coins[i] = max(coins[i], coins[i + 1] + 1)

    return sum(coins)

