def longest_divisible_subsequence(n, numbers):
    # Initialize dp array with 1s since each element itself is a subsequence of length 1
    dp = [1] * n

    # Iterate through each element in the list
    for i in range(n):
        # Check all previous elements
        for j in range(i):
            # If numbers[j] divides numbers[i], update dp[i]
            if numbers[i] % numbers[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    # The result is the maximum value in the dp array
    return max(dp)

