def can_partition(nums):
    total_sum = sum(nums)

    # If total sum is odd, it's impossible to partition into two equal subsets
    if total_sum % 2 != 0:
        return "NO"

    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: subset with sum 0 is always possible

    for num in nums:
        for i in range(target, num - 1, -1):
            if dp[i - num]:
                dp[i] = True

    return "YES" if dp[target] else "NO"

