def countPaths(grid):
    n = len(grid)

    # If the start or end cell is blocked, there are no paths
    if grid[0][0] == 1 or grid[n-1][n-1] == 1:
        return 0

    # Create a 2D DP table
    dp = [[0] * n for _ in range(n)]

    # There's only one way to reach the starting cell
    dp[0][0] = 1

    # Fill the first row
    for i in range(1, n):
        if grid[0][i] == 0:
            dp[0][i] = dp[0][i-1]
        else:
            break  # Blocked cell, no further paths in this row

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            break  # Blocked cell, no further paths in this column

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Blocked cell, no paths through it

    return dp[n-1][n-1]

