from typing import List, Tuple

def find_pairs(nums: List[int], target: int) -> List[Tuple[int, int]]:
    seen = set()
    pairs = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            # Ensure the smaller number comes first
            pair = tuple(sorted((num, complement)))
            pairs.add(pair)
        seen.add(num)

    # Sort the result by the first element of each tuple
    return sorted(pairs)

