def min_wildcards_to_form_subsequence(s, t):
    i = j = wildcards = 0
    len_s, len_t = len(s), len(t)

    while i < len_s and j < len_t:
        if s[i] == t[j]:
            i += 1
            j += 1
        else:
            wildcards += 1
            i += 1

    # If we have exhausted `s` but not `t`, we need to add wildcards to match the rest of `t`
    wildcards += len_t - j

    # If we have not matched all of `t`, return -1
    if j < len_t:
        return -1

    return wildcards

