def count_unique_triplets(arr, target_sum):
    arr.sort()
    unique_triplets = set()
    n = len(arr)

    for i in range(n - 2):
        left = i + 1
        right = n - 1

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]

            if current_sum == target_sum:
                # Store the triplet in sorted order
                unique_triplets.add((arr[i], arr[left], arr[right]))
                left += 1
                right -= 1
            elif current_sum < target_sum:
                left += 1
            else:
                right -= 1

    return len(unique_triplets)

