secure_solution:
def remove_k_digits(num, k):
    stack = []

    for digit in num:
        while k > 0 and stack and stack[-1] > digit:
            stack.pop()
            k -= 1
        stack.append(digit)

    # If k > 0, remove the last k digits
    if k > 0:
        stack = stack[:-k]

    # Remove leading zeros
    result = ''.join(stack).lstrip('0')

    return result if result != '' else '0'

