def fib_modified(x, y, n):
    assert n >= 0, "n must be a non-negative integer"

    if n == 0:
        return x
    elif n == 1:
        return y

    prev_prev = x  # F(n-2)
    prev = y       # F(n-1)

    for _ in range(2, n + 1):
        current = prev_prev + prev
        prev_prev, prev = prev, current

    return prev

