from typing import List
import re

def search_substring(
    strings: List[str],
    target: str,
    whole_word: bool = False
) -> List[str]:
    result = []
    target_lower = target.lower()
    pattern = r'\b' + re.escape(target_lower) + r'\b' if whole_word else target_lower

    for s in strings:
        s_lower = s.lower()
        if whole_word:
            # Use regex to match exact word
            if re.search(pattern, s_lower):
                result.append(s)
        else:
            # Check if substring is present in lowercased string
            if pattern in s_lower:
                result.append(s)
    return result

