def knapsack(n, W, items):
    # dp[i][w] will represent the maximum value that can be obtained using the first i items and weight w
    dp = [[0] * (W + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        w_i, v_i = items[i - 1]
        for w in range(W + 1):
            # If the current item's weight is more than the available weight, skip it
            if w_i > w:
                dp[i][w] = dp[i - 1][w]
            else:
                # Otherwise, choose the max between including or excluding the current item
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - w_i] + v_i)

    return dp[n][W]

