def canPartition(nums):
    total_sum = sum(nums)
    if total_sum % 2 != 0:
        return False  # If total sum is odd, partition is not possible

    target = total_sum // 2
    dp = set()
    dp.add(0)  # Starting with sum 0

    for num in nums:
        new_sums = set()
        for s in dp:
            new_sum = s + num
            if new_sum == target:
                return True
            if new_sum < target:
                new_sums.add(new_sum)
        dp.update(new_sums)

    return False

