def min_difference(n, values):
    total_sum = sum(values)
    possible_sums = {0}  # Start with sum 0

    for value in values:
        new_sums = set()
        for s in possible_sums:
            new_sums.add(s)
            new_sums.add(s + value)
        possible_sums = new_sums

    min_diff = float('inf')
    for s in possible_sums:
        diff = abs(total_sum - 2 * s)
        if diff < min_diff:
            min_diff = diff

    return min_diff

