def max_path_sum(grid):
    m = len(grid)
    n = len(grid[0])

    # Initialize the first cell
    grid[0][0] = grid[0][0]

    # Fill the first row
    for j in range(1, n):
        grid[0][j] += grid[0][j - 1]

    # Fill the first column
    for i in range(1, m):
        grid[i][0] += grid[i - 1][0]

    # Fill the rest of the grid
    for i in range(1, m):
        for j in range(1, n):
            grid[i][j] += max(grid[i - 1][j], grid[i][j - 1])

    return grid[m - 1][n - 1]

