def can_partition(nums):
    total_sum = sum(nums)

    # If total sum is odd, partition is not possible
    if total_sum % 2 != 0:
        return "NO"

    target = total_sum // 2
    dp = set()
    dp.add(0)

    for num in nums:
        new_sums = set()
        for s in dp:
            new_sum = s + num
            if new_sum <= target:
                new_sums.add(new_sum)
        dp.update(new_sums)

    return "YES" if target in dp else "NO"

