def can_swap_to_equal(s, t):
    # Check if s and t are already equal
    if s == t:
        return True

    # Find the indices where s and t differ
    diff = []
    for i in range(len(s)):
        if s[i] != t[i]:
            diff.append(i)

    # There must be exactly two differing indices to swap
    if len(diff) != 2:
        return False

    # Check if swapping the two differing characters in t makes it equal to s
    i, j = diff
    return t[i] == s[j] and t[j] == s[i]

