from typing import List

def longest_zigzag_subarray(arr: List[int]) -> int:
    if len(arr) < 2:
        return len(arr)

    n = len(arr)
    up = [1] * n  # Length of zigzag subarray ending at i with up direction
    down = [1] * n  # Length of zigzag subarray ending at i with down direction

    for i in range(1, n):
        if arr[i] > arr[i - 1]:
            up[i] = down[i - 1] + 1
            down[i] = down[i - 1]  # No change to down since we are going up now
        elif arr[i] < arr[i - 1]:
            down[i] = up[i - 1] + 1
            up[i] = up[i - 1]  # No change to up since we are going down now
        else:
            # Equal values, cannot form a zigzag subarray
            up[i] = up[i - 1]
            down[i] = down[i - 1]

    return max(max(up), max(down))

