from typing import List
from collections import deque, defaultdict

def find_ladder(start: str, target: str, word_list: List[str]) -> List[str]:
    if target not in word_list:
        return []

    word_set = set(word_list)
    word_set.add(start)  # Include the start word in the set for BFS

    # Bidirectional BFS
    forward_queue = deque([(start, 0)])
    backward_queue = deque([(target, 0)])

    forward_parent = {start: None}
    backward_parent = {target: None}

    forward_visited = {start}
    backward_visited = {target}

    # Helper function to generate all words that differ by one character
    def get_neighbors(word):
        neighbors = []
        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c != word[i]:
                    new_word = word[:i] + c + word[i+1:]
                    if new_word in word_set:
                        neighbors.append(new_word)
        return neighbors

    while forward_queue and backward_queue:
        # Forward BFS
        current_forward, steps_forward = forward_queue.popleft()
        for neighbor in get_neighbors(current_forward):
            if neighbor not in forward_visited:
                forward_visited.add(neighbor)
                forward_parent[neighbor] = current_forward
                forward_queue.append((neighbor, steps_forward + 1))
                if neighbor in backward_visited:
                    return reconstruct_path(forward_parent, backward_parent, neighbor, start, target)

        # Backward BFS
        current_backward, steps_backward = backward_queue.popleft()
        for neighbor in get_neighbors(current_backward):
            if neighbor not in backward_visited:
                backward_visited.add(neighbor)
                backward_parent[neighbor] = current_backward
                backward_queue.append((neighbor, steps_backward + 1))
                if neighbor in forward_visited:
                    return reconstruct_path(forward_parent, backward_parent, neighbor, start, target)

    return []

def reconstruct_path(forward_parent, backward_parent, meet_word, start, target):
    path = []
    # Reconstruct path from start to meet_word
    current = meet_word
    while current is not None:
        path.append(current)
        current = forward_parent[current]
    path.reverse()

    # Reconstruct path from meet_word to target
    current = backward_parent[meet_word]
    while current is not None:
        path.append(current)
        current = backward_parent[current]

    # Ensure that we have the correct path from start to target
    if path[0] == target:
        path.reverse()

    return path

