import heapq
from typing import List

def trapRainWater(heightMap: List[List[int]]) -> int:
    if not heightMap or not heightMap[0]:
        return 0

    m, n = len(heightMap), len(heightMap[0])
    visited = [[False] * n for _ in range(m)]
    heap = []

    # Initialize the heap with boundary cells
    for i in range(m):
        for j in [0, n - 1]:
            heapq.heappush(heap, (heightMap[i][j], i, j))
            visited[i][j] = True

    for j in range(1, n - 1):
        for i in [0, m - 1]:
            heapq.heappush(heap, (heightMap[i][j], i, j))
            visited[i][j] = True

    # Directions: up, down, left, right
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    trapped_water = 0

    while heap:
        height, x, y = heapq.heappop(heap)
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                # If the neighbor is lower, water can be trapped
                if heightMap[nx][ny] < height:
                    trapped_water += height - heightMap[nx][ny]
                # Push the effective height (max of current and neighbor height) to the heap
                heapq.heappush(heap, (max(height, heightMap[nx][ny]), nx, ny))

    return trapped_water

def maxSumSubgrid(grid, limit):
    m, n = len(grid), len(grid[0])

    # Step 1: Create a prefix sum matrix
    prefix = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m):
        for j in range(n):
            prefix[i + 1][j + 1] = grid[i][j] + prefix[i][j + 1] + prefix[i + 1][j] - prefix[i][j]

    max_sum = 0

    # Step 2: Iterate over all possible subgrids
    for i1 in range(m):
        for i2 in range(i1, m):
            for j1 in range(n):
                for j2 in range(j1, n):
                    # Calculate the sum of the subgrid (i1, j1) to (i2, j2)
                    sum_sub = prefix[i2 + 1][j2 + 1] - prefix[i1][j2 + 1] - prefix[i2 + 1][j1] + prefix[i1][j1]
                    if sum_sub <= limit:
                        max_sum = max(max_sum, sum_sub)

    return max_sum

