def minimum_repeats_needed(A: str, B: str) -> int:
    if B in A:
        return 1

    # Check if all characters in B are present in A
    if not set(B).issubset(set(A)):
        return -1

    # Compute the minimum number of repetitions to check
    len_A = len(A)
    len_B = len(B)
    min_repeats = (len_B // len_A) + 2

    # Concatenate A min_repeats times and check for B
    repeated_A = A * min_repeats
    if B in repeated_A:
        # Try to find the minimum number of repetitions needed
        for i in range(1, min_repeats + 1):
            if B in (A * i):
                return i
    return -1

