def longest_arith_seq_length(nums):
    if len(nums) < 2:
        return len(nums)

    n = len(nums)
    dp = [{} for _ in range(n)]  # dp[i] is a dictionary mapping difference to subsequence length

    max_length = 2  # Minimum possible length of an arithmetic subsequence with at least 2 elements

    for i in range(n):
        for j in range(i):
            diff = nums[i] - nums[j]
            # If there was a subsequence ending at j with the same difference
            # Then we can extend it by one more element (nums[i])
            dp[i][diff] = dp[j].get(diff, 1) + 1
            max_length = max(max_length, dp[i][diff])

    return max_length

