def run_length_encoding(s: str) -> str:
    if not s:
        return ""

    encoded = []
    count = 1
    current_char = s[0]

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            encoded.append(f"{current_char}{count}")
            current_char = char
            count = 1

    # Append the last group
    encoded.append(f"{current_char}{count}")

    return ''.join(encoded)

