def knapsack(n, W, gemstones):
    # Initialize dp array to store the maximum value for each weight
    dp = [0] * (W + 1)

    for value, weight in gemstones:
        # Iterate backwards to ensure each gemstone is used at most once
        for w in range(W, weight - 1, -1):
            dp[w] = max(dp[w], dp[w - weight] + value)

    return dp[W]

