def max_coins(n, m, grid):
    # Initialize DP table
    dp = [[0] * m for _ in range(n)]

    # Starting cell
    dp[0][0] = 1 if grid[0][0] == 'C' else 0

    # Fill the first row
    for j in range(1, m):
        dp[0][j] = dp[0][j-1] + (1 if grid[0][j] == 'C' else 0)

    # Fill the first column
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + (1 if grid[i][0] == 'C' else 0)

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + (1 if grid[i][j] == 'C' else 0)

    return dp[n-1][m-1]

