def countPowerOutage(n, edges, faulty):
    # Build the adjacency list
    graph = [[] for _ in range(n + 1)]  # Using 1-based indexing
    for a, b in edges:
        graph[a].append(b)

    # Use a set to keep track of visited nodes
    visited = set()

    # Depth-First Search
    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph[node]:
            dfs(neighbor)

    # Start DFS from the faulty node
    dfs(faulty)

    # Return the number of substations that lost power
    return len(visited)

