def count_even_product_pairs(n, array):
    even_count = 0
    odd_count = 0

    for num in array:
        if num % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    total_pairs = n * (n - 1) // 2
    odd_pairs = odd_count * (odd_count - 1) // 2
    result = total_pairs - odd_pairs

    return result

