secure_solution:
def evaluate_rpn(expression: str) -> int:
    tokens = expression.split()
    stack = []

    for token in tokens:
        if token in "+-*/":
            # Pop the top two operands from the stack
            operand2 = stack.pop()
            operand1 = stack.pop()

            # Perform the operation based on the token
            if token == "+":
                result = operand1 + operand2
            elif token == "-":
                result = operand1 - operand2
            elif token == "*":
                result = operand1 * operand2
            elif token == "/":
                # Use integer division with floor division
                result = operand1 // operand2

            # Push the result back to the stack
            stack.append(result)
        else:
            # Convert the token to an integer and push to the stack
            stack.append(int(token))

    # The final result is the only remaining element in the stack
    return stack[0]

