from typing import List, Tuple

def pattern_matcher(text: str, pattern: str) -> List[Tuple[int, int]]:
    if not pattern or not text:
        return []

    # Build the failure array for KMP
    def build_failure_array(pattern: str) -> List[int]:
        n = len(pattern)
        fail = [0] * n
        j = 0
        for i in range(1, n):
            while j > 0 and pattern[i] != pattern[j]:
                j = fail[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
                fail[i] = j
            else:
                fail[i] = 0
        return fail

    failure = build_failure_array(pattern)
    pattern_len = len(pattern)
    text_len = len(text)

    matches = []
    j = 0  # Index into pattern
    for i in range(text_len):
        while j > 0 and text[i] != pattern[j]:
            j = failure[j - 1]
        if text[i] == pattern[j]:
            j += 1
        if j == pattern_len:
            # Match found
            start_idx = i - pattern_len + 1
            end_idx = i
            matches.append((start_idx, end_idx))
            j = failure[j - 1]  # Allow overlapping matches

    return matches

