from typing import List

def containsNearbyAlmostDuplicate(nums: List[int], k: int, t: int) -> bool:
    if k < 0 or t < 0:
        return False

    buckets = {}

    for i, num in enumerate(nums):
        # Bucket ID: we divide the number by (t + 1) to create buckets
        bucket_id = num // (t + 1)

        # Check the current bucket
        if bucket_id in buckets:
            return True

        # Check the previous bucket (bucket_id - 1)
        if (bucket_id - 1) in buckets and abs(num - buckets[bucket_id - 1]) <= t:
            return True

        # Check the next bucket (bucket_id + 1)
        if (bucket_id + 1) in buckets and abs(num - buckets[bucket_id + 1]) <= t:
            return True

        # Store the current number in the bucket
        buckets[bucket_id] = num

        # Keep the window size at most k by removing the oldest element
        if i >= k:
            old_bucket_id = nums[i - k] // (t + 1)
            del buckets[old_bucket_id]

    return False

