def can_achieve_xp(xp, L):
    # Initialize a set to keep track of achievable XP values
    achievable = {0}  # Start with 0 XP, which is always achievable

    for x in xp:
        # For each achievable XP value, add x to it and update the set
        new_achievable = set()
        for val in achievable:
            new_val = val + x
            if new_val <= L:
                new_achievable.add(new_val)
        achievable.update(new_achievable)

    return L in achievable

