def longest_repeated_substring(s: str) -> tuple:
    """
    Finds the longest substring of consecutive repeated characters in a given string.

    Args:
        s (str): The input string.

    Returns:
        tuple: A tuple containing the longest repeated substring and its length.
    """
    if not s:
        return ('', 0)

    max_len = 1
    current_len = 1
    max_substring = s[0]

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            current_len += 1
        else:
            if current_len > max_len:
                max_len = current_len
                max_substring = s[i - current_len:i]
            current_len = 1

    # Check the last substring
    if current_len > max_len:
        max_len = current_len
        max_substring = s[-current_len:]

    return (max_substring, max_len)

