def generate_purchase_report(json_data, output_file):
    try:
        # Parse the JSON string into a Python list of dictionaries
        purchases = json.loads(json_data)

        # Dictionary to store user summary data
        user_summary = {}

        # Process each purchase to accumulate data
        for purchase in purchases:
            user_id = purchase["user_id"]
            amount = float(purchase["amount"])

            if user_id in user_summary:
                user_summary[user_id]["total_purchases"] += 1
                user_summary[user_id]["total_amount"] += amount
            else:
                user_summary[user_id] = {
