secure_solution:
def min_transformations_to_same_string(words):
    if not words:
        return -1  # or 0, depending on interpretation

    # Check if all strings have the same length
    length = len(words[0])
    for word in words:
        if len(word) != length:
            return -1

    from collections import Counter

    # Count the frequency of each string
    freq = Counter(words)

    # For each unique word, calculate the total number of transformations
    min_transformations = float('inf')
    for word in freq:
        transformations = 0
        for other_word in words:
            transformations += sum(1 for a, b in zip(word, other_word) if a != b)
        min_transformations = min(min_transformations, transformations)

    return min_transformations if min_transformations != float('inf') else -1

