def encrypt_message(s, k):
    result = []
    for char in s:
        if char.isalpha():
            # Determine the base for uppercase or lowercase
            base = ord('A') if char.isupper() else ord('a')
            # Shift character and wrap around using modulo
            shifted_char = chr((ord(char) - base + k) % 26 + base)
            result.append(shifted_char)
        else:
            result.append(char)
    return ''.join(result)

