def max_tricks(N, M, P):
    # Sort tricks based on the net cost (P_i // 2)
    P_sorted = sorted(P)

    tricks_performed = 0
    current_magic = M

    for p in P_sorted:
        if current_magic >= p:
            tricks_performed += 1
            current_magic -= p
            current_magic += p // 2
        else:
            break

    return tricks_performed

