def highlight_keywords(sentence: str, keywords: list) -> str:
    """
    Highlight keywords in a sentence by enclosing them with square brackets.

    :param sentence: A string representing the sentence to process
    :param keywords: A list of strings representing the keywords to highlight
    :return: A string with keywords highlighted
    """
    # Convert the list of keywords to lowercase for case-insensitive matching
    lower_keywords = {keyword.lower() for keyword in keywords}

    # Split the sentence into words
    words = sentence.split()

    # Iterate over each word and check if it is a keyword (case-insensitive)
    highlighted_words = []
    for word in words:
        if word.lower() in lower_keywords:
            highlighted_words.append(f"[{word}]")
        else:
            highlighted_words.append(word)

    # Join the words back into a sentence
    return " ".join(highlighted_words)

