def find_pairs(numbers, target_sum):
    seen = set()
    result = set()

    for num in numbers:
        complement = target_sum - num
        if complement in seen:
            # Ensure the pair is in ascending order
            result.add(tuple(sorted((num, complement))))
        seen.add(num)

    # Convert the set of tuples to a sorted list of tuples
    return sorted(result)

