import heapq
from collections import deque, Counter

def rearrange_string(s, k):
    if k == 0:
        return s  # No distance requirement

    # Count frequency of each character
    count = Counter(s)

    # Max heap based on frequency (negative used for max heap emulation)
    max_heap = []
    for char, freq in count.items():
        heapq.heappush(max_heap, (-freq, char))

    result = []
    queue = deque()

    while max_heap:
        freq, char = heapq.heappop(max_heap)
        result.append(char)
        queue.append((freq + 1, char))  # freq + 1 because we used one occurrence

        # If we have reached the limit k, we can pop elements from the queue and add them back to heap
        if len(queue) == k:
            next_freq, next_char = queue.popleft()
            if next_freq != 0:
                heapq.heappush(max_heap, (next_freq, next_char))

    # If we were able to use all characters, return the result
    if len(result) == len(s):
        return ''.join(result)
    else:
        return ""

