def smallest_palindrome(n, s):
    s = list(s)

    # Check if palindrome is possible and replace symmetric characters
    for i in range(n // 2):
        j = n - 1 - i
        if s[i] == '?' and s[j] == '?':
            s[i] = 'a'
            s[j] = 'a'
        elif s[i] == '?':
            s[i] = s[j]
        elif s[j] == '?':
            s[j] = s[i]
        elif s[i] != s[j]:
            return "-1"

    # Handle middle character in case of odd length
    if n % 2 == 1:
        mid = n // 2
        if s[mid] == '?':
            s[mid] = 'a'

