def trap(height):
    if not height or len(height) < 3:
        return 0

    left, right = 0, len(height) - 1
    max_left = max_right = 0
    water_trapped = 0

    while left < right:
        if height[left] < height[right]:
            if height[left] >= max_left:
                max_left = height[left]
            else:
                water_trapped += max_left - height[left]
            left += 1
        else:
