def int_divide(n):
    # Initialize a 2D DP table
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: There is exactly 1 way to partition 0 (with no elements)
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i < j:
                dp[i][j] = dp[i][i]
            elif i == j:
                dp[i][j] = 1 + dp[i][j - 1]
            else:
                dp[i][j] = dp[i][j - 1] + dp[i - j][j]

