def longest_arith_seq_length(nums):
    n = len(nums)
    if n <= 2:
        return n  # A sequence of 1 or 2 elements is trivially arithmetic

    dp = [{} for _ in range(n)]  # dp[i] is a dictionary: {difference: length}
    max_length = 2  # Minimum length is 2

    for i in range(n):
        for j in range(i):
            d = nums[i] - nums[j]
            # Get the length of subsequence ending at j with difference d
            dp[i][d] = dp[j].get(d, 1) + 1
            max_length = max(max_length, dp[i][d])

    return max_length

