def can_partition_to_max_weight(weights, maxWeight):
    total_weight = sum(weights)

    # If total weight exceeds twice maxWeight, it's impossible
    if total_weight > 2 * maxWeight:
        return False

    # We want to find a subset with sum in the range [total_weight - maxWeight, maxWeight]
    target = maxWeight

    # Use a set to track possible subset sums
    possible_sums = {0}

    for weight in weights:
        new_sums = set()
        for s in possible_sums:
            new_sum = s + weight
            if new_sum <= target:
                new_sums.add(new_sum)
        possible_sums.update(new_sums)

    # Check if there exists a subset sum between (total_weight - maxWeight) and maxWeight
    for s in possible_sums:
        if total_weight - maxWeight <= s <= maxWeight:
            return True

    return False

