def secure_mod_exp(base, exponent, mod):
    # Handle edge case when exponent is 0
    if exponent == 0:
        return 1 % mod  # Ensure it's in [0, mod)

    # Ensure base is within [0, mod) for correct modular arithmetic
    base = base % mod

    result = 1
    base = base % mod  # Make sure base is in the correct range

    while exponent > 0:
        # If exponent is odd, multiply result by base
        if exponent % 2 == 1:
            result = (result * base) % mod

        # Square the base and halve the exponent
        base = (base * base) % mod
        exponent = exponent // 2

    return result

