def find_cheapest_price(n, flights, src, dst, k):
    # Initialize the cost array: cost[i] is the minimum cost to reach city i
    cost = [float('inf')] * n
    cost[src] = 0

    # Iterate for k+1 times (k stops means k+1 edges)
    for _ in range(k + 1):
        temp_cost = cost.copy()  # Keep a copy of the previous iteration's costs
        updated = False
        for u, v, w in flights:
            if cost[u] != float('inf') and cost[u] + w < temp_cost[v]:
                temp_cost[v] = cost[u] + w
                updated = True
        if not updated:
            break  # No more updates, can exit early
        cost = temp_cost

    return cost[dst] if cost[dst] != float('inf') else -1

