from collections import defaultdict, deque

def longest_path_in_dag(n, edges):
    # Build the adjacency list and in-degree count
    graph = defaultdict(list)
    in_degree = [0] * n

    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    # Topological sort using Kahn's algorithm
    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    # DP array to store the longest path ending at each node
    dp = [0] * n

    while queue:
        u = queue.popleft()
        for v in graph[u]:
            dp[v] = max(dp[v], dp[u] + 1)
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Return the maximum value in dp array
    return max(dp)

