def num_paths(R, C, grid):
    MOD = 10**9 + 7
    dp = [[0] * C for _ in range(R)]

    # Initialize the first cell
    if grid[0][0] == '#':
        return 0
    dp[0][0] = 1

    # Fill the first row
    for j in range(1, C):
        if grid[0][j] == '#':
            break
        dp[0][j] = dp[0][j-1]

    # Fill the first column
    for i in range(1, R):
        if grid[i][0] == '#':
            break
        dp[i][0] = dp[i-1][0]

    # Fill the rest of the dp table
    for i in range(1, R):
        for j in range(1, C):
            if grid[i][j] == '#':
                continue
            dp[i][j] = (dp[i-1][j] + dp[i][j-1]) % MOD

    return dp[R-1][C-1]

