def max_money(Alice, N):
    def helper(l, r, turn):
        # Base case: no coins left
        if l > r:
            return 0

        # If it's Alice's turn, she wants to maximize her total
        if turn == 0:
            return max(Alice[l] + helper(l + 1, r, 1), Alice[r] + helper(l, r - 1, 1))
        # If it's Bob's turn, he wants to minimize Alice's total (i.e. maximize his own)
        else:
            return min(helper(l + 1, r, 0), helper(l, r - 1, 0))

    return helper(0, N - 1, 0)

