def lexicographically_smallest_string(s, k):
    stack = []
    for char in s:
        while k > 0 and stack and stack[-1] > char:
            stack.pop()
            k -= 1
        stack.append(char)

    # If there are still k characters to remove, remove from the end
    if k > 0:
        stack = stack[:-k]

    return ''.join(stack)

