def largest_possible_integer(N, K, digits):
    stack = []

    for digit in digits:
        while K > 0 and stack and stack[-1] < digit:
            stack.pop()
            K -= 1
        stack.append(digit)

    # If K > 0 after processing all digits, remove from the end
    if K > 0:
        stack = stack[:-K]

    # Remove leading zeros and handle empty case
    result = ''.join(stack).lstrip('0')
    return result if result else '0'

def transform_and_validate_array(arr: list[int], target_sum: int) -> bool:
    # Apply the transformation rules
    transformed = []
    for num in arr:
        if num > 0:
            transformed.append(num + 1)
        elif num < 0:
            transformed.append(-num)
        else:
            transformed.append(num)

    # Calculate the sum of the transformed array
    total = sum(transformed)

    # Validate if the sum matches the target_sum
    return total == target_sum

