def three_sum(arr, k):
    arr.sort()
    n = len(arr)
    for i in range(n - 2):
        # Avoid duplicate elements for the first number
        if i > 0 and arr[i] == arr[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == k:
                return True
            elif current_sum < k:
                left += 1
            else:
                right -= 1
    return False

