def optimize_backpack(weights, values, max_weight):
    n = len(weights)
    # Initialize a 2D DP array with (n+1) rows and (max_weight + 1) columns
    dp = [[0] * (max_weight + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(max_weight + 1):
            # If the current item's weight is more than the current capacity, skip it
            if weights[i - 1] > w:
                dp[i][w] = dp[i - 1][w]
            else:
                # Take the max of including or excluding the current item
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - weights[i - 1]] + values[i - 1])

    return dp[n][max_weight]

