def count_paths(grid):
    N = len(grid)

    # If the grid is 1x1, check the only cell
    if N == 1:
        return 1 if grid[0][0] == 1 else 0

    # Initialize DP table
    dp = [[0] * N for _ in range(N)]

    # Starting point: only one way to be at (0, 0) if it's navigable
    if grid[0][0] == 1:
        dp[0][0] = 1
    else:
        return 0  # Cannot start from (0, 0)

    # Fill DP table
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue  # Skip starting point
            if grid[i][j] == 1:
                # Add paths from top (i-1, j) and left (i, j-1) if they are valid
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[N-1][N-1]

