from typing import List

def max_area(heights: List[int]) -> int:
    left, right = 0, len(heights) - 1
    max_area = 0

    while left < right:
        current_area = min(heights[left], heights[right]) * (right - left)
        max_area = max(max_area, current_area)

        # Move the pointer pointing to the shorter line
        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1

    return max_area

def product_stability(n, blocks, weights, m, queries):
    # Check if the arrays have the same length
    if len(blocks) != n or len(weights) != n:
        return [-1] * m

    # Compute prefix sums of products
    prefix_sums = [0] * (n + 1)
    for i in range(n):
        prefix_sums[i + 1] = prefix_sums[i] + blocks[i] * weights[i]

    # Process each query
    results = []
    for l, r in queries:
        if l > r or l < 1 or r > n:
            results.append(-1)
        else:
            # Convert 1-based to 0-based
            res = prefix_sums[r] - prefix_sums[l - 1]
            results.append(res)

    return results

