def find_unsorted_subarray(arr):
    n = len(arr)
    if n <= 1:
        return 0

    # Step 1: Find the first index from the start where arr[i] > arr[i+1]
    start = 0
    while start < n - 1 and arr[start] <= arr[start + 1]:
        start += 1

    if start == n - 1:
        return 0  # array is already sorted

    # Step 2: Find the first index from the end where arr[i] < arr[i-1]
    end = n - 1
    while end > 0 and arr[end] >= arr[end - 1]:
        end -= 1

    # Step 3: Find min and max in the unsorted subarray
    sub_min = min(arr[start:end + 1])
    sub_max = max(arr[start:end + 1])

    # Step 4: Extend the subarray to include out-of-order elements
    while start > 0 and arr[start - 1] > sub_min:
        start -= 1

    while end < n - 1 and arr[end + 1] < sub_max:
        end += 1

    return end - start + 1

