def minimize_absolute_differences(nums):
    nums.sort()
    n = len(nums)

    if n % 2 == 1:
        median = nums[n // 2]
    else:
        median = (nums[n // 2 - 1] + nums[n // 2]) / 2

    total_diff = sum(abs(num - median) for num in nums)
    return total_diff

