def min_cost_path(matrix):
    if not matrix or not matrix[0]:
        return 0

    rows, cols = len(matrix), len(matrix[0])

    # Initialize a DP table with the same dimensions as the matrix
    dp = [[0] * cols for _ in range(rows)]

    # Base case: starting point
    dp[0][0] = matrix[0][0]

    # Fill the first row (can only move right)
    for j in range(1, cols):
        dp[0][j] = dp[0][j - 1] + matrix[0][j]

    # Fill the first column (can only move down)
    for i in range(1, rows):
        dp[i][0] = dp[i - 1][0] + matrix[i][0]

    # Fill the rest of the DP table
    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = matrix[i][j] + min(dp[i - 1][j], dp[i][j - 1])

    # The result is in the bottom-right corner
    return dp[rows - 1][cols - 1]

def dynamic_array_operations(operations):
    arr = []
    results = []

    for op in operations:
        parts = op.split()
        if parts[0] == 'insert':
            x = int(parts[1])
            y = int(parts[2])
            if y > len(arr):
                arr.append(x)
            else:
                arr.insert(y - 1, x)
        elif parts[0] == 'sum':
            x = int(parts[1])
            y = int(parts[2])
            if x < 1 or y < 1 or x > len(arr) or y > len(arr):
                results.append(-1)
            else:
                total = sum(arr[x - 1:y])
                results.append(total)

    return results

