def can_transform(A, B):
    # If the lengths differ by more than 1, transformation is not possible
    if len(B) - len(A) != 1:
        return "NO"

    # Pointers for A and B
    i, j = 0, 0

    # Traverse both strings
    while i < len(A) and j < len(B):
        if A[i] == B[j]:
            i += 1
            j += 1
        else:
            # Insert one character in A, so we move j forward
            j += 1

    # If we reached the end of A, then it's valid
    return "YES" if i == len(A) else "NO"

