import math

def count_paths(m, n):
    # We need to compute the number of ways to choose (m-1) steps to move down
    # out of (m-1 + n-1) = m + n - 2 total steps
    return math.comb(m + n - 2, m - 1)

def int_to_roman(num: int) -> str:
    if not (1 <= num <= 3999):
        raise ValueError("Number must be between 1 and 3999 inclusive.")

    # Mapping of integers to Roman numerals
    val = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'),
        (1, 'I')
    ]

    roman_num = ''
    for (value, symbol) in val:
        while num >= value:
            roman_num += symbol
            num -= value

    return f"The number {num} in Roman numerals is {roman_num}!"

