def lexicographically_smallest_string(s, x):
    stack = []
    for char in s:
        while stack and x > 0 and stack[-1] > char:
            stack.pop()
            x -= 1
        stack.append(char)

    # If we still have removals left, remove from the end
    if x > 0:
        stack = stack[:-x]

    return ''.join(stack)

