from typing import List

def max_popularity_score(n: int, durations: List[int], popularity_scores: List[int], D: int) -> int:
    # Initialize a DP array where dp[t] represents the max popularity score with duration t
    dp = [0] * (D + 1)

    for i in range(n):
        duration = durations[i]
        popularity = popularity_scores[i]

        # Update the dp array from back to front to prevent reusing the same song
        for t in range(D, duration - 1, -1):
            dp[t] = max(dp[t], dp[t - duration] + popularity)

    # The maximum value in dp[0...D] is the result
    return max(dp)

