def check_divisibility(N, K, sequence, queries):
    # Compute prefix sums modulo K
    prefix_mod = [0] * (N + 1)  # index 0 to N
    for i in range(1, N + 1):
        prefix_mod[i] = (prefix_mod[i - 1] + sequence[i - 1]) % K

    # Process each query
    results = []
    for l, r in queries:
        if prefix_mod[r] == prefix_mod[l - 1]:
            results.append("YES")
        else:
            results.append("NO")

    return results

