import string

def can_form_palindrome(s):
    # Step 1: Clean the string by removing non-alphanumeric characters and convert to lowercase
    cleaned = ''.join(char.lower() for char in s if char.isalnum())

    # Step 2: Count frequency of each character
    char_count = {}
    for char in cleaned:
        char_count[char] = char_count.get(char, 0) + 1

    # Step 3: Count how many characters have odd frequencies
    odd_count = sum(1 for count in char_count.values() if count % 2 != 0)

    # Step 4: Check the palindrome condition based on the length of the cleaned string
    if len(cleaned) % 2 == 0:
        return odd_count == 0
    else:
        return odd_count == 1

