    if total_sum != 2 * target:
        return False

    # Use a set to keep track of all achievable sums
    achievable_sums = {0}
    for num in arr:
        new_sums = set()
        for s in achievable_sums:
            new_sums.add(s + num)
        achievable_sums.update(new_sums)

    return target in achievable_sums

