def can_form_palindrome(s):
    from collections import Counter

    # Count the frequency of each character
    freq = Counter(s)

    # Count how many characters have odd frequency
    odd_count = sum(1 for count in freq.values() if count % 2 != 0)

    # If more than one character has odd count, not possible
    if odd_count > 1:
        return ""

    # Prepare left and middle parts
    left = []
    middle = ""
    for char, count in freq.items():
        if count % 2 == 0:
            left.append(char * (count // 2))
        else:
            middle = char
            left.append(char * (count // 2))

    # Build the palindrome: left + middle + reversed left
    return "".join(left) + middle + "".join(reversed(left))

