def lexicographically_smallest_subsequence(s, k):
    stack = []
    n = len(s)

    for i, ch in enumerate(s):
        # While the stack is not empty, and the current character is smaller than the top of the stack
        # and we can still remove characters (i.e., len(stack) - 1 + (n - i) >= k)
        while stack and ch < stack[-1] and len(stack) - 1 + (n - i) >= k:
            stack.pop()
        stack.append(ch)

    # Return the first k characters from the stack
    return ''.join(stack[:k])

