from typing import List, Tuple

def constrained_shortest_path(adj_matrix: List[List[int]], max_edges: int) -> Tuple[int, List[int]]:
    n = len(adj_matrix)
    INF = float('inf')

    # Initialize DP table
    # dp[node][edges_used] = (cost, path)
    dp = [[(INF, []) for _ in range(max_edges + 1)] for _ in range(n)]
    dp[0][0] = (0, [0])  # Starting at node 0 with 0 edges used

    # Fill DP using dynamic programming
    for e in range(1, max_edges + 1):
        for u in range(n):
            for v in range(n):
                if adj_matrix[u][v] != INF and dp[u][e - 1][0] < INF:
                    new_cost = dp[u][e - 1][0] + adj_matrix[u][v]
                    if new_cost < dp[v][e][0]:
                        dp[v][e] = (new_cost, dp[u][e - 1][1] + [v])

    # Find the minimum cost path using at most max_edges edges
    min_cost = INF
    min_path = []
    for e in range(max_edges + 1):
        if dp[n - 1][e][0] < min_cost:
            min_cost = dp[n - 1][e][0]
            min_path = dp[n - 1][e][1]

    return (min_cost, min_path if min_cost != INF else [])

