def divide(dividend, divisor):
    # Handle edge cases
    if dividend == 0:
        return (0, 0)

    # Determine the sign of the result
    negative = (dividend < 0) != (divisor < 0)

    # Work with absolute values
    dividend, divisor = abs(dividend), abs(divisor)

    quotient = 0
    remainder = dividend

    # Use bit shifting to find the largest multiple of divisor less than or equal to dividend
    while divisor <= remainder:
        temp = divisor
        multiple = 1
        while temp <= remainder:
            temp <<= 1
            multiple <<= 1
        remainder -= temp >> 1
        quotient += multiple >> 1

    # Adjust the sign
    if negative:
        quotient = -quotient

    return (quotient, remainder)

