def process_operations(p, operations):
    # Max heap for lower half (using negative numbers to simulate max heap in Python)
    lower_half = []
    # Min heap for upper half
    upper_half = []

    results = []

    for op in operations:
        if op[0] == 1:
            x = op[1]
            # Insert into appropriate heap
            if not lower_half or x <= -lower_half[0]:
                heappush(lower_half, -x)
            else:
                heappush(upper_half, x)

            # Rebalance the heaps
            if len(lower_half) > len(upper_half) + 1:
                heappush(upper_half, -heappop(lower_half))
            elif len(upper_half) > len(lower_half):
                heappush(lower_half, -heappop(upper_half))

        elif op[0] == 2:
            # Median is the top of the lower half (max heap)
            results.append(-lower_half[0])

    return results

