import heapq

def shortest_longest_delivery_time(n, m, edges, s):
    # Build the adjacency list
    graph = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm
    dist = [float('inf')] * (n + 1)
    dist[s] = 0
    heap = [(0, s)]

    while heap:
        current_dist, u = heapq.heappop(heap)
        if current_dist > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))

    # Check for unreachable nodes
    max_time = -1
    for i in range(1, n + 1):
        if dist[i] == float('inf'):
            return "UNREACHABLE"
        max_time = max(max_time, dist[i])

    return max_time

