                row_sum += grid[i][j]
                prefix[i + 1][j + 1] = prefix[i][j + 1] + row_sum

        max_sum = 0
        # Iterate over all k x k subgrids
        for i in range(n - k + 1):
            for j in range(m - k + 1):
                # Calculate sum of the k x k subgrid
                total = prefix[i + k][j + k] - prefix[i][j + k] - prefix[i + k][j] + prefix[i][j]
                if total > max_sum:
                    max_sum = total
        results.append(max_sum)
    return results

