def minOperations(num1, num2):
    operations = 0

    while num1 > 0 and num2 > 0:
        # Find the largest power of 2 less than or equal to num1
        k = num1.bit_length() - 1
        power_of_two = 1 << k  # Equivalent to 2^k

        num1 -= power_of_two
        num2 -= 1
        operations += 1

    if num1 == 0:
        return operations
    else:
        return -1

