def lexicographically_smallest_string(S):
    n = len(S)
    min_string = S  # Initialize with the original string

    for i in range(n):
        # Move the substring from index i to the end to the front
        new_string = S[i:] + S[:i]
        if new_string < min_string:
            min_string = new_string

    return min_string

