import heapq

def find_shortest_travel_time(edges, src, dst):
    # Build the adjacency list
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append((v, w))

    # Dijkstra's algorithm
    min_heap = [(0, src)]  # (current_time, station)
    shortest_time = {src: 0}

    while min_heap:
        time, node = heapq.heappop(min_heap)

        if node == dst:
            return time

        if time > shortest_time.get(node, float('inf')):
            continue

        for neighbor, weight in graph.get(node, []):
            new_time = time + weight
            if new_time < shortest_time.get(neighbor, float('inf')):
                shortest_time[neighbor] = new_time
                heapq.heappush(min_heap, (new_time, neighbor))

    # If we reach here, there's no path from src to dst
    return -1

