def maxConsecutiveOnes(s: str, k: int) -> int:
    left = 0
    max_length = 0
    zero_count = 0

    for right in range(len(s)):
        if s[right] == '0':
            zero_count += 1

        # If zero_count exceeds k, move the left pointer to the right
        while zero_count > k:
            if s[left] == '0':
                zero_count -= 1
            left += 1

        # Update the maximum window size
        max_length = max(max_length, right - left + 1)

    return max_length

