            # Ensure the smaller number comes first
            if num < complement:
                pairs.add((num, complement))
            else:
                pairs.add((complement, num))
        seen.add(num)

    # Convert the set of tuples to a list of lists and sort by the first element
    return [list(pair) for pair in sorted(pairs)]

