def unique_paths_with_obstacles(n, grid):
    MOD = 10**9 + 7

    # Initialize a DP table
    dp = [[0] * n for _ in range(n)]

    # Check if the starting cell is an obstacle
    if grid[0][0] == '#':
        return 0
    dp[0][0] = 1

    # Fill the first row
    for j in range(1, n):
        if grid[0][j] == '#':
            dp[0][j] = 0
        else:
            dp[0][j] = dp[0][j-1]

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == '#':
            dp[i][0] = 0
        else:
            dp[i][0] = dp[i-1][0]

    # Fill the rest of the dp table
    for i in range(1, n):
        for j in range(1, n):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                dp[i][j] = (dp[i-1][j] + dp[i][j-1]) % MOD

    return dp[n-1][n-1]

