def remove_duplicates(s: str) -> str:
    last_occurrence = {}  # Keep track of the last index of each character
    for i, c in enumerate(s):
        last_occurrence[c] = i  # Update last occurrence of each character

    stack = []
    visited = set()  # To keep track of characters in the stack

    for i, c in enumerate(s):
        if c in visited:
            continue  # Skip if we've already added this character

        # Pop from stack if the current character is smaller and the top of stack appears later
        while stack and c < stack[-1] and last_occurrence[stack[-1]] > i:
            visited.remove(stack.pop())

        stack.append(c)
        visited.add(c)

    return ''.join(stack)

