def is_scramble(s1: str, s2: str) -> bool:
    from functools import lru_cache

    @lru_cache(None)
    def dp(s1, s2):
        if s1 == s2:
            return True
        if len(s1) != len(s2):
            return False
        n = len(s1)
        # Check if sorted versions are equal (basic check for scramble possibility)
        if sorted(s1) != sorted(s2):
            return False
        # Try all possible splits
        for i in range(1, n):
            if (dp(s1[:i], s2[:i]) and dp(s1[i:], s2[i:])) or \
               (dp(s1[:i], s2[n-i:]) and dp(s1[i:], s2[:n-i])):
                return True
        return False

    return dp(s1, s2)

