from collections import defaultdict
from math import comb

def count_vertical_pairs(points):
    x_coords = defaultdict(int)

    # Count occurrences of each x-coordinate
    for x, y in points:
        x_coords[x] += 1

    # For each x-coordinate with at least 2 points, compute combinations of 2
    total_pairs = 0
    for count in x_coords.values():
        if count >= 2:
            total_pairs += comb(count, 2)

    return total_pairs

