def longest_common_subsequence_length(n, m, A, B):
    # Create a 2D DP table with (n+1) rows and (m+1) columns
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if A[i - 1] == B[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The result is in the bottom-right cell
    return dp[n][m]

