def longest_substring_with_k_distinct(t, k):
    if k == 0 or not t:
        return ""

    char_map = {}
    left = 0
    max_length = 0
    result = ""

    for right in range(len(t)):
        char = t[right]
        char_map[char] = right  # Maintain the rightmost index of the character

        # If the number of distinct characters exceeds k, move the left pointer
        while len(char_map) > k:
            leftmost_char = t[left]
            if char_map[leftmost_char] == left:
                del char_map[leftmost_char]
            left += 1

        # Update result if current window is longer
        if right - left + 1 > max_length:
            max_length = right - left + 1
            result = t[left:right + 1]

    return result

