def min_subset_difference(n, arr):
    total_sum = sum(arr)
    dp = [False] * (total_sum + 1)
    dp[0] = True  # Base case: sum 0 is always possible

    for num in arr:
        for i in range(total_sum, num - 1, -1):
            if dp[i - num]:
                dp[i] = True

    # Find the largest possible sum <= total_sum / 2
    for i in range(total_sum // 2, -1, -1):
        if dp[i]:
            return total_sum - 2 * i

    return total_sum  # This line is theoretically unreachable for n >= 1

