from collections import Counter

def can_partition_into_equal_sum_pairs(nums):
    n = len(nums) // 2
    total_sum = sum(nums)

    # If total sum is not divisible by n, then we can't have equal sum pairs
    if total_sum % n != 0:
        return False

    target_sum = total_sum // n
    freq = Counter(nums)

    # Check if all numbers appear exactly twice
    for count in freq.values():
        if count != 2:
            return False

    # Try to form pairs with sum equal to target_sum
    used = set()
    for num in nums:
        if num in used:
            continue
        complement = target_sum - num
        if freq[num] == 0 or freq[complement] == 0:
            return False
        if num == complement:
            if freq[num] < 2:
                return False
            freq[num] -= 2
        else:
            freq[num] -= 1
            freq[complement] -= 1
        used.add(num)
        used.add(complement)

    return True

