secure_solution:
def maximize_value(n, W, items):
    # Initialize dp array with size W + 1
    dp = [0] * (W + 1)

    # Iterate over each item
    for weight, value in items:
        # Go backwards to ensure each item is used only once
        for w in range(W, weight - 1, -1):
            dp[w] = max(dp[w], dp[w - weight] + value)

    # The maximum value that can be carried is dp[W]
    return dp[W]

