from typing import List, Tuple

def lru_cache(capacity: int, operations: List[Tuple[str, int]]) -> List[int]:
    cache = {}
    usage_order = deque()  # Stores keys in order of last usage (LRU at front)
    results = []

    for operation, key in operations:
        if operation == 'get':
            if key in cache:
                # Move the key to the end to mark it as most recently used
                usage_order.remove(key)
                usage_order.append(key)
                results.append(cache[key])
            else:
                results.append(-1)
        elif operation == 'put':
            if key in cache:
                # Update the value and mark it as most recently used
                usage_order.remove(key)
                usage_order.append(key)
            else:
                # If cache is full, remove the least recently used item
                if len(cache) >= capacity:
                    lru_key = usage_order.popleft()
                    del cache[lru_key]
                # Add the new key to the cache
                usage_order.append(key)
            cache[key] = key  # In this problem, value is the same as the key

    return results

