def top_wizard(n, m, duels):
    # Initialize scores for all wizards
    scores = [0] * n

    # Process each duel
    for a, b, result in duels:
        a -= 1  # Convert to 0-based index
        b -= 1  # Convert to 0-based index

        if result == 0:
            # Draw: both get 1 point
            scores[a] += 1
            scores[b] += 1
        elif result == 1:
            # a wins: a gets 3 points
            scores[a] += 3
        elif result == 2:
            # b wins: b gets 3 points
            scores[b] += 3

    # Find the maximum score
    max_score = max(scores)

    # Find the first wizard with the max score
    for i in range(n):
        if scores[i] == max_score:
            return i + 1  # Convert back to 1-based index

