def transform_string(s):
    vowels = 'aeiou'
    result = []
    for char in s:
        if char in vowels:
            # Find the next vowel in the sequence
            index = vowels.index(char)
            next_vowel = vowels[(index + 1) % 5]
            result.append(next_vowel)
        else:
            result.append(char)
    return ''.join(result)

