def is_valid_parentheses(sequence):
    # Mapping of closing brackets to their corresponding opening brackets
    bracket_map = {')': '(', '}': '{', ']': '['}

    # Use a stack to keep track of opening brackets
    stack = []

    for char in sequence:
        if char in bracket_map.values():
            # If it's an opening bracket, push it onto the stack
            stack.append(char)
        elif char in bracket_map:
            # If it's a closing bracket, check if the stack is not empty and
            # the top of the stack matches the corresponding opening bracket
            if not stack or stack[-1] != bracket_map[char]:
                return "NO"
            stack.pop()

    # If the stack is empty, all opening brackets were matched
    return "YES" if not stack else "NO"

