from typing import List

def find_max_average_subarray(arr: List[int], k: int) -> float:
    # Edge case: if k is equal to the length of the array
    if k == len(arr):
        return sum(arr) / k

    max_sum = current_sum = sum(arr[:k])

    for i in range(k, len(arr)):
        current_sum += arr[i] - arr[i - k]
        max_sum = max(max_sum, current_sum)

    return max_sum / k

