        return [1, 3, 2]

    # Build a permutation by placing odd numbers first, then even numbers
    permutation = []

    # Start with 1
    permutation.append(1)

    # Add odd numbers greater than 1
    for i in range(3, n + 1, 2):
        permutation.append(i)

    # Add even numbers
    for i in range(2, n + 1, 2):
        permutation.append(i)

    # Check if the permutation is valid (only for safety, since the logic guarantees it)
    for i in range(len(permutation) - 1):
        if gcd(permutation[i], permutation[i + 1]) != 1:
            return -1

    return permutation


def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

