import heapq
from collections import defaultdict

def network_delay_time(times: list, n: int, k: int) -> int:
    # Build the adjacency list
    graph = defaultdict(list)
    for u, v, w in times:
        graph[u].append((v, w))

    # Dijkstra's algorithm
    min_heap = [(0, k)]
    shortest_times = {}

    while min_heap:
        time, node = heapq.heappop(min_heap)

        # If this node was already processed with a shorter time, skip
        if node in shortest_times:
            continue

        # Record the shortest time to reach this node
        shortest_times[node] = time

        # Explore all neighbors
        for neighbor, weight in graph[node]:
            if neighbor not in shortest_times:
                heapq.heappush(min_heap, (time + weight, neighbor))

    # If we have not reached all nodes, return -1
    if len(shortest_times) != n:
        return -1

    # If only one node, return 0 since no delay is needed
    if n == 1:
        return 0

    # Return the maximum delay time among all reachable nodes
    return max(shortest_times.values())

