def longest_contiguous_ones(n, s):
    left = 0
    max_length = 0
    zero_count = 0

    for right in range(n):
        if s[right] == '0':
            zero_count += 1

        # Shrink the window if zero_count exceeds 1
        while zero_count > 1:
            if s[left] == '0':
                zero_count -= 1
            left += 1

        # Update the maximum length of the window
        max_length = max(max_length, right - left + 1)

    return max_length

