def fibonacci_last_digit(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1

    # Pisano period for modulo 10 is 60
    n = n % 60

    # Compute the last digit of F(n)
    a, b = 0, 1
    for _ in range(n):
        a, b = b, (a + b) % 10

    return a

