def shift_string(s, k):
    result = []
    k = k % 26  # Reduce k to its effective shift within the alphabet
    for char in s:
        if char.isalpha():
            # Determine the base ASCII value ('A' or 'a')
            base = ord('A') if char.isupper() else ord('a')
            # Shift the character and wrap around using modulo
            shifted = chr((ord(char) - base + k) % 26 + base)
            result.append(shifted)
        else:
            # Non-alphabetic characters remain unchanged
            result.append(char)
    return ''.join(result)

