def count_interesting_sections(n, k, grid):
    count = 0
    # Iterate over all possible top-left corners of subgrids
    for i in range(n):
        for j in range(n):
            # Iterate over all possible bottom-right corners of subgrids starting from (i, j)
            for x in range(i, n):
                for y in range(j, n):
                    # Extract the subgrid from (i, j) to (x, y)
                    subgrid = [row[j:y+1] for row in grid[i:x+1]]
                    # Flatten the subgrid to find min and max values
                    min_val = min(val for row in subgrid for val in row)
                    max_val = max(val for row in subgrid for val in row)
                    if max_val - min_val <= k:
                        count += 1
    return count

