def longest_growth_spurt(n, k, heights):
    max_length = 0
    current_length = 1  # At least 1 day if we consider a single day

    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            current_length += 1
        else:
            current_length = 1  # Reset the counter if the growth is broken

        # Update the maximum length if current_length is greater than the previous maximum
        if current_length > max_length:
            max_length = current_length

    # If the longest streak is at least k days, return it, else return 0
    return max_length if max_length >= k else 0

