def maxCoins(grid):
    # Get the number of rows and columns
    rows = len(grid)
    cols = len(grid[0])

    # Update the grid in place to store the maximum coins collected up to each cell
    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                continue  # Starting point, no coins collected before
            elif i == 0:
                grid[i][j] += grid[i][j - 1]  # Only come from the left
            elif j == 0:
                grid[i][j] += grid[i - 1][j]  # Only come from above
            else:
                grid[i][j] += max(grid[i - 1][j], grid[i][j - 1])  # Max of up or left

    # Return the maximum coins collected at the bottom-right corner
    return grid[-1][-1]

