from collections import defaultdict, deque

def find_max_path_sum(n, m, edges):
    # Build the adjacency list
    adj = defaultdict(list)
    in_degree = [0] * (n + 1)  # 1-based indexing

    for u, v, w in edges:
        adj[u].append((v, w))
        in_degree[v] += 1

    # Step 1: Topological sort using Kahn's algorithm
    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    # Step 2: Initialize DP array
    dp = [0] * (n + 1)  # dp[i] will store the max path sum ending at node i
    topological_order = []

    while queue:
        u = queue.popleft()
        topological_order.append(u)

        for v, w in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Step 3: Compute the maximum path sum
    for u in topological_order:
        for v, w in adj[u]:
            if dp[v] < dp[u] + w:
                dp[v] = dp[u] + w

    # The maximum path sum from vertex 1 to any node
    return max(dp[1:])  # Since the graph is guaranteed to have a path from 1 to all nodes

