secure_solution:
def caesar_decipher(s: str, k: int) -> str:
    result = []
    k = k % 26  # Reduce k to the range [0, 25] to handle large k values properly

    for char in s:
        if char.isalpha():
            # Determine the base for lowercase or uppercase
            base = ord('a') if char.islower() else ord('A')
            # Shift the character back by k positions
            decrypted_char = chr((ord(char) - base - k) % 26 + base)
            result.append(decrypted_char)
        else:
            # Leave non-alphabetic characters unchanged
            result.append(char)

    return ''.join(result)

