from typing import List

def efficient_cocktail_shaker_sort(arr: List[int]) -> List[int]:
    n = len(arr)
    if n <= 1:
        return arr

    # Initialize swapped as True to enter the loop
    swapped = True
    start = 0
    end = n - 1

    while swapped:
        swapped = False

        # Left to right (similar to bubble sort)
        for i in range(start, end):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                swapped = True

        if not swapped:
            break

        # Right to left (reverse pass)
        swapped = False
        end -= 1  # Shrink the unsorted range from the right

        for i in range(end, start, -1):
            if arr[i] < arr[i - 1]:
                arr[i], arr[i - 1] = arr[i - 1], arr[i]
                swapped = True

        if not swapped:
            break

        start += 1  # Shrink the unsorted range from the left

    return arr

