def calculate_weighted_ratings(products, ratings):
    # Initialize a dictionary to store the weighted ratings for each product
    weighted_ratings = {product: [0.0, 0.0] for product in products}  # [total_weighted_score, total_weight]

    # Iterate through each rating and update the weighted ratings
    for rating in ratings:
        scores = rating[0]
        weight = rating[1]

        for i, score in enumerate(scores):
            product = products[i]
            weighted_ratings[product][0] += score * weight
            weighted_ratings[product][1] += weight

    # Calculate the final weighted average and round to nearest integer
    result = {}
    for product in products:
        total_weighted_score = weighted_ratings[product][0]
        total_weight = weighted_ratings[product][1]
        if total_weight == 0:
            result[product] = 0
        else:
            average = total_weighted_score / total_weight
            result[product] = round(average)

    return result

