def find_median_word(n, words):
    # Sort the words lexicographically
    sorted_words = sorted(words)

    # Determine the index of the median word
    if n % 2 == 1:
        median_index = n // 2
    else:
        median_index = (n // 2) - 1  # Take the word before the middle for even length

    # Return the median word
    return sorted_words[median_index]

