import math
from functools import reduce

def max_gcd_after_removal(n, arr):
    def compute_gcd(list_nums):
        return reduce(math.gcd, list_nums, 0)

    prefix = [0] * n
    suffix = [0] * n

    prefix[0] = arr[0]
    for i in range(1, n):
        prefix[i] = math.gcd(prefix[i - 1], arr[i])

    suffix[n - 1] = arr[n - 1]
    for i in range(n - 2, -1, -1):
        suffix[i] = math.gcd(suffix[i + 1], arr[i])

    max_gcd = 0
    for i in range(n):
        if i == 0:
            current_gcd = suffix[1]
        elif i == n - 1:
            current_gcd = prefix[n - 2]
        else:
            current_gcd = math.gcd(prefix[i - 1], suffix[i + 1])
        max_gcd = max(max_gcd, current_gcd)

    return max_gcd

