def intersect_sorted_arrays(array1, array2):
    # Initialize pointers for both arrays
    i, j = 0, 0
    result = []

    # Traverse both arrays
    while i < len(array1) and j < len(array2):
        # If elements are equal, add to result (only once)
        if array1[i] == array2[j]:
            # Check if the element is already in result to ensure uniqueness
            if not result or result[-1] != array1[i]:
                result.append(array1[i])
            i += 1
            j += 1
        # Move the pointer with the smaller element
        elif array1[i] < array2[j]:
            i += 1
        else:
            j += 1

    return result

