def canPartition(n, arr):
    total_sum = sum(arr)
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    dp = [[False] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for s in range(target + 1):
            if dp[i - 1][s]:
                dp[i][s] = True
                if s + arr[i - 1] <= target:
                    dp[i][s + arr[i - 1]] = True

    return dp[n][target]

