from typing import List

def min_difference_partition(nums: List[int]) -> int:
    total_sum = sum(nums)
    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum of 0 is always possible

    for num in nums:
        for j in range(target, num - 1, -1):
            if dp[j - num]:
                dp[j] = True

    # Find the maximum sum <= target that can be formed
    max_subset_sum = 0
    for i in range(target, -1, -1):
        if dp[i]:
            max_subset_sum = i
            break

    return total_sum - 2 * max_subset_sum

