def unique_substrings(s: str, k: int) -> List[str]:
    if k > len(s) or k < 1:
        return []

    seen = set()
    result = []

    for i in range(len(s) - k + 1):
        substring = s[i:i + k]
        if substring not in seen:
            seen.add(substring)
            result.append(substring)

    return sorted(result)

