            count += 1
            last_end_time = end

    return count

import heapq

def trap_rain_water(height_map):
    if not height_map or not height_map[0]:
        return 0

    m, n = len(height_map), len(height_map[0])
    visited = [[False] * n for _ in range(m)]
    min_heap = []

    # Initialize the heap with boundary cells
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(min_heap, (height_map[i][j], i, j))
                visited[i][j] = True

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    trapped_water = 0

    while min_heap:
        height, x, y = heapq.heappop(min_heap)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                # The current height is the minimum boundary, so water can be trapped
                if height_map[nx][ny] < height:
                    trapped_water += height - height_map[nx][ny]
                # Push the new cell to the heap with the updated boundary height
                heapq.heappush(min_heap, (max(height, height_map[nx][ny]), nx, ny))

    return trapped_water

