def knapsack(n, W, items):
    # Initialize a DP array with size W + 1 (since weights can be 0 to W)
    dp = [0] * (W + 1)

    # Iterate over each item
    for weight, value in items:
        # Traverse the dp array in reverse to prevent reuse of the same item
        for w in range(W, weight - 1, -1):
            dp[w] = max(dp[w], dp[w - weight] + value)

    # The result is the maximum value achievable with weight up to W
    return dp[W]

