def is_even_sum_subarray(n, k, a):
    # Calculate the sum of the first window of size k
    current_sum = sum(a[:k])

    # If the sum is even, return "YES"
    if current_sum % 2 == 0:
        return "YES"

    # Slide the window across the array
    for i in range(k, n):
        current_sum += a[i] - a[i - k]
        if current_sum % 2 == 0:
            return "YES"

    # If no even sum subarray found
    return "NO"

