from typing import List

def is_subset_sum_possible(arr: List[int], S: int) -> bool:
    # Edge case: if the target sum is zero, it's always possible (empty subset)
    if S == 0:
        return True

    # Edge case: if array is empty and sum is not zero
    if not arr:
        return False

    # Create a DP array
    dp = [False] * (S + 1)
    dp[0] = True  # Subset sum of 0 is always possible (empty subset)

    # Update the dp array for each number in the array
    for num in arr:
        # Make sure the number is not larger than the target
        if num > S:
            continue
        # Update dp from S down to num to avoid reusing the same element
        for j in range(S, num - 1, -1):
            if dp[j - num]:
                dp[j] = True

    return dp[S]

