def maximal_rectangle(grid):
    if not grid or not grid[0]:
        return 0

    h, w = len(grid), len(grid[0])
    heights = [0] * w
    max_area = 0

    for row in range(h):
        for col in range(w):
            if grid[row][col] == '1':
                heights[col] += 1
            else:
                heights[col] = 0

        # Now compute the largest rectangle in histogram
        stack = []
        for i in range(w):
            while stack and heights[i] < heights[stack[-1]]:
                height = heights[stack.pop()]
                width = i if not stack else i - stack[-1] - 1
                max_area = max(max_area, height * width)
            stack.append(i)

        # After processing the row, check if stack has remaining elements
        while stack:
            height = heights[stack.pop()]
            width = w if not stack else w - stack[-1] - 1
            max_area = max(max_area, height * width)

    return max_area

