from typing import List, Dict

def digit_occurrence_count(numbers: List[int]) -> Dict[int, int]:
    # Initialize the count dictionary for digits 0-9
    count: Dict[int, int] = {digit: 0 for digit in range(10)}

    for number in numbers:
        # Take absolute value to handle negative numbers
        num = abs(number)

        # Convert the number to a string to iterate over its digits
        for ch in str(num):
            digit = int(ch)
            count[digit] += 1

    return count

