def smallest_divisible_by_3(num):
    from collections import Counter
    import heapq

    digits = list(num)
    total = sum(int(d) for d in digits)

    if total % 3 == 0:
        # If sum is divisible by 3, sort the digits to get the smallest number
        return ''.join(sorted(digits)) if digits[0] != '0' else '0'

    # Total is not divisible by 3; try to remove digits to make the sum divisible by 3
    remainder = total % 3
    digits = [int(d) for d in digits]

    # Try to remove one digit that has a remainder of `remainder`
    candidates = [i for i, d in enumerate(digits) if d % 3 == remainder]
    if candidates:
        # Remove the smallest such digit (by value, to get the smallest number)
        min_idx = min(candidates, key=lambda i: digits[i])
        new_digits = digits[:min_idx] + digits[min_idx+1:]
        new_digits.sort()
        if new_digits and new_digits[0] != 0:
            return ''.join(map(str, new_digits))
        elif new_digits and new_digits[0] == 0:
            return '0'
        else:
            return '-1'

    # Try to remove two digits that each have remainder `(3 - remainder) % 3`
    candidates = [i for i, d in enumerate(digits) if d % 3 == (3 - remainder) % 3]
    if len(candidates) >= 2:
        # Remove two smallest such digits
        indices = sorted(candidates, key=lambda i: digits[i])[:2]
        new_digits = digits[:indices[0]] + digits[indices[0]+1:indices[1]] + digits[indices[1]+1:]
        new_digits.sort()
        if new_digits and new_digits[0] != 0:
            return ''.join(map(str, new_digits))
        elif new_digits and new_digits[0] == 0:
            return '0'
        else:
            return '-1'

    return '-1'

