def max_non_overlapping_tasks(tasks):
    # Step 1: Sort tasks by their end times
    tasks.sort(key=lambda x: x[1])

    count = 0
    last_end = 0

    for start, end in tasks:
        if start >= last_end:
            count += 1
            last_end = end

    return count

from typing import List

def find_all_ones_submatrix(n: int, m: int, matrix: List[List[int]], a: int, b: int) -> str:
    # Check if the dimensions of the matrix are sufficient to contain the submatrix
    if a > n or b > m:
        return "NO"

    # Iterate over all possible top-left corners of the a x b submatrix
    for i in range(n - a + 1):
        for j in range(m - b + 1):
            # Check if the submatrix starting at (i, j) has only 1s
            is_all_ones = True
            for x in range(a):
                for y in range(b):
                    if matrix[i + x][j + y] != 1:
                        is_all_ones = False
                        break
                if not is_all_ones:
                    break
            if is_all_ones:
                return "YES"

    return "NO"

