def unique_paths_with_obstacles(grid):
    n = len(grid)
    m = len(grid[0])

    # If the start or end is blocked, no path exists
    if grid[0][0] == 1 or grid[n-1][m-1] == 1:
        return 0

    # Initialize DP table with the same dimensions as grid
    dp = [[0 for _ in range(m)] for _ in range(n)]

    # Starting point has 1 path
    dp[0][0] = 1

    # Fill first row
    for j in range(1, m):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]
        else:
            dp[0][j] = 0  # obstacle, no path

    # Fill first column
    for i in range(1, n):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = 0  # obstacle, no path

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # obstacle, no path

    return dp[n-1][m-1]

