def max_candies(grid):
    n, m = len(grid), len(grid[0])
    dp = [[0] * m for _ in range(n)]

    # Initialize the first row
    for j in range(m):
        dp[0][j] = grid[0][j]

    # Fill the DP table
    for i in range(1, n):
        for j in range(m):
            # Possible moves: from (i-1, j-1), (i-1, j), (i-1, j+1)
            max_prev = 0
            for dj in [-1, 0, 1]:
                prev_j = j + dj
                if 0 <= prev_j < m:
                    max_prev = max(max_prev, dp[i-1][prev_j])
            dp[i][j] = grid[i][j] + max_prev

    # The answer is the maximum value in the last row
    return max(dp[-1])

