def min_cut_palindrome_partition(s):
    n = len(s)
    if n <= 1:
        return 0

    # Step 1: Precompute palindrome table
    is_pal = [[False] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if i == j:
                is_pal[i][j] = True
            elif s[i] == s[j]:
                if i + 1 > j - 1 or is_pal[i + 1][j - 1]:
                    is_pal[i][j] = True
            else:
                is_pal[i][j] = False

    # Step 2: Dynamic Programming to find min cuts
    dp = [0] * n
    for i in range(n):
        dp[i] = i  # Max cuts possible is i (each character is a separate cut)
        for j in range(i + 1):
            if is_pal[j][i]:
                if j == 0:
                    dp[i] = 0
                else:
                    dp[i] = min(dp[i], dp[j - 1] + 1)

    return dp[n - 1]

