def count_ladders(n, d, rods):
    def backtrack(index, current_sum):
        if current_sum == d:
            return 1
        if current_sum > d or index >= n:
            return 0
        # Include the current rod
        include = backtrack(index + 1, current_sum + rods[index])
        # Exclude the current rod
        exclude = backtrack(index + 1, current_sum)
        return include + exclude

    return backtrack(0, 0)

