import math

def calculate_total_effort(n, checkpoints):
    total_effort = 0.0
    for i in range(n - 1):
        x1, y1 = checkpoints[i]
        x2, y2 = checkpoints[i + 1]
        distance = math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)
        total_effort += distance
    return round(total_effort, 2)

