def check_travelers(a, b, r, travelers):
    results = []
    for x, y in travelers:
        # Calculate the squared distance from (x, y) to the center (a, b)
        dx = x - a
        dy = y - b
        distance_squared = dx * dx + dy * dy
        radius_squared = r * r

        if distance_squared < radius_squared:
            results.append("APPROVED")
        else:
            results.append("DENIED")
    return results

