from collections import Counter

def longest_subsequence_with_difference(n, sequence, d):
    if d == 0:
        # If d is 0, all elements must be the same to form a valid sequence
        return max(Counter(sequence).values(), default=0)

    freq = Counter(sequence)
    max_length = 0

    for num in freq:
        current = num
        length = 0
        while freq.get(current, 0) > 0:
            length += 1
            current += d
        max_length = max(max_length, length)

    return max_length

def max_different_items_collected(N, schedules):
    from collections import defaultdict

    # Create a dictionary that maps day to list of items offered by all shops
    day_to_items = defaultdict(list)

    # Populate the day_to_items dictionary
    for shop in schedules:
        k, *rest = shop
        for i in range(k):
            day, item = rest[2*i], rest[2*i + 1]
            day_to_items[day].append(item)

    # Greedily collect unique items
    unique_items = set()

    # Try to collect up to 7 days
    for day in range(1, 8):
        for item in day_to_items[day]:
            if item not in unique_items:
                unique_items.add(item)
                break

    return len(unique_items)

