def minPalindromicSplits(s: str) -> int:
    n = len(s)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0  # base case: no splits needed for empty string

    for i in range(1, n + 1):
        for j in range(i):
            if is_palindrome(s[j:i]):
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[n] - 1  # subtract 1 because we count splits, not substrings

