def min_adjacent_swaps(n, A, B):
    from bisect import bisect_left, insort

    # Map each value in B to its index
    index_map = {val: idx for idx, val in enumerate(B)}

    # Convert A to a list of indices according to B
    transformed = [index_map[val] for val in A]

    # Count the number of inversions in transformed list using a Binary Indexed Tree (Fenwick Tree)
    def count_inversions(arr):
        # Compress the indices to a smaller range
        sorted_unique = sorted(set(arr))
        rank = {v: i + 1 for i, v in enumerate(sorted_unique)}  # 1-based indexing
        compressed = [rank[x] for x in arr]

        # Fenwick Tree to count inversions
        class FenwickTree:
            def __init__(self, size):
                self.n = size
                self.tree = [0] * (self.n + 1)

            def update(self, index, delta):
                while index <= self.n:
                    self.tree[index] += delta
                    index += index & -index

            def query(self, index):
                res = 0
                while index > 0:
                    res += self.tree[index]
                    index -= index & -index
                return res

        max_rank = max(compressed)
        ft = FenwickTree(max_rank)
        inversions = 0

        for i in reversed(range(len(compressed))):
            inversions += ft.query(compressed[i] - 1)
            ft.update(compressed[i], 1)

        return inversions

    return count_inversions(transformed)

