def containsNearbyAlmostDuplicate(nums, k, t):
    if t < 0:
        return False  # t is non-negative per constraints

    buckets = {}
    bucket_size = t + 1

    for i in range(len(nums)):
        num = nums[i]
        bucket_id = num // bucket_size

        # Check if the same bucket exists
        if bucket_id in buckets:
            return True

        # Check adjacent buckets to handle possible overflow
        if (bucket_id - 1) in buckets and abs(num - buckets[bucket_id - 1]) <= t:
            return True
        if (bucket_id + 1) in buckets and abs(num - buckets[bucket_id + 1]) <= t:
            return True

        # Keep only the latest index within the window size k
        buckets[bucket_id] = num
        if i >= k:
            # Remove the element that is out of the window
            old_bucket_id = nums[i - k] // bucket_size
            if old_bucket_id in buckets and buckets[old_bucket_id] == nums[i - k]:
                del buckets[old_bucket_id]

    return False

