def max_area(heights):
    left = 0
    right = len(heights) - 1
    max_area = 0
    result = [0, 0]

    while left < right:
        current_area = (right - left) * min(heights[left], heights[right])
        if current_area > max_area or (current_area == max_area and (left < result[0] or (left == result[0] and right < result[1]))):
            max_area = current_area
            result = [left, right]

        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1

    return result

