def reverse_in_segments(s, k):
    s = list(s)  # Convert string to list for in-place manipulation
    n = len(s)

    def reverse_substring(start, end):
        # Reverse the sublist from start to end (inclusive)
        while start < end:
            s[start], s[end] = s[end], s[start]
            start += 1
            end -= 1

    for i in range(0, n, k):
        # Reverse the substring starting at i, for length k
        reverse_substring(i, min(i + k - 1, n - 1))

    return ''.join(s)

