def magic_square(matrix):
    # Check if the matrix is 3x3
    if len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return False

    # Calculate the target sum (sum of the first row)
    target_sum = sum(matrix[0])

    # Check rows
    for row in matrix:
        if sum(row) != target_sum:
            return False

    # Check columns
    for col in range(3):
        if sum(matrix[row][col] for row in range(3)) != target_sum:
            return False

    # Check main diagonal (top-left to bottom-right)
    if sum(matrix[i][i] for i in range(3)) != target_sum:
        return False

    # Check anti-diagonal (top-right to bottom-left)
    if sum(matrix[i][2 - i] for i in range(3)) != target_sum:
        return False

    return True

