def longest_equal_subarray(arr):
    count_map = {}
    count = 0
    max_length = 0

    for num in arr:
        # Treat 0 as -1 to convert the problem to finding the longest subarray with sum 0
        count += 1 if num == 1 else -1

        # If the count is 0, the subarray from index 0 to current index is valid
        if count == 0:
            max_length = len(arr)
        elif count in count_map:
            # The difference in indices gives the length of the subarray
            max_length = max(max_length, len(arr) - count_map[count])
        else:
            # Store the first occurrence of this count
            count_map[count] = len(arr)

    return max_length

