def decode_message(shift, encoded_message):
    result = ""
    for char in encoded_message:
        if char == " ":
            result += char
        else:
            # Shift the character back by the given amount
            # ord('A') = 65, so we subtract shift and wrap around using modulo
            original_char = chr((ord(char) - ord('A') - shift) % 26 + ord('A'))
            result += original_char
    return result

