            counts[value] = counts.get(value, 0) + 1
        elif sign == '-':
            counts[value] = counts.get(value, 0) - 1

    # Filter out values with zero count
    non_zero = [num for num, cnt in counts.items() if cnt != 0]

    if len(non_zero) == 1:
        return non_zero[0]
    else:
        return None

