def minimum_energy_to_reach_destination(n, m, dungeon):
    if n == 0 or m == 0:
        return -1

    # Initialize a DP table with the same dimensions as dungeon
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = dungeon[0][0]

    # Fill the first row
    for j in range(1, m):
        dp[0][j] = dp[0][j-1] + dungeon[0][j]

    # Fill the first column
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + dungeon[i][0]

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + dungeon[i][j]

    return dp[n-1][m-1] if dp[n-1][m-1] > 0 else -1

