from collections import deque

def bounded_shortest_path(graph, start_node, end_node, max_steps):
    if start_node == end_node:
        return [start_node]

    # Queue for BFS: (current_node, path, steps_taken)
    queue = deque([(start_node, [start_node], 0)])
    visited = set()

    while queue:
        current, path, steps = queue.popleft()

        if current == end_node:
            return path

        if steps >= max_steps:
            continue

        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor], steps + 1))

    return []

