def trap_rain_water(buildings):
    if not buildings or len(buildings) < 3:
        return 0

    left, right = 0, len(buildings) - 1
    max_left = max_right = 0
    water_trapped = 0

    while left < right:
        if buildings[left] < buildings[right]:
            if buildings[left] > max_left:
                max_left = buildings[left]
            else:
                water_trapped += max_left - buildings[left]
            left += 1
        else:
            if buildings[right] > max_right:
                max_right = buildings[right]
            else:
                water_trapped += max_right - buildings[right]
            right -= 1

    return water_trapped

