secure_solution:
def exists_subarray_with_mean_greater_than_threshold(n, d, t, arr):
    # Calculate the sum of the first window of size d
    current_sum = sum(arr[:d])

    # If the average of the first window is greater than t, return "YES"
    if current_sum / d > t:
        return "YES"

    # Slide the window across the array
    for i in range(1, n - d + 1):
        current_sum = current_sum - arr[i - 1] + arr[i + d - 1]
        if current_sum / d > t:
            return "YES"

    # If no such subarray is found, return "NO"
    return "NO"

