def max_rectangle_area(heights):
    if len(heights) < 2:
        return 0  # At least two trees are needed to form a rectangle

    max_area = 0
    left = 0
    right = len(heights) - 1

    while left < right:
        current_area = min(heights[left], heights[right]) * (right - left)
        max_area = max(max_area, current_area)

        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1

    return max_area

