def max_disjoint_interesting_substrings(S):
    used = set()
    count = 0
    i = 0
    while i < len(S):
        if S[i] not in used:
            used.add(S[i])
            i += 1
        else:
            # End of a valid interesting substring, reset
            count += 1
            used = set()
    # Count the last substring
    if used:
        count += 1
    return count

