def max_sum_of_consecutive_wands(n, powers):
    if n == 0:
        return 0

    max_sum = powers[0]
    current_sum = powers[0]
    start = 0

    for end in range(1, n):
        if powers[end] == powers[end - 1]:
            # Reset window
            start = end
            current_sum = powers[end]
        else:
            current_sum += powers[end]

        max_sum = max(max_sum, current_sum)

    return max_sum

