secure_solution:
def smallest_string_after_deletions(d, S):
    stack = []
    for char in S:
        while d > 0 and stack and stack[-1] > char:
            stack.pop()
            d -= 1
        stack.append(char)

    # If we still have deletions left, remove from the end
    if d > 0:
        stack = stack[:-d]

    return ''.join(stack)

