def has_hamiltonian_path(n, m, edges):
    # Build the adjacency list
    graph = [[] for _ in range(n + 1)]  # 1-based indexing

    for u, v in edges:
        graph[u].append(v)

    # Keep track of visited nodes
    visited = [False] * (n + 1)

    # Result variable
    result = [False]

    def dfs(node, count):
        # If we have visited all nodes, we found a Hamiltonian path
        if count == n:
            result[0] = True
            return

        visited[node] = True

        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, count + 1)

        visited[node] = False  # Backtrack

    # Try starting from each node
    for start in range(1, n + 1):
        dfs(start, 1)
        if result[0]:
            return "YES"

    return "NO"

