def is_rearrangement_divisible_by_k(sequence, k):
    # Generate all permutations of the digits in the sequence
    for perm in permutations(sequence):
        # Convert permutation to integer
        num = int(''.join(perm))
        # Check if it's divisible by k
        if num % k == 0:
            return 'Possible!'
