from typing import List

def max_subarray_sum(n: int, array: List[int]) -> int:
    if not array:
        return 0

    max_current = max_global = array[0]

    for num in array[1:]:
        max_current = max(num, max_current + num)
        max_global = max(max_global, max_current)

    return max_global

