def longest_ones(nums, k):
    left = 0
    max_length = 0
    zero_count = 0

    for right in range(len(nums)):
        if nums[right] == 0:
            zero_count += 1

        # If the number of zeros exceeds k, move the left pointer
        while zero_count > k:
            if nums[left] == 0:
                zero_count -= 1
            left += 1

        # Update the maximum length of the subarray
        max_length = max(max_length, right - left + 1)

    return max_length

