def find_min_difference(n, weights):
    total_sum = sum(weights)

    def backtrack(index, current_sum):
        if index == n:
            return abs(total_sum - 2 * current_sum)
        # Try including the current ball
        include = backtrack(index + 1, current_sum + weights[index])
        # Try excluding the current ball
        exclude = backtrack(index + 1, current_sum)
        return min(include, exclude)

    return backtrack(0, 0)

