from collections import deque, defaultdict

def find_transformation_path(start_word: str, end_word: str, word_list: list[str]) -> (int, list[str]):
    # Handle the case where end_word isn't in the word_list
    word_set = set(word_list)
    if end_word not in word_set:
        return (0, [])

    # If start_word is already the end_word, return length 1 and the path
    if start_word == end_word:
        return (1, [start_word])

    # Build a parent map to reconstruct the path
    parent = defaultdict(list)
    visited = set()

    # Queue stores (current_word, path)
    queue = deque([(start_word, [start_word])])
    visited.add(start_word)

    while queue:
        current_word, path = queue.popleft()

        # Generate all one-letter variations
        for i in range(len(current_word)):
            for c in "abcdefghijklmnopqrstuvwxyz":
                next_word = current_word[:i] + c + current_word[i+1:]

                if next_word in word_set and next_word not in visited:
                    visited.add(next_word)
                    parent[next_word] = path + [next_word]

                    if next_word == end_word:
                        return (len(parent[next_word]), parent[next_word])

                    queue.append((next_word, parent[next_word]))

    # If we exited the loop without returning, no path was found
    return (0, [])

