from collections import deque

def min_jumps(arr):
    n = len(arr)
    if n == 1:
        return 0  # Already at the end

    visited = [False] * n
    queue = deque([(0, 0)])  # (current index, jumps taken)
    visited[0] = True

    while queue:
        index, jumps = queue.popleft()

        # Try all possible jumps from current index
        for i in range(1, arr[index] + 1):
            next_index = index + i
            if next_index == n - 1:
                return jumps + 1
            if next_index < n and not visited[next_index]:
                visited[next_index] = True
                queue.append((next_index, jumps + 1))

    return -1

