def can_form_palindrome(s):
    # A string can form a palindrome if at most one character has an odd count
    char_count = {}

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Count how many characters have odd counts
    odd_count = sum(1 for count in char_count.values() if count % 2 != 0)

    # For even length strings, all counts must be even
    # For odd length strings, exactly one character can have an odd count
    return odd_count <= 1

