from collections import deque, defaultdict

def get_invite_list(n, m, friendships, k):
    # Build the adjacency list for the graph
    graph = defaultdict(list)
    for u, v in friendships:
        graph[u].append(v)
        graph[v].append(u)

    # Use BFS to find friends and friends of friends (up to 2 levels)
    visited = set()
    queue = deque()
    queue.append((k, 0))  # (user_id, depth)
    visited.add(k)

    while queue:
        user, depth = queue.popleft()
        if depth == 2:
            continue
        for neighbor in graph[user]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, depth + 1))

    # Remove the organizer's own ID and sort the result
    visited.remove(k)
    return sorted(visited)

