def findClosestElements(arr, k, x):
    left = 0
    right = len(arr) - 1

    # Binary search to find the position to insert x
    while left < right:
        mid = (left + right) // 2
        if arr[mid] < x:
            left = mid + 1
        else:
            right = mid

    # Now, left is the position where x would be inserted
    # Use two pointers to find the k closest elements
    left_result = 0
    right_result = len(arr) - 1

    while right_result - left_result + 1 > k:
        if x - arr[left_result] > arr[right_result] - x:
            left_result += 1
        else:
            right_result -= 1

    return arr[left_result:right_result + 1]

