def partitionLabels(s):
    last_occurrence = {}  # To store the last index of each character
    for i, char in enumerate(s):
        last_occurrence[char] = i

    result = []
    start, end = 0, 0

    for i, char in enumerate(s):
        end = max(end, last_occurrence[char])
        if i == end:
            result.append(end - start + 1)
            start = i + 1

    return result

