from typing import List
from collections import deque

def is_consecutive_with_queue(stack: List[int]) -> bool:
    if not stack:
        return True  # An empty stack is considered to have no consecutive constraints

    n = len(stack)
    queue = deque()

    # Step 1: Move all elements from stack to queue
    for num in stack:
        queue.append(num)

    # Step 2: Restore the stack and check for consecutive sequence
    for i in range(n):
        if i == 0:
            # First element, nothing to compare
            val = queue.popleft()
            stack[i] = val
        else:
            # Check if current element is one greater than the previous
            if queue:
                next_val = queue.popleft()
                if next_val != stack[i - 1] + 1:
                    return False
                stack[i] = next_val
            else:
                return False  # Not enough elements in queue

    return True

