MOD = 10**9 + 7

def count_necklaces(c, k):
    if k == 0:
        return 0
    if k == 1:
        return c % MOD

    # dp[i] = number of valid sequences of length i
    dp = [0] * (k + 1)
    dp[1] = c % MOD

    for i in range(2, k + 1):
        dp[i] = ((c - 1) * dp[i - 1]) % MOD

    return dp[k]

