def is_valid_expression(expr):
    if not expr:
        return False

    operators = {'+', '-', '*', '/'}
    i = 0

    # Rule 1: It must not start with an operator
    if expr[0] in operators:
        return False

    while i < len(expr):
        # Check if the current character is a digit
        if expr[i].isdigit():
            # Check for leading zero in multi-digit numbers
            if i > 0 and expr[i] == '0' and expr[i-1] in operators:
                return False
            # Skip digits
            while i < len(expr) and expr[i].isdigit():
                i += 1
        # Check if the current character is an operator
        elif expr[i] in operators:
            # Rule 2: It must not end with an operator
            if i == len(expr) - 1:
                return False
            # Rule 3: It must not contain two consecutive operators
            if i > 0 and expr[i-1] in operators:
                return False
            i += 1
        else:
            # Any other character is invalid
            return False

    return True

