    dist = [INF] * n
    dist[0] = 0  # Starting at node 0 (router 1)
    heap = [(0, 0)]  # (distance, node)

    while heap:
        current_dist, u = heapq.heappop(heap)
        if current_dist > dist[u]:
            continue
        for v, cost in graph[u]:
            if dist[v] > dist[u] + cost:
                dist[v] = dist[u] + cost
                heapq.heappush(heap, (dist[v], v))

    return dist[n - 1]  # Return the minimum cost to reach node n-1 (router n)

