def find_the_longest_substring(s: str) -> int:
    # Vowel to bit position mapping
    vowel_map = {'a': 0, 'e': 1, 'i': 2, 'o': 3, 'u': 4}

    # Initialize mask to 0 (all vowels have even counts initially)
    mask = 0

    # Dictionary to store the first occurrence of a mask
    first_occurrence = {0: -1}  # Mask 0 occurs at index -1

    max_length = 0

    for i, char in enumerate(s):
        if char in vowel_map:
            # Toggle the bit corresponding to the current vowel
            mask ^= (1 << vowel_map[char])

        # Check if this mask has been seen before
        if mask in first_occurrence:
            # Update max_length if current index - first occurrence is larger
            max_length = max(max_length, i - first_occurrence[mask])
        else:
            # Record the first occurrence of this mask
            first_occurrence[mask] = i

    return max_length

