def min_difference(weights):
    total_sum = sum(weights)
    possible_sums = {0}

    for weight in weights:
        new_sums = set()
        for s in possible_sums:
            new_sums.add(s)
            new_sums.add(s + weight)
        possible_sums = new_sums

    # Find the sum closest to total_sum // 2
    closest = min(possible_sums, key=lambda x: abs(total_sum - 2 * x))
    return total_sum - 2 * closest

