def can_sort_with_k_swaps(s, k):
    sorted_s = ''.join(sorted(s))

    # If already sorted, return YES
    if s == sorted_s:
        return "YES"

    # Count mismatches
    mismatch_count = 0
    for c1, c2 in zip(s, sorted_s):
        if c1 != c2:
            mismatch_count += 1

    # Each swap can fix at most 2 mismatches
    required_swaps = (mismatch_count + 1) // 2

    return "YES" if required_swaps <= k else "NO"

def is_safe_path_exists(grid):
    M = len(grid)
    N = len(grid[0]) if M > 0 else 0

    # If start or end cell is an obstacle, no path exists
    if grid[0][0] == 1 or grid[M-1][N-1] == 1:
        return "false"

    # Use dynamic programming to check if a safe path exists
    dp = [[False] * N for _ in range(M)]
    dp[0][0] = True  # Starting point is safe

    # Fill the first row
    for j in range(1, N):
        if grid[0][j] == 0 and dp[0][j-1]:
            dp[0][j] = True
        else:
            break  # Obstacle encountered, rest of the row is blocked

    # Fill the first column
    for i in range(1, M):
        if grid[i][0] == 0 and dp[i-1][0]:
            dp[i][0] = True
        else:
            break  # Obstacle encountered, rest of the column is blocked

    # Fill the rest of the grid
    for i in range(1, M):
        for j in range(1, N):
            if grid[i][j] == 0 and (dp[i-1][j] or dp[i][j-1]):
                dp[i][j] = True

    return "true" if dp[M-1][N-1] else "false"

