def unique_paths_with_obstacles(grid):
    n = len(grid)
    m = len(grid[0])

    # Initialize a DP table with the same dimensions as the grid
    dp = [[0 for _ in range(m)] for _ in range(n)]

    # Starting point
    if grid[0][0] == 1:
        dp[0][0] = 1
    else:
        return 0  # Start is blocked, no path possible

    # Fill the first row
    for j in range(1, m):
        if grid[0][j] == 1:
            dp[0][j] = dp[0][j - 1]
        else:
            dp[0][j] = 0

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == 1:
            dp[i][0] = dp[i - 1][0]
        else:
            dp[i][0] = 0

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == 1:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
            else:
                dp[i][j] = 0

    return dp[n - 1][m - 1]

