def minPathSum(grid):
    m = len(grid)
    n = len(grid[0])

    # Update the first row (only can come from left)
    for j in range(1, n):
        grid[0][j] += grid[0][j - 1]

    # Update the first column (only can come from top)
    for i in range(1, m):
        grid[i][0] += grid[i - 1][0]

    # Update the rest of the grid
    for i in range(1, m):
        for j in range(1, n):
            grid[i][j] += min(grid[i - 1][j], grid[i][j - 1])

    return grid[m - 1][n - 1]

