def max_presentations(n, presentations):
    # Sort the presentations by their ending time
    presentations.sort(key=lambda x: x[1])

    count = 0
    last_end = -1  # Initialize with a value before any possible start time

    for start, end in presentations:
        if start >= last_end:
            count += 1
            last_end = end

    return count

