def max_berries(n, berries):
    if n == 0:
        return 0
    if n == 1:
        return berries[0]

    # Initialize dp array
    dp = [0] * n
    dp[0] = berries[0]
    dp[1] = max(berries[0], berries[1])

    for i in range(2, n):
        dp[i] = max(dp[i - 1], dp[i - 2] + berries[i])

    return dp[-1]

