def unique_paths_with_obstacles(grid):
    m = len(grid)
    n = len(grid[0])

    # Initialize a DP table with the same dimensions as the grid
    dp = [[0 for _ in range(n)] for _ in range(m)]

    # If the starting cell is not blocked, set it to 1
    if grid[0][0] == 0:
        dp[0][0] = 1
    else:
        return 0  # Starting cell is blocked, no path is possible

    # Fill the first row
    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j - 1]
        else:
            dp[0][j] = 0

    # Fill the first column
    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i - 1][0]
        else:
            dp[i][0] = 0

    # Fill the rest of the DP table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
            else:
                dp[i][j] = 0

    return dp[m - 1][n - 1]

