def encrypt_message(s, k):
    result = []
    # Reduce the number of shifts using modulo 26
    shift = k % 26
    for char in s:
        # Shift each character and wrap around using modulo 26
        shifted_char = chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
        result.append(shifted_char)
    return ''.join(result)

