def is_palindrome_permutation(s):
    # Normalize the string: convert to lowercase, remove spaces
    s = s.replace(" ", "").lower()

    # Use a dictionary to count the frequency of each character
    char_count = {}

    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # Count how many characters have an odd count
    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    # A string can be a palindrome permutation if at most one character has an odd count
    return odd_count <= 1

