def find_two_sum_indices(n, k, array):
    num_index_map = {}  # Maps value to its index (1-based)

    for i in range(n):
        current = array[i]
        complement = k - current

        if complement in num_index_map:
            # Found the pair
            return (num_index_map[complement] + 1, i + 1)

        # Store current number and its 1-based index
        num_index_map[current] = i

    # If no pair found
    return -1

