from collections import deque

def minimumEffortPath(heights):
    m, n = len(heights), len(heights[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def canReach(max_diff):
        visited = [[False for _ in range(n)] for _ in range(m)]
        queue = deque()
        queue.append((0, 0))
        visited[0][0] = True

        while queue:
            x, y = queue.popleft()
            if x == m - 1 and y == n - 1:
                return True
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                    if abs(heights[nx][ny] - heights[x][y]) <= max_diff:
                        visited[nx][ny] = True
                        queue.append((nx, ny))
        return False

    left, right = 0, max(max(row) for row in heights) - min(min(row) for row in heights)
    answer = right

    while left <= right:
        mid = (left + right) // 2
        if canReach(mid):
            answer = mid
            right = mid - 1
        else:
            left = mid + 1

    return answer

