import heapq

def trap_rain_water(heightMap):
    if not heightMap or not heightMap[0]:
        return 0

    m, n = len(heightMap), len(heightMap[0])
    visited = [[False for _ in range(n)] for _ in range(m)]
    heap = []

    # Push all border cells into the heap
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(heap, (heightMap[i][j], i, j))
                visited[i][j] = True

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    trapped_water = 0

    while heap:
        height, row, col = heapq.heappop(heap)
        for dr, dc in directions:
            r, c = row + dr, col + dc
            if 0 <= r < m and 0 <= c < n and not visited[r][c]:
                visited[r][c] = True
                # If the neighbor is lower, water can be trapped
                if heightMap[r][c] < height:
                    trapped_water += height - heightMap[r][c]
                # Push the new height (max of current boundary and neighbor height)
                heapq.heappush(heap, (max(height, heightMap[r][c]), r, c))

    return trapped_water

