def maximize_difficulties(n, k, p, challenges):
    from collections import defaultdict

    # Group challenges by difficulty level
    difficulty_map = defaultdict(list)
    for d, t in challenges:
        difficulty_map[d].append(t)

    # Sort each difficulty group by time (keep shortest time per difficulty)
    for d in difficulty_map:
        difficulty_map[d].sort()

    # Now, we try to collect up to k challenges with different difficulties
    selected = []
    for d, times in difficulty_map.items():
        if len(selected) >= k:
            break
        # Pick the shortest time for the difficulty
        selected.append(times[0])

    # Check if the total time used is within p
    if sum(selected) <= p and len(selected) >= k:
        return len(selected)

    # If not, we need to select k challenges with the lowest durations overall
    # Combine all challenges and sort them by time
    all_sorted = sorted(challenges, key=lambda x: x[1])  # sort by time
    total_time = 0
    count = 0
    used_difficulties = set()

    for d, t in all_sorted:
        if total_time + t > p:
            break
        if d not in used_difficulties:
            total_time += t
            used_difficulties.add(d)
            count += 1
            if count == k:
                break

    return count

