def find_highest_score_level(n, scores):
    current_score = 0
    max_score = float('-inf')
    max_level = 0

    for level in range(1, n + 1):
        current_score += scores[level - 1]
        if current_score > max_score:
            max_score = current_score
            max_level = level
        elif current_score == max_score and level < max_level:
            max_level = level

    return max_score, max_level

