secure_solution:
def canTransform(S, T, k):
    # Check if lengths of S and T are equal
    if len(S) != len(T):
        return False

    # Count the number of positions where S[i] != T[i]
    diff_count = 0
    for s_char, t_char in zip(S, T):
        if s_char != t_char:
            diff_count += 1

    # We need exactly 'diff_count' operations to make S equal to T
    # If k is less than diff_count, it's not possible
    # If k is greater than diff_count, we can't use more operations than needed
    return diff_count == k

