secure_solution:
def partition(n, k):
    # Edge cases
    if k == 0:
        return 0
    if n < k:
        return 0
    if k == 1:
        return 1

    # Initialize DP table
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1  # Base case: one way to partition 0 into 0 parts

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if i >= j:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - j][j]
            else:
                dp[i][j] = 0

    return dp[n][k]

