    selected = []
    selected_indices = set()

    # Try to pick the h houses with minimum cost that are not adjacent
    for idx, cost in sorted_by_cost:
        if len(selected) < h:
            if idx not in selected_indices and (len(selected) == 0 or abs(idx - selected[-1][0]) > 1):
                selected.append((idx, cost))
                selected_indices.add(idx)
        else:
