def can_supreme_be_dragon(T, test_cases):
    results = []
    for M, K, creatures in test_cases:
        N = M * K
        cluster_supremes = []

        for i in range(M):
            start = i * K
            end = start + K
            cluster = creatures[start:end]
            d_count = cluster.count('D')
            p_count = K - d_count
            if d_count > p_count:
                cluster_supremes.append('D')
            else:
                cluster_supremes.append('P')

        d_clusters = cluster_supremes.count('D')
        p_clusters = M - d_clusters

        if d_clusters > p_clusters:
            results.append(1)
        else:
            results.append(0)

    return results

