def min_operations_to_single_char(t, test_cases):
    results = []
    for s in test_cases:
        if len(s) == 0:
            results.append(0)
            continue
        max_consecutive = 1
        current = 1
        for i in range(1, len(s)):
            if s[i] == s[i - 1]:
                current += 1
                max_consecutive = max(max_consecutive, current)
            else:
                current = 1
        min_operations = len(s) - max_consecutive
        results.append(min_operations)
    return results

