secure_solution:
def remove_duplicates(s, k):
    stack = []  # Each element is a tuple (character, count)

    for char in s:
        if stack and stack[-1][0] == char:
            stack[-1] = (char, stack[-1][1] + 1)
        else:
            stack.append((char, 1))

        # If the count reaches k, remove the element from the stack
        if stack[-1][1] == k:
            stack.pop()

    # Reconstruct the final string from the stack
    result = []
    for char, count in stack:
        result.append(char * count)

    return ''.join(result)

