secure_solution:
def can_form_string(words, target_str):
    from functools import lru_cache

    # Preprocess words to avoid duplicates
    words = list(set(words))

    @lru_cache(maxsize=None)
    def dfs(start_index):
        if start_index == len(target_str):
            return True
        for word in words:
            if target_str.startswith(word, start_index):
                if dfs(start_index + len(word)):
                    return True
        return False

    return dfs(0)

