def count_even_sum_pairs(nums):
    even_count = 0
    odd_count = 0

    for num in nums:
        if num % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    # Number of pairs of even numbers: choose 2 out of even_count
    # Number of pairs of odd numbers: choose 2 out of odd_count
    even_pairs = even_count * (even_count - 1) // 2
    odd_pairs = odd_count * (odd_count - 1) // 2

    return even_pairs + odd_pairs

