def max_candy_robbed(n, candies):
    if n == 0:
        return 0
    if n == 1:
        return candies[0]

    # dp_prev_prev = max candy for first i-2 houses
    # dp_prev = max candy for first i-1 houses
    dp_prev_prev = candies[0]
    dp_prev = max(candies[0], candies[1])

    for i in range(2, n):
        current = max(candies[i] + dp_prev_prev, dp_prev)
        dp_prev_prev, dp_prev = dp_prev, current

    return dp_prev

