def tsp(n, s, adj):
    from functools import lru_cache

    # Convert 1-based index to 0-based
    s -= 1

    # Use memoization with lru_cache
    @lru_cache(maxsize=None)
    def dp(mask, u):
        if mask == (1 << n) - 1:
            return adj[u][s]  # Return to starting city

        res = float('inf')
        for v in range(n):
            if not (mask & (1 << v)):
                res = min(res, adj[u][v] + dp(mask | (1 << v), v))
        return res

    # Initial call: mask with only starting city 's' visited, starting at 's'
    initial_mask = 1 << s
    min_cycle = dp(initial_mask, s)

    return min_cycle if min_cycle != float('inf') else -1

