def min_groups(N, heights, D):
    if N == 0:
        return 0

    # Step 1: Sort the heights
    heights.sort()

    groups = 1
    first_tree = heights[0]

    # Step 2: Iterate through the heights and form groups
    for i in range(1, N):
        if heights[i] - first_tree > D:
            groups += 1
            first_tree = heights[i]

    return groups

