secure_solution:
def uniquePaths(N, M, BlockedCells):
    # Convert BlockedCells to a set for O(1) lookup
    blocked = set(BlockedCells)

    # If start or end is blocked, return 0
    if (0, 0) in blocked or (N - 1, M - 1) in blocked:
        return 0

    # Initialize DP table
    dp = [[0 for _ in range(M)] for _ in range(N)]
    dp[0][0] = 1  # Starting point

    # Fill DP table
    for i in range(N):
        for j in range(M):
            if (i, j) in blocked:
                dp[i][j] = 0
                continue
            if i > 0:
                dp[i][j] += dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i][j - 1]

    return dp[N - 1][M - 1]

