def find_arithmetic_progression(n, arr):
    from collections import defaultdict

    # Map from value to list of indices (1-based)
    value_to_indices = defaultdict(list)
    for idx, val in enumerate(arr):
        value_to_indices[val].append(idx + 1)  # 1-based

    for i in range(n):
        for j in range(i + 1, n):
            a = arr[i]
            b = arr[j]
            d = b - a

            # Check for the next two elements in the AP
            c = b + d
            d_val = c + d

            # Check if c and d_val exist in the array
            if c in value_to_indices and d_val in value_to_indices:
                # Get indices for c and d_val
                idx_c = value_to_indices[c]
                idx_d = value_to_indices[d_val]

                # Check for distinct indices
                for idx1 in idx_c:
                    if idx1 == i + 1 or idx1 == j + 1:
                        continue
                    for idx2 in idx_d:
                        if idx2 == i + 1 or idx2 == j + 1 or idx2 == idx1:
                            continue
                        return [i + 1, j + 1, idx1, idx2]

    return -1

