def can_form_target(words, target):
    n = len(target)
    m = len(words)

    # dp[i] will be True if the first i characters of target can be formed
    dp = [False] * (n + 1)
    dp[0] = True  # Base case: empty target can be formed with 0 words

    for i in range(1, n + 1):
        for j in range(m):
            if dp[j] and target[i - 1] in words[j]:
                dp[i] = True
                break  # No need to check further once it's possible

    return dp[n]

