def longest_unique_substring(s):
    if not s:
        return ""

    start = 0
    max_length = 0
    max_start = 0
    seen = {}

    for end in range(len(s)):
        char = s[end]
        if char in seen and seen[char] >= start:
            start = seen[char] + 1
        seen[char] = end
        if end - start + 1 > max_length:
            max_length = end - start + 1
            max_start = start

    return s[max_start:max_start + max_length]

