import heapq

def trapRainWater(matrix):
    if not matrix or not matrix[0]:
        return 0

    rows, cols = len(matrix), len(matrix[0])
    visited = [[False] * cols for _ in range(rows)]
    min_heap = []

    # Initialize the heap with the border cells
    for i in range(rows):
        for j in [0, cols - 1]:
            heapq.heappush(min_heap, (matrix[i][j], i, j))
            visited[i][j] = True
    for j in range(1, cols - 1):
        for i in [0, rows - 1]:
            heapq.heappush(min_heap, (matrix[i][j], i, j))
            visited[i][j] = True

    # Directions to move: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    trapped_water = 0

    while min_heap:
        height, row, col = heapq.heappop(min_heap)
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                visited[nr][nc] = True
                # The water level at this new cell is the max of current boundary and its own height
                water_level = max(height, matrix[nr][nc])
                trapped_water += water_level - matrix[nr][nc]
                heapq.heappush(min_heap, (water_level, nr, nc))
    return trapped_water

