def rotate_list(nums, k):
    if not nums:
        return []

    n = len(nums)
    k %= n  # Ensure k is within the range of the list length

    # If k is 0, return the original list
    if k == 0:
        return nums

    # Rotate list by slicing
    return nums[-k:] + nums[:-k]

