def longest_subarray_with_sum(nums, S):
    prefix_sum_map = {}
    prefix_sum = 0
    max_length = 0

    # Initialize the map with prefix_sum 0 at index -1
    prefix_sum_map[0] = -1

    for i, num in enumerate(nums):
        prefix_sum += num

        # Check if (prefix_sum - S) exists in the map
        if (prefix_sum - S) in prefix_sum_map:
            max_length = max(max_length, i - prefix_sum_map[prefix_sum - S])

        # Store the first occurrence of the current prefix_sum
        if prefix_sum not in prefix_sum_map:
            prefix_sum_map[prefix_sum] = i

    return max_length

