def count_friendly_pairs(n, scores):
    even_count = 0
    odd_count = 0

    for score in scores:
        if score % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    # Count pairs of even and odd scores
    even_pairs = even_count * (even_count - 1) // 2
    odd_pairs = odd_count * (odd_count - 1) // 2

    return even_pairs + odd_pairs

