def reverse_preserve_spaces(input_string):
    if not isinstance(input_string, str):
        raise TypeError("input_string must be a string.")

    # Split the input string into words and spaces, preserving spaces
    tokens = []
    i = 0
    while i < len(input_string):
        if input_string[i] == ' ':
            # Add the space(s) as a single token
            j = i
            while j < len(input_string) and input_string[j] == ' ':
                j += 1
            tokens.append(('space', input_string[i:j]))
            i = j
        else:
            # Add the word
            j = i
            while j < len(input_string) and input_string[j] != ' ':
                j += 1
            tokens.append(('word', input_string[i:j]))
            i = j

    # Extract the words in a list
    words = [token[1] for token in tokens if token[0] == 'word']
    # Reverse the words
    words = words[::-1]

    # Reconstruct the string with reversed words and original space positions
    result = []
    word_index = 0
    for token in tokens:
        if token[0] == 'word':
            result.append(words[word_index])
            word_index += 1
        else:
            result.append(token[1])

    return ''.join(result)

