def min_flips_to_palindrome(S):
    i, j = 0, len(S) - 1
    flips = 0

    while i < j:
        if S[i] != S[j]:
            flips += 1
            # Flip the substring from i to j
            S = S[:i] + S[i:j+1][::-1] + S[j+1:]
            j -= 1  # Move inward after flipping
        else:
            i += 1
            j -= 1

    return flips

