def reverse_sections(string: str, indices: List[Tuple[int, int]]) -> str:
    if not string:
        return ""

    # Split the string into words
    words = string.split()

    # Process the indices in reverse order to avoid interfering with earlier operations
    for i, j in reversed(indices):
        if i < j:
            # Reverse the subarray from i to j inclusive
            words[i:j+1] = words[i:j+1][::-1]

    # Join the words back into a single string
    return ' '.join(words)

