secure_solution:
def process_commands(command_string: str) -> str:
    # Split the input string by colon
    sections = command_string.split(':')

    # Header and Footer should be "BEGIN" and "END" respectively
    if sections[0] != "BEGIN" or sections[-1] != "END":
        return "BEGIN:ERROR_INVALID_FORMAT:END"

    # Initialize the accumulator
    accumulator = 0

    # Process each command section between Header and Footer
    for section in sections[1:-1]:
        if not section:
            continue  # Skip empty sections if any

        # Extract operation and value
        if len(section) < 4 or not section[:3].isupper():
            return "BEGIN:ERROR_INVALID_COMMAND:END"

        operation = section[:3]
        try:
            value = int(section[3:])
        except ValueError:
            return "BEGIN:ERROR_INVALID_VALUE:END"

        # Process the operation
        if operation == "ADD":
            accumulator += value
        elif operation == "SUB":
            accumulator -= value
        elif operation == "MUL":
            accumulator *= value
        elif operation == "DIV":
            if value == 0:
                return "BEGIN:ERROR_DIV_BY_ZERO:END"
            accumulator = accumulator // value
        else:
            return "BEGIN:ERROR_INVALID_OPERATION:END"

        # Ensure accumulator is non-negative
        accumulator = max(accumulator, 0)

    # Return the formatted result
    return f"BEGIN:RESULT{accumulator}:END"

