from collections import deque

def minimum_moves_to_food(n, m, maze):
    # Find the starting position 'S' and the food position 'F'
    start = None
    end = None

    for i in range(n):
        for j in range(m):
            if maze[i][j] == 'S':
                start = (i, j)
            elif maze[i][j] == 'F':
                end = (i, j)

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # Initialize BFS
    visited = [[False] * m for _ in range(n)]
    queue = deque()

    queue.append((start[0], start[1], 0))  # (row, col, moves)
    visited[start[0]][start[1]] = True

    while queue:
        row, col, moves = queue.popleft()

        # If we reached the food
        if (row, col) == end:
            return moves

        # Explore neighbors
        for dr, dc in directions:
            nr, nc = row + dr, col + dc

            # Check if the move is valid
            if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc] and maze[nr][nc] != '#':
                visited[nr][nc] = True
                queue.append((nr, nc, moves + 1))

    # If food is unreachable
    return -1

