from typing import List

def max_ones_index(arr: List[int]) -> int:
    left = 0
    max_length = 0
    max_index = -1
    zero_count = 0

    for right in range(len(arr)):
        if arr[right] == 0:
            zero_count += 1

        # If there are more than one zero, move the window to the right
        while zero_count > 1:
            if arr[left] == 0:
                zero_count -= 1
            left += 1

        # Update the maximum length and corresponding zero index
        if zero_count <= 1:
            if right - left + 1 > max_length:
                max_length = right - left + 1
                # Find the index of the zero in the current window
                for i in range(left, right + 1):
                    if arr[i] == 0:
                        max_index = i
                        break
    return max_index if max_index != -1 else -1

