def min_words_to_form_target(words, target):
    from collections import defaultdict
    import math

    n = len(target)
    dp = [math.inf] * (n + 1)
    dp[0] = 0  # Base case: 0 words needed to form an empty string

    # Preprocess words by length to make matching faster
    word_map = defaultdict(list)
    for word in words:
        word_map[len(word)].append(word)

    for i in range(1, n + 1):
        # Check all possible word lengths that can form a substring ending at position i
        for length in word_map:
            if i - length >= 0:
                for word in word_map[length]:
                    if target[i - length:i] == word:
                        dp[i] = min(dp[i], dp[i - length] + 1)

    return dp[n] if dp[n] != math.inf else -1

