from typing import List

def find_subarray(arr: List[int], n: int) -> int:
    prefix_sum = 0
    sum_index_map = {}
    max_length = -1
    for i, num in enumerate(arr):
        prefix_sum += num
        # If current prefix_sum is exactly n, update max_length
        if prefix_sum == n:
            max_length = i + 1
        # Check if (prefix_sum - n) has been seen before
        elif (prefix_sum - n) in sum_index_map:
            max_length = max(max_length, i - sum_index_map[prefix_sum - n])
        # Store the first occurrence of the prefix_sum
        if prefix_sum not in sum_index_map:
            sum_index_map[prefix_sum] = i
    return max_length

