import heapq

def furthest_building(heights, bricks, ladders):
    min_heap = []

    for i in range(1, len(heights)):
        diff = heights[i] - heights[i - 1]
        if diff <= 0:
            continue  # No need for bricks or ladders

        # Use bricks for the smallest height difference
        heapq.heappush(min_heap, diff)

        # If we have more height differences than ladders, use bricks for the smallest one
        if len(min_heap) > ladders:
            bricks -= heapq.heappop(min_heap)

            if bricks < 0:
                return i - 1  # Not enough bricks and ladders to proceed

    return len(heights) - 1  # Successfully reached the last building

