from collections import deque

def longest_concatenation(words):
    words.sort(key=lambda x: (len(x), x))  # Sort by length, then lexicographic order
    n = len(words)
    best = ""

    # Queue stores tuples of (current_string, used_indices)
    queue = deque()
    for i in range(n):
        queue.append((words[i], {i}))

    while queue:
        current_str, used = queue.popleft()
        if len(current_str) > len(best) or (len(current_str) == len(best) and current_str < best):
            best = current_str

        # Try to extend the current string with unused words
        for i in range(n):
            if i not in used:
                new_used = used.copy()
                new_used.add(i)
                queue.append((current_str + words[i], new_used))

    return best

