def power_function(base, exponent, modulo=None):
    # Handle edge cases
    if exponent == 0:
        return 1
    if base == 0:
        return 0
    if modulo is not None and modulo == 1:
        return 0  # Any number mod 1 is 0

    def power_helper(a, n, mod):
        if n == 0:
            return 1
        result = power_helper(a, n // 2, mod)
        result = (result * result) % mod if mod is not None else result * result
        if n % 2 == 1:
            result = (result * a) % mod if mod is not None else result * a
        return result

    if modulo is None:
        return power_helper(base, exponent, None)
    else:
        return power_helper(base, exponent, modulo)

