def longest_balanced_subarray_length(n, sequence):
    balance_counts = {0: -1}  # To handle subarrays starting at index 0
    balance = 0
    max_length = 0

    for i in range(n):
        num = sequence[i]
        if num % 2 == 0:
            balance += 1
        else:
            balance -= 1

        # We are looking for balances: -1, 0, 1
        if balance in balance_counts:
            max_length = max(max_length, i - balance_counts[balance])
        else:
            balance_counts[balance] = i

    return max_length

