def top_student_per_subject(students: List[Dict[str, Union[str, int]]]) -> Dict[str, Union[List[str], str]]:
    if not students:
        return {}

    # Initialize a dictionary to store the highest score for each subject
    subject_scores = defaultdict(int)
    # Initialize a dictionary to store students for each subject
    subject_students = defaultdict(list)

    # Extract subjects from the first student (assuming all students have the same subjects)
    subjects = [key for key in students[0] if key != 'name']

    # Process each student
    for student in students:
        name = student['name']
        for subject in subjects:
            score = student[subject]
            # Update the highest score and students if necessary
            if score > subject_scores[subject]:
                subject_scores[subject] = score
                subject_students[subject] = [name]
            elif score == subject_scores[subject]:
                subject_students[subject].append(name)

    # Convert lists with single student to string for consistency with the expected output
    result = {}
    for subject in subjects:
        students_list = subject_students[subject]
        if len(students_list) == 1:
            result[subject] = students_list[0]
        else:
            result[subject] = students_list

    return result

