def minimum_boxes(A, B, C):
    min_boxes = float('inf')

    # Try all possible numbers of large boxes (from 0 to C // A)
    for large in range(C // A + 1):
        remaining = C - large * A
        if remaining < 0:
            continue  # Too many large boxes

        # Calculate the number of small boxes needed
        small = (remaining + B - 1) // B  # Ceiling division

        total_boxes = large + small
        if total_boxes < min_boxes:
            min_boxes = total_boxes

    return min_boxes

