def unique_paths_with_obstacles(grid):
    n = len(grid)
    if grid[0][0] == 1 or grid[n-1][n-1] == 1:
        return 0  # Start or end is blocked

    # Initialize DP table
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = 1  # Starting point

    # Fill first row
    for i in range(1, n):
        if grid[0][i] == 0:
            dp[0][i] = dp[0][i-1]
        else:
            dp[0][i] = 0  # Blocked, no paths

    # Fill first column
    for i in range(1, n):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = 0  # Blocked, no paths

    # Fill the rest of the grid
    for i in range(1, n):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Blocked, no paths

    return dp[n-1][n-1]

