def largest_secure_area(n, grid):
    # Step 1: Create a prefix sum matrix for 2D range sum queries
    prefix = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n):
        row_sum = 0
        for j in range(n):
            row_sum += grid[i][j]
            prefix[i + 1][j + 1] = prefix[i][j + 1] + row_sum

    # Function to check if there's a k x k square with all 0s
    def has_secure_square(k):
        if k > n:
            return False
        for i in range(n - k + 1):
            for j in range(n - k + 1):
                # Calculate sum of the k x k submatrix starting at (i, j)
                submatrix_sum = prefix[i + k][j + k] - prefix[i][j + k] - prefix[i + k][j] + prefix[i][j]
                if submatrix_sum == 0:
                    return True
        return False

    # Step 2: Binary search for the largest k
    low, high = 1, n
    result = 0
    while low <= high:
        mid = (low + high) // 2
        if has_secure_square(mid):
            result = mid
            low = mid + 1
        else:
            high = mid - 1
    return result

