def can_reach_end(arr, k):
    n = len(arr)
    current = 0  # Start at the first position

    while current < n - 1:
        # Find the farthest position we can jump to from the current position
        farthest = current
        while farthest + 1 < n and abs(arr[farthest + 1] - arr[current]) <= k:
            farthest += 1

        if farthest == current:
            # Cannot move forward
            return False

        current = farthest

    return True

