secure_solution:
def min_operations(s1, s2):
    # Lengths of the two strings
    m, n = len(s1), len(s2)

    # Create a 2D DP table with (m+1) rows and (n+1) columns
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the first row and column
    for i in range(m + 1):
        dp[i][0] = i  # Deleting all characters from s1
    for j in range(n + 1):
        dp[0][j] = j  # Inserting all characters into s1

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                # No operation needed if the characters are the same
                dp[i][j] = dp[i - 1][j - 1]
            else:
                # Take the minimum of insert, delete, or replace
                dp[i][j] = 1 + min(
                    dp[i - 1][j],    # Delete
                    dp[i][j - 1],    # Insert
                    dp[i - 1][j - 1] # Replace
                )

    # The result is in the bottom-right corner
    return dp[m][n]

