def capitalize_concatenate(words):
    result = ""
    for word in words:
        # Remove non-alphabetic characters and convert to lowercase
        cleaned_word = ''.join(char for char in word if char.isalpha()).lower()
        # Capitalize the first letter and append to result
        if cleaned_word:
            result += cleaned_word[0].upper() + cleaned_word[1:]
    return result

