    # Helper function to convert algebraic notation to numerical coordinates
    def pos_to_coords(pos):
        col = ord(pos[0]) - ord('a')  # Convert 'a' to 0, 'h' to 7
        row = int(pos[1]) - 1  # Convert '1' to 0, '8' to 7
        return (row, col)

    # Validate positions
    if not (len(start_pos) == 2 and len(end_pos) == 2):
        return False

    if not (start_pos[0].isalpha() and start_pos[0].lower() in "abcdefgh" and
            start_pos[1].isdigit() and start_pos[1] in "12345678" and
            end_pos[0].isalpha() and end_pos[0].lower() in "abcdefgh" and
            end_pos[1].isdigit() and end_pos[1] in "12345678"):
        return False

    start_row, start_col = pos_to_coords(start_pos)
    end_row, end_col = pos_to_coords(end_pos)

    # Check if move is to the same square
    if (start_row, start_col) == (end_row, end_col):
        return False

    # Pawn movement
    if piece == "pawn":
        # Determine direction based on starting row
        direction = -1 if start_row > end_row else 1  # pawns move forward, but only first move can be two squares
        if direction == -1 and start_row == 6 and end_row == 4 and start_col == end_col:  # White pawn moving from e2 to e4
            return True
        if direction == 1 and start_row == 1 and end_row == 3 and start_col == end_col:  # Black pawn moving from e7 to e5
            return True
        if start_col == end_col and abs(start_row - end_row) == 1:
            return True
        if abs(start_col - end_col) == 1 and abs(start_row - end_row) == 1:
            return True
        return False

    # Rook movement
    elif piece == "rook":
        if start_row == end_row or start_col == end_col:
            return True
        return False

    # Knight movement
    elif piece == "knight":
        row_diff = abs(start_row - end_row)
        col_diff = abs(start_col - end_col)
        if (row_diff == 2 and col_diff == 1) or (row_diff == 1 and col_diff == 2):
            return True
        return False

    # Bishop movement
    elif piece == "bishop":
        if abs(start_row - end_row) == abs(start_col - end_col):
            return True
        return False

    # Queen movement (combination of rook and bishop)
    elif piece == "queen":
        if start_row == end_row or start_col == end_col or abs(start_row - end_row) == abs(start_col - end_col):
            return True
        return False

    # King movement
    elif piece == "king":
        if abs(start_row - end_row) <= 1 and abs(start_col - end_col) <= 1:
            return True
        return False

    # Invalid piece type
    else:
        return False

def count_paths(n, m, grid):
    MOD = 10**9 + 7

    # Initialize a DP table
    dp = [[0] * m for _ in range(n)]

    # Starting point
    dp[0][0] = 1 if grid[0][0] == '.' else 0

    # Fill the first row
    for j in range(1, m):
        if grid[0][j] == '.':
            dp[0][j] = dp[0][j - 1]
        else:
            dp[0][j] = 0

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == '.':
            dp[i][0] = dp[i - 1][0]
        else:
            dp[i][0] = 0

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == '.':
                dp[i][j] = (dp[i - 1][j] + dp[i][j - 1]) % MOD
            else:
                dp[i][j] = 0

    return dp[n - 1][m - 1]

