def can_partition_coins(coins):
    total_sum = sum(coins)

    # If the total sum is odd, it's impossible to partition
    if total_sum % 2 != 0:
        return "NO"

    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: zero sum is always possible

    for coin in coins:
        for i in range(target, coin - 1, -1):
            if dp[i - coin]:
                dp[i] = True

    return "YES" if dp[target] else "NO"

