def calculate_min_route_cost(N, cost_matrix):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def tsp(mask, curr):
        if mask == (1 << N) - 1:
            return cost_matrix[curr][0]  # Return to start city (0)

        min_cost = float('inf')
        for next_city in range(N):
            if not (mask & (1 << next_city)):
                new_mask = mask | (1 << next_city)
                min_cost = min(min_cost, cost_matrix[curr][next_city] + tsp(new_mask, next_city))
        return min_cost

    return tsp(1 << 0, 0)  # Start from city 0 with only city 0 visited

