def smallest_subarray_with_given_sum(n, s, arr):
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + arr[i]

    dq = deque()
    min_len = float('inf')

