def min_egg_drops(K: int, N: int) -> int:
    # We use a 1D DP array to reduce space complexity
    dp_prev = [0] * (N + 1)  # dp_prev[i] = min drops for i floors using K-1 eggs

    for k in range(1, K + 1):
        dp_curr = [0] * (N + 1)
        for n in range(1, N + 1):
            if k == 1:
                dp_curr[n] = n  # Only one egg: we must check every floor one by one
            elif n == 1:
                dp_curr[n] = 1  # Only one floor: one drop is sufficient
            else:
                # Try each floor from 1 to n and find the optimal one
                min_tries = float('inf')
                for i in range(1, n + 1):
                    res = 1 + max(dp_prev[i - 1], dp_curr[n - i])
                    min_tries = min(min_tries, res)
                dp_curr[n] = min_tries
        dp_prev = dp_curr  # Move to the next row

    return dp_prev[N]

