def count_paths(grid):
    m = len(grid)
    n = len(grid[0])

    # If the start or end cell is 0, no valid path exists
    if grid[0][0] == 0 or grid[m-1][n-1] == 0:
        return 0

    # Initialize a DP table
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1  # Starting cell

    # Fill the first row
    for j in range(1, n):
        if grid[0][j] == 1:
            dp[0][j] = dp[0][j-1]
        else:
            dp[0][j] = 0

    # Fill the first column
    for i in range(1, m):
        if grid[i][0] == 1:
            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = 0

    # Fill the rest of the DP table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 1:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0

    return dp[m-1][n-1]

