def check_submatrix_sum(n, m, k, matrix):
    # Iterate over all possible top-left corners of 2x2 submatrices
    for i in range(n - 1):
        for j in range(m - 1):
            # Extract the 2x2 submatrix
            submatrix = [
                [matrix[i][j], matrix[i][j + 1]],
                [matrix[i + 1][j], matrix[i + 1][j + 1]]
            ]
            # Calculate the sum of the submatrix
            submatrix_sum = sum(sum(row) for row in submatrix)
            # Check if the sum matches k
            if submatrix_sum == k:
                return "YES"
    return "NO"

