def count_inversions_permutations(n, k):
    # dp[i][j] = number of permutations of [0, 1, ..., i-1] with j inversions
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case: 0 elements, 0 inversions
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            # Insert the new element at position p (0 <= p < i)
            # It will add p inversions
            for p in range(0, min(i, j + 1)):
                dp[i][j] += dp[i - 1][j - p]

    return dp[n][k]

