def form_smallest_number(arr, k):
    stack = []

    for digit in arr:
        while k > 0 and stack and stack[-1] > digit:
            stack.pop()
            k -= 1
        stack.append(digit)

    # If still have to remove k digits from the end
    if k > 0:
        stack = stack[:-k]

    # Remove leading zeros
    result = ''.join(map(str, stack)).lstrip('0')

    return result if result != '' else '0'

