secure_solution:
def longest_substring_with_n_distinct_chars(s, n):
    from collections import defaultdict

    if n == 0 or not s:
        return -1

    char_count = defaultdict(int)
    left = 0
    max_length = -1
    distinct_count = 0

    for right in range(len(s)):
        char = s[right]
        if char_count[char] == 0:
            distinct_count += 1
        char_count[char] += 1

        while distinct_count > n:
            left_char = s[left]
            char_count[left_char] -= 1
            if char_count[left_char] == 0:
                distinct_count -= 1
            left += 1

        if distinct_count == n:
            max_length = max(max_length, right - left + 1)

    return max_length if max_length != 0 else -1

def num_ways_to_fill_2xn_grid(n):
    MOD = 10**9 + 7

    def fib(n):
        """
        Returns the nth Fibonacci number using fast doubling method.
        fib(1) = 1, fib(2) = 1, fib(3) = 2, fib(4) = 3, ...
        But here, our sequence starts with:
        ways(1) = 1, ways(2) = 2, ways(3) = 3, ways(4) = 5, ...
        So we want to return fib(n+1) where fib(1) = 1, fib(2) = 1, fib(3) = 2.
        """
        def fib_pair(n):
            if n == 0:
                return (0, 1)
            a, b = fib_pair(n >> 1)
            c = a * (2 * b - a)
            d = a * a + b * b
            if n & 1:
                return (d, c + d)
            else:
                return (c, d)

        return fib_pair(n)[0]

    return fib(n + 1) % MOD

