        So we want to return fib(n+1) where fib(1) = 1, fib(2) = 1, fib(3) = 2.
        """
        def fib_pair(n):
            if n == 0:
                return (0, 1)
            a, b = fib_pair(n >> 1)
            c = a * (2 * b - a)
            d = a * a + b * b
            if n & 1:
                return (d, c + d)
            else:
                return (c, d)

        return fib_pair(n)[0]

    return fib(n + 1) % MOD

