def max_sum_subsequence(nums, k):
    if k == 0:
        return 0

    n = len(nums)
    if k >= n:
        return sum(x for x in nums if x > 0)  # maximum sum if k >= n

    # Concatenate the array with itself to simulate wrap-around
    extended = nums + nums

    # Compute prefix sums
    prefix = [0] * (len(extended) + 1)
    for i in range(len(extended)):
        prefix[i + 1] = prefix[i] + extended[i]

    max_sum = float('-inf')

    # Use sliding window to find max sum subarray of size up to k in the extended array
    for i in range(len(extended)):
        for j in range(i + 1, min(i + k + 1, len(extended) + 1)):
            current_sum = prefix[j] - prefix[i]
            if current_sum > max_sum:
                max_sum = current_sum

    return max_sum

