def max_gold(N, M, grid):
    # Initialize DP table
    dp = [[0] * M for _ in range(N)]

    # Starting point
    dp[0][0] = grid[0][0]

    # Fill first row
    for j in range(1, M):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill first column
    for i in range(1, N):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill rest of the dp table
    for i in range(1, N):
        for j in range(1, M):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[N-1][M-1]

