    # Initialize a set to store all possible sums that can be achieved
    possible_sums = {0}

    for weight in weights:
        # For each weight, update the possible sums by adding the weight
        new_sums = set()
        for s in possible_sums:
            new_sum = s + weight
            if new_sum <= target:
                new_sums.add(new_sum)
        possible_sums.update(new_sums)

    # Find the maximum sum <= target
    closest = 0
    for s in possible_sums:
        if s <= target and s > closest:
            closest = s

    return closest

