def wordBreak(s, wordDict):
    word_set = set(wordDict)  # Convert to a set for O(1) lookups
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True  # Empty string can be segmented

    max_len = max(len(word) for word in word_set) if word_set else 0

    for i in range(1, n + 1):
        # Check substrings ending at i of length up to max_len
        for j in range(i - 1, max(i - max_len - 1, -1), -1):
            if dp[j] and s[j:i] in word_set:
                dp[i] = True
                break  # No need to check further once we find a valid split
    return dp[n]

