def count_even_sum_pairs(N, A):
    even_count = 0
    odd_count = 0

    for num in A:
        if num % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    # Calculate combinations of even and odd pairs
    even_pairs = even_count * (even_count - 1) // 2
    odd_pairs = odd_count * (odd_count - 1) // 2

    return even_pairs + odd_pairs

