def move_zeros_in_place(array):
    # Track the position to place the next non-zero element
    insert_pos = 0

    # First pass: move all non-zero elements to the front
    for element in array:
        # Only move elements that are not zero (and ensure we don't mistake False for 0)
        if element != 0 or isinstance(element, bool):
            array[insert_pos] = element
            insert_pos += 1

    # Second pass: fill the remaining positions with zeros
    while insert_pos < len(array):
        array[insert_pos] = 0
        insert_pos += 1

