from typing import List, Dict, Any
from collections import deque

def shortest_path_bfs(graph: Dict[int, List[int]], start: int, end: int) -> List[int]:
    # Input validation
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError("Both 'start' and 'end' must be integers.")

    if start not in graph or end not in graph:
        raise ValueError("Either 'start' or 'end' node does not exist in the graph.")

    # Early return if start is the end
    if start == end:
        return [start]

    # BFS initialization
    queue = deque()
    queue.append((start, [start]))  # (current_node, path)
    visited = set()
    visited.add(start)

    while queue:
        current_node, path = queue.popleft()

        for neighbor in graph[current_node]:
            if neighbor == end:
                return path + [neighbor]

            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))

    # If no path is found
    return []

