def min_page_difference(N, pages):
    total_pages = sum(pages)
    target = total_pages // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: 0 pages can be achieved

    for pages_count in pages:
        for i in range(target, pages_count - 1, -1):
            if dp[i - pages_count]:
                dp[i] = True

    # Find the maximum value <= target that can be achieved
    for i in range(target, -1, -1):
        if dp[i]:
            return abs(total_pages - 2 * i)

