from typing import List

def unique_character_labels(labels: List[str]) -> List[str]:
    result = []
    for label in labels:
        seen = set()
        unique_label = []
        for char in label:
            if char not in seen:
                seen.add(char)
                unique_label.append(char)
        result.append(''.join(unique_label))
    return result

