from collections import deque, defaultdict

def min_time_to_complete_tasks(n, dependencies):
    # Build the graph
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)

    for a, b in dependencies:
        graph[a].append(b)
        in_degree[b] += 1

    # Use a queue for Kahn's algorithm
    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    # Track the time each task is completed
    time = [1] * (n + 1)  # Start with 1 unit for each task

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            time[neighbor] = max(time[neighbor], time[node] + 1)  # Longest path
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If all tasks were processed, return the max time
    if all(in_degree[i] == 0 for i in range(1, n + 1)):
        return max(time[1:])  # Skip index 0
    else:
        return -1  # Cycle found

