from typing import List

def tic_tac_toe_winner(board: List[List[str]]) -> str:
    # Check rows for a winner
    for row in board:
        if row[0] == row[1] == row[2] and row[0] != '':
            return row[0]

    # Check columns for a winner
    for col in range(3):
        if board[0][col] == board[1][col] == board[2][col] and board[0][col] != '':
            return board[0][col]

    # Check diagonals for a winner
    if board[0][0] == board[1][1] == board[2][2] and board[0][0] != '':
        return board[0][0]
    if board[0][2] == board[1][1] == board[2][0] and board[0][2] != '':
        return board[0][2]

    # If no winner, check if the board is full (draw)
    is_full = all(cell != '' for row in board for cell in row)
    if is_full:
        return 'Draw'

    # If no winner and board is not full, the game is still in progress
    return 'Draw'  # This is a fallback, but the note says input is valid, so it's safe

