from collections import defaultdict, deque

def find_critical_path(n: int, dependencies: list[tuple[int, int, int]]) -> list[int]:
    # Build the graph
    graph = defaultdict(list)
    in_degree = [0] * n
    for u, v, w in dependencies:
        graph[u].append((v, w))
        in_degree[v] += 1

    # Perform topological sort using Kahn's algorithm
    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    topo_order = []
    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v, w in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Initialize dp array to store the max path length ending at each node
    dp = [0] * n

    # Update dp using topological order
    for u in topo_order:
        for v, w in graph[u]:
            if dp[v] < dp[u] + w:
                dp[v] = dp[u] + w

    # Find the node with the maximum dp value (the end of the critical path)
    max_len = max(dp)
    end_node = dp.index(max_len)

    # Backtrack from end_node to find the critical path
    critical_path = []
    current = end_node
    while True:
        critical_path.append(current)
        found = False
        for u, v, w in dependencies:
            if v == current and dp[current] == dp[u] + w:
                current = u
                found = True
                break
        if not found:
            break

    # Reverse to get the path from start to end
    return critical_path[::-1]

