def recursive_binomial_coefficient(n, k):
    if k < 0 or k > n:
        raise ValueError("k must be between 0 and n inclusive.")

    # Use symmetry to reduce the number of recursive calls
    k = min(k, n - k)

    # Memoization dictionary to store computed binomial coefficients
    memo = {}

    def helper(n, k):
        if (n, k) in memo:
            return memo[(n, k)]
        if k == 0 or k == n:
            return 1
        result = helper(n - 1, k - 1) + helper(n - 1, k)
        memo[(n, k)] = result
        return result

    return helper(n, k)

