def can_be_expressed_as_sum_of_two_squares(N):
    if N < 0:
        return "NO"

    # Handle N = 0 as a special case
    if N == 0:
        return "YES"

    # Check for each prime factor
    n = N
    while n % 2 == 0:
        n //= 2

    # Check primes of the form 4k + 3
    i = 3
    while i * i <= n:
        if n % i == 0:
            count = 0
            while n % i == 0:
                n //= i
                count += 1
            if count % 2 != 0 and i % 4 == 3:
                return "NO"
        i += 2

    # If n is a prime of the form 4k + 3
    if n % 4 == 3:
        return "NO"

    return "YES"

