from typing import List

def is_zigzag(arr: List[int]) -> bool:
    # A single element or empty list is trivially a zigzag
    if len(arr) <= 1:
        return True

    # Check each triplet (i-1, i, i+1) to ensure zigzag condition
    for i in range(1, len(arr) - 1):
        if (arr[i] > arr[i - 1] and arr[i] > arr[i + 1]) or \
           (arr[i] < arr[i - 1] and arr[i] < arr[i + 1]):
            continue
        else:
            return False
    return True

