def min_path_cost(grid: List[List[int]]) -> Tuple[int, List[Tuple[int, int]]]:
    m, n = len(grid), len(grid[0])

    # Initialize DP table with the same dimensions as grid
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = grid[0][0]

    # Fill first row
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill first column
    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the DP table
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    # Backtrack to find the path
    path = []
    i, j = m - 1, n - 1
    path.append((i, j))

    while i > 0 or j > 0:
        if i == 0:
            j -= 1
        elif j == 0:
            i -= 1
        else:
            if dp[i][j] - grid[i][j] == dp[i-1][j]:
                i -= 1
            else:
                j -= 1
        path.append((i, j))

    # Reverse the path to get from (0, 0) to (m-1, n-1)
    path.reverse()

    return (dp[m-1][n-1], path)

