def shortest_subarray_length(arr, x):
    n = len(arr)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + arr[i]

    min_len = float('inf')
    from collections import deque

    dq = deque()
    for i in range(n + 1):
        while dq and prefix[i] <= prefix[dq[-1]]:
            dq.pop()
        dq.append(i)

        while prefix[i] - prefix[dq[0]] > x:
            min_len = min(min_len, i - dq[0])
            dq.popleft()

    return min_len if min_len != float('inf') else -1

