from typing import List

def can_partition(nums: List[int]) -> bool:
    total_sum = sum(nums)

    # If the total sum is odd, it's not possible to partition
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum of 0 is always possible

    for num in nums:
        # We iterate from back to front to avoid using the same number multiple times
        for j in range(target, num - 1, -1):
            if dp[j - num]:
                dp[j] = True

    return dp[target]

def group_in_intervals(lst):
    if not lst:
        return []

    # Find the minimum and maximum values in the list to determine the range
    min_val = min(lst)
    max_val = max(lst)

    # Determine the number of intervals needed
    # We use the ceiling of (max_val + 5) / 5 to ensure we cover the full range
    num_intervals = ((max_val + 5) // 5) - (min_val // 5)

    # Initialize a dictionary to count the occurrences in each interval
    interval_counts = {}

    # Initialize interval counts for all intervals from 0 to max_val
    for i in range(0, max_val + 5, 5):
        interval_counts[(i, i + 4)] = 0

    # Count how many numbers fall into each interval
    for num in lst:
        for start in range(0, max_val + 5, 5):
            end = start + 4
            if start <= num <= end:
                interval_counts[(start, end)] += 1
                break

    # Format the results into the required string format
    result = []
    for start, end in interval_counts:
        result.append(f"{start}-{end}: {interval_counts[(start, end)]}")

    return result

from typing import List

def binary_search_rotated(arr: List[int], target: int) -> int:
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return mid

        # Check if the left half is sorted
        if arr[left] <= arr[mid]:
            if arr[left] <= target < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if arr[mid] < target <= arr[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

