def maxGold(M, n, m):
    # Initialize DP table
    dp = [[0 for _ in range(m)] for _ in range(n)]

    # Base case: first cell
    dp[0][0] = M[0][0]

    # Fill first row
    for j in range(1, m):
        dp[0][j] = dp[0][j-1] + M[0][j]

    # Fill first column
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + M[i][0]

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = M[i][j] + max(dp[i-1][j], dp[i][j-1])

    return dp[n-1][m-1]

