def longest_ones(arr, k):
    left = 0
    max_length = 0
    count_zeros = 0  # Count of zeros in the current window

    for right in range(len(arr)):
        if arr[right] == 0:
            count_zeros += 1

        # If the number of zeros exceeds k, move the left pointer to the right
        while count_zeros > k:
            if arr[left] == 0:
                count_zeros -= 1
            left += 1

        # Update the maximum length of the window
        max_length = max(max_length, right - left + 1)

    return max_length

