from collections import Counter
import re

def can_form_palindrome(input_string):
    # Normalize the string: lowercase and remove non-alphanumeric characters
    normalized = re.sub(r'[^a-z0-9]', '', input_string.lower())

    # Count the frequency of each character
    char_counts = Counter(normalized)

    # Check if the string can form a palindrome
    odd_count = sum(1 for count in char_counts.values() if count % 2 != 0)
    can_form = odd_count <= 1

    if not can_form:
        return (False, None)

    # Build the palindrome
    half_palindrome = []
    middle_char = ''

    for char, count in char_counts.items():
        if count % 2 == 0:
            half_palindrome.append(char * (count // 2))
        else:
            middle_char = char
            half_palindrome.append(char * (count // 2))

    # Join the half and its reverse
    left = ''.join(half_palindrome)
    right = left[::-1]

    # Add the middle character if any
    if middle_char:
        palindrome = left + middle_char + right
    else:
        palindrome = left + right

    return (True, palindrome)

