def fibonacci_sum(n):
    if n <= 0:
        return 0

    # First two Fibonacci numbers
    a, b = 0, 1
    total = a  # Sum starts with the first Fibonacci number (0)

    if n == 1:
        return total

    total += b  # Add the second Fibonacci number (1)

    for _ in range(2, n):
        a, b = b, a + b
        total += b

    return total

