def rock_paper_scissors_score(rounds: list[str]) -> tuple[int, int]:
    score_p1 = 0
    score_p2 = 0

    # Define the winning conditions
    wins = {
        "R": "S",  # Rock beats Scissors
        "S": "P",  # Scissors beat Paper
        "P": "R"   # Paper beats Rock
    }

    for round_result in rounds:
        p1_move, p2_move = round_result.split()

        if p1_move == p2_move:
            continue  # Tie, no points awarded
        elif wins[p1_move] == p2_move:
            score_p1 += 1  # Player 1 wins
        else:
            score_p2 += 1  # Player 2 wins

    return (score_p1, score_p2)

