    target = total // 2
    possible_sums = {0}

    for candy in candies:
        new_sums = set()
        for s in possible_sums:
            new_sum = s + candy
            if new_sum <= target:
                new_sums.add(new_sum)
        possible_sums.update(new_sums)

    closest = max(possible_sums)
    return total - 2 * closest

