    def kadane(arr):
        max_current = max_global = arr[0]
        for x in arr[1:]:
            max_current = max(x, max_current + x)
            max_global = max(max_global, max_current)
        return max_global

    max_sum = kadane(arr)
    target_remainder = max_sum % k

    max_valid_sum = float('-inf')
    current_sum = 0
    for num in arr:
        current_sum += num
        if current_sum % k == target_remainder:
            max_valid_sum = max(max_valid_sum, current_sum)
        # Reset if current_sum becomes negative (as we are looking for maximum valid sum)
        if current_sum < 0:
            current_sum = 0

    return max_valid_sum

