def days_until_more_rainfall(n, rainfall):
    result = [0] * n
    stack = []

    for i in range(n - 1, -1, -1):
        # Pop elements from the stack that are not greater than current day's rainfall
        while stack and rainfall[stack[-1]] <= rainfall[i]:
            stack.pop()

        # If stack is not empty, the top element is the index of the next greater day
        if stack:
            result[i] = stack[-1] - i
        else:
            result[i] = 0

        # Push current index onto the stack
        stack.append(i)

    return result

