def min_moves_to_arrange(heights):
    # We'll use a list 'tails' to store the smallest possible tail of all increasing subsequences
    # with various lengths.
    tails = []

    for height in heights:
        # Use binary search to find the first index in 'tails' >= current height
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] > height:
                right = mid
            else:
                left = mid + 1
        if left == len(tails):
            tails.append(height)
        else:
            tails[left] = height

    # The length of the longest non-decreasing subsequence
    lnds_length = len(tails)
    return len(heights) - lnds_length

