def max_array_value(nums, k, updates):
    n = len(nums)
    diff = [0] * (n + 1)  # To handle index r+1 safely

    # Apply all updates to the difference array
    for l, r, v in updates:
        diff[l] += v
        if r + 1 < n:
            diff[r + 1] -= v

    # Compute prefix sums to apply the updates
    current = 0
    for i in range(n):
        current += diff[i]
        nums[i] += current

    # Return the maximum value in the modified nums array
    return max(nums)

