def min_subset_difference(arr):
    total_sum = sum(arr)
    target = total_sum // 2
    dp = set()
    dp.add(0)

    for num in arr:
        temp = set()
        for s in dp:
            if s + num <= target:
                temp.add(s + num)
        dp.update(temp)

    max_subset_sum = max(dp)
    return total_sum - 2 * max_subset_sum

