def max_merge_operations(M, intervals):
    # Sort intervals based on start point, and if same start, by end point
    intervals.sort()

    stack = []
    operations = 0

    for s, e in intervals:
        if stack and stack[-1][0] <= s and stack[-1][1] >= e:
            # Current interval is completely inside the last interval in the stack
            operations += 1
        else:
            stack.append((s, e))

    return operations

