def gc_content(dna_sequence: str) -> float:
    # Convert the sequence to uppercase for case-insensitive comparison
    dna_sequence = dna_sequence.upper()

    # Define valid characters
    valid_chars = {'A', 'T', 'G', 'C'}

    # Check for invalid characters
    for char in dna_sequence:
        if char not in valid_chars:
            raise ValueError("Invalid character in DNA sequence")

    # Count 'G' and 'C'
    gc_count = dna_sequence.count('G') + dna_sequence.count('C')
    total_length = len(dna_sequence)

    # Avoid division by zero in case of empty string
    if total_length == 0:
        return 0.00

    # Calculate and round the GC content to two decimal places
    gc_percentage = (gc_count / total_length) * 100
    return round(gc_percentage, 2)

