def longest_substring_with_k_chars(s, k):
    if k <= 0 or not s:
        return 0

    char_count = {}
    left = 0
    max_length = 0

    for right in range(len(s)):
        char = s[right]
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

        # If the number of different characters exceeds k, move the left pointer
        while len(char_count) > k:
            left_char = s[left]
            char_count[left_char] -= 1
            if char_count[left_char] == 0:
                del char_count[left_char]
            left += 1

        # Update the maximum length
        max_length = max(max_length, right - left + 1)

    return max_length

