def count_uncolored_blocks(n, operations):
    diff = [0] * (n + 2)  # diff array to track changes

    for l, r in operations:
        diff[l] += 1
        diff[r + 1] -= 1

    # Compute the prefix sum to get the number of times each block was colored
    colored = 0
    uncolored = 0

    for i in range(1, n + 1):
        colored += diff[i]
        if colored == 0:
            uncolored += 1

    return uncolored

