def min_difference_barn_cows(N, cows):
    total = sum(cows)
    target = total // 2
    dp = {0}  # set of achievable sums

    for cow in cows:
        new_sums = set()
        for s in dp:
            new_sums.add(s)
            new_sums.add(s + cow)
        dp = new_sums

    # Find the closest achievable sum to target
    closest = min(dp, key=lambda x: abs(x - target))
    return abs(total - 2 * closest)

from typing import List

def find_median_sorted_arrays(nums1: List[int], nums2: List[int]) -> float:
    # Ensure nums1 is the smaller array for efficiency
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1

    m, n = len(nums1), len(nums2)
    low, high = 0, m

    while low <= high:
        partition_nums1 = (low + high) // 2
        partition_nums2 = (m + n + 1) // 2 - partition_nums1

        # Handle edge cases where partition is at the ends
        max_left_nums1 = nums1[partition_nums1 - 1] if partition_nums1 > 0 else float('-inf')
        min_right_nums1 = nums1[partition_nums1] if partition_nums1 < m else float('inf')
        max_left_nums2 = nums2[partition_nums2 - 1] if partition_nums2 > 0 else float('-inf')
        min_right_nums2 = nums2[partition_nums2] if partition_nums2 < n else float('inf')

        # Check if the partition is correct
        if max_left_nums1 <= min_right_nums2 and max_left_nums2 <= min_right_nums1:
            if (m + n) % 2 == 0:
                return (max(max_left_nums1, max_left_nums2) + min(min_right_nums1, min_right_nums2)) / 2
            else:
                return float(max(max_left_nums1, max_left_nums2))
        elif max_left_nums1 > min_right_nums2:
            # Move partition in nums1 to the left
            high = partition_nums1 - 1
        else:
            # Move partition in nums1 to the right
            low = partition_nums1 + 1

    return 0.0  # This line is theoretically unreachable

