from typing import List

def optimized_cocktail_shaker_sort(arr: List[int]) -> List[int]:
    if len(arr) <= 1:
        return arr  # Already sorted for single-element or empty lists

    n = len(arr)
    swapped = True
    start = 0
    end = n - 1
    last_swap = 0

    while swapped:
        swapped = False

        # Left to right pass (smallest element moves to the left)
        for i in range(start, end):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                swapped = True
                last_swap = i

        if not swapped:
            break  # No swaps, list is sorted

        end -= 1  # Reduce the range for the next pass

        # Right to left pass (largest element moves to the right)
        for i in range(end, start, -1):
            if arr[i] < arr[i - 1]:
                arr[i], arr[i - 1] = arr[i - 1], arr[i]
                swapped = True
                last_swap = i

        if not swapped:
            break  # No swaps, list is sorted

        start += 1  # Reduce the range for the next pass

    return arr

def word_wrap(text: str, max_width: int) -> str:
    words = text.split()
    lines = []
    current_line = []

    for word in words:
        # If the current line is empty, we can add the word directly
        if not current_line:
            current_line.append(word)
        else:
            # Calculate the length of the current line if we add the word
            line_length = len(" ".join(current_line)) + 1 + len(word)
            if line_length <= max_width:
                current_line.append(word)
            else:
                # Add the current line to lines
                lines.append(" ".join(current_line))
                current_line = [word]

    # Add the last line
    if current_line:
        lines.append(" ".join(current_line))

    # Join the lines with '\n' and return the result
    return "\n".join(lines)

