import heapq

def find_shortest_time(N, M, routes, A, B):
    # Build adjacency list
    adj = [[] for _ in range(N + 1)]
    for u, v, w in routes:
        adj[u].append((v, w))

    # Dijkstra's algorithm
    dist = [float('inf')] * (N + 1)
    dist[A] = 0
    heap = [(0, A)]

    while heap:
        current_dist, u = heapq.heappop(heap)

        if u == B:
            return current_dist

        if current_dist > dist[u]:
            continue

        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))

    return -1

