from collections import defaultdict, deque

MOD = 10**9 + 7

def count_paths(n, m, d, values, edges):
    # Build the graph
    graph = defaultdict(list)
    in_degree = [0] * n

    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    # Topological sort using Kahn's algorithm
    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    topological_order = []
    while queue:
        u = queue.popleft()
        topological_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Initialize DP: dp[node][r] = number of paths to node with sum % d == r
    dp = [ [0] * d for _ in range(n) ]
    dp[0][values[0] % d] = 1  # Starting at node 0 with its own value

    for u in topological_order:
        for v in graph[u]:
            for r in range(d):
                new_remainder = (values[v] + r) % d
                dp[v][new_remainder] = (dp[v][new_remainder] + dp[u][r]) % MOD

    # Result is the number of paths to node n-1 with sum mod d == 0
    return dp[n-1][0]

def generate_pascals_triangle(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("generate_pascals_triangle() requires a non-negative integer for n")

    triangle = []
    for row in range(n):
        if row == 0:
            triangle.append([1])
        else:
            prev_row = triangle[row - 1]
            current_row = [1]
            for i in range(1, row):
                current_row.append(prev_row[i - 1] + prev_row[i])
            current_row.append(1)
            triangle.append(current_row)

    return triangle

