from typing import List

def longest_str_chain(words: List[str]) -> int:
    # Sort words by length to ensure we process shorter words first
    words.sort(key=lambda x: len(x))

    # Dictionary to store the longest chain ending with each word
    dp = {word: 1 for word in words}

    # For each word, try to build longer chains by checking predecessors
    for word in words:
        for i in range(len(word)):
            predecessor = word[:i] + word[i+1:]
            if predecessor in dp:
                dp[word] = max(dp[word], dp[predecessor] + 1)

    # Return the maximum chain length
    return max(dp.values())

