def maximize_score(n, T, puzzles):
    # Initialize a 1D DP array where dp[t] is the maximum score achievable with time t
    dp = [0] * (T + 1)

    # Iterate through each puzzle
    for time, score in puzzles:
        # Update dp in reverse to avoid overwriting values we still need
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + score)

    # The answer is the maximum score achievable within time T
    return dp[T]

