def repeat_string(A: str, B: str) -> int:
    if not A or not B:
        return -1  # As per the note, handle empty string case

    # If B is already a substring of A
    if B in A:
        return 1

    # We build the repeated string until it's long enough to possibly contain B
    # We'll try up to len(B) // len(A) + 2 concatenations
    max_repeats = len(B) // len(A) + 2

    for repeat in range(2, max_repeats + 1):
        repeated = A * repeat
        if B in repeated:
            return repeat

    # If not found in the repeated string, return -1
    return -1

