def consecutive_sum_ways(n):
    count = 0
    k = 1
    while True:
        # Calculate the minimum value of n for a sequence of k terms
        min_sum = k * (k + 1) // 2
        if min_sum > n:
            break
        if (n - min_sum) % k == 0:
            count += 1
        k += 1
    return count

