def most_frequent_k_length_substring(sequence, k):
    if k <= 0 or len(sequence) < k:
        return ""

    substring_counts = {}

    for i in range(len(sequence) - k + 1):
        substring = sequence[i:i + k]
        substring_counts[substring] = substring_counts.get(substring, 0) + 1

    # Find the maximum frequency
    max_count = max(substring_counts.values())

    # Collect all substrings with the max frequency
    candidates = [sub for sub, count in substring_counts.items() if count == max_count]

    # Return the lexicographically smallest one
    return min(candidates)

