from itertools import permutations

def can_rearrange_to_divisible(n, k):
    if k == 0:
        return False  # Division by zero is not allowed

    binary = bin(n)[2:]  # Get binary representation without '0b' prefix

    # Generate all unique permutations of the binary digits
    seen = set()
    for p in permutations(binary):
        perm_str = ''.join(p)
        if perm_str in seen:
            continue
        seen.add(perm_str)
        # Skip permutations starting with '0' (except for the case when it's '0' itself)
        if perm_str[0] == '0' and len(perm_str) > 1:
            continue
        num = int(perm_str, 2)
        if num % k == 0:
            return True
    return False

