def can_partition(n, arr):
    total_sum = sum(arr)

    # If the total sum is odd, partition is not possible
    if total_sum % 2 != 0:
        return "NO"

    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: zero sum is always possible

    for num in arr:
        for j in range(target, num - 1, -1):
            if dp[j - num]:
                dp[j] = True

    return "YES" if dp[target] else "NO"

