def predict_patients(n, patients):
    # If there's only one day of data, we can't determine a geometric progression
    if n == 1:
        return patients[0]

    # Check if the sequence is a geometric progression
    is_geometric = True
    ratio = patients[1] / patients[0]

    for i in range(2, n):
        if patients[i] / patients[i - 1] != ratio:
            is_geometric = False
            break

    if is_geometric:
        # The next term in the geometric progression
        return int(patients[-1] * ratio)
    else:
        # If not geometric, the next day is the same as the previous day
        return patients[-1]

