    for i in range(n):
        swapped = False
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
                if simulation:
                    print(f"iteration {i + 1} : {' '.join(map(str, arr))}")
        if not swapped:
            break  # Early termination if no swaps occurred in the pass
    return arr

