from typing import List, Union
from functools import reduce

def filter_with_limits(arr: List[int], min_lim: Union[int, None], max_lim: Union[int, None]) -> List[int]:
    if not arr:
        return []

    # Determine the actual min and max limits based on `None`
    if min_lim is None:
        min_lim = min(arr)
    if max_lim is None:
        max_lim = max(arr)

    # Filter the array based on limits
    filtered = [x for x in arr if min_lim <= x <= max_lim]

    # If both limits were None, return the array sorted
    if min_lim is None and max_lim is None:
        return sorted(arr)

    return filtered

