def min_recognition_stars(ratings):
    n = len(ratings)
    if n == 0:
        return 0

    stars = [1] * n  # Every employee gets at least one star

    # Left to right pass
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            stars[i] = stars[i - 1] + 1

    # Right to left pass
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            stars[i] = max(stars[i], stars[i + 1] + 1)

    return sum(stars)

