def generate_potion_elements(S, N, rules):
    from collections import defaultdict

    # Create a dictionary for transformation rules
    transform = defaultdict(list)
    for rule in rules:
        parts = rule.split(" -> ")
        src = parts[0]
        dests = parts[1]
        transform[src] = list(dests)

    result = set()

    def dfs(current):
        # If no more transformations can be applied, add to result
        if not any(c in transform for c in current):
            result.add(current)
            return

        # Try transforming each character in current that can be transformed
        for i in range(len(current)):
            if current[i] in transform:
                # For each possible replacement
                for replacement in transform[current[i]]:
                    # Recurse with the new string
                    dfs(current[:i] + replacement + current[i+1:])

    # Start DFS with the original string
    dfs(S)

    # Sort and return the results
