def is_merge(s, part1, part2):
    # Pre-check: combined length should match s
    if len(part1) + len(part2) != len(s):
        return False

    # Memoization cache
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i, j):
        # If we have reached the end of both part1 and part2, we are successful
        if i == len(part1) and j == len(part2):
            return True
        # If we have reached the end of part1 or part2, check the rest
        if i == len(part1):
            return s[i + j:] == part2[j:]
        if j == len(part2):
            return s[i + j:] == part1[i:]

        # Check if the current character of s matches the next character in part1 or part2
        if s[i + j] == part1[i] and dp(i + 1, j):
            return True
        if s[i + j] == part2[j] and dp(i, j + 1):
            return True
        return False

    return dp(0, 0)

