import heapq

def calculateTrappedWater(heightMap, volume):
    if not heightMap or not heightMap[0] or volume == 0:
        return 0

    rows, cols = len(heightMap), len(heightMap[0])
    visited = [[False] * cols for _ in range(rows)]
    min_heap = []

    # Initialize the boundary
    for i in range(rows):
        for j in range(cols):
            if i == 0 or i == rows - 1 or j == 0 or j == cols - 1:
                heapq.heappush(min_heap, (heightMap[i][j], i, j))
                visited[i][j] = True

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    trapped_water = 0

    while min_heap and volume > 0:
        height, x, y = heapq.heappop(min_heap)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny]:
                visited[nx][ny] = True
                if heightMap[nx][ny] < height:
                    # Water can be trapped here
                    trapped_water += height - heightMap[nx][ny]
                    volume -= height - heightMap[nx][ny]
                    if volume <= 0:
                        return trapped_water
                # Push the neighbor to the heap with max of their height and the current height
                heapq.heappush(min_heap, (max(height, heightMap[nx][ny]), nx, ny))

    return trapped_water

