def num_paths(grid, n, m, k):
    # Initialize DP table
    dp = [[0] * m for _ in range(n)]

    # Start from top-left corner
    if grid[0][0] == 0:
        dp[0][0] = 1
    else:
        return 0  # Start cell is blocked

    # Fill the DP table
    for i in range(n):
        for j in range(m):
            if i == 0 and j == 0:
                continue  # Already initialized
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                top = dp[i - 1][j] if i > 0 else 0
                left = dp[i][j - 1] if j > 0 else 0
                dp[i][j] = (top + left) % k

    return dp[n - 1][m - 1]

