def can_transform(source, target):
    if len(source) != len(target):
        return False

    mapping = {}
    for s_char, t_char in zip(source, target):
        # If character in source has already been mapped, check if it matches the current target char
        if s_char in mapping:
            if mapping[s_char] != t_char:
                return False
        else:
            # Check if target character has already been assigned to a different source character
            if t_char in mapping.values():
                return False
            mapping[s_char] = t_char

    # Now verify that applying the mapping to source gives target
    transformed = ''.join([mapping[char] for char in source])
    return transformed == target

