def eraseOverlapIntervals(intervals):
    if not intervals:
        return 0

    # Sort intervals by their end points
    intervals.sort(key=lambda x: x[1])

    count = 1  # Count of non-overlapping intervals
    end = intervals[0][1]

    for start, _end in intervals[1:]:
        if start >= end:
            count += 1
            end = _end

    return len(intervals) - count

