from typing import List

def find_min_rotated(array: List[int]) -> int:
    low, high = 0, len(array) - 1

    while low < high:
        mid = (low + high) // 2

        if array[mid] > array[high]:
            # The minimum is in the right half
            low = mid + 1
        else:
            # The minimum is in the left half or at mid
            high = mid

    return array[low]

