def is_good_sequence(n, sequence):
    total_sum = sum(sequence)

    # If total sum is odd, it's impossible to split into two equal parts
    if total_sum % 2 != 0:
        return "NO"

    target = total_sum // 2
    dp = set()
    dp.add(0)

    for num in sequence:
        new_dp = set()
        for s in dp:
            new_sum = s + num
            if new_sum <= target:
                new_dp.add(new_sum)
        dp.update(new_dp)

    return "YES" if target in dp else "NO"

