from typing import List
from collections import Counter

def longest_harmonious_subsequence(nums: List[int]) -> int:
    freq = Counter(nums)
    max_length = 0

    for num in freq:
        if num + 1 in freq:
            max_length = max(max_length, freq[num] + freq[num + 1])

    return max_length

def maximum_sum_subgrid(n, m, grid):
    max_sum = float('-inf')

    # Iterate over all possible pairs of left and right columns
    for left in range(m):
        # Initialize a temporary array to store row sums
        temp = [0] * n
        for right in range(left, m):
            # Update the temp array with column sums from left to right
            for i in range(n):
                temp[i] += grid[i][right]

            # Apply Kadane's algorithm on the temp array
            current_sum = 0
            for val in temp:
                current_sum = max(val, current_sum + val)
                max_sum = max(max_sum, current_sum)

    return max_sum

