from collections import deque

def min_operations(start, goal):
    if start == goal:
        return 0

    queue = deque()
    queue.append((start, 0))  # (current_value, operations)
    visited = set()
    visited.add(start)

    while queue:
        current, steps = queue.popleft()

        # Try all allowed operations
        for next_val in [current + 1, current - 1, current * 2]:
            if next_val == goal:
                return steps + 1
            if next_val not in visited and next_val >= 0:
                visited.add(next_val)
                queue.append((next_val, steps + 1))

    return -1

