def alice_collects(n, sequence):
    from functools import lru_cache

    @lru_cache(None)
    def dp(i, j, turn):
        if i > j:
            return 0
        if turn == 0:  # Alice's turn
            return max(sequence[i] + dp(i + 1, j, 1), sequence[j] + dp(i, j - 1, 1))
        else:  # Bob's turn
            return min(dp(i + 1, j, 0), dp(i, j - 1, 0))

    return dp(0, n - 1, 0)

