from typing import List

def has_subarray_sum(nums: List[int], k: int) -> bool:
    prefix_sums = set()
    current_sum = 0

    for num in nums:
        current_sum += num
        if current_sum == k:
            return True
        if (current_sum - k) in prefix_sums:
            return True
        prefix_sums.add(current_sum)

    return False

def knapsack(n, W, items):
    # Initialize a DP array where dp[w] represents the maximum value achievable with weight w
    dp = [0] * (W + 1)

    for weight, value in items:
        # Traverse the dp array in reverse to ensure each item is only used once
        for w in range(W, weight - 1, -1):
            dp[w] = max(dp[w], dp[w - weight] + value)

    # The maximum value achievable within the weight limit is at dp[W]
    return dp[W]

