def count_ways(strings, n, k):
    from collections import defaultdict

    # Convert each string to a bitmask of unique characters
    char_masks = []
    for s in strings:
        mask = 0
        for ch in set(s):
            mask |= 1 << (ord(ch) - ord('a'))
        char_masks.append(mask)

    # dp[mask] is a dictionary of {char_mask: count}
    dp = [defaultdict(int) for _ in range(1 << n)]
    dp[0][0] = 1  # Start with empty subset and empty character set

    for mask in range(1 << n):
        if dp[mask]:
            for i in range(n):
                if not (mask & (1 << i)):
                    new_mask = mask | (1 << i)
                    for char_set, count in dp[mask].items():
                        new_char_set = char_set | char_masks[i]
                        dp[new_mask][new_char_set] += count

    # Count all subsets with at least k unique characters
    result = 0
    for mask in range(1 << n):
        for char_set, count in dp[mask].items():
            if bin(char_set).count('1') >= k:
                result += count

    return result

