def dp_binomial_coefficient(n: int, k: int) -> int:
    # Create a 2D list to store the binomial coefficients
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base cases
    for i in range(n + 1):
        dp[i][0] = 1  # C(n, 0) = 1
        if i <= k:
            dp[i][i] = 1  # C(n, n) = 1

    # Fill the dp table using the recurrence relation
    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]

    return dp[n][k]

