        else:
            dp[0][j] = 0  # Wall, no paths can go through

    # Fill the first column
    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i - 1][0]
        else:
            dp[i][0] = 0  # Wall, no paths can go through

