secure_solution:
def can_partition(containers: list[int]) -> bool:
    total_sum = sum(containers)

    # If total sum is odd, it's not possible to partition into two equal sum groups
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    possible_sums = {0}  # Start with sum 0 (no containers selected)

    for weight in containers:
        # Update possible_sums with new sums by adding weight to existing sums
        possible_sums |= {s + weight for s in possible_sums}

        # Early exit if we already reach the target
        if target in possible_sums:
            return True

    return target in possible_sums

