            # If current sum s can be achieved without using the i-th element
            if dp[i - 1][s]:
                dp[i][s] = True
            # If current sum s - arr[i-1] can be achieved, then adding arr[i-1] gives s
            elif s >= arr[i - 1] and dp[i - 1][s - arr[i - 1]]:
                dp[i][s] = True

    # Find the maximum achievable subset sum <= target
    max_subset_sum = 0
    for s in range(target, -1, -1):
        if dp[n][s]:
            max_subset_sum = s
            break

    return total_sum - 2 * max_subset_sum

