        if obstacle_grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = 0  # Obstacle, no path here

    # Fill the rest of the DP table
    for i in range(1, m):
        for j in range(1, n):
