secure_solution:
def nextGreaterElements(nums):
    n = len(nums)
    result = [-1] * n
    stack = []

    for i in range(2 * n):
        # Use modulo to simulate circular behavior
        current = nums[i % n]
        while stack and nums[stack[-1]] < current:
            index = stack.pop()
            result[index] = current
        if i < n:
            stack.append(i)

    return result

