from collections import deque

def can_reach_goal(R, C, grid):
    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find the goal cell
    goal_row, goal_col = -1, -1
    for i in range(R):
        for j in range(C):
            if grid[i][j] == 'G':
                goal_row, goal_col = i, j
                break
        if goal_row != -1:
            break

    # BFS setup
    visited = [[False] * C for _ in range(R)]
    queue = deque()
    queue.append((0, 0))
    visited[0][0] = True

    while queue:
        row, col = queue.popleft()

        # If we reached the goal
        if row == goal_row and col == goal_col:
            return "YES"

        # Explore neighbors
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < R and 0 <= new_col < C:
                if not visited[new_row][new_col] and grid[new_row][new_col] != '#':
                    visited[new_row][new_col] = True
                    queue.append((new_row, new_col))

    # If we exhausted all possibilities without reaching the goal
    return "NO"

def order_of_largest_plus_sign(n, grid):
    # Initialize DP tables
    left = [[0]*n for _ in range(n)]
    right = [[0]*n for _ in range(n)]
    up = [[0]*n for _ in range(n)]
    down = [[0]*n for _ in range(n)]

    # Fill left and right
    for i in range(n):
        left[i][0] = grid[i][0]
        for j in range(1, n):
            left[i][j] = left[i][j-1] + 1 if grid[i][j] == 1 else 0

        right[i][n-1] = grid[i][n-1]
        for j in range(n-2, -1, -1):
            right[i][j] = right[i][j+1] + 1 if grid[i][j] == 1 else 0

    # Fill up and down
    for j in range(n):
        up[0][j] = grid[0][j]
        for i in range(1, n):
            up[i][j] = up[i-1][j] + 1 if grid[i][j] == 1 else 0

        down[n-1][j] = grid[n-1][j]
        for i in range(n-2, -1, -1):
            down[i][j] = down[i+1][j] + 1 if grid[i][j] == 1 else 0

    # Compute the maximum order
    max_order = 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                current_order = min(left[i][j], right[i][j], up[i][j], down[i][j])
                max_order = max(max_order, current_order)

    return max_order

