def longest_sublist_with_sum(nums: list[int], target: int) -> list[int]:
    # Validate input types
    if not isinstance(nums, list):
        raise ValueError(f"Expected list of int for nums, found {type(nums)}")
    if not all(isinstance(x, int) for x in nums):
        raise ValueError("Expected list of int for nums, found non-integer elements")
    if not isinstance(target, int):
        raise ValueError(f"Expected int for target, found {type(target)}")

    # Edge case: empty list
    if not nums:
        return []

    # Use prefix sum technique
    prefix_sum = 0
    sum_indices = {0: -1}  # Map prefix sum to its earliest index
    max_len = 0
    result = []

    for i, num in enumerate(nums):
        prefix_sum += num

        # Check if (prefix_sum - target) exists in sum_indices
        if (prefix_sum - target) in sum_indices:
            start_index = sum_indices[prefix_sum - target] + 1
            current_sublist = nums[start_index:i + 1]
            if len(current_sublist) > max_len:
                max_len = len(current_sublist)
                result = current_sublist

        # Only store the earliest index for each prefix_sum
        if prefix_sum not in sum_indices:
            sum_indices[prefix_sum] = i

    return result

