def optimized_selection_sort(arr: list[int]) -> list[int]:
    n = len(arr)
    for i in range(n):
        # Check if the remaining portion of the array is already sorted
        is_sorted = True
        for j in range(i + 1, n):
            if arr[j] < arr[j - 1]:
                is_sorted = False
                break
        if is_sorted:
            break

        # Perform the selection sort step
        min_index = i
        for j in range(i + 1, n):
            if arr[j] < arr[min_index]:
                min_index = j
        arr[i], arr[min_index] = arr[min_index], arr[i]
    return arr

