def find_unique_pairs(nums: list, target: int) -> list:
    seen = set()
    pairs = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            # Ensure the pair is sorted so (a, b) and (b, a) are considered the same
            pair = tuple(sorted((num, complement)))
            pairs.add(pair)
        seen.add(num)

    # Convert the set of pairs to a sorted list of tuples
    return sorted(pairs)

