from typing import List

def can_partition(nums: List[int]) -> bool:
    total_sum = sum(nums)

    # If the total sum is odd, it's impossible to partition into two equal subsets
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: we can always form a subset sum of 0

    for num in nums:
        for j in range(target, num - 1, -1):
            if dp[j - num]:
                dp[j] = True

    return dp[target]

