def can_make_palindrome(s, k):
    n = len(s)
    changes_needed = 0

    # Compare characters from both ends towards the center
    for i in range(n // 2):
        if s[i] != s[n - 1 - i]:
            changes_needed += 1

    # If the number of changes needed is less than or equal to k, return "YES"
    return "YES" if changes_needed <= k else "NO"

