secure_solution:
def encrypt_title(title, k):
    result = ""
    for char in title:
        if char.isalpha():
            # Determine if the character is uppercase or lowercase
            is_upper = char.isupper()
            # Convert to ASCII value, shift by k, wrap around using modulo 26
            shifted = ord(char) + k
            if is_upper:
                # Wrap around for uppercase letters (A-Z)
                shifted = (shifted - ord('A')) % 26 + ord('A')
            else:
                # Wrap around for lowercase letters (a-z)
                shifted = (shifted - ord('a')) % 26 + ord('a')
            result += chr(shifted)
        else:
            # Non-alphabetic characters remain unchanged
            result += char
    return result

