secure_solution:
def min_swaps_to_group_ones(arr):
    total_ones = sum(arr)
    n = len(arr)
    if total_ones == 0 or total_ones == n:
        return 0  # No swaps needed if all are 0s or all are 1s

    min_swaps = float('inf')
    current_zeros = 0

    # Initialize the first window
    for i in range(total_ones):
        if arr[i] == 0:
            current_zeros += 1

    min_swaps = current_zeros

    # Slide the window
    for i in range(total_ones, n):
        if arr[i] == 0:
            current_zeros += 1
        if arr[i - total_ones] == 0:
            current_zeros -= 1
        min_swaps = min(min_swaps, current_zeros)

    return min_swaps

