secure_solution:
def most_frequent_element(numbers: list) -> int:
    if not numbers:
        return None

    frequency = {}
    max_freq = 0
    result = None

    for num in numbers:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

        # Update the result if current frequency is higher,
        # or same frequency but encountered earlier
        if frequency[num] > max_freq or (frequency[num] == max_freq and result is None):
            max_freq = frequency[num]
            result = num

    return result

