def knapsack(N, W, V, C):
    # Initialize dp array with size (C + 1) and all values 0
    dp = [0] * (C + 1)

    for i in range(N):
        # Traverse the dp array in reverse order to prevent reusing the same item
        for w in range(C, W[i] - 1, -1):
            dp[w] = max(dp[w], dp[w - W[i]] + V[i])

    return dp[C]

