def knapsack(nums, weights, limit):
    # Initialize DP array with size (limit + 1), starting with 0 value
    dp = [0] * (limit + 1)

    # Iterate through each item
    for i in range(len(nums)):
        # Go backward to prevent reusing the same item
        for w in range(limit, weights[i] - 1, -1):
            dp[w] = max(dp[w], dp[w - weights[i]] + nums[i])

    return dp[limit]

def max_contiguous_subarray_sum(arr, k):
    if k <= 0 or k > len(arr):
        return 0

    current_sum = sum(arr[:k])
    max_sum = current_sum

    for i in range(k, len(arr)):
        current_sum += arr[i] - arr[i - k]
        max_sum = max(max_sum, current_sum)

    return max_sum

def array_rank_transform(arr):
    # Create a sorted version of the array
    sorted_arr = sorted(arr)

    # Create a dictionary to map each unique element to its rank
    rank_map = {}
    rank = 1
    for num in sorted_arr:
        if num not in rank_map:
            rank_map[num] = rank
            rank += 1

    # Replace each element in the original array with its rank
    return [rank_map[num] for num in arr]

