                        if 0 <= ni < N and 0 <= nj < N:
                            if result[ni][nj] == 'S':
                                place = False
                                break
                    if not place:
                        break
                if place:
                    result[i][j] = 'S'

    # Convert back to strings
    return [''.join(row) for row in result]

