def max_subarray_len(nums: List[int], k: int) -> int:
    prefix_sum = 0
    sum_indices = {0: -1}  # Maps prefix sum to its earliest index
    max_length = 0

    for i, num in enumerate(nums):
        prefix_sum += num
        if (prefix_sum - k) in sum_indices:
            max_length = max(max_length, i - sum_indices[prefix_sum - k])
        if prefix_sum not in sum_indices:
            sum_indices[prefix_sum] = i

    return max_length

def longestValidParentheses(s: str) -> int:
    stack = [-1]  # Initialize stack with -1 to handle base case
    max_length = 0

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                current_length = i - stack[-1]
                max_length = max(max_length, current_length)

    return max_length

