from typing import List

def count_paths(matrix: List[List[str]]) -> int:
    n = len(matrix)
    m = len(matrix[0])

    # Initialize DP table
    dp = [[0 for _ in range(m)] for _ in range(n)]

    # Starting point
    dp[0][0] = 1 if matrix[0][0] == '.' else 0

    # Fill the DP table
    for i in range(n):
        for j in range(m):
            if matrix[i][j] == '#':
                dp[i][j] = 0
                continue
            if i > 0:
                dp[i][j] += dp[i-1][j]
            if j > 0:
                dp[i][j] += dp[i][j-1]

    return dp[n-1][m-1]

