from typing import List

def rotate_array(arr: List[int], k: int) -> List[int]:
    n = len(arr)
    if n == 0:
        return arr

    k = k % n  # Reduce unnecessary rotations
    if k == 0:
        return arr

    # Rotate the array by k steps to the right
    return arr[-k:] + arr[:-k]

