def tribonacci(k):
    # Base cases
    if k == 0:
        return 0
    elif k == 1 or k == 2:
        return 1

    # Initialize the first three numbers
    a, b, c = 0, 1, 1

    # Compute the sequence up to the kth number
    for _ in range(3, k + 1):
        next_val = a + b + c
        a, b, c = b, c, next_val

    return c

