def unique_paths_with_obstacles(grid):
    m = len(grid)
    n = len(grid[0])

    # Initialize DP matrix with the same dimensions as grid
    dp = [[0 for _ in range(n)] for _ in range(m)]

    # If starting cell is blocked, no path exists
    if grid[0][0] == 1:
        return 0

    # First row and first column initialization
    for i in range(m):
        if grid[i][0] == 1:
            break
        dp[i][0] = 1

    for j in range(n):
        if grid[0][j] == 1:
            break
        dp[0][j] = 1

    # Fill the DP table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 1:
                dp[i][j] = 0  # Obstacle, cannot pass
            else:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

