def max_dominated_chain_length(points):
    if not points:
        return 0

    # Sort points by x, then by y
    points.sort()

    n = len(points)
    dp = [1] * n  # dp[i] is the max chain length ending at i

    for i in range(n):
        for j in range(i):
            # Check if points[j] dominates points[i]
            if points[j][0] <= points[i][0] and points[j][1] <= points[i][1] and (points[j][0] != points[i][0] or points[j][1] != points[i][1]):
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

