def island_perimeter(grid):
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    perimeter = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                # Start with 4 sides
                perimeter += 4
                # Check top
                if i > 0 and grid[i - 1][j] == 1:
                    perimeter -= 1
                # Check bottom
                if i < rows - 1 and grid[i + 1][j] == 1:
                    perimeter -= 1
                # Check left
                if j > 0 and grid[i][j - 1] == 1:
                    perimeter -= 1
                # Check right
                if j < cols - 1 and grid[i][j + 1] == 1:
                    perimeter -= 1

    return perimeter

