def smallest_prime_gap(N):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    primes = []
    num = 2
    while len(primes) < N:
        if is_prime(num):
            primes.append(num)
        num += 1

    # Compute the prime gaps
    gaps = [primes[i+1] - primes[i] for i in range(len(primes) - 1)]

    return min(gaps)

