def longest_balanced_subarray(votes):
    sum_index = {0: -1}  # Initialize with sum 0 at index -1
    max_length = 0
    current_sum = 0

    for i, vote in enumerate(votes):
        current_sum += vote
        if current_sum in sum_index:
            # If we've seen this sum before, compute length
            max_length = max(max_length, i - sum_index[current_sum])
        else:
            # Store the first occurrence of this sum
            sum_index[current_sum] = i

    return max_length

def largest_open_square(n, m, grid):
    # Initialize DP table
    dp = [[0] * m for _ in range(n)]
    max_side = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
