def find_minimum_imbalance(n, k, values):
    values.sort()

    def is_possible(max_diff):
        count = 1
        start = values[0]
        for i in range(1, n):
            if values[i] - start > max_diff:
                count += 1
                start = values[i]
                if count > k:
                    return False
        return True

    # Binary search on the answer
    left = 0
    right = values[-1] - values[0]

    while left < right:
        mid = (left + right) // 2
        if is_possible(mid):
            right = mid
        else:
            left = mid + 1

    return left

