def can_split_into_three_equal_sum_subarrays(nums):
    total_sum = sum(nums)
    if total_sum % 3 != 0:
        return False

    target = total_sum // 3
    count = 0
    cumulative_sum = 0

    for num in nums:
        cumulative_sum += num
        if cumulative_sum == target:
            count += 1
            cumulative_sum = 0  # Reset for the next subarray

        if count == 2:
            return True

    return False

