def min_transport_cost(n, m, q, roads, queries):
    import sys
    input = sys.stdin.read
    data = input().split()

    INF = float('inf')

    # Initialize distance matrix
    dist = [[INF] * (n + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dist[i][i] = 0

    # Populate direct road costs
    for u, v, w in roads:
        dist[u][v] = w
        dist[v][u] = w  # assuming roads are bidirectional

    # Floyd-Warshall algorithm
    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Answer the queries
    result = []
    for a, b in queries:
        if dist[a][b] == INF:
            result.append(-1)
        else:
            result.append(dist[a][b])

    return result

