from typing import List

def three_sum(nums: List[int], target: int) -> bool:
    nums.sort()  # Sort the list for two-pointer approach
    n = len(nums)

    for i in range(n - 2):
        # Skip duplicate elements to avoid redundant checks
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left = i + 1
        right = n - 1

        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]

            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return False

