def min_number_of_steps(n, entries, edges):
    # Build the adjacency list
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)

    # Initialize the queue with nodes having no incoming edges
    queue = deque()
    for i in range(n):
        if entries[i] == 0:
            queue.append(i)

    steps = 0
    processed = 0

