from typing import List

def find_triplet_with_sum(arr: List[int], target: int) -> bool:
    # If the array has fewer than 3 elements, return False
    if len(arr) < 3:
        return False

    # Sort the array to facilitate the two-pointer approach
    arr.sort()

    # Iterate through each element in the array
    for i in range(len(arr) - 2):
        # Use two pointers to find the remaining two elements
        left = i + 1
        right = len(arr) - 1

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]

