            if grid[i][j] == '0':
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
                max_square_size = max(max_square_size, dp[i][j])
            else:
                dp[i][j] = 0  # Building, cannot be part of a square of empty cells

    return max_square_size

