secure_solution:
def min_moves_to_sort_deck(n, cards):
    # Map each card value to its index in the input to get the positions
    pos = {card: i for i, card in enumerate(cards)}

    # Extract positions in the order of the values from 1 to n
    sequence = [pos[i] for i in range(1, n + 1)]

    # Compute the length of the longest increasing subsequence (LIS)
    import bisect
    lis = []
    for p in sequence:
        idx = bisect.bisect_left(lis, p)
        if idx == len(lis):
            lis.append(p)
        else:
            lis[idx] = p

    # Minimum number of moves is n - length of LIS
    return n - len(lis)

