def find_max_difference(nums):
    if not nums or len(nums) < 2:
        return 0  # Not enough elements to form a subarray with 2 elements

    max_diff = 0
    min_so_far = nums[0]

    for j in range(1, len(nums)):
        max_diff = max(max_diff, nums[j] - min_so_far)
        min_so_far = min(min_so_far, nums[j])

    return max_diff

