def max_apples(grid):
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]

    # Initialize first cell
    dp[0][0] = grid[0][0]

    # Fill first row
    for j in range(1, n):
        dp[0][j] = grid[0][j] + dp[0][j-1]

    # Fill first column
    for i in range(1, m):
        dp[i][0] = grid[i][0] + dp[i-1][0]

    # Fill rest of the dp table
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = grid[i][j] + max(dp[i-1][j], dp[i][j-1])

    return dp[m-1][n-1]

