def knapsack(maxWeight, weights, values):
    # Initialize dp array with size maxWeight + 1
    dp = [0] * (maxWeight + 1)

    # Iterate through each item
    for i in range(len(weights)):
        # Update dp in reverse to prevent reusing the same item
        for w in range(maxWeight, weights[i] - 1, -1):
            dp[w] = max(dp[w], dp[w - weights[i]] + values[i])

    # The maximum value that can be achieved is in dp[maxWeight]
    return dp[maxWeight]

def first_non_repeating_character(s):
    # Create a dictionary to store character counts
    char_count = {}

    # First pass: count the occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Second pass: find the first character with a count of 1
    for char in s:
        if char_count[char] == 1:
            return char

    # If no non-repeating character is found, return an empty string
    return ""

