def num_distinct_subsequences(s: str, t: str) -> int:
    m, n = len(s), len(t)

    # Edge cases
    if n == 0:
        return 1
    if m < n:
        return 0

    # Initialize DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: empty t is a subsequence of any s (even empty)
    for i in range(m + 1):
        dp[i][0] = 1

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s[i-1] == t[j-1]:
                dp[i][j] = dp[i-1][j] + dp[i-1][j-1]
            else:
                dp[i][j] = dp[i-1][j]

    return dp[m][n]

