def find_viewpoints(heights):
    viewpoints = []
    max_height = float('-inf')

    # Iterate from right to left
    for i in range(len(heights) - 1, -1, -1):
        if heights[i] > max_height:
            viewpoints.append(i)
            max_height = heights[i]

    # Reverse to maintain left-to-right order of indices
    return viewpoints[::-1]

