def min_dishes(calories, T):
    # Initialize a dictionary to store the minimum number of dishes needed for each calorie sum
    dp = {0: 0}  # Base case: 0 calories can be achieved with 0 dishes

    for cal in calories:
        # We need to make a copy of the current dictionary to avoid overwriting during iteration
        temp_dp = dp.copy()
        for total in dp:
            new_total = total + cal
            if new_total > T:
                continue
            if new_total not in temp_dp or dp[total] + 1 < temp_dp[new_total]:
                temp_dp[new_total] = dp[total] + 1
        dp = temp_dp

    return dp.get(T, -1)

