def books_readable_by_students(n, m, reading_capacities, pages_in_books):
    # Sort the list of book pages
    pages_in_books.sort()

    # For each student, count how many books they can read
    result = []
    for capacity in reading_capacities:
        # Binary search for the rightmost page <= capacity
        left, right = 0, m
        while left < right:
            mid = (left + right) // 2
            if pages_in_books[mid] <= capacity:
                left = mid + 1
            else:
                right = mid
        result.append(left)

    return result

import math
from functools import reduce

def min_sequence_length(t, test_cases):
    results = []

    for case in test_cases:
        n, a = case
        if n == 1:
            results.append(1)
            continue

        # Function to compute GCD of a list
        def gcd_list(lst):
            return reduce(math.gcd, lst)

        # Compute global GCD of the whole sequence
        global_gcd = gcd_list(a)

        # Count how many elements are divisible by global_gcd
        count = sum(1 for x in a if x % global_gcd == 0)

        # If all elements are divisible by global_gcd, we can reduce to 1
        if count == n:
            results.append(1)
        else:
            # Otherwise, the minimal length is at least 2
            results.append(2)

    return results

