def maximize_book_value(L, n, books):
    # Initialize dp array where dp[w] is the max value with total width w
    dp = [0] * (L + 1)

    for w_i, v_i in books:
        # Traverse from L down to w_i to ensure each item is used only once
        for w in range(L, w_i - 1, -1):
            dp[w] = max(dp[w], dp[w - w_i] + v_i)

    # The maximum value is the maximum value for any width up to L
    return max(dp)

