secure_solution:
def max_sum_k_consecutive(arr, k):
    if len(arr) < k or k <= 0:
        return 0

    current_sum = sum(arr[:k])
    max_sum = current_sum

    for i in range(k, len(arr)):
        current_sum += arr[i] - arr[i - k]
        max_sum = max(max_sum, current_sum)

    return max_sum

