def redistribute_resources(resources):
    total_resources = sum(resources)
    n = len(resources)

    # Check if total resources can be evenly distributed
    if total_resources % n != 0:
        # Equal distribution not possible, set all to -1
        for i in range(n):
            resources[i] = -1
