def find_duplicates(nums):
    result = []
    for num in nums:
        # Calculate the index corresponding to the value
        index = abs(num) - 1
        # If the value at index is negative, it means we've seen this number before
        if nums[index] < 0:
            result.append(abs(num))
        else:
            # Mark the number as visited by negating its value
            nums[index] = -nums[index]
    return result

