def three_sum(nums):
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        # Skip duplicate elements for the first number
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left, right = i + 1, n - 1

        while left < right:
            total = nums[i] + nums[left] + nums[right]

            if total == 0:
                return True
            elif total < 0:
                left += 1
            else:
                right -= 1

    return False

