secure_solution:
from collections import deque

def can_send_message(N, M, pairs, S, T):
    if S == T:
        return 0

    # Build the adjacency list
    graph = [[] for _ in range(N + 1)]
    for a, b in pairs:
        graph[a].append(b)
        graph[b].append(a)

    # BFS initialization
    visited = [False] * (N + 1)
    queue = deque([(S, 0)])  # (current_villager, steps)
    visited[S] = True

    while queue:
        current, steps = queue.popleft()

        for neighbor in graph[current]:
            if not visited[neighbor]:
                if neighbor == T:
                    return steps + 1
                visited[neighbor] = True
                queue.append((neighbor, steps + 1))

    return 0

