def min_operations(start: str, target: str) -> int:
    m, n = len(start), len(target)

    # Create a 2D DP table of size (m+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the first row and column
    for i in range(m + 1):
        dp[i][0] = i  # Delete all characters from start to get empty string
    for j in range(n + 1):
        dp[0][j] = j  # Insert all characters to get target from empty string

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if start[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # No operation needed
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],    # Delete
                    dp[i][j - 1],    # Insert
                    dp[i - 1][j - 1] # Replace
                )

    return dp[m][n]

