def longest_word(words):
    words.sort(key=lambda x: (len(x), x))  # Sort by length first, then lexicographically
    word_set = set()
    longest = ""

    for word in words:
        # Check if all prefixes of the current word exist in the set
        if all(word[:i] in word_set for i in range(1, len(word))):
            word_set.add(word)
            # Update longest word based on length and lexicographical order
            if len(word) > len(longest) or (len(word) == len(longest) and word < longest):
                longest = word

    return longest

