def recommend_friends(user_id, friendships):
    # Get the list of the user's direct friends
    direct_friends = set(friendships.get(user_id, []))

    # Initialize a set to store potential recommendations
    recommendations = set()

    # Iterate through each friend of the user
    for friend in friendships.get(user_id, []):
        # Get the friends of the current friend (mutual friends)
        for mutual_friend in friendships.get(friend, []):
            # Skip if the mutual friend is the user themselves or a direct friend
            if mutual_friend != user_id and mutual_friend not in direct_friends:
                recommendations.add(mutual_friend)

    return recommendations

