def longest_divisible_subsequence(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Sort the array to make divisibility checks more efficient
    arr.sort()

    # dp[i] = length of the longest divisible subsequence ending at index i
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            if arr[i] % arr[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

