def smallest_fibonacci_greater_than_or_equal_to(n):
    # Edge case: if n is 0 or 1, return n itself as it is a Fibonacci number
    if n <= 1:
        return n

    # Initialize the first two Fibonacci numbers
    a, b = 0, 1

    # Generate Fibonacci numbers until we find one >= n
    while b < n:
        a, b = b, a + b

    return b

