def can_activate_boost_mode(n, energy_levels, threshold):
    max_current = max_global = energy_levels[0]

    for i in range(1, n):
        max_current = max(energy_levels[i], max_current + energy_levels[i])
        max_global = max(max_global, max_current)

    return 'YES' if max_global >= threshold else 'NO'

