    breaths.sort()

    # Try to create the zigzag pattern by swapping adjacent elements
    for i in range(1, len(breaths) - 1, 2):  # step by 2 to process pairs
        if breaths[i] < breaths[i + 1]:
            breaths[i], breaths[i + 1] = breaths[i + 1], breaths[i]

    # Check the zigzag pattern
    for i in range(len(breaths) - 1):
        if i % 2 == 0:
            if breaths[i] >= breaths[i + 1]:
                return "NO"
        else:
            if breaths[i] <= breaths[i + 1]:
                return "NO"

    return "YES"

