def is_one_edit_distance(s, t):
    # Ensure s is the shorter string for easier comparison
    if len(s) > len(t):
        s, t = t, s

    # If the difference in lengths is more than 1, it's not possible with one edit
    if len(t) - len(s) > 1:
        return "No"

    # Check for replacement (same length)
    if len(s) == len(t):
        diff = 0
        for i in range(len(s)):
            if s[i] != t[i]:
                diff += 1
                if diff > 1:
                    return "No"
        return "Yes" if diff == 1 else "No"

    # Check for insertion/delete (difference in length is 1)
    i = 0  # index for s
    j = 0  # index for t
    diff = 0

    while i < len(s) and j < len(t):
        if s[i] != t[j]:
            diff += 1
            if diff > 1:
                return "No"
            j += 1  # Move only in t (insert/delete)
        else:
            i += 1
            j += 1

    return "Yes"  # If we reached here, at most one edit is needed

