def largest_sum_increasing_subsequence(n, sequence):
    # Initialize a list to store the maximum sum for each position
    # dp[i] will store the maximum sum of increasing subsequence ending at index i
    dp = [0] * n
    dp[0] = sequence[0]  # The first element itself is the largest sum for itself

    for i in range(1, n):
        # Start with the element itself as the subsequence
        dp[i] = sequence[i]
        for j in range(i):
            # If sequence[j] < sequence[i], we can extend the subsequence ending at j
            if sequence[j] < sequence[i]:
                # Update dp[i] to be the maximum of its current value or dp[j] + sequence[i]
                dp[i] = max(dp[i], dp[j] + sequence[i])

    # The answer is the maximum value in dp
    return max(dp)

