def calculate_total_time_on_campus(logs):
    from datetime import datetime

    # Dictionary to store entry times for each student
    entry_times = {}

    # Sort logs by timestamp
    sorted_logs = sorted(logs, key=lambda x: x[2])

    # Dictionary to store total time spent on campus for each student
    total_time = {}

    for log in sorted_logs:
        student_id, action, timestamp = log
        dt = datetime.strptime(timestamp, "%Y-%m-%d %H:%M")

        if action == "entry":
            entry_times[student_id] = dt
        else:  # action == "exit"
            if student_id in entry_times:
                entry_dt = entry_times[student_id]
                delta = dt - entry_dt
                total_time[student_id] = total_time.get(student_id, 0) + delta.total_seconds() // 60
                del entry_times[student_id]  # Remove the entry after pairing with an exit

    return total_time

