def find_triplets(nums):
    nums.sort()
    n = len(nums)
    result = []

    if n < 3:
        return result

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue  # Skip duplicate elements for the first number

        left, right = i + 1, n - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]

            if current_sum == 0:
                result.append([nums[i], nums[left], nums[right]])
                while left < right and nums[left] == nums[left + 1]:
                    left += 1  # Skip duplicate elements for the second number
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1  # Skip duplicate elements for the third number
                left += 1
                right -= 1

            elif current_sum < 0:
                left += 1
            else:
                right -= 1

    return result

