def check_divisible_sum_pairs(nums: List[int], k: int) -> bool:
    seen_remainders = set()

    for num in nums:
        remainder = num % k
        complement = (k - remainder) % k

        if complement in seen_remainders:
            return True

        seen_remainders.add(remainder)

    return False

