def longest_scenic_route(n, heights):
    # dp[i] will store the length of the longest increasing subsequence ending at index i
    # count[i] will store the number of such subsequences ending at index i
    dp = [1] * n
    count = [1] * n

    for i in range(n):
        for j in range(i):
            if heights[i] > heights[j]:
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
                    count[i] = count[j]
                elif dp[j] + 1 == dp[i]:
                    count[i] += count[j]

    max_length = max(dp)
    total_routes = 0

    for i in range(n):
        if dp[i] == max_length:
            total_routes += count[i]

    return max_length, total_routes

