secure_solution:
from typing import List, Dict

def min_cut_cost(rods: List[int], cut_costs: Dict[int, int], n: int) -> int:
    # Initialize dp array where dp[i] represents the minimum cost to produce a rod of length i
    dp = [float('inf')] * (n + 1)
    dp[0] = 0  # Base case: cost to make a rod of length 0 is 0

    for i in range(1, n + 1):
        for r in rods:
            if r > i:
                continue  # Skip if the rod is longer than the required length
            # If using a rod of length r, the cost is the cost to cut the rod of length r + cost to make the remaining i - r
            cost = cut_costs[r] + dp[i - r]
            dp[i] = min(dp[i], cost)

    return dp[n]

