secure_solution:
def can_partition(nums):
    total_sum = sum(nums)

    # If total sum is odd, it's not possible to partition into two equal subsets
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    dp = set()
    dp.add(0)

    for num in nums:
        new_dp = set()
        for value in dp:
            new_value = value + num
            if new_value <= target:
                new_dp.add(new_value)
        dp.update(new_dp)

    return target in dp

