def find_combination(prices, M):
    # Sort the prices to optimize the search
    prices.sort()

    # Iterate through each price as the first element of the triplet
    for i in range(len(prices) - 2):
        # Use two pointers to find the other two elements
        left = i + 1
        right = len(prices) - 1

        while left < right:
            current_sum = prices[i] + prices[left] + prices[right]

            if current_sum == M:
                return [prices[i], prices[left], prices[right]]
            elif current_sum < M:
                left += 1
            else:
                right -= 1

    return []

