secure_solution:
def longest_subarray_with_k_odds(nums, k):
    left = 0
    odd_count = 0
    max_length = 0

    for right in range(len(nums)):
        if nums[right] % 2 == 1:
            odd_count += 1

        # If the number of odds exceeds k, move the left pointer to the right
        while odd_count > k:
            if nums[left] % 2 == 1:
                odd_count -= 1
            left += 1

        # Update the maximum length of the subarray
        max_length = max(max_length, right - left + 1)

    return max_length

