def max_value_of_gift_bags(n, values):
    if n == 0:
        return 0
    if n == 1:
        return values[0]

    # prev_prev: max value up to i - 2
    # prev: max value up to i - 1
    prev_prev = values[0]
    prev = max(values[0], values[1])

    for i in range(2, n):
        current = max(prev, prev_prev + values[i])
        prev_prev, prev = prev, current

    return prev

