def count_anagrams(sentence: str, target: str) -> int:
    import re

    # Function to get the sorted signature of a word (alphabetic characters only)
    def get_signature(word):
        return ''.join(sorted(re.findall(r'[a-zA-Z]', word), key=lambda x: x.lower()))

    # Normalize target to lowercase and compute its signature
    target_signature = get_signature(target.lower())
    target_length = len(target_signature)

    # Split the sentence into words
    words = re.findall(r'\b\w+\b', sentence.lower())

    # Count matches of the target's signature
    count = 0
    for word in words:
        if len(word) == target_length:
            if get_signature(word) == target_signature:
                count += 1
    return count

