def maxCoins(coins):
    n = len(coins)
    if n == 0:
        return 0
    if n == 1:
        return coins[0]

    # Initialize dp array
    dp = [0] * n
    dp[0] = coins[0]
    dp[1] = max(coins[0], coins[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], coins[i] + dp[i-2])

    return dp[-1]

