def can_transform(s, t):
    m, n = len(s), len(t)
    # dp[i][j] = True if s[0..i-1] can match t[0..j-1]
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # Empty pattern matches empty string
    dp[0][0] = True

    # Initialize first row (s starts with '*')
    for i in range(1, m + 1):
        if s[i - 1] == '*':
            dp[i][0] = dp[i - 1][0]
        else:
            break  # No more '*' to match empty string

