        for j in range(1, n + 1):
            if s[i - 1] == t[j - 1] or s[i - 1] == '?':
                dp[i][j] = dp[i - 1][j - 1]
            elif s[i - 1] == '*':
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]

    return "YES" if dp[m][n] else "NO"

