def lexicographically_smallest_string(t, strings):
    results = []
    for s in strings:
        min_str = s  # Initialize with the original string
        n = len(s)

        # Try removing one character
        for i in range(n):
            candidate = s[:i] + s[i+1:]
            if candidate < min_str:
                min_str = candidate

        # Try swapping each pair of adjacent characters
        for i in range(n - 1):
            # Create a list for easy swapping
            s_list = list(s)
            s_list[i], s_list[i+1] = s_list[i+1], s_list[i]
            candidate = ''.join(s_list)
            if candidate < min_str:
                min_str = candidate

        results.append(min_str)

    return results

