def count_paths(n, m, grid):
    MOD = 10**9 + 7

    dp = [[0] * m for _ in range(n)]

    # Start from (0,0)
    if grid[0][0] == '#':
        return -1
    dp[0][0] = 1

    # Fill the first row
    for j in range(1, m):
        if grid[0][j] == '#':
            break
        dp[0][j] = dp[0][j-1]

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == '#':
            break
        dp[i][0] = dp[i-1][0]

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == '#':
                continue
            dp[i][j] = (dp[i-1][j] + dp[i][j-1]) % MOD

    return dp[n-1][m-1] if dp[n-1][m-1] != 0 else -1

