        return 0

    num_set = set(arr)
    longest_sequence = 0

    for num in num_set:
        if num - 1 not in num_set:
            current_num = num
            current_length = 1

            while current_num + 1 in num_set:
                current_num += 1
                current_length += 1

            longest_sequence = max(longest_sequence, current_length)

