def count_ways_to_climb(n: int) -> int:
    if n <= 1:
        return 1
    if n == 2:
        return 2

    # Use variables to keep track of previous two results
    prev_prev = 1  # ways to reach step 1
    prev = 2       # ways to reach step 2
    for _ in range(3, n + 1):
        current = prev_prev + prev
        prev_prev, prev = prev, current

    return prev

