from collections import deque

def is_k_diverse(arr, k):
    if k == 0:
        return True  # Edge case: trivially true if k is 0

    n = len(arr)
    if k > n:
        return False  # Cannot have a subarray of size > n

    # Deques to maintain indices of max and min values
    max_deque = deque()
    min_deque = deque()

    for i in range(n):
        # Maintain max_deque: remove indices of elements smaller than current
        while max_deque and arr[max_deque[-1]] <= arr[i]:
            max_deque.pop()
        max_deque.append(i)

        # Maintain min_deque: remove indices of elements greater than current
        while min_deque and arr[min_deque[-1]] >= arr[i]:
            min_deque.pop()
        min_deque.append(i)

        # Remove indices that are out of the current window
        while max_deque[0] <= i - k:
            max_deque.popleft()
        while min_deque[0] <= i - k:
            min_deque.popleft()

        # Once the window reaches size k
        if i >= k - 1:
            max_val = arr[max_deque[0]]
            min_val = arr[min_deque[0]]
            if max_val - min_val > k:
                return False

    return True

