def num_rescue_boats(weights, limit):
    weights.sort()
    left, right = 0, len(weights) - 1
    boats = 0

    while left <= right:
        if weights[left] + weights[right] <= limit:
            left += 1
        right -= 1
        boats += 1

    return boats

