def find_non_decreasing_sequences(arr):
    if not arr:
        return []

    result = []
    start = 0

    for i in range(1, len(arr)):
        if arr[i] < arr[i - 1]:
            # End of a non-decreasing sequence
            result.append([start, i - 1])
            start = i
    # Add the last sequence
    result.append([start, len(arr) - 1])

    return result

