def calculate_averages(grades: dict) -> (dict, float):
    subject_averages = {}

    # Compute average for each subject
    for subject, grade_list in grades.items():
        average = sum(grade_list) / len(grade_list)
        subject_averages[subject] = round(average, 2)

    # Compute overall average
    total_grades = []
    for grade_list in grades.values():
        total_grades.extend(grade_list)

    overall_average = round(sum(total_grades) / len(total_grades), 2)

    return subject_averages, overall_average

