secure_solution:
def min_deletions_to_make_palindrome(s):
    n = len(s)

    # Create a DP table where dp[i][j] represents the length of LPS from s[i] to s[j]
    dp = [[0] * n for _ in range(n)]

    # Each single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the DP table
    for length in range(2, n + 1):  # length of the substring
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = 2 + dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    # Length of LPS
    lps_length = dp[0][n - 1]

    # Minimum deletions = total length - length of LPS
    return n - lps_length

