def max_unique_pollen_colors(n, pollen_colors):
    last_seen = {}
    max_unique = 0
    left = 0
    unique_count = 0

    for right in range(n):
        color = pollen_colors[right]

        if color in last_seen and last_seen[color] >= left:
            left = last_seen[color] + 1

        last_seen[color] = right
        unique_count = right - left + 1
        max_unique = max(max_unique, unique_count)

    return max_unique

def is_anagram_substring(s1, s2):
    # Input validation
    if not isinstance(s1, str) or not isinstance(s2, str):
        raise ValueError("Both inputs must be strings")

    if len(s1) > len(s2):
        raise ValueError("First string must not be longer than the second string")

    if len(s1) == 0:
        return True  # Empty string is always a substring

    # Function to count characters in a string
    def get_char_count(s):
        count = [0] * 26  # For 'a' to 'z'
        for char in s:
            count[ord(char) - ord('a')] += 1
        return count

    # Get character count for s1
    s1_count = get_char_count(s1)
    window_count = get_char_count(s2[:len(s1)])

    # Sliding window over s2
    for i in range(len(s2) - len(s1) + 1):
        if i > 0:
            # Remove the character leaving the window
            out_char = s2[i - 1]
            window_count[ord(out_char) - ord('a')] -= 1
            # Add the new character entering the window
            in_char = s2[i + len(s1) - 1]
            window_count[ord(in_char) - ord('a')] += 1

        # Compare the counts
        if window_count == s1_count:
            return True

    return False

