def max_fulfilled_requests(m, tickets, p, requests):
    max_requests = 0

    # Try all subsets of requests to find the maximum number of compatible ones
    from itertools import combinations

    for k in range(p, 0, -1):  # go from max to min number of requests
        for subset in combinations(range(p), k):
            # Check if this subset of requests can be fulfilled
            req_sum = [0] * m
            for idx in subset:
                for i in range(m):
                    req_sum[i] += requests[idx][i]
            if all(req_sum[i] <= tickets[i] for i in range(m)):
                max_requests = k
                return max_requests  # We found the max possible, return early

    return max_requests

