from typing import List
import bisect

def longest_increasing_subsequence(step_counts: List[int]) -> int:
    """
    This function computes the length of the longest increasing subsequence in the list of step counts.

    :param step_counts: List of integers where each integer represents the step count for a day.
    :return: Integer value representing the length of the longest increasing subsequence.
    """
    if not step_counts:
        return 0

    tails = []
    for num in step_counts:
        # Use bisect_left to find the insertion point
        idx = bisect.bisect_left(tails, num)
        if idx == len(tails):
            tails.append(num)
        else:
            tails[idx] = num
    return len(tails)

