secure_solution:
def min_swaps_to_sort(arr):
    n = len(arr)
    visited = [False] * n
    swaps = 0

    for i in range(n):
        if not visited[i]:
            cycle_size = 0
            j = i
            while not visited[j]:
                visited[j] = True
                j = arr[j] - 1  # arr[j] is the value at index j, map it to the correct index
                cycle_size += 1
            if cycle_size > 0:
                swaps += (cycle_size - 1)

    return swaps

