def contains_arithmetic_progression(arr):
    n = len(arr)
    for i in range(n):
        for k in range(i + 2, n):
            # We need to find j such that 2*arr[j] == arr[i] + arr[k]
            target = (arr[i] + arr[k]) / 2
            # Use binary search to check if target exists between i and k
            left, right = i + 1, k - 1
            while left <= right:
                mid = (left + right) // 2
                if arr[mid] == target:
                    return True
                elif arr[mid] < target:
                    left = mid + 1
                else:
                    right = mid - 1
    return False

