from typing import List

def matrix_diagonal_difference(matrix: List[List[int]]) -> int:
    n = len(matrix)
    primary_diagonal_sum = 0
    secondary_diagonal_sum = 0

    for i in range(n):
        primary_diagonal_sum += matrix[i][i]
        secondary_diagonal_sum += matrix[i][n - 1 - i]

    return abs(primary_diagonal_sum - secondary_diagonal_sum)

def find_suspicious_entries(records, time_window):
    # Sort records by timestamp
    records.sort()

    # Dictionary to store the timestamps for each employee
    employee_timestamps = {}

    # Set to store suspicious employee IDs
    suspicious_employees = set()

    # Process each record
    for timestamp, employee_id in records:
        # If the employee is not in the dictionary, initialize with the current timestamp
        if employee_id not in employee_timestamps:
            employee_timestamps[employee_id] = []

        # Keep only the timestamps within the current time window
        while employee_timestamps[employee_id] and timestamp - employee_timestamps[employee_id][0] > time_window:
            employee_timestamps[employee_id].pop(0)

        # If there's a previous timestamp within the window, mark as suspicious
        if employee_timestamps[employee_id]:
            suspicious_employees.add(employee_id)

        # Add the current timestamp to the list
        employee_timestamps[employee_id].append(timestamp)

    # Convert the set to a sorted list of strings
    return sorted(suspicious_employees)

