secure_solution:
def has_permutation_of_first_k_naturals(arr, k):
    if k <= 0 or k > len(arr):
        return False

    required = set(range(1, k + 1))

    # Initialize the first window
    current_window = set(arr[:k])

    if current_window == required:
        return True

    # Slide the window over the array
    for i in range(k, len(arr)):
        current_window.remove(arr[i - k])
        current_window.add(arr[i])
        if current_window == required:
            return True

    return False

