def partition_array(arr, k):
    result = []
    current_sum = 0
    current_subarray = []

    for num in arr:
        if current_sum + num > k:
            result.append(current_subarray)
            current_subarray = [num]
            current_sum = num
        else:
            current_subarray.append(num)
            current_sum += num

    # Add the last subarray
    if current_subarray:
        result.append(current_subarray)

    return result

