def max_points(points):
    if not points:
        return 0
    if len(points) == 1:
        return points[0]

    prev_prev = points[0]
    prev = max(points[0], points[1])

    for i in range(2, len(points)):
        current = max(prev, prev_prev + points[i])
        prev_prev, prev = prev, current

    return prev

