from typing import List
from collections import deque

def word_ladder_steps(beginWord: str, endWord: str, wordList: List[str]) -> int:
    # Check if all words have the same length
    if len(set(len(word) for word in [beginWord] + wordList)) != 1:
        return 0

    # Check if endWord is not in wordList
    word_set = set(wordList)
    if endWord not in word_set:
        return 0

    # Initialize BFS
    queue = deque([(beginWord, 1)])  # (current_word, steps)
    visited = set([beginWord])

    # Character set
    chars = "abcdefghijklmnopqrstuvwxyz"

    while queue:
        current_word, steps = queue.popleft()

        # If we've reached the end word
        if current_word == endWord:
            return steps

        # Generate all possible one-character variations
        for i in range(len(current_word)):
            for c in chars:
                if c != current_word[i]:
                    next_word = current_word[:i] + c + current_word[i+1:]
                    if next_word in word_set and next_word not in visited:
                        visited.add(next_word)
                        queue.append((next_word, steps + 1))

    # If endWord is unreachable
    return 0

