def max_beauty(nums, k):
    left = 0
    max_beauty = 0
    count = 0  # number of elements <= k in current window

    for right in range(len(nums)):
        if nums[right] <= k:
            count += 1

        # Try to shrink the window if we can (no need to keep all elements)
        while left <= right and nums[left] > k:
            left += 1

        # Update max_beauty with the number of valid elements in window
        max_beauty = max(max_beauty, count)

