def min_containers(t, test_cases):
    results = []

    for n, m, containers in test_cases:
        # Sort containers by capacity in descending order to use the largest ones first
        containers.sort(reverse=True, key=lambda x: x[0])

        total_capacity = 0
        total_containers = 0
        used = 0

        for c_i, a_i in containers:
            # How many containers of this type we can use
            max_use = min(a_i, (n - used + c_i - 1) // c_i)  # Ceiling division
            if max_use == 0:
                continue
            total_containers += max_use
            used += max_use * c_i
            if used >= n:
                break

        if used >= n:
            results.append(total_containers)
        else:
            results.append(-1)

    return results

def first_non_repeating_character(s: str) -> int:
    # Create an array to store the counts of each character (a-z)
    count = [0] * 26

    # First pass: Count the occurrences of each character
    for char in s:
        index = ord(char) - ord('a')
        count[index] += 1

    # Second pass: Find the first character with a count of 1
    for i, char in enumerate(s):
        index = ord(char) - ord('a')
        if count[index] == 1:
            return i

    return -1

