def findMaxLength(nums):
    # Dictionary to store the first occurrence of prefix sums
    prefix_sum_index = {0: -1}  # Initialize with 0 at index -1
    max_length = 0
    current_sum = 0

    for i, num in enumerate(nums):
        current_sum += 1 if num == 1 else -1

        # If the prefix sum has been seen before, update max_length
        if current_sum in prefix_sum_index:
            max_length = max(max_length, i - prefix_sum_index[current_sum])
        else:
            prefix_sum_index[current_sum] = i

    return max_length

def max_distinct_items(costs, budget):
    # Sort the costs in ascending order
    costs.sort()

    total = 0
    count = 0

    for cost in costs:
        if total + cost <= budget:
            total += cost
            count += 1
        else:
            break  # Can't afford this item

    return count

