def lexicographically_smallest_subsequence(nums, k):
    stack = []
    n = len(nums)

    for i, num in enumerate(nums):
        # While the stack is not empty, and the current number is smaller than the last element in the stack,
        # and we can remove elements (i.e., there are enough remaining elements to fill the rest of the subsequence),
        # pop the last element from the stack.
        while stack and num < stack[-1] and len(stack) - 1 + (n - i) >= k:
            stack.pop()
        if len(stack) < k:
            stack.append(num)

    return stack

