from collections import deque

def min_jumps(n, k, cells):
    positions = [i for i, cell in enumerate(cells) if cell == '1']

    if not positions:
        return -1  # no '1's in the cells

    if len(positions) == 1:
        return 0  # only one '1', no jumps needed

    visited = set()
    queue = deque([(positions[0], 0)])  # (current_position, jumps)
    visited.add(positions[0])

    while queue:
        current_pos, jumps = queue.popleft()

        if current_pos == positions[-1]:
            return jumps

        # Try all positions from current_pos + 1 up to current_pos + k
        # and also from current_pos - k to current_pos - 1, but only if within range
        for next_pos in range(current_pos + 1, min(current_pos + k + 1, n)):
            if next_pos in positions and next_pos not in visited:
                visited.add(next_pos)
                queue.append((next_pos, jumps + 1))

        # Try leftward jumps (not necessary for this specific problem but included for completeness)
        for next_pos in range(max(0, current_pos - k), current_pos):
            if next_pos in positions and next_pos not in visited:
                visited.add(next_pos)
                queue.append((next_pos, jumps + 1))

    return -1  # no path found

