def count_paths(n, m, blocked_cells):
    # Initialize a DP grid with 0s
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Create a set of blocked cells for quick lookup
    blocked = set((i, j) for i, j in blocked_cells)

    # Start position is (1, 1)
    if (1, 1) in blocked:
        return 0

    dp[1][1] = 1  # One way to start from (1, 1)

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if (i, j) in blocked:
                dp[i][j] = 0
                continue
            if i == 1 and j == 1:
                continue  # Already initialized
            # Sum of paths from top and left
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1]

    return dp[n][m]

