def max_sum_subarray(nums, k):
    if not nums or k <= 0 or k > len(nums):
        return None

    current_sum = sum(nums[:k])
    max_sum = current_sum

    for i in range(k, len(nums)):
        current_sum += nums[i] - nums[i - k]
        max_sum = max(max_sum, current_sum)

    return max_sum

def max_contiguous_buildings(N, heightsA, heightsB):
    max_len = 0

    # Iterate over all possible starting points in both arrays
    for i in range(N):
        for j in range(N):
            # Compare the subarrays starting at i in A and j in B
            current_len = 0
            while i + current_len < N and j + current_len < N and heightsA[i + current_len] == heightsB[j + current_len]:
                current_len += 1
            max_len = max(max_len, current_len)

    return max_len

