def find_combination(n, t, arr):
    def backtrack(start, target, path, result):
        if target == 0:
            result.extend(path)
            return True
        for i in range(start, len(arr)):
            if arr[i] > target:
                continue
            if i > start and arr[i] == arr[i - 1]:
                continue  # Skip duplicates to avoid same combination
            if backtrack(i + 1, target - arr[i], path + [arr[i]], result):
                return True
        return False

