def josephus_problem(people: List[int], k: int) -> Tuple[List[int], int]:
    n = len(people)
    result = []
    current = 0  # Start from index 0

    while len(people) > 1:
        # Calculate the index of the next person to remove
        current = (current + k - 1) % len(people)
        result.append(people.pop(current))

    return (result, people[0])

