def calculate_monthly_payment(principal: float, annual_rate: float, months: int) -> float:
    # Step 1: Validate input parameters
    if principal <= 0 or annual_rate < 0 or months <= 0:
        raise ValueError("principal must be positive, annual_rate must be non-negative, and months must be positive integer")

    # Step 2: Convert annual interest rate to monthly rate
    monthly_rate = (annual_rate / 100) / 12

    # Special case: if there's no interest, just divide principal by months
    if monthly_rate == 0:
        return round(principal / months, 2)

    # Step 3: Apply the annuity formula
    payment = (principal * monthly_rate) / (1 - (1 + monthly_rate) ** -months)

    # Step 4: Round the result to 2 decimal places
    return round(payment, 2)

