import bisect

def min_removals_to_non_decreasing(n, a):
    # We'll use a list to keep track of the smallest tail of all increasing subsequences
    # with length i+1
    tails = []

    for num in a:
        # Use bisect_right to maintain non-decreasing order
        idx = bisect.bisect_right(tails, num)
        if idx == len(tails):
            tails.append(num)
        else:
            tails[idx] = num

    # The length of the longest non-decreasing subsequence is len(tails)
    return n - len(tails)

