def min_string_value(s):
    n = len(s)
    # Convert string to list of integers
    digits = [int(c) for c in s]

    # Initialize DP table
    dp = [[0] * n for _ in range(n)]

    # Base case: single digit
    for i in range(n):
        dp[i][i] = digits[i]

    # Fill the DP table for substrings of length 2 to n
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float('inf')
            for k in range(i, j):
                # Combine left and right part by multiplying their results
                current_value = dp[i][k] * dp[k+1][j]
                if current_value < dp[i][j]:
                    dp[i][j] = current_value

    return dp[0][n-1]

