def longest_palindromic_subsequence(arr):
    n = len(arr)
    # Create a 2D DP table
    dp = [[0] * n for _ in range(n)]

    # All single elements are palindromes of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the DP table for subsequences of length >= 2
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if arr[i] == arr[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = 2 + dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]

