def can_partition(nums):
    total_sum = sum(nums)
    if total_sum % 2 != 0:
        return False  # If total sum is odd, cannot partition into two equal subsets

    target = total_sum // 2
    possible_sums = set()
    possible_sums.add(0)

    for num in nums:
        temp = set()
        for s in possible_sums:
            if s + num <= target:
                temp.add(s + num)
        possible_sums.update(temp)

    return target in possible_sums

