def longest_arithmetic_subarray(n, arr):
    if n <= 2:
        return n  # Any subarray of length 1 or 2 is automatically an arithmetic sequence

    max_length = 2  # Minimum length of a valid arithmetic subarray is 2
    current_length = 2
    diff = arr[1] - arr[0]

    for i in range(2, n):
        new_diff = arr[i] - arr[i - 1]

        if new_diff == diff:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            diff = new_diff
            current_length = 2

    return max_length

def min_cost_path(n, m, grid):
    # Initialize a dp array to store the minimum cost to reach each cell
    dp = [0] * m
    dp[0] = grid[0][0]  # Starting cell

    # Fill the first row
    for j in range(1, m):
        dp[j] = dp[j - 1] + grid[0][j]

    # Fill the rest of the dp matrix
    for i in range(1, n):
        dp[0] += grid[i][0]  # First column
        for j in range(1, m):
            dp[j] = grid[i][j] + min(dp[j - 1], dp[j])

    return dp[-1]

