from typing import Dict, List, Optional

def recommend_book(purchase_history: Dict[str, List[str]], genre_books: Dict[str, List[str]], genre: str) -> str:
    # Step 1: Check if the genre exists in genre_books
    if genre not in genre_books:
        return ""

    # Step 2: Get all books in the specified genre
    books_in_genre = genre_books[genre]

    # Step 3: Identify the user who has bought the most books in this genre
    user_genre_counts = {}
    max_books = 0
    selected_user = ""

    for user, books in purchase_history.items():
        count = sum(1 for book in books if book in books_in_genre)
        user_genre_counts[user] = count
        if count > max_books:
            max_books = count
            selected_user = user

    # Step 4: Check if any user has bought books in this genre
    if max_books == 0:
        return ""

    # Step 5: Find a book in the genre that the user hasn't bought
    for book in books_in_genre:
        if book not in purchase_history[selected_user]:
            return book

    # Step 6: If the user has bought all books in the genre, return an empty string
    return ""

