def min_operations(s, t):
    # Lengths of the strings
    m = len(s)
    n = len(t)

    # Create a DP table with only the previous row
    prev = [0] * (n + 1)

    for i in range(1, m + 1):
        curr = [0] * (n + 1)
        for j in range(1, n + 1):
            if s[i - 1] == t[j - 1]:
                curr[j] = prev[j - 1] + 1
            else:
                curr[j] = max(prev[j], curr[j - 1])
        prev = curr

    lcs_length = prev[n]
    return m + n - 2 * lcs_length

