def can_partition(nums):
    total_sum = sum(nums)

    # If total sum is odd, it's impossible to partition into two equal subsets
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum 0 can be achieved with an empty subset

    for num in nums:
        for j in range(target, num - 1, -1):
            if dp[j - num]:
                dp[j] = True

    return dp[target]

