from typing import List

def relay_race(distance: int, capacities: List[int]) -> int:
    capacities.sort(reverse=True)  # Sort from strongest to weakest runner
    participants_used = 0
    remaining_distance = distance

    for cap in capacities:
        if remaining_distance == 0:
            break
        if cap <= remaining_distance:
            participants_used += 1
            remaining_distance -= cap
        else:
            # This runner can take the remaining distance, but not full capacity
            participants_used += 1
            remaining_distance = 0

    return participants_used if remaining_distance == 0 else -1

