def wave(s):
    result = []
    for i in range(len(s)):
        if s[i].isspace():
            continue  # Skip spaces
        # Create a new string with the i-th character in uppercase
        new_s = s[:i] + s[i].upper() + s[i+1:]
        result.append(new_s)
    return result

