def is_merge(s: str, part1: str, part2: str) -> bool:
    # Edge case: if s is empty, both part1 and part2 must be empty
    if not s:
        return part1 == "" and part2 == ""

    # Check if the total length of part1 and part2 matches s
    if len(part1) + len(part2) != len(s):
        return False

    # Create a 2D DP array
    m, n = len(part1), len(part2)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True  # Empty part1 and part2 form empty s

    # Initialize first row (part1 is empty)
    for j in range(1, n + 1):
        if part2[j-1] == s[j-1] and dp[0][j-1]:
            dp[0][j] = True

    # Initialize first column (part2 is empty)
    for i in range(1, m + 1):
        if part1[i-1] == s[i-1] and dp[i-1][0]:
            dp[i][0] = True

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # Check if the current character in s matches part1[i-1] or part2[j-1]
            if (part1[i-1] == s[i+j-1] and dp[i-1][j]) or (part2[j-1] == s[i+j-1] and dp[i][j-1]):
                dp[i][j] = True

    return dp[m][n]

