secure_solution:
def count_reversible_words(words):
    word_set = set(words)  # Use a set for O(1) lookups
    reversible_count = 0
    seen = set()  # To track words we've already checked

    for word in words:
        if word in seen:
            continue  # Skip words we've already processed
        reversed_word = word[::-1]
        if reversed_word in word_set and reversed_word != word:
            reversible_count += 1
            seen.add(word)
            seen.add(reversed_word)
        elif reversed_word in word_set and reversed_word == word:
            # Word is the same when reversed (e.g., "madam")
            # It counts as a reversible word only if it appears more than once
            if words.count(word) > 1:
                reversible_count += 1
                seen.add(word)

    return reversible_count

