from itertools import permutations

def arrange_animals(n: int, restrictions: List[Tuple[int, int]]) -> List[int]:
    # Convert restrictions to a set for faster lookups
    forbidden_pairs = set()
    for a, b in restrictions:
        forbidden_pairs.add((a, b))
        forbidden_pairs.add((b, a))  # Make it bidirectional

    # Generate all permutations of the animals
    for perm in permutations(range(1, n + 1)):
        valid = True
        for i in range(len(perm) - 1):
            if (perm[i], perm[i + 1]) in forbidden_pairs:
                valid = False
                break
        if valid:
            return list(perm)

    return [-1]

