def min_path_cost(grid):
    m = len(grid)
    n = len(grid[0])

    # If the start or end cell is an obstacle, return -1
    if grid[0][0] == -1 or grid[m-1][n-1] == -1:
        return -1

    # Initialize the DP table
    dp = [[float('inf')] * n for _ in range(m)]
    dp[0][0] = grid[0][0]

    # Fill the DP table
    for i in range(m):
        for j in range(n):
            if grid[i][j] == -1:
                dp[i][j] = float('inf')
                continue
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j] + grid[i][j])
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j-1] + grid[i][j])

    return dp[m-1][n-1] if dp[m-1][n-1] != float('inf') else -1

