from typing import List

MOD = 10**9 + 7

def sum_of_subarray_mins(arr: List[int]) -> int:
    n = len(arr)
    left = [0] * n  # previous smaller or equal index
    right = [0] * n  # next smaller index

    # Monotonic stack to find previous smaller or equal element
    stack = []
    for i in range(n):
        while stack and arr[stack[-1]] > arr[i]:
            stack.pop()
        if stack:
            left[i] = i - stack[-1]
        else:
            left[i] = i + 1  # if no smaller, it spans from 0 to i
        stack.append(i)

    # Monotonic stack to find next smaller element
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and arr[stack[-1]] >= arr[i]:
            stack.pop()
        if stack:
            right[i] = stack[-1] - i
        else:
            right[i] = n - i  # if no smaller, it spans from i to end
        stack.append(i)

    # Compute the sum of min values over all subarrays
    res = 0
    for i in range(n):
        res += arr[i] * left[i] * right[i]
        res %= MOD

    return res

def minEnergy(P, Q, grid):
    # Initialize DP table
    dp = [[0 for _ in range(Q)] for _ in range(P)]

    # Base case: starting cell
    dp[0][0] = grid[0][0]

    # Fill first row
    for j in range(1, Q):
        dp[0][j] = dp[0][j - 1] + grid[0][j]

    # Fill first column
    for i in range(1, P):
        dp[i][0] = dp[i - 1][0] + grid[i][0]

    # Fill the rest of the DP table
    for i in range(1, P):
        for j in range(1, Q):
            dp[i][j] = grid[i][j] + min(dp[i - 1][j], dp[i][j - 1])

    return dp[P - 1][Q - 1]

