from collections import Counter

def min_removals_to_make_anagram(s, t):
    count_s = Counter(s)
    count_t = Counter(t)

    total_removals = 0

    # Check if it's possible to form an anagram of t from s
    for char in count_t:
        if count_s[char] < count_t[char]:
            return "-1"
        total_removals += count_s[char] - count_t[char]

    # Also account for characters in s that are not in t (they must be removed)
    for char in count_s:
        if char not in count_t:
            total_removals += count_s[char]

    return total_removals

