def max_consecutive_ones(data, k):
    left = 0
    max_length = 0
    zero_count = 0

    for right in range(len(data)):
        if data[right] == 0:
            zero_count += 1

        # If number of zeros exceeds k, move left pointer
        while zero_count > k:
            if data[left] == 0:
                zero_count -= 1
            left += 1

        # Update the max window size
        max_length = max(max_length, right - left + 1)

    return max_length

