def count_arrangements(N, M):
    MOD = 10**9 + 7

    if N == 0:
        return 1  # By definition, an empty sequence has 1 arrangement.
    if M == 0:
        return 0  # No colors, no arrangements possible.
    if N == 1:
        return M  # Just one stone, can be any of M colors.

