def can_build_road(cost, capacity, B, R):
    n = len(cost)

    # dp[i][c]: maximum capacity achievable with the first i routes and cost c
    dp = [[0] * (B + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for c in range(B + 1):
            # Option 1: Do not include the i-th route
            dp[i][c] = dp[i - 1][c]
            # Option 2: Include the i-th route if budget allows
            if c >= cost[i - 1]:
                dp[i][c] = max(dp[i][c], dp[i - 1][c - cost[i - 1]] + capacity[i - 1])

    # Check if any budget <= B results in capacity >= R
    for c in range(B + 1):
        if dp[n][c] >= R:
            return True

    return False

