def sum_of_diagonals(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    diagonal_sums = set()

    # Iterate over each cell in the grid
    for i in range(m):
        for j in range(n):
            # For top-left to bottom-right diagonals
            diag1 = i - j
            # For top-right to bottom-left diagonals
            diag2 = i + j
            diagonal_sums.add((diag1, diag2))

    # Now sum all the values in the grid that belong to any of the diagonals
    total_sum = 0
    for i in range(m):
        for j in range(n):
            diag1 = i - j
            diag2 = i + j
            if (diag1, diag2) in diagonal_sums:
                total_sum += grid[i][j]

    return total_sum

