def tsp_min_distance(n, distances):
    from functools import lru_cache

    # Convert to 0-based indexing
    # The distance matrix is already 0-based

    @lru_cache(None)
    def dp(mask, u):
        if mask == (1 << n) - 1:
            return distances[u][0]  # Return to starting city (0)

        res = float('inf')
        for v in range(n):
            if not (mask & (1 << v)):
                res = min(res, distances[u][v] + dp(mask | (1 << v), v))
        return res

    return dp(1 << 0, 0)  # Start at city 0 with only city 0 visited

