def min_removals_to_increasing(arr):
    import bisect

    n = len(arr)
    lis = []  # This will store the smallest tail of all increasing subsequences with different lengths

    for num in arr:
        # Use bisect_left to find the index where num can replace the first element >= to it
        idx = bisect.bisect_left(lis, num)
        if idx == len(lis):
            lis.append(num)  # If num is larger than all elements in lis, append it
        else:
            lis[idx] = num  # Otherwise, replace the element at idx with num

    # The length of LIS is the length of the lis list
    return n - len(lis)

