def minimum_moves_to_sort_books(test_cases):
    def longest_increasing_subsequence_length(arr):
        # This function computes the length of the LIS using dynamic programming
        n = len(arr)
        dp = [1] * n
        for i in range(n):
            for j in range(i):
                if arr[i] > arr[j]:
                    dp[i] = max(dp[i], dp[j] + 1)
        return max(dp)

    results = []
    for case in test_cases:
        n, a = case
        # Sort the list to determine the correct order
        sorted_a = sorted(a)
        # Find the indices of elements in the original list relative to the sorted list
        # This is crucial for finding the LIS in the permutation
        index_map = {word: i for i, word in enumerate(sorted_a)}
        indexed_list = [index_map[word] for word in a]
        # Compute LIS in the indexed list
        lis_length = longest_increasing_subsequence_length(indexed_list)
        # Minimum moves needed is the total number of books minus the length of LIS
        results.append(n - lis_length)

    return results

