def max_sum_with_negative(N, energies):
    max_sum = float('-inf')
    current_sum = 0
    has_negative = False

    for i in range(N):
        current_sum += energies[i]
        if energies[i] < 0:
            has_negative = True

        # If we have seen at least one negative and current_sum is positive, update max_sum
        if has_negative and current_sum > max_sum:
            max_sum = current_sum

        # If current_sum becomes negative, reset the current subarray
        if current_sum < 0:
            current_sum = 0
            has_negative = False  # Reset the flag since we start a new subarray

    return max_sum

