    if set(source) != set(target):
        return -1  # Cannot convert if elements are different

    n = len(source)
    i = 0  # Pointer for source
    j = 0  # Pointer for target

    while i < n and j < n:
        if source[i] == target[j]:
            i += 1
            j += 1
        else:
            i += 1  # Move to next element in source

    # The number of elements not in the subsequence is the number of moves
    return n - j

