def reorder_string(s: str) -> str:
    """
    Reorders the input string such that:
    - All digits come first, in their original relative order
    - Followed by alphabetic characters (both upper and lower case), in their original relative order
    - Followed by special characters, in their original relative order
    """
    digits = []
    letters = []
    special_chars = []

    for char in s:
        if char.isdigit():
            digits.append(char)
        elif char.isalpha():
            letters.append(char)
        else:
            special_chars.append(char)

    return ''.join(digits + letters + special_chars)

