from collections import defaultdict, deque
from typing import Dict, List

def find_task_order(graph: Dict[int, List[int]]) -> List[int]:
    # Step 1: Build adjacency list and in-degree dictionary
    adj = defaultdict(list)
    in_degree = defaultdict(int)
    all_nodes = set(graph.keys())

    for u in graph:
        for v in graph[u]:
            adj[u].append(v)
            in_degree[v] += 1
            all_nodes.add(v)

    # Step 2: Initialize the queue with nodes of in-degree 0
    queue = deque()
    for node in all_nodes:
        if in_degree.get(node, 0) == 0:
            queue.append(node)

    result = []

    # Step 3: Process the nodes
    while queue:
        u = queue.popleft()
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Step 4: Check for cycles
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in the graph; topological sort is not possible.")

    return result

