from typing import List

def longest_subarray_sum_k(nums: List[int], k: int) -> int:
    prefix_sum = 0
    sum_indices = {0: -1}  # To handle the case where prefix_sum == k from the start
    max_length = 0

    for i, num in enumerate(nums):
        prefix_sum += num
        if (prefix_sum - k) in sum_indices:
            max_length = max(max_length, i - sum_indices[prefix_sum - k])
        if prefix_sum not in sum_indices:
            sum_indices[prefix_sum] = i

    return max_length

