import heapq

def network_delay_time(graph, source):
    n = len(graph)
    adj = [[] for _ in range(n)]  # Adjacency list

    # Build the adjacency list
    for i in range(n):
        for j in range(n):
            if graph[i][j] > 0 and i != j:
                adj[i].append((j, graph[i][j]))  # (neighbor, time)

    # Dijkstra's algorithm
    min_time = [float('inf')] * n
    min_time[source] = 0
    heap = [(0, source)]  # (time, server)

    while heap:
        time, u = heapq.heappop(heap)
        if time > min_time[u]:
            continue  # Skip outdated entries
        for v, weight in adj[u]:
            if min_time[v] > min_time[u] + weight:
                min_time[v] = min_time[u] + weight
                heapq.heappush(heap, (min_time[v], v))

    # Check if all servers are reachable
    max_time = max(min_time)
    return max_time if max_time != float('inf') else -1

