def smallest_lexicographical_string(s):
    min_str = s  # Initialize with the original string
    for i in range(len(s)):
        # Create the string by removing the i-th character
        new_str = s[:i] + s[i+1:]
        # Update the minimum string if the new string is smaller
        if new_str < min_str:
            min_str = new_str
    return min_str

