def maximum_product_of_three(numbers):
    if len(numbers) < 3:
        return 0

    # Sort the list
    numbers.sort()

    # The maximum product can be from:
    # 1. The product of the three largest positive numbers
    # 2. The product of the two smallest (possibly negative) numbers and the largest positive number
    return max(
        numbers[-1] * numbers[-2] * numbers[-3],
        numbers[0] * numbers[1] * numbers[-1]
    )

