def largestNumberWithAdjacentSwaps(digits, k):
    digits = list(digits)  # Convert string into a list for easy manipulation
    n = len(digits)

    for i in range(n):
        if k <= 0:
            break  # No more swaps allowed
        # Find the index of the maximum digit in the range [i, i + k]
        max_pos = i
        for j in range(i + 1, min(i + k + 1, n)):
            if digits[j] > digits[max_pos]:
                max_pos = j

        # Bring the max digit to position i by swapping adjacent elements
        for j in range(max_pos, i, -1):
            digits[j], digits[j - 1] = digits[j - 1], digits[j]
            k -= 1  # Each adjacent swap reduces remaining k by 1

    return ''.join(digits)

