def calculate_merged_parks_length(n, parks):
    # Sort the parks based on their start positions
    parks.sort()

    merged = []
    for park in parks:
        if not merged:
            merged.append(park)
        else:
            last = merged[-1]
            # Check if the current park touches or overlaps with the last merged park
            if park[0] <= last[1]:
                # Merge them by updating the end of the last park
                merged[-1] = (last[0], max(last[1], park[1]))
            else:
                merged.append(park)

    # Calculate the total length of merged parks
    total_length = sum(end - start for start, end in merged)
    return total_length

