import heapq

def min_meeting_rooms(meetings: list[tuple[int, int]]) -> int:
    if not meetings:
        return 0

    # Sort the meetings by start time
    meetings.sort(key=lambda x: x[0])

    # Min-heap to keep track of the earliest ending time of meetings
    min_heap = []

    for start, end in meetings:
        # If the earliest ending time is <= start time, we can reuse that room
        if min_heap and min_heap[0] <= start:
            heapq.heappop(min_heap)

        # Add the current meeting's end time to the heap
        heapq.heappush(min_heap, end)

    # The size of the heap at the end represents the number of rooms needed
    return len(min_heap)

