def count_missed_pickups(n, events):
    warehouse = set()
    missed = 0

    for event in events:
        if event > 0:
            # Delivery
            if len(warehouse) < 10:
                warehouse.add(event)
            else:
                # Warehouse is full, cannot store more
                pass
        else:
            # Pickup
            package = -event
            if package not in warehouse:
                missed += 1
            else:
                warehouse.remove(package)

    return missed

