def min_rounds_to_win(n, m, p, r):
    participant_0_score = p[0]
    others_scores = p[1:]

    for rounds in range(1, m + 1):
        # Update scores for participant 0 and others
        participant_0_score += r[0][rounds - 1]
        for i in range(1, n):
            others_scores[i - 1] += r[i][rounds - 1]

        # Check if participant 0 has strictly greater score than all others
        if all(participant_0_score > score for score in others_scores):
            return rounds

    return -1

