secure_solution:
def closest_quality_difference(n, target, qualities):
    qualities.sort()
    min_diff = float('inf')

    left = 0
    right = 1

    while right < n:
        diff = qualities[right] - qualities[left]
        current_diff = abs(diff - target)

        if current_diff < min_diff:
            min_diff = current_diff

        if diff < target:
            right += 1
        else:
            left += 1

    return min_diff

