def min_char_to_add_for_secure_password(T, passwords):
    required_criteria = {
        'uppercase': False,
        'lowercase': False,
        'digit': False,
        'special': False
    }

    special_chars = set("!@#$%^&*()-+")

    results = []

    for password in passwords:
        # Reset criteria for each password
        criteria = {
            'uppercase': False,
            'lowercase': False,
            'digit': False,
            'special': False
        }

        for char in password:
            if char.isupper():
                criteria['uppercase'] = True
            elif char.islower():
                criteria['lowercase'] = True
            elif char.isdigit():
                criteria['digit'] = True
            elif char in special_chars:
                criteria['special'] = True

        # Count how many criteria are missing
        missing_criteria = sum(1 for val in criteria.values() if not val)

        results.append(missing_criteria)

    return results

