secure_solution:
def count_special_triplets(N, X, arr):
    count = 0
    # Iterate through all possible triplets (i, j, k) with i < j < k
    for i in range(N):
        for j in range(i + 1, N):
            for k in range(j + 1, N):
                if (arr[i] + arr[j] + arr[k]) % X == 0:
                    count += 1
    return count

