def max_path_sum(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Initialize dp with the same dimensions as grid
    dp = [[0] * n for _ in range(m)]

    # Base case: first row
    for j in range(n):
        dp[0][j] = grid[0][j]

    # Fill dp table
    for i in range(1, m):
        for j in range(n):
            # Consider only valid positions from the previous row
            prev_max = 0
            for dj in [-1, 0, 1]:
                prev_j = j + dj
                if 0 <= prev_j < n:
                    prev_max = max(prev_max, dp[i-1][prev_j])
            dp[i][j] = grid[i][j] + prev_max

    # The answer is the maximum value in the last row
    return max(dp[-1])

