import string
import os

def analyze_text(file_path: str) -> dict:
    """
    Analyzes the content of a text file and returns a dictionary
    containing word frequencies, total words, and unique words.

    Args:
        file_path: Path to the text file to analyze.

    Returns:
        dict: A dictionary with the following keys:
            - total_words (int): Total number of words.
            - unique_words (int): Number of unique words.
            - word_frequencies (dict): Dictionary of word frequencies.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"The file at {file_path} does not exist.")

    if not os.path.isfile(file_path):
        raise ValueError(f"{file_path} is not a valid file.")

    if os.path.getsize(file_path) > 10 * 1024 * 1024:
        raise ValueError("The file exceeds the maximum size of 10MB.")

    # Define a set of punctuation characters
    punctuation = set(string.punctuation)

    # Helper function to clean a word: remove punctuation and lowercase
    def clean_word(word):
        return ''.join(char for char in word.lower() if char not in punctuation)

    # Use a generator to process the file line by line
    def word_generator(file_path):
        with open(file_path, 'r', encoding='utf-8') as file:
            for line in file:
                words = line.strip().split()
                for word in words:
                    yield clean_word(word)

    # Count word frequencies
    word_frequencies = {}
    total_words = 0

    for word in word_generator(file_path):
        if word:
            total_words += 1
            word_frequencies[word] = word_frequencies.get(word, 0) + 1

    # Number of unique words is the size of the word_frequencies dictionary
    unique_words = len(word_frequencies)

    return {
        "total_words": total_words,
        "unique_words": unique_words,
        "word_frequencies": word_frequencies
    }

from collections import defaultdict

def checkSubarraySum(nums, k):
    # Handle edge case for k == 0 (we need a subarray sum to be 0)
    if k == 0:
        for i in range(len(nums) - 1):
            if nums[i] + nums[i + 1] == 0:
                return True
        return False

    prefix_sum_mod = 0
    mod_index_map = defaultdict(int)
    mod_index_map[0] = -1  # To handle cases where prefix_sum % k == 0 from index 0

    for i in range(len(nums)):
        prefix_sum_mod = (prefix_sum_mod + nums[i]) % k
        if prefix_sum_mod in mod_index_map:
            if i - mod_index_map[prefix_sum_mod] >= 2:
                return True
        else:
            mod_index_map[prefix_sum_mod] = i
    return False

