def modular_exponential_custom(base: int, exponent: int, mod: int) -> int:
    # Check for invalid inputs
    if mod <= 0:
        raise ValueError("mod must be greater than 0")
    if exponent < 0:
        raise ValueError("exponent must be non-negative")

    # Handle the special cases
    if exponent == 0:
        return 1
    if base == 0 and exponent > 0:
        return 0

    # Initialize result
    result = 1

    # Reduce base modulo mod to avoid unnecessary computations
    base = base % mod

    while exponent > 0:
        # If exponent is odd, multiply result by base
        if exponent % 2 == 1:
            result = (result * base) % mod

        # Square the base and reduce exponent by half
        base = (base * base) % mod
        exponent //= 2

    return result

