secure_solution:
def partitionArray(arr, N):
    total_sum = sum(arr)
    target = total_sum // 2

    # dp[i][s] is True if sum s can be formed using first i elements
    dp = [[False] * (target + 1) for _ in range(N + 1)]
    dp[0][0] = True  # Base case: sum 0 using 0 elements

    for i in range(1, N + 1):
        for s in range(target + 1):
            # If the current sum can be formed without the current element
            if dp[i - 1][s]:
                dp[i][s] = True
            # If the current sum can be formed with the current element
            if s >= arr[i - 1] and dp[i - 1][s - arr[i - 1]]:
                dp[i][s] = True

    # Find the maximum sum s less than or equal to target
    for s in range(target, -1, -1):
        if dp[N][s]:
            return total_sum - 2 * s

    return total_sum  # Fallback if no subset sum found, although this should never happen

