from collections import deque

def find_all_elements(n, initial_elements, m, transformation_rules):
    # Convert the list of initial elements into a set for fast lookup
    elements = set(initial_elements)

    # Parse transformation rules into a dictionary for easy access
    rules = {}
    for rule in transformation_rules:
        left, right = rule.split(" -> ")
        e1, e2 = left.split()
        rules[(e1, e2)] = right
        rules[(e2, e1)] = right  # Since order doesn't matter for combination

    # Use BFS to explore all possible elements
    queue = deque(initial_elements)
    while queue:
        e1 = queue.popleft()
        # Try combining e1 with all elements in the set
        for e2 in list(elements):
            if e1 != e2:  # Avoid combining element with itself unless a rule exists for it
                key = tuple(sorted((e1, e2)))  # Ensure consistent key format
                if key in rules:
                    new_element = rules[key]
                    if new_element not in elements:
                        elements.add(new_element)
                        queue.append(new_element)

    # Return sorted list of all elements
    return sorted(elements)

