        for j in range(n):
            if grid[i][j] == 1:
                # Start with 4 sides
                perimeter += 4
                # Check top neighbor
                if i > 0 and grid[i - 1][j] == 1:
                    perimeter -= 1
                # Check bottom neighbor
                if i < m - 1 and grid[i + 1][j] == 1:
                    perimeter -= 1
                # Check left neighbor
                if j > 0 and grid[i][j - 1] == 1:
                    perimeter -= 1
                # Check right neighbor
                if j < n - 1 and grid[i][j + 1] == 1:
                    perimeter -= 1

    return perimeter

