def countPaths(n, m, office_layout):
    # Initialize a DP table with the same dimensions as the office_layout
    dp = [[0 for _ in range(m)] for _ in range(n)]

    # If the starting cell is blocked, there are no paths
    if office_layout[0][0] == 1:
        return 0

    # Starting point has 1 path (itself)
    dp[0][0] = 1

    # Fill the first row
    for j in range(1, m):
        if office_layout[0][j] == 0:
            dp[0][j] = dp[0][j - 1]
        else:
            dp[0][j] = 0  # Blocked, no path

    # Fill the first column
    for i in range(1, n):
        if office_layout[i][0] == 0:
            dp[i][0] = dp[i - 1][0]
        else:
            dp[i][0] = 0  # Blocked, no path

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            if office_layout[i][j] == 0:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
            else:
                dp[i][j] = 0  # Blocked, no path

    return dp[n - 1][m - 1]

