def can_reach_end(grid):
    if not grid or grid[0][0] == '#' or grid[-1][-1] == '#':
        return False

    n, m = len(grid), len(grid[0])
    visited = [[False for _ in range(m)] for _ in range(n)]

    def dfs(x, y):
        if x == n - 1 and y == m - 1:
            return True
        if x < 0 or y < 0 or x >= n or y >= m or grid[x][y] == '#' or visited[x][y]:
            return False

        visited[x][y] = True

        # Try moving in all 4 directions
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dx, dy in directions:
            if dfs(x + dx, y + dy):
                return True

        return False

    return dfs(0, 0)

