def findMaxLength(nums):
    # Dictionary to store the first occurrence of each prefix sum
    sum_index = {0: -1}
    max_length = 0
    current_sum = 0

    for i, num in enumerate(nums):
        current_sum += 1 if num == 1 else -1

        # If the current sum has been seen before, update max_length
        if current_sum in sum_index:
            max_length = max(max_length, i - sum_index[current_sum])
        else:
            sum_index[current_sum] = i

    return max_length

