def make_change(amount: int, denominations: list) -> int:
    # Edge case: amount is 0, no coins needed
    if amount == 0:
        return 0

    # Initialize dp array with infinity
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0  # Base case: 0 coins needed to make 0 amount

    # Dynamic programming to find minimum coins
    for i in range(1, amount + 1):
        for coin in denominations:
            if coin <= i:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    # If dp[amount] is still infinity, means it's not possible to make the amount
    return dp[amount] if dp[amount] != float('inf') else -1

