def process_instructions(instructions):
    # Use a set to keep track of the lights that are on
    on_lights = set()

    for instruction in instructions:
        # Extract the coordinates from the instruction
        _, coord_str = instruction.split()
        x_str, y_str = coord_str.split(',')
        x, y = int(x_str), int(y_str)
        coord = (x, y)

        # Toggle the light: if it's on, turn it off; if it's off, turn it on
        if coord in on_lights:
            on_lights.remove(coord)
        else:
            on_lights.add(coord)

    # Return the list of on lights sorted by coordinates
    return sorted(on_lights)

