def max_coins(grid):
    n = len(grid)
    m = len(grid[0])

    # Initialize the DP table with the same values as the grid
    dp = [row[:] for row in grid]

    # Start from the second row
    for i in range(1, n):
        for j in range(m):
            # Determine the possible previous positions
            max_prev = 0
            if j - 1 >= 0:
                max_prev = max(max_prev, dp[i-1][j-1])
            if j + 1 < m:
                max_prev = max(max_prev, dp[i-1][j+1])
            max_prev = max(max_prev, dp[i-1][j])
            dp[i][j] += max_prev

    # The result is the maximum value in the last row
    return max(dp[-1])

