from collections import defaultdict, deque

def minimum_completion_time(n, task_times, d, dependencies):
    # Build the graph and in-degree count
    graph = defaultdict(list)
    in_degree = [0] * n

    for u, v in dependencies:
        graph[u - 1].append(v - 1)  # Convert to 0-based indexing
        in_degree[v - 1] += 1

    # Initialize earliest finish times with the task times (since no dependencies = start at day 0)
    earliest_finish_time = [0] * n
    for i in range(n):
        earliest_finish_time[i] = task_times[i]

    # Topological sort using Kahn's algorithm
    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    while queue:
        u = queue.popleft()
        for v in graph[u]:
            # The earliest finish time for v is max of its current value or (earliest_finish_time[u] + task_times[v])
            earliest_finish_time[v] = max(earliest_finish_time[v], earliest_finish_time[u] + task_times[v])
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # The result is the maximum finish time among all tasks
    return max(earliest_finish_time)

