from collections import deque

def shortest_subarray(nums, k):
    n = len(nums)
    prefix_sums = [0] * (n + 1)  # prefix_sums[0] = 0, prefix_sums[1] = nums[0], etc.

    for i in range(n):
        prefix_sums[i + 1] = prefix_sums[i] + nums[i]

    dq = deque()
    result = -1

    for i in range(n + 1):
        while dq and prefix_sums[i] - prefix_sums[dq[0]] >= k:
            result = min(result, i - dq.popleft()) if result != -1 else i - dq.popleft()

        while dq and prefix_sums[i] <= prefix_sums[dq[-1]]:
            dq.pop()

        dq.append(i)

    return result

