from collections import deque

def min_time_to_infect(grid):
    m = len(grid)
    n = len(grid[0])

    # Find the initial infected cell
    start = None
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                start = (i, j)
                break
        if start:
            break

    if not start:
        return -1  # No infected cell

    # If the entire grid is already infected
    if all(cell == 1 for row in grid for cell in row):
        return 0

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    visited = [[False] * n for _ in range(m)]
    queue = deque()
    queue.append((start[0], start[1], 0))  # (row, col, time)
    visited[start[0]][start[1]] = True

    max_time = 0

    while queue:
        r, c, t = queue.popleft()
        max_time = max(max_time, t)

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and not visited[nr][nc] and grid[nr][nc] == 0:
                visited[nr][nc] = True
                queue.append((nr, nc, t + 1))

    # Check if all cells are visited (infected)
    for i in range(m):
        for j in range(n):
            if not visited[i][j]:
                return -1

    return max_time

