import math

def repeated_string_match(A: str, B: str) -> int:
    # If B is not a subset of A's characters, it can never be a substring
    if not set(B).issubset(set(A)):
        return -1

    # Minimum number of repetitions needed
    min_repeats = math.ceil(len(B) / len(A))

    # Try with min_repeats, min_repeats + 1, and min_repeats + 2
    for i in range(min_repeats, min_repeats + 2):
        if B in A * i:
            return i

    return -1

