def find_shortest_subarray(arr: list) -> int:
    n = len(arr)
    if n <= 1:
        return 0

    # Step 1: Find the unsorted subarray
    start = 0
    while start < n - 1 and arr[start] <= arr[start + 1]:
        start += 1

    if start == n - 1:
        return 0  # The array is already sorted

    end = n - 1
    while end > 0 and arr[end] >= arr[end - 1]:
        end -= 1

    # Step 2: Find min and max in the unsorted subarray
    min_sub = min(arr[start:end + 1])
    max_sub = max(arr[start:end + 1])

    # Step 3: Expand the subarray to include out-of-order elements
    while start > 0 and arr[start - 1] > min_sub:
        start -= 1

    while end < n - 1 and arr[end + 1] < max_sub:
        end += 1

    # Step 4: Return the length of the subarray
    return end - start + 1

def max_treasures(grid, treasures):
    from collections import defaultdict

    n = len(grid)
    m = len(grid[0])

    # Convert treasures to a set for fast lookup
    treasure_set = set(treasures)

    # Initialize DP table
    dp = [[-1 for _ in range(m)] for _ in range(n)]

    # Start point
    if grid[0][0] == 0:
        dp[0][0] = 1 if (0, 0) in treasure_set else 0
    else:
        return 0  # Start cell is blocked, no path

    # Fill DP table
    for i in range(n):
        for j in range(m):
            if i == 0 and j == 0:
                continue
            if grid[i][j] == 1:
                dp[i][j] = -1
                continue
            max_val = -1
            if i > 0 and dp[i-1][j] != -1:
                max_val = max(max_val, dp[i-1][j])
            if j > 0 and dp[i][j-1] != -1:
                max_val = max(max_val, dp[i][j-1])
            if max_val != -1:
                dp[i][j] = max_val + (1 if (i, j) in treasure_set else 0)

    return dp[n-1][m-1] if dp[n-1][m-1] != -1 else 0

