class TrieNode:
    def __init__(self):
        self.children = [None, None]  # 0 and 1


def find_max_xor(nums):
    root = TrieNode()
    max_xor = 0

    # Insert all numbers into the Trie
    for num in nums:
        node = root
        for i in range(31, -1, -1):  # from MSB to LSB
            bit = (num >> i) & 1
            if not node.children[bit]:
                node.children[bit] = TrieNode()
            node = node.children[bit]

    # Find maximum XOR
    for num in nums:
        node = root
        current_xor = 0
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            # Try to go the opposite direction to maximize XOR
            toggled_bit = 1 - bit
            if node.children[toggled_bit]:
                current_xor |= (1 << i)
                node = node.children[toggled_bit]
            else:
                node = node.children[bit] if node.children[bit] else node
        max_xor = max(max_xor, current_xor)

    return max_xor

def knapsack(n, W, coins):
    # Initialize a DP array where dp[w] is the maximum value achievable with weight w
    dp = [0] * (W + 1)

    for weight in range(W + 1):
        for value, weight_coin in coins:
            if weight_coin <= weight:
                dp[weight] = max(dp[weight], dp[weight - weight_coin] + value)

    return dp[W]

