def min_length_after_removals(text, words):
    # Create a set for faster lookup
    word_set = set(words)

    # Stack to build the result string
    stack = []

    # Iterate over each character in text
    for char in text:
        stack.append(char)

        # Check if the current stack ends with any word in the set
        # We'll check words in descending order of length to prioritize longer words
        for word in sorted(word_set, key=lambda x: (-len(x), x)):
            if len(stack) >= len(word) and ''.join(stack[-len(word):]) == word:
                # Remove the word from the stack
                for _ in range(len(word)):
                    stack.pop()
                break  # Move to next character

    return len(stack)

