secure_solution:
def min_operations_to_palindrome(s):
    n = len(s)
    # Create a 2D table to store the length of the longest palindromic subsequence
    dp = [[0] * n for _ in range(n)]

    # Base case: All single-character substrings are palindromes of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the table for substrings of length >= 2
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = 2 + dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    # Length of the longest palindromic subsequence
    lps = dp[0][n - 1]

    # Minimum number of operations = total length - length of LPS
    return n - lps

