def find_equilibrium_permutation(t, test_cases):
    results = []

    for case in test_cases:
        n, permutation = case
        total_sum = sum(permutation)
        left_sum = 0

        for i in range(n):
            right_sum = total_sum - left_sum - permutation[i]
            if left_sum == right_sum:
                results.append(permutation[i])
                break
            left_sum += permutation[i]
        else:
            results.append(-1)

    return results

