from typing import List

def cyclic_sort(arr: List[int]) -> List[int]:
    n = len(arr)
    i = 0
    while i < n:
        # The correct position of the element at index i is arr[i] - 1
        correct_pos = arr[i] - 1
        if arr[i] != arr[correct_pos]:
            # Swap the elements
            arr[i], arr[correct_pos] = arr[correct_pos], arr[i]
        else:
            i += 1
    return arr

