    Args:
        moves (str): A string of moves, each being 'U', 'D', 'L', or 'R'.

    Returns:
        bool: True if the robot returns to the origin, False otherwise.
    """
    x, y = 0, 0  # Starting position

    for move in moves:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
        # Ignore any other characters as per the requirement

