secure_solution:
def can_partition(arr):
    total_sum = sum(arr)

    # If total sum is odd, it's impossible to split into two equal sum subarrays
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    n = len(arr)

    # dp[i][s] will be True if we can get sum s using the first i elements
    dp = [[False] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = True  # Base case: sum 0 can be achieved with 0 elements

    for i in range(1, n + 1):
        for s in range(target + 1):
            # If we can achieve sum s without considering the ith element
            if dp[i - 1][s]:
                dp[i][s] = True
                # If the current element can be added without exceeding target
                if s + arr[i - 1] <= target:
                    dp[i][s + arr[i - 1]] = True

    return dp[n][target]

