def convert_temperature(temperature: float, from_unit: str, to_unit: str) -> float:
    """
    Convert the temperature from one unit to another.

    Input Parameters:
        temperature (float): The input temperature value.
        from_unit (str): The unit of the input temperature. It must be one of: 'Celsius', 'Fahrenheit', 'Kelvin'.
        to_unit (str): The unit of the output temperature. It must be one of: 'Celsius', 'Fahrenheit', 'Kelvin'.

    Returns:
        float: The converted temperature.

    Raises:
        ValueError: If the input temperature is below absolute zero in the provided unit.
        ValueError: If `from_unit` or `to_unit` are not valid temperature units.
    """
    # Validate the units
    valid_units = ['Celsius', 'Fahrenheit', 'Kelvin']
    if from_unit not in valid_units or to_unit not in valid_units:
        raise ValueError(f"Invalid temperature unit '{from_unit if from_unit not in valid_units else to_unit}'.")

    # Check if temperature is below absolute zero
    if from_unit == 'Celsius':
        if temperature < -273.15:
            raise ValueError("Temperature below absolute zero.")
    elif from_unit == 'Fahrenheit':
        if temperature < -459.67:
            raise ValueError("Temperature below absolute zero.")
    elif from_unit == 'Kelvin':
        if temperature < 0:
            raise ValueError("Temperature below absolute zero.")

    # Convert temperature to Kelvin first (common reference point)
    if from_unit == 'Celsius':
        kelvin = temperature + 273.15
    elif from_unit == 'Fahrenheit':
        kelvin = (temperature - 32) * 5/9 + 273.15
    elif from_unit == 'Kelvin':
        kelvin = temperature

    # Convert from Kelvin to the target unit
    if to_unit == 'Celsius':
        return kelvin - 273.15
    elif to_unit == 'Fahrenheit':
        return (kelvin - 273.15) * 9/5 + 32
    elif to_unit == 'Kelvin':
        return kelvin

