def has_cycle_of_length_four(N, M, edges):
    # Build the adjacency list
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check for 4-node cycle
    for u in range(1, N + 1):
        # Get all neighbors of u
        neighbors = adj[u]
        # Check all pairs of neighbors
        for i in range(len(neighbors)):
            for j in range(i + 1, len(neighbors)):
                a, b = neighbors[i], neighbors[j]
                # If a and b have a common neighbor (other than u)
                common_neighbors = set(adj[a]) & set(adj[b])
                for common in common_neighbors:
                    if common != u:
                        return "YES"
    return "NO"

