def egg_drop(K, N):
    # Create a 2D list where dp[i][j] represents the minimum number of attempts
    # required to find the critical floor using i eggs and j floors.
    dp = [[0] * (N + 1) for _ in range(K + 1)]

    # If there is only one floor, then only one attempt is needed
    for i in range(K + 1):
        dp[i][1] = 1

    # If there is only one egg, then we need to check every floor one by one
    for j in range(1, N + 1):
        dp[1][j] = j

    # Fill the rest of the table
    for i in range(2, K + 1):
        for j in range(2, N + 1):
            dp[i][j] = float('inf')
            # Try dropping the egg from every floor and take the minimum worst-case attempt
            for x in range(1, j + 1):
                dp[i][j] = min(dp[i][j], 1 + max(dp[i - 1][x - 1], dp[i][j - x]))

    return dp[K][N]

