            dp[i][j] = float('inf')
            # Try dropping the egg from every floor and take the minimum worst-case attempt
            for x in range(1, j + 1):
                dp[i][j] = min(dp[i][j], 1 + max(dp[i - 1][x - 1], dp[i][j - x]))

    return dp[K][N]

