def can_store_items(items, shelves):
    # Sort items in descending order (largest to smallest)
    items.sort(reverse=True)
    # Sort shelves in descending order (largest to smallest)
    shelves.sort(reverse=True)

    # Try placing each item on the largest available shelf
    for item in items:
        placed = False
        for i in range(len(shelves)):
            if shelves[i] >= item:
                shelves[i] -= item  # Deduct the item size from the shelf capacity
                placed = True
                break
        if not placed:
            return False  # No shelf can hold the item
    return True

