import math

def find_circle_intersection(x1: float, y1: float, r1: float, x2: float, y2: float, r2: float) -> str:
    if r1 < 0 or r2 < 0:
        raise ValueError("Radius cannot be negative.")

    # Calculate distance between centers
    dx = x2 - x1
    dy = y2 - y1
    distance = math.hypot(dx, dy)  # Euclidean distance

    # Special case: same center
    if distance == 0:
        if r1 == r2:
            return "Touching"  # Same circle
        else:
            return "Disjoint"  # One circle inside the other

    # Check relationship
    sum_radii = r1 + r2
    diff_radii = abs(r1 - r2)

    if distance > sum_radii:
        return "Disjoint"
    elif distance < diff_radii:
        return "Disjoint"
    elif distance == sum_radii or distance == diff_radii:
        return "Touching"
    else:
        return "Intersecting"

