def num_trees(n: int) -> int:
    if n == 0:
        return 1

    # dp[i] represents the number of unique BSTs with i nodes
    dp = [0] * (n + 1)
    dp[0] = 1  # One way to form an empty tree

    for i in range(1, n + 1):
        for j in range(i):
            dp[i] += dp[j] * dp[i - 1 - j]

    return dp[n]

