from typing import List

def unique_paths(grid: List[List[str]]) -> int:
    m = len(grid)
    n = len(grid[0])

    # Initialize DP table with the same size as grid
    dp = [[0] * n for _ in range(m)]

    # Set starting point
    if grid[0][0] == "O":
        dp[0][0] = 1
    else:
        return 0  # If starting point is blocked, no paths possible

    # Fill the first row
    for j in range(1, n):
        if grid[0][j] == "O":
            dp[0][j] = dp[0][j-1]
        else:
            dp[0][j] = 0

    # Fill the first column
    for i in range(1, m):
        if grid[i][0] == "O":
            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = 0

    # Fill rest of the table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == "O":
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0

    return dp[m-1][n-1]

