def is_interesting_sequence(k, sequence):
    if k == 0:
        return "NO"  # k is at least 1 as per constraints

    n = len(sequence)
    i = 0

    while i < n:
        current_digit = sequence[i]
        count = 0

        # Count how many times the current_digit appears consecutively
        while i < n and sequence[i] == current_digit:
            count += 1
            i += 1

        # If the count is not exactly k, the sequence is not interesting
        if count != k:
            return "NO"

    return "YES"

