def min_difference(N, arr):
    total_sum = sum(arr)
    target = total_sum // 2
    dp = set()
    dp.add(0)

    for num in arr:
        new_sums = set()
        for s in dp:
            new_sum = s + num
            if new_sum <= target:
                new_sums.add(new_sum)
        dp.update(new_sums)

    closest_sum = max(dp)
    return abs(total_sum - 2 * closest_sum)

