def count_valleys(log):
    sea_level = 0
    valleys = 0
    in_valley = False

    for step in log:
        if step == 'U':
            sea_level += 1
        elif step == 'D':
            sea_level -= 1
        # '_' does not affect the height, so we skip it

        # Check if we have entered a valley (from sea level to below)
        if sea_level < 0 and not in_valley:
            in_valley = True
        # Check if we have exited a valley (from below sea level to sea level)
        elif sea_level == 0 and in_valley:
            valleys += 1
            in_valley = False

    return valleys

