def unique_paths(n, m, k, obstacles):
    # Initialize a grid with all zeros
    grid = [[0] * (m + 1) for _ in range(n + 1)]

    # Mark obstacles
    for x, y in obstacles:
        grid[x][y] = -1  # -1 indicates an obstacle

    # Initialize starting point
    if grid[1][1] != -1:
        grid[1][1] = 1

    # Fill the DP grid
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if grid[i][j] == -1:
                grid[i][j] = 0  # Obstacle, no paths go through this
                continue
            if i == 1 and j == 1:
                continue  # Already initialized
            # Include paths from top and left
            grid[i][j] = grid[i - 1][j] + grid[i][j - 1]

    return grid[n][m]

