def can_carry_weight(n, weights, capacity):
    # Create a boolean DP array where dp[i] is True if a subset with sum i can be formed
    dp = [False] * (capacity + 1)
    dp[0] = True  # Base case: a sum of 0 can always be formed with an empty subset

    for weight in weights:
        # Traverse the dp array in reverse to avoid reusing the same item multiple times
        for i in range(capacity, weight - 1, -1):
            if dp[i - weight]:
                dp[i] = True

    return "YES" if dp[capacity] else "NO"

