def lexicographically_smallest_subsequence(s, k):
    stack = []
    n = len(s)

    for i, ch in enumerate(s):
        # While the stack is not empty, and the current character is smaller than the last in stack
        # and we can remove the last character and still have enough characters left to reach size k
        while stack and ch < stack[-1] and len(stack) - 1 + (n - i) >= k:
            stack.pop()
        stack.append(ch)

    # Return the first k characters from the stack
    return ''.join(stack[:k])

