def min_remove_to_make_valid(s: str) -> str:
    """
    :param s: A string containing parentheses.
    :return: A valid string with the minimum number of removals.
    """
    stack = []
    to_remove = set()

    # First pass: left to right to find unmatched closing parentheses
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                to_remove.add(i)

    # Second pass: right to left to find unmatched opening parentheses
    for i in stack:
        to_remove.add(i)

    # Build the result string
    result = []
    for i, char in enumerate(s):
        if i not in to_remove:
            result.append(char)

    return ''.join(result)

