from typing import List

def subsequence_sum_exists(nums: List[int], target: int) -> bool:
    # Handle the edge case: if the list is empty and target is 0, return True
    if not nums and target == 0:
        return True

    # Initialize the set of achievable sums with 0 (empty subsequence)
    achievable_sums = {0}

    for num in nums:
        # Use a temporary set to avoid overwriting the achievable_sums during iteration
        new_sums = set()
        for s in achievable_sums:
            new_sums.add(s + num)
        # Update the set of achievable sums
        achievable_sums.update(new_sums)

        # Early exit if we've reached the target
        if target in achievable_sums:
            return True

    return target in achievable_sums

