    prices.sort()

    count = 0
    total_cost = 0

    # Accumulate prices until the budget is exceeded
    for price in prices:
        if total_cost + price <= budget:
            total_cost += price
            count += 1
        else:
            break  # No more items can be bought without exceeding the budget

    return count

