def roman_to_int(s: str) -> int:
    # Define the mapping of Roman numerals to integers
    roman_dict = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    # Check if the input string is valid
    if not s or len(s) > 15:
        return -1

    # Validate Roman numeral characters
    for char in s:
        if char not in roman_dict:
            return -1

    # Check for invalid subtractive combinations
    invalid_subtractions = {"IL", "IC", "ID", "IM", "XD", "XM", "VL", "VC", "VD", "VM"}
    for i in range(len(s) - 1):
        current_char = s[i]
        next_char = s[i + 1]
        if current_char in ["I", "X", "C"] and next_char in roman_dict:
            if f"{current_char}{next_char}" in invalid_subtractions:
                return -1

    # Calculate the value of the Roman numeral
    total = 0
    for i in range(len(s)):
        if i > 0 and roman_dict[s[i]] > roman_dict[s[i - 1]]:
            total -= roman_dict[s[i - 1]]
        else:
            total += roman_dict[s[i - 1]] if i > 0 else 0
    total += roman_dict[s[-1]]

    # Ensure the total is within the valid range
    if total < 1 or total > 3999:
        return -1

    return total


