def largest_number(arr, k):
    stack = []
    n = len(arr)

    for i, digit in enumerate(arr):
        # While we can still remove digits from the stack
        while stack and stack[-1] < digit and len(stack) + (n - i) > k:
            stack.pop()
        stack.append(digit)

    # Return the stack as a string
    return ''.join(map(str, stack[:k]))

