def findRepeatedPhrases(text, phraseLength):
    if phraseLength <= 0 or not text:
        return []

    words = text.split()
    if len(words) < phraseLength:
        return []

    phrase_counts = {}
    result = []
    seen = set()

    # Iterate over the text with a sliding window of `phraseLength` words
    for i in range(len(words) - phraseLength + 1):
        phrase = ' '.join(words[i:i + phraseLength])
        if phrase in phrase_counts:
            # If we've seen the phrase before, and it's not already in the result,
            # add it to the result list (only once).
            if phrase not in seen:
                result.append(phrase)
                seen.add(phrase)
        else:
            phrase_counts[phrase] = 1

    return result

