def paint_buildings(heights):
    n = len(heights)
    if n == 0:
        return 0, []

    # Initialize colors with first building as color 1
    colors = [1]

    for i in range(1, n):
        # If current building is same as previous, need to change color
        if heights[i] == heights[i - 1]:
            if colors[i - 1] == 1:
                colors.append(2)
            else:
                colors.append(1)
        else:
            # If different, can reuse same color if not same as previous
            if colors[i - 1] == 1:
                colors.append(2)
            else:
                colors.append(1)

    # Count how many unique colors we used (colors can be 1, 2, or possibly 3)
    unique_colors = len(set(colors))
    return unique_colors, colors

