def find_pairs_with_sum(arr, s):
    seen = set()
    pairs = set()

    for num in arr:
        complement = s - num
        if complement in seen:
            # Ensure a < b by sorting the pair
            pair = tuple(sorted((num, complement)))
            pairs.add(pair)
        seen.add(num)

    # Convert the set of pairs to a sorted list
    return sorted(pairs)

