def max_unique_prime_divisors(n):
    if n < 2:
        return 0  # No prime numbers less than 2

    # Step 1: Sieve of Eratosthenes to get smallest prime factor (SPF) for each number
    spf = list(range(n + 1))  # spf[i] will hold the smallest prime factor of i

    for i in range(2, int(n ** 0.5) + 1):
        if spf[i] == i:  # i is a prime
            for j in range(i * i, n + 1, i):
                if spf[j] == j:
                    spf[j] = i

    max_unique = 0

    # Step 2: For each number in range [2, n], count unique prime divisors
    for x in range(2, n + 1):
        num = x
        unique_primes = set()
        while num > 1:
            p = spf[num]
            unique_primes.add(p)
            while num % p == 0:
                num //= p
        max_unique = max(max_unique, len(unique_primes))

    return max_unique

