def canPartition(arr):
    total_sum = sum(arr)
    n = len(arr)

    # If total sum is odd, partition is not possible
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2

    # Initialize dp table
    dp = [[False] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = True  # Base case: zero elements sum to zero

    for i in range(1, n + 1):
        num = arr[i - 1]
        for s in range(target + 1):
            if dp[i - 1][s]:
                dp[i][s] = True
                if s + num <= target:
                    dp[i][s + num] = True

    return dp[n][target]

