def unique_k_length_subarrays(nums, k, target):
    n = len(nums)
    if n < k:
        return 0

    seen = set()
    current_sum = sum(nums[:k])

    if current_sum == target:
        seen.add((0, k - 1))

    for i in range(1, n - k + 1):
        current_sum = current_sum - nums[i - 1] + nums[i + k - 1]
        if current_sum == target:
            seen.add((i, i + k - 1))

    return len(seen)

