def distribute_requests(n, m, response_times):
    import sys
    sys.setrecursionlimit(10000)

    def can_assign(max_time):
        servers = [0] * m
        count = 0
        for time in response_times:
            # Try to assign to the server with the smallest current sum
            i = 0
            for j in range(1, m):
                if servers[j] < servers[i]:
                    i = j
            if servers[i] + time <= max_time:
                servers[i] += time
                count += 1
            else:
                return False
        return count >= n

    # Binary search to find the minimum possible max_time
    left, right = min(response_times), sum(response_times)
    ans_max_time = right

    while left <= right:
        mid = (left + right) // 2
        if can_assign(mid):
            ans_max_time = mid
            right = mid - 1
        else:
            left = mid + 1

    # Now, assign requests to servers based on the minimal max_time
    servers = [0] * m
    assignment = [0] * n

    for idx, time in enumerate(response_times):
        # Choose the server with the smallest current sum
        i = 0
        for j in range(1, m):
            if servers[j] < servers[i]:
                i = j
        assignment[idx] = i + 1  # 1-based index
        servers[i] += time

    return assignment

