def rearrange_string(s):
    digits = []
    alphabets = []

    # Separate digits and alphabets while preserving their relative order
    for char in s:
        if char.isdigit():
            digits.append(char)
        else:
            alphabets.append(char)

    # Combine digits followed by alphabets
    return ''.join(digits + alphabets)

