import heapq

def trapRainWater(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    heap = []

    # Initialize the heap with boundary cells
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(heap, (grid[i][j], i, j))
                visited[i][j] = True

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    water_trapped = 0

    while heap:
        height, x, y = heapq.heappop(heap)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                # If the new cell is lower than the current boundary height,
                # it can trap water
                if grid[nx][ny] < height:
                    water_trapped += height - grid[nx][ny]
                # Push the new cell's height (the higher of the two)
                heapq.heappush(heap, (max(grid[nx][ny], height), nx, ny))

    return water_trapped

