def max_operations(n, k, arr):
    from collections import Counter

    freq = Counter(arr)
    operations = 0

    for num in freq:
        complement = k - num
        if complement in freq:
            if num < complement:
                # Count the number of pairs (num, complement)
                count = min(freq[num], freq[complement])
                operations += count
            elif num == complement:
                # Each pair requires two elements
                count = freq[num] // 2
                operations += count

    return operations

