def maxProduct(N, arr):
    # Initialize the first four values for comparisons
    first_max = second_max = float('-inf')
    first_min = second_min = float('inf')

    for num in arr:
        # Update max values
        if num > first_max:
            second_max = first_max
            first_max = num
        elif num > second_max:
            second_max = num

        # Update min values
        if num < first_min:
            second_min = first_min
            first_min = num
        elif num < second_min:
            second_min = num

    # Compute possible maximum products
    product1 = first_max * second_max
    product2 = first_min * second_min

    # Return the maximum of the two products
    return max(product1, product2)

