def min_operations_to_convert(s, t):
    # Lengths of the two strings
    m = len(s)
    n = len(t)

    # Initialize a DP table with (m+1) rows and (n+1) columns
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases: converting an empty string to another string of length n needs n insertions
    for i in range(m + 1):
        dp[i][0] = i

    # Base cases: converting a string of length m to an empty string needs m deletions
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s[i - 1] == t[j - 1]:
                # No operation needed if characters are the same
                dp[i][j] = dp[i - 1][j - 1]
            else:
                # Take the minimum of insert, delete, or replace
                dp[i][j] = 1 + min(
                    dp[i - 1][j],    # Delete
                    dp[i][j - 1],    # Insert
                    dp[i - 1][j - 1] # Replace
                )

    return dp[m][n]

from typing import List

def compute_all_pairs_shortest_paths(adj_matrix: List[List[float]]) -> List[List[float]]:
    n = len(adj_matrix)
    # Initialize the result matrix with the same values as the adjacency matrix
    result_matrix = [row[:] for row in adj_matrix]

    # Apply Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                # Avoid overflow by checking if the path through k is shorter
                if result_matrix[i][k] + result_matrix[k][j] < result_matrix[i][j]:
                    result_matrix[i][j] = result_matrix[i][k] + result_matrix[k][j]

    return result_matrix

