from typing import List

def interpolation_search(array: List[int], search_key: int) -> int:
    """
    Perform interpolation search on a sorted array to find the index of the given search key.

    Args:
        array (List[int]): A list of integers sorted in increasing order.
        search_key (int): The integer to search for in the array.

    Returns:
        int: The index of the search key if found, otherwise -1.
    """
    if not array:
        return -1

    low = 0
    high = len(array) - 1

    while low <= high and array[low] <= search_key <= array[high]:
        # Avoid division by zero and ensure that the interpolation is calculated safely
        if array[low] == array[high]:
            if array[low] == search_key:
                return low
            else:
                return -1

        # Calculate the position using interpolation formula
        pos = low + ((search_key - array[low]) * (high - low)) // (array[high] - array[low])

        if array[pos] == search_key:
            return pos
        elif array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1

def find_higher_rank_later(ranks, scores):
    results = []
    n = len(scores)

    for i in range(n):
        found = False
        for j in range(i + 1, n):
            if scores[j] > scores[i]:
                results.append(ranks[j])
                found = True
                break
        if not found:
            results.append(-1)

    return results

