from collections import deque

def min_moves_maze(grid):
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return -1  # Start or end is a wall

    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    queue = deque([(0, 0, 0)])  # (row, col, moves)
    visited[0][0] = True

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up

    while queue:
        row, col, moves = queue.popleft()

        if row == rows - 1 and col == cols - 1:
            return moves

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols and not visited[new_row][new_col] and grid[new_row][new_col] == 0:
                visited[new_row][new_col] = True
                queue.append((new_row, new_col, moves + 1))

    return -1  # No path found

