def contains_nearby_almost_duplicate(nums, k, t):
    if t < 0 or k < 0:
        return False

    bucket_size = t + 1
    buckets = {}

    for i, num in enumerate(nums):
        bucket_id = num // bucket_size

        # Check if the current bucket has an element in the window
        if bucket_id in buckets:
            return True

        # Check neighboring buckets for possible match
        if (bucket_id - 1) in buckets and abs(num - buckets[bucket_id - 1]) <= t:
            return True
        if (bucket_id + 1) in buckets and abs(num - buckets[bucket_id + 1]) <= t:
            return True

        # Add current number to the bucket
        buckets[bucket_id] = num

        # Maintain the window size of k
        if i >= k:
            # Remove the number that is out of the window
            old_bucket_id = nums[i - k] // bucket_size
            del buckets[old_bucket_id]

    return False

