def can_partition(arr):
    total_sum = sum(arr)

    # If the total sum is odd, it's impossible to split into two equal subsets.
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    n = len(arr)

    # dp[i] = True if a subset with sum i can be formed
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: subset with sum 0 is always possible

    for num in arr:
        for i in range(target, num - 1, -1):
            if dp[i - num]:
                dp[i] = True

    return dp[target]

