def longest_consecutive_ones(s, k):
    left = 0
    max_length = 0
    zero_count = 0

    for right in range(len(s)):
        if s[right] == '0':
            zero_count += 1

        # If the number of zeros exceeds k, move the left pointer forward
        while zero_count > k:
            if s[left] == '0':
                zero_count -= 1
            left += 1

        # Update the maximum length of the window
        max_length = max(max_length, right - left + 1)

    return max_length

from collections import defaultdict, deque

def can_travel(bus_routes, queries):
    # Build adjacency list graph
    graph = defaultdict(set)

    # Create a mapping from bus stop to the routes (indices) it belongs to
    stop_to_routes = defaultdict(set)

    for route_idx, route in enumerate(bus_routes):
        for stop in route:
            stop_to_routes[stop].add(route_idx)

    # Build the graph by connecting all stops on the same route
    for route in bus_routes:
        for i in range(len(route)):
            for j in range(i + 1, len(route)):
                graph[route[i]].add(route[j])
                graph[route[j]].add(route[i])

    # BFS to check if there's a path from start to end
    def has_path(start, end):
        if start == end:
            return True
        visited = set()
        queue = deque([start])
        visited.add(start)

        while queue:
            current = queue.popleft()
            for neighbor in graph[current]:
                if neighbor == end:
                    return True
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return False

    # Process each query
    results = []
    for start, end in queries:
        if has_path(start, end):
            results.append("YES")
        else:
            results.append("NO")

    return results

