def lexicographically_smallest_sequence(arr):
    n = len(arr)
    # Traverse the list to find the first instance where arr[i] > arr[i + 1]
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            # Remove the element at index i
            return arr[:i] + arr[i + 1:]
    # If the list is non-decreasing, remove the last element
    return arr[:-1]

