def max_sum_of_k_subarray_max_elements(nums, k):
    n = len(nums)
    if n < k:
        return -1

    # memoization for max of nums[i:j]
    max_subarray = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n):
        current_max = nums[i]
        for j in range(i + 1, n + 1):
            current_max = max(current_max, nums[j - 1])
            max_subarray[i][j] = current_max

    # DP table
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for p in range(j - 1, i):
                dp[i][j] = max(dp[i][j], dp[p][j - 1] + max_subarray[p][i])

    return dp[n][k]

