from typing import List, Tuple

class SegmentTree:
    def __init__(self, size: int):
        self.n = size
        self.tree = [0] * (4 * self.n)
        self.lazy = [0] * (4 * self.n)

    def push(self, node: int, start: int, end: int):
        if self.lazy[node] != 0:
            self.tree[node] += self.lazy[node]
            if start != end:
                self.lazy[2 * node] += self.lazy[node]
                self.lazy[2 * node + 1] += self.lazy[node]
            self.lazy[node] = 0

    def update_range(self, node: int, start: int, end: int, l: int, r: int, value: int):
        self.push(node, start, end)
        if r < start or end < l:
            return
        if l <= start and end <= r:
            self.lazy[node] += value
            self.push(node, start, end)
            return
        mid = (start + end) // 2
        self.update_range(2 * node, start, mid, l, r, value)
        self.update_range(2 * node + 1, mid + 1, end, l, r, value)
        self.tree[node] = max(self.tree[2 * node], self.tree[2 * node + 1])

    def query_max(self, node: int, start: int, end: int, l: int, r: int) -> int:
        self.push(node, start, end)
        if r < start or end < l:
            return float('-inf')
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        left_max = self.query_max(2 * node, start, mid, l, r)
        right_max = self.query_max(2 * node + 1, mid + 1, end, l, r)
        return max(left_max, right_max)

def array_operations(n: int, operations: List[Tuple[str, int, int, int]]) -> List[int]:
    st = SegmentTree(n)
    results = []
    for op, start, end, value in operations:
        if op == "add":
            st.update_range(1, 0, n - 1, start, end, value)
        elif op == "max":
            result = st.query_max(1, 0, n - 1, start, end)
            results.append(result)
    return results

