def solve(matrix, queries):
    n = len(matrix)
    m = len(matrix[0])

    # Initialize prefix sum matrix
    prefix = [[0] * m for _ in range(n)]

    # Precompute prefix sums
    for i in range(n):
        for j in range(m):
            prefix[i][j] = matrix[i][j]
            if i > 0:
                prefix[i][j] += prefix[i-1][j]
            if j > 0:
                prefix[i][j] += prefix[i][j-1]
            if i > 0 and j > 0:
                prefix[i][j] -= prefix[i-1][j-1]  # Avoid double counting

    # Answer queries
    result = []
    for r, c in queries:
        result.append(prefix[r][c])

    return result

