def max_events(events):
    # Sort events by their end time
    events.sort(key=lambda x: x[1])

    count = 0
    last_end = -1  # Initialize with a value less than any possible start time

    for start, end in events:
        if start >= last_end:
            count += 1
            last_end = end

    return count

