def max_len_subarray_zero_sum(arr):
    prefix_sum = 0
    sum_index_map = {}
    max_length = 0

    for i, num in enumerate(arr):
        prefix_sum += num

        # If prefix_sum is 0, it means subarray from index 0 to i has sum zero
        if prefix_sum == 0:
            max_length = i + 1

        # If prefix_sum has been seen before, update max_length
        elif prefix_sum in sum_index_map:
            max_length = max(max_length, i - sum_index_map[prefix_sum])

        else:
            # Store the first occurrence of this prefix_sum
            sum_index_map[prefix_sum] = i

    return max_length

