def longest_subarray_divisible_by_x(nums, x):
    prefix_mod = {}
    prefix_sum = 0
    max_len = -1
    first_index = -1

    for i, num in enumerate(nums):
        prefix_sum += num
        mod = prefix_sum % x

        if mod == 0:
            # Subarray from start to current index is divisible
            max_len = i + 1
            first_index = -1
        elif mod in prefix_mod:
            # Subarray between first occurrence of this mod and current index is divisible
            max_len = max(max_len, i - prefix_mod[mod])
        else:
            # Store first occurrence of this mod
            prefix_mod[mod] = i

    return max_len if max_len != 0 else -1

