def sales_statistics(n, k, sales):
    if k == 0 or k > n:
        return 0, 0  # or handle this according to domain rules

    current_sum = sum(sales[:k])
    max_sum = current_sum

    for i in range(k, n):
        current_sum += sales[i] - sales[i - k]
        if current_sum > max_sum:
            max_sum = current_sum

    # Calculate average (rounded down)
    average = max_sum // k

    return max_sum, average

