        parts = line.strip().split()
        room_id = int(parts[0])
        num_connections = int(parts[1])
        connections = {}
        i = 2
        while i < len(parts):
            direction = parts[i]
            connected_room = int(parts[i + 1])
            connections[direction] = connected_room
            i += 2
        room_connections[room_id] = connections

    # Start from room 1
    current_room = 1

