import math

def calculate_rms(signal: list) -> float:
    if not signal:
        raise ValueError("Signal list cannot be empty")

    sum_of_squares = 0.0
    n = len(signal)

    for x in signal:
        sum_of_squares += x ** 2

    rms = math.sqrt(sum_of_squares / n)
    return rms

