from typing import List, Optional, Tuple

def find_subarray_with_sum(array: List[int], target_sum: int) -> Optional[Tuple[int, int]]:
    prefix_sum = 0
    prefix_sums = {0: -1}  # Maps prefix sum to its index

    for end_index, value in enumerate(array):
        prefix_sum += value

        # Check if (current prefix sum - target_sum) exists in the map
        if (prefix_sum - target_sum) in prefix_sums:
            start_index = prefix_sums[prefix_sum - target_sum] + 1
            return (start_index, end_index)

        # Store current prefix sum and its index
        prefix_sums[prefix_sum] = end_index

    return None

