def find_longest_path(n, edges, weights):
    from collections import defaultdict, deque

    # Build adjacency list and in-degree count
    graph = defaultdict(list)
    in_degree = [0] * n

    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    # Topological sort using Kahn's algorithm
    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    # DP array where dp[i] is the maximum path sum ending at node i
    dp = [0] * n

    while queue:
        u = queue.popleft()

        for v in graph[u]:
            # Relax the edge u -> v
            if dp[v] < dp[u] + weights[edges.index([u, v])]:
                dp[v] = dp[u] + weights[edges.index([u, v])]
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return max(dp)

