def can_be_palindrome_by_one_change(s):
    left, right = 0, len(s) - 1
    diff_count = 0

    while left < right:
        if s[left] != s[right]:
            diff_count += 1
            if diff_count > 1:
                return False
            # Assume we change the left character to match the right
            # or vice versa; no need to check both, just move one pointer
            left += 1
            right -= 1
        else:
            left += 1
            right -= 1

    return True

