def count_ways(n, m, coins):
    # Initialize dp array with 0s
    dp = [0] * (n + 1)
    dp[0] = 1  # Base case: one way to make 0

    # Iterate over each coin
    for coin in coins:
        # Update dp for each amount from coin to n
        for amount in range(coin, n + 1):
            dp[amount] += dp[amount - coin]

    return dp[n]

