import math

def findCubics(m):
    result = []
    max_a = int(m ** (1/3)) + 1  # Cube root of m as approximation

    for a in range(1, max_a + 1):
        a_cubed = a ** 3
        if a_cubed > m:
            break
        b_cubed = m - a_cubed
        b = round(b_cubed ** (1/3))
        if b ** 3 == b_cubed and a <= b:
            result.append((a, b))

    return result

