def longest_ones(bits):
    left = 0
    max_length = 0
    zero_count = 0

    for right in range(len(bits)):
        if bits[right] == 0:
            zero_count += 1

        # If there are more than one zero, move left pointer
        while zero_count > 1:
            if bits[left] == 0:
                zero_count -= 1
            left += 1

        # Update the maximum length of the window
        max_length = max(max_length, right - left + 1)

    return max_length

