def unique_paths(n, m, grid):
    # If start or end cell is blocked, return 0
    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return 0

    # Initialize a DP table with the same dimensions as the grid
    dp = [[0 for _ in range(m)] for _ in range(n)]
    dp[0][0] = 1  # Starting point has one way to reach itself

    # Fill the first row
    for j in range(1, m):
        if grid[0][j] == '.':
            dp[0][j] = dp[0][j-1]
        else:
            break  # Blocked, no further paths in this row

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == '.':
            dp[i][0] = dp[i-1][0]
        else:
            break  # Blocked, no further paths in this column

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == '.':
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Blocked cell, no paths through here

    return dp[n-1][m-1]

