from collections import deque

def shortest_subarray_with_sum(n, arr, target_sum):
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + arr[i]

    dq = deque()
    result = float('inf')

    for i in range(n + 1):
        while dq and prefix_sum[i] - prefix_sum[dq[0]] >= target_sum:
            result = min(result, i - dq.popleft())
        while dq and prefix_sum[i] <= prefix_sum[dq[-1]]:
            dq.pop()
        dq.append(i)

    return result if result != float('inf') else 0

