def find_longest_balanced_segment(N, traffic_data):
    prefix_sum = 0
    prefix_map = {0: -1}  # Store prefix sum -> first index
    max_length = 0

    for i in range(N):
        prefix_sum += traffic_data[i]
        if prefix_sum in prefix_map:
            # If this prefix_sum has been seen before, calculate the segment length
            segment_length = i - prefix_map[prefix_sum]
            if segment_length > max_length:
                max_length = segment_length
        else:
            # Store the first occurrence of this prefix_sum
            prefix_map[prefix_sum] = i

    return max_length

