secure_solution:
def max_tasks_on_time(tasks, deadlines):
    # Pair each task with its deadline and sort by deadline
    task_deadline_pairs = sorted(zip(tasks, deadlines), key=lambda x: x[1])

    time_used = 0
    completed_tasks = 0

    for task_time, deadline in task_deadline_pairs:
        if time_used + task_time <= deadline:
            time_used += task_time
            completed_tasks += 1
        else:
            # Cannot complete this task on time
            continue

    return completed_tasks

