def min_operations_to_sort_plants(N, garden):
    # Extract the non-zero heights from the garden
    heights = [h for h in garden if h != 0]

    # If there are no plants, no operations are needed
    if not heights:
        return 0

    # Function to find longest non-decreasing subsequence using patience sorting
    def longest_non_decreasing_subsequence_length(arr):
        import bisect
        tails = []
        for x in arr:
            # Use bisect_right to find the first index where x can be placed
            idx = bisect.bisect_right(tails, x)
            if idx == len(tails):
                tails.append(x)
            else:
                tails[idx] = x
        return len(tails)

    # Find the length of the longest non-decreasing subsequence
    lnds_length = longest_non_decreasing_subsequence_length(heights)

    # Minimum operations required = number of plants - length of LNDS
    return len(heights) - lnds_length

