def num_paths_with_obstacles(W, H, field):
    MOD = 10**9 + 7

    # Initialize dp table
    dp = [[0] * W for _ in range(H)]
    dp[0][0] = 1  # Starting point

    # Fill the dp table
    for i in range(H):
        for j in range(W):
            if i == 0 and j == 0:
                continue  # starting point already initialized
            if field[i][j] == 'R':
                dp[i][j] = 0
            else:
                # Sum from top (i-1, j) and left (i, j-1)
                top = dp[i-1][j] if i > 0 else 0
                left = dp[i][j-1] if j > 0 else 0
                dp[i][j] = (top + left) % MOD

    return dp[H-1][W-1]

