def longest_unique_subarray(arr):
    if not arr:
        return 0

    start = 0
    max_length = 0
    seen = {}

    for end in range(len(arr)):
        current = arr[end]

        # If the current element is seen and is within the current window, move start
        if current in seen and seen[current] >= start:
            start = seen[current] + 1

        # Update the last seen index of the current element
        seen[current] = end

        # Update the maximum length of the subarray
        max_length = max(max_length, end - start + 1)

    return max_length

