from collections import deque

def is_path_possible(n, m, grid):
    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return "NO"

    visited = [[False for _ in range(m)] for _ in range(n)]
    queue = deque()
    queue.append((0, 0))
    visited[0][0] = True

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        x, y = queue.popleft()
        if x == n - 1 and y == m - 1:
            return "YES"

