def find_shortest_subarray(n, m, playlist, favorites):
    from collections import defaultdict

    # Convert favorites to a set for fast lookup
    favorites_set = set(favorites)
    if m == 0:
        return (1, 1)  # edge case, though m >= 1 per input constraints

    # Map each favorite song to its index in the playlist
    index_map = {}
    for idx, song in enumerate(playlist):
        if song in favorites_set:
            index_map[song] = idx

    # Initialize variables for sliding window
    left = 0
    min_len = float('inf')
    start_idx = 0
    end_idx = 0
    count = 0
    freq = defaultdict(int)

    for right in range(n):
        song = playlist[right]
        if song in favorites_set:
            freq[song] += 1
            if freq[song] == 1:
                count += 1

        # When all favorites are in the current window
        while count == m:
            current_window_len = right - left + 1
            if current_window_len < min_len:
                min_len = current_window_len
                start_idx = left + 1  # convert to 1-based
                end_idx = right + 1  # convert to 1-based

            # Try to shrink the window from the left
            left_song = playlist[left]
            if left_song in favorites_set:
                freq[left_song] -= 1
                if freq[left_song] == 0:
                    count -= 1
            left += 1

    return (start_idx, end_idx)

