from typing import List, Tuple

def maximize_knapsack_value(items: List[Tuple[int, int]], capacity: int) -> int:
    n = len(items)
    # Edge case: if no items or no capacity, return 0
    if n == 0 or capacity == 0:
        return 0

    # Initialize a DP table of size (n + 1) x (capacity + 1)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    # Fill the DP table
    for i in range(1, n + 1):
        value, weight = items[i - 1]
        for w in range(1, capacity + 1):
            if weight > w:
                dp[i][w] = dp[i - 1][w]
            else:
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - weight] + value)

    return dp[n][capacity]

