def max_crystals(N, M, grid):
    # Initialize a 1D DP array with size M
    dp = [0] * M
    dp[0] = grid[0][0]  # Starting point

    # Fill the first row
    for j in range(1, M):
        dp[j] = dp[j - 1] + grid[0][j]

    # Fill the rest of the DP table
    for i in range(1, N):
        dp[0] += grid[i][0]  # Only can come from above
        for j in range(1, M):
            dp[j] = grid[i][j] + max(dp[j - 1], dp[j])

    return dp[-1]

from collections import deque

def shortest_path(matrix):
    if not matrix or matrix[0][0] == 0 or matrix[-1][-1] == 0:
        return -1  # Start or end is blocked

    m, n = len(matrix), len(matrix[0])
    visited = [[False] * n for _ in range(m)]
    queue = deque([(0, 0, 1)])  # (row, col, path_length)
    visited[0][0] = True

    directions = [(0, 1), (1, 0)]  # Right and Down

    while queue:
        row, col, length = queue.popleft()

        if row == m - 1 and col == n - 1:
            return length

        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < m and 0 <= nc < n and matrix[nr][nc] == 1 and not visited[nr][nc]:
                visited[nr][nc] = True
                queue.append((nr, nc, length + 1))

    return -1

