def fib_sum(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return 0

    # Initialize the first two Fibonacci numbers
    a, b = 0, 1
    total = a + b  # sum of first 2 numbers

    # Iterate from the 3rd number to the nth number
    for _ in range(2, n):
        a, b = b, a + b
        total += b

    return total

