def vending_machine(money, snacks):
    # Sort snacks by their cost in ascending order
    sorted_snacks = sorted(snacks, key=lambda x: x[1])

    total_cost = 0
    selected_snacks = []

    for name, cost in sorted_snacks:
        if total_cost + cost <= money:
            selected_snacks.append(name)
            total_cost += cost
        else:
            # If adding this snack exceeds the money, skip it
            continue

    return selected_snacks

