def can_partition(nums):
    total = sum(nums)

    # If the total is odd, it's not possible to split into two equal subsets
    if total % 2 != 0:
        return False

    target = total // 2
    n = len(nums)

    # Use a 1D DP array to track achievable sums up to the target
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum 0 is always possible

    for num in nums:
        for j in range(target, num - 1, -1):
            if dp[j - num]:
                dp[j] = True

    return dp[target]

