def contains_nearby_almost_duplicate(nums, k, t):
    if t < 0:
        return False  # t can't be negative
    bucket_size = t + 1
    buckets = {}

    for i, num in enumerate(nums):
        bucket_id = num // bucket_size

        # Check if the current number is in the same bucket or adjacent bucket
        for b in [bucket_id - 1, bucket_id, bucket_id + 1]:
            if b in buckets:
                if abs(num - buckets[b]) <= t:
                    return True

        # Add the current number to the bucket
        buckets[bucket_id] = num

        # Maintain the window size by removing the element out of range
        if i >= k:
            out_of_window_id = nums[i - k] // bucket_size
            del buckets[out_of_window_id]

    return False

