def distinct_ways_to_top(steps: int) -> int:
    if steps == 1:
        return 1
    elif steps == 2:
        return 2

    # Initialize the number of ways for step 1 and step 2
    one_step_back = 1  # ways to reach step 1
    two_steps_back = 2  # ways to reach step 2

    for i in range(3, steps + 1):
        current = one_step_back + two_steps_back
        one_step_back, two_steps_back = two_steps_back, current

    return two_steps_back

def four_sum(nums, target):
    nums.sort()
    n = len(nums)
    result = []

    for i in range(n - 3):
        # Skip duplicates for i
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        for j in range(i + 1, n - 2):
            # Skip duplicates for j
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue

            # Two pointers approach for the remaining two numbers
            left = j + 1
            right = n - 1

            while left < right:
                current_sum = nums[i] + nums[j] + nums[left] + nums[right]

                if current_sum == target:
                    result.append([nums[i], nums[j], nums[left], nums[right]])

                    # Skip duplicates for left
                    while left < right and nums[left] == nums[left + 1]:
                        left += 1
                    # Skip duplicates for right
                    while left < right and nums[right] == nums[right - 1]:
                        right -= 1

                    left += 1
                    right -= 1

                elif current_sum < target:
                    left += 1
                else:
                    right -= 1

    return result

