from collections import defaultdict, deque

def can_rearrange_words(words):
    if not words:
        return True  # Empty list is trivially rearrangeable

    # Build graph and degree counts
    graph = defaultdict(list)
    in_degree = defaultdict(int)
    out_degree = defaultdict(int)

    for word in words:
        start = word[0]
        end = word[-1]
        graph[start].append(end)
        out_degree[start] += 1
        in_degree[end] += 1

    # Check degree conditions for Eulerian path/circuit
    start_nodes = []
    end_nodes = []
    for node in set(in_degree.keys()).union(out_degree.keys()):
        if out_degree[node] - in_degree[node] == 1:
            start_nodes.append(node)
        elif in_degree[node] - out_degree[node] == 1:
            end_nodes.append(node)
        elif out_degree[node] == 0 and in_degree[node] == 0:
            continue  # Ignore isolated nodes
        else:
            # More than one node with imbalance
            if len(start_nodes) > 1 or len(end_nodes) > 1:
                return False

    if len(start_nodes) > 1 or len(end_nodes) > 1:
        return False

    # If no start/end nodes, we need to check if the graph is connected
    if not start_nodes and not end_nodes:
        # Pick any node with out-degree > 0
        if not graph:
            return True  # All words are empty (though this is not possible per problem)
        start_node = next(iter(graph.keys()))
        visited = set()
        stack = [start_node]
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    stack.append(neighbor)

        # Check if all nodes with non-zero degrees are visited
        for node in set(in_degree.keys()).union(out_degree.keys()):
            if out_degree[node] > 0 or in_degree[node] > 0:
                if node not in visited:
                    return False

    return True

