from typing import List, Tuple

def find_pairs(nums: List[int], k: int) -> List[Tuple[int, int]]:
    seen = set()
    pairs = set()

    for num in nums:
        complement = k - num
        if complement in seen:
            pair = tuple(sorted((num, complement)))
            pairs.add(pair)
        seen.add(num)

    return sorted(pairs)

