def count_sentences(input_string, word_dict):
    n = len(input_string)
    dp = [0] * (n + 1)
    dp[0] = 1  # Empty string has one way to be segmented

    # To speed up substring lookups
    word_set = set(word_dict)

    for i in range(1, n + 1):
        for j in range(i):
            if input_string[j:i] in word_set:
                dp[i] += dp[j]

    return dp[n]

