def can_convert_in_one_operation(s, t):
    # Check if the lengths differ by more than 1
    if abs(len(s) - len(t)) > 1:
        return "NO"

    # If lengths are equal, check for exactly one replacement
    if len(s) == len(t):
        diff = 0
        for a, b in zip(s, t):
            if a != b:
                diff += 1
                if diff > 1:
                    return "NO"
        return "YES" if diff == 1 else "NO"

    # If lengths differ by 1, check for exactly one insertion or deletion
    # We'll use a two-pointer approach
    i = j = 0
    diff = 0
    while i < len(s) and j < len(t):
        if s[i] == t[j]:
            i += 1
            j += 1
        else:
            # Insertion or deletion
            if len(s) < len(t):
                j += 1
            else:
                i += 1
            diff += 1
            if diff > 1:
                return "NO"
    # If we reached the end of one string, the rest of the other string is the difference
    diff += abs(len(s) - i) + abs(len(t) - j)
    return "YES" if diff == 1 else "NO"

