def convert_base(number, base_from, base_to):
    # Helper function to convert a number from any base to base 10
    def to_decimal(num_str, base):
        decimal_value = 0
        for char in num_str:
            if char.isdigit():
                digit = int(char)
            else:
                digit = ord(char.upper()) - ord('A') + 10
            decimal_value = decimal_value * base + digit
        return decimal_value

    # Helper function to convert a number from base 10 to any base
    def from_decimal(decimal_value, base):
        if decimal_value == 0:
            return '0'
        digits = []
        while decimal_value > 0:
            remainder = decimal_value % base
            if remainder < 10:
                digits.append(str(remainder))
            else:
                digits.append(chr(ord('A') + remainder - 10))
            decimal_value //= base
        return ''.join(reversed(digits))

    # Convert to base 10 first if the source base is not 10
    if base_from != 10:
        decimal_value = to_decimal(number, base_from)
    else:
        decimal_value = int(number)

    # Convert from base 10 to the target base
    return from_decimal(decimal_value, base_to)

