def find_shortest_path(n, m, grid):
    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # Find the start position 'S'
    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
                break
        if start:
            break

    if not start:
        return -1  # Start not found for some reason

    # BFS initialization
    visited = [[False] * m for _ in range(n)]
    queue = deque([(start[0], start[1], 0)])  # (row, col, distance)
    visited[start[0]][start[1]] = True

    while queue:
        r, c, dist = queue.popleft()

        # Check if current cell is the treasure
        if grid[r][c] == 'X':
            return dist

        # Explore neighbors
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc]:
                if grid[nr][nc] in ('.', 'X'):
                    visited[nr][nc] = True
                    queue.append((nr, nc, dist + 1))

    # If we exit the loop without finding 'X'
    return -1

