import heapq

def trapRainWater(heightMap):
    if not heightMap or not heightMap[0]:
        return 0

    m, n = len(heightMap), len(heightMap[0])
    visited = [[False for _ in range(n)] for _ in range(m)]
    heap = []

    # Push all boundary cells into the heap
    for i in range(m):
        for j in [0, n - 1]:
            heapq.heappush(heap, (heightMap[i][j], i, j))
            visited[i][j] = True
    for j in range(1, n - 1):
        for i in [0, m - 1]:
            heapq.heappush(heap, (heightMap[i][j], i, j))
            visited[i][j] = True

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    trapped_water = 0

    while heap:
        height, x, y = heapq.heappop(heap)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                # Water trapped is max(0, current height - neighbor height)
                if heightMap[nx][ny] < height:
                    trapped_water += height - heightMap[nx][ny]
                # Push the neighbor cell into heap with its own height (not the current height)
                heapq.heappush(heap, (max(height, heightMap[nx][ny]), nx, ny))

    return trapped_water

