def most_frequent_char(s):
    # Dictionary to store character frequencies
    freq = {}
    # Dictionary to store the first occurrence index of each character
    first_occurrence = {}

    # First pass: count frequencies and record first occurrence
    for index, char in enumerate(s):
        if char not in freq:
            freq[char] = 1
            first_occurrence[char] = index
        else:
            freq[char] += 1

    # Find the character with the maximum frequency
    max_freq = max(freq.values())
    # Filter characters with max frequency
    candidates = [char for char, count in freq.items() if count == max_freq]

    # Return the one that appears first in the string
    return min(candidates, key=lambda x: first_occurrence[x])

# Example usage:
# print(most_frequent_char("character"))  # Output: 'c'
# print(most_frequent_char("occurrence")) # Output: 'c'

