def feast_time(n, k, m, preparation_times, t):
    # Get the preparation time for the favorite dish
    favorite_time = preparation_times[k - 1]

    # Calculate total time required for m servings of the favorite dish
    total_favorite_time = favorite_time * m

    # Check if the total time is sufficient
    if total_favorite_time > t:
        return "IMPOSSIBLE"
    else:
        return t - total_favorite_time

def find_best_post_office_location(grid):
    buildings = []

    # Step 1: Collect coordinates of all buildings
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                buildings.append((i, j))

    if not buildings:
        return None  # No buildings, no need for a post office

    # Step 2: Compute median x and median y
    x_coords = [x for x, y in buildings]
    y_coords = [y for x, y in buildings]

    x_coords.sort()
    y_coords.sort()

    # If even number of buildings, choose any of the two middle points (e.g., the first one)
    median_x = x_coords[len(x_coords) // 2]
    median_y = y_coords[len(y_coords) // 2]

    # Ensure the median coordinates are within the grid
    return (median_x, median_y)

