def largest_rectangle(n):
    if n == 0:
        return (0, 0)
    # Start from the square root and go downwards to find the closest factor pair
    for i in range(int(math.isqrt(n)), 0, -1):
        if n % i == 0:
            return (n // i, i)
    return (1, n)  # In case n is 0 (though the constraints say n >= 1)

