def k_th_prime_factor(n, k):
    if n < 2 or k < 1:
        return -1

    prime_factors = []

    # Check divisibility by 2
    while n % 2 == 0:
        prime_factors.append(2)
        n //= 2

    # Check for odd numbers from 3 to sqrt(n)
    i = 3
    while i * i <= n:
        while n % i == 0:
            prime_factors.append(i)
            n //= i
        i += 2

    # If n is a prime number greater than 2
    if n > 1:
        prime_factors.append(n)

    # Return k-th prime factor if it exists
    if len(prime_factors) >= k:
        return prime_factors[k - 1]
    else:
        return -1

