def count_submatrices_with_sum(n, m, k, matrix, a, b):
    # Compute the prefix sum matrix
    prefix = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n):
        row_sum = 0
        for j in range(m):
            row_sum += matrix[i][j]
            prefix[i + 1][j + 1] = prefix[i][j + 1] + row_sum

    count = 0

    # Iterate over all possible top-left corners of a x b submatrix
    for i in range(n - a + 1):
        for j in range(m - b + 1):
            # Calculate the sum of the submatrix using prefix sum
            submatrix_sum = prefix[i + a][j + b] - prefix[i][j + b] - prefix[i + a][j] + prefix[i][j]
            if submatrix_sum == k:
                count += 1

    return count

