def minimize_max_time(n, durations):
    def backtrack(index, machine1_time, machine2_time):
        # If all tasks are assigned, return the maximum of the two machine times
        if index == n:
            return max(machine1_time, machine2_time)

        # Try assigning current task to machine1
        assign_to_machine1 = backtrack(index + 1, machine1_time + durations[index], machine2_time)

        # Try assigning current task to machine2
        assign_to_machine2 = backtrack(index + 1, machine1_time, machine2_time + durations[index])

        # Return the minimum of both options
        return min(assign_to_machine1, assign_to_machine2)

    return backtrack(0, 0, 0)

