def generate_playlist(songs, max_duration):
    # Sort songs by duration in ascending order
    sorted_songs = sorted(songs, key=lambda x: x[1])

    playlist = []
    total_duration = 0

    for song, duration in sorted_songs:
        if total_duration + duration <= max_duration:
            playlist.append(song)
            total_duration += duration
        else:
            # No more songs can be added
            break

    return playlist

