    seen = set()
    result = set()
    for num in array:
        complement = K - num
        if complement in seen:
            # Ensure the smaller number comes first to avoid duplicates
            pair = tuple(sorted((num, complement)))
            result.add(pair)
        seen.add(num)
    return sorted(result)

