def max_product(nums):
    if len(nums) < 2:
        raise ValueError("List must contain at least two elements.")

    # Sort the list
    nums.sort()

    # The maximum product can be either:
    # 1. Product of the two largest positive numbers
    # 2. Product of the two smallest (most negative) numbers
    return max(nums[-1] * nums[-2], nums[0] * nums[1])

