def allocate_parcels(n, m, parcels, capacities):
    # Initialize the assignment matrix with 0s
    assignment = [[0 for _ in range(n)] for _ in range(m)]

    # Keep track of how many parcels each truck has been assigned
    truck_load = [0] * m

    # Assign each parcel to the first truck that has not exceeded its capacity
    for parcel_index in range(n):
        for truck_index in range(m):
            if truck_load[truck_index] < capacities[truck_index]:
                assignment[truck_index][parcel_index] = 1
                truck_load[truck_index] += 1
                break

    return assignment

