def find_paths(n, m, k, forbidden):
    MOD = 10**9 + 7

    # Convert forbidden cells into a set for O(1) lookups
    forbidden_cells = set((x - 1, y - 1) for x, y in forbidden)

    # Edge case: if start or end is forbidden
    if (0, 0) in forbidden_cells or (n - 1, m - 1) in forbidden_cells:
        return 0

    # Initialize DP table
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1  # Starting point

    # Fill the DP table
    for i in range(n):
        for j in range(m):
            if (i, j) in forbidden_cells:
                dp[i][j] = 0
                continue
            if i > 0:
                dp[i][j] += dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i][j - 1]
            dp[i][j] %= MOD

    return dp[n - 1][m - 1]

