def convert(s, n):
    if n == 1 or n >= len(s):
        return s

    # Initialize a list of empty strings for each row
    rows = [''] * n
    current_row = 0
    going_down = False  # Controls direction (down or up)

    for char in s:
        rows[current_row] += char
        # Change direction if we hit the top or bottom row
        if current_row == 0 or current_row == n - 1:
            going_down = not going_down
        current_row += 1 if going_down else -1

    # Concatenate all rows to form the final string
    return ''.join(rows)

