def apply_operations(data):
    result = 0
    i = 0
    n = len(data)

    while i < n:
        # Determine the operation
        op = data[i]
        i += 1

        # Parse the number
        num = 0
        while i < n and data[i].isdigit():
            num = num * 10 + int(data[i])
            i += 1

        # Apply the operation
        if op == '+':
            result += num
        elif op == '-':
            result -= num
        elif op == '*':
            result *= num
        elif op == '/':
            result //= num  # Integer division

    return result

