def min_operations_to_non_decreasing(s):
    n = len(s)
    # dp[i] will store the length of the longest non-decreasing subsequence
    # ending at index i
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            if s[j] <= s[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    # Length of the longest non-decreasing subsequence
    lnds_length = max(dp)
    return n - lnds_length

