def caesar_cipher(input_str: str, shift: int) -> str:
    result = []
    for char in input_str:
        # Shift the character and wrap around using modulo
        shifted_char = chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
        result.append(shifted_char)
    return ''.join(result)

