def max_number_of_days(time, limit):
    time.sort()
    left = 0
    right = len(time) - 1
    days = 0

    while left < right:
        if time[left] + time[right] <= limit:
            days += 1
            left += 1
            right -= 1
        else:
            right -= 1

    return days

def decode_message(n, m, measurements):
    # Initialize a list to accumulate counts for each bit position
    bit_counts = [0] * n

    # Count occurrences of '1' at each position
    for measurement in measurements:
        for i in range(n):
            if measurement[i] == '1':
                bit_counts[i] += 1

    # Construct the most probable original message
    original = []
    for count in bit_counts:
        # If 1 appears more than half the time, it's more likely the original bit
        if count > m // 2:
            original.append('1')
        else:
            original.append('0')

    return ''.join(original)

