def intersection(arr1, arr2):
    # Initialize two pointers
    i, j = 0, 0
    result = []

    # Traverse both arrays
    while i < len(arr1) and j < len(arr2):
        if arr1[i] == arr2[j]:
            # If the elements are equal, add to result
            result.append(arr1[i])
            i += 1
            j += 1
        elif arr1[i] < arr2[j]:
            i += 1
        else:
            j += 1

    return result

