def max_ticket_value(n, ticket_values):
    if n == 0:
        return 0
    if n == 1:
        return ticket_values[0]

    # Initialize previous two values
    prev_prev = ticket_values[0]
    prev = max(ticket_values[0], ticket_values[1])

    for i in range(2, n):
        current = max(prev, prev_prev + ticket_values[i])
        prev_prev, prev = prev, current

    return prev

