def maximize_points(n, T, problems):
    # Initialize DP array with 0s
    dp = [0] * (T + 1)

    # Loop through each problem
    for time, points in problems:
        # Traverse the DP array in reverse to avoid reusing the same problem
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + points)

    # The answer is the maximum points achievable within time T
    return dp[T]

from typing import List
from collections import deque

def shortest_path(forest_grid: List[List[str]]) -> int:
    # Find start and end positions
    n = len(forest_grid)
    m = len(forest_grid[0])
    start = end = None

    for i in range(n):
        for j in range(m):
            if forest_grid[i][j] == 'S':
                start = (i, j)
            elif forest_grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1  # Should not happen due to problem constraints

    # BFS initialization
    queue = deque()
    queue.append((start[0], start[1], 0))  # (row, col, steps)
    visited = set()
    visited.add((start[0], start[1]))

    # Define movement directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        x, y, steps = queue.popleft()

        # If we reached the exit
        if (x, y) == end:
            return steps

        # Explore all four directions
        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            # Check if the new cell is within bounds and passable
            if 0 <= nx < n and 0 <= ny < m:
                if forest_grid[nx][ny] != '#' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, steps + 1))

    return -1  # No path found

