def find_sum_of_powers(n: int) -> list:
    # Generate all powers of 2 up to n
    powers_of_two = set()
    power = 1
    while power <= n:
        powers_of_two.add(power)
        power *= 2

    result = []
    for a in powers_of_two:
        b = n - a
        if b in powers_of_two and a < b:
            result.append((a, b))

    return result

