def min_time_to_complete_tasks(tasks):
    total_sum = sum(tasks)
    n = len(tasks)

    # Create a set to store all possible sums
    possible_sums = set()
    possible_sums.add(0)

    # Use dynamic programming to find all possible sums
    for task in tasks:
        temp = set()
        for s in possible_sums:
            temp.add(s + task)
        possible_sums.update(temp)

    # Find the sum closest to total_sum / 2
    half_total = total_sum / 2
    best_sum = 0
    for s in possible_sums:
        if s <= half_total and s > best_sum:
            best_sum = s

    # The minimum time to complete all tasks is the maximum of the two subsets
    return max(best_sum, total_sum - best_sum)

