import math

def solve_quadratic(a: int, b: int, c: int) -> tuple:
    discriminant = b**2 - 4*a*c

    # Handle precision issues by allowing a small tolerance for discriminant
    if discriminant > 1e-9:  # Consider as positive discriminant
        sqrt_discriminant = math.sqrt(discriminant)
        root1 = (-b + sqrt_discriminant) / (2*a)
        root2 = (-b - sqrt_discriminant) / (2*a)
        return (min(root1, root2), max(root1, root2))
    elif abs(discriminant) < 1e-9:  # Consider as zero discriminant (due to floating-point precision)
        root = -b / (2*a)
        return (root, root)
    else:  # Negative discriminant
        return ()

