def longest_palindrome(s):
    from collections import Counter

    count = Counter(s)
    length = 0
    has_odd = False

    for char_freq in count.values():
        if char_freq % 2 == 0:
            length += char_freq
        else:
            length += char_freq - 1
            has_odd = True

    # Add 1 if there is an odd frequency character
    if has_odd:
        length += 1

    return length

