def minimum_jumps_to_avoid_obstacles(n, m, obstacles):
    # Convert the obstacles list to a set for O(1) lookups
    obstacle_set = set(obstacles)

    # Initialize DP array with infinity
    dp = [float('inf')] * (n + 1)

    # Starting position (position 0) requires 0 jumps
    dp[0] = 0

    # Fill DP array
    for i in range(1, n + 1):
        # Skip if current position is an obstacle
        if i in obstacle_set:
            continue

        # Check positions from which we can reach current position
        for j in range(1, 4):
            if i - j >= 0 and dp[i - j] != float('inf'):
                dp[i] = min(dp[i], dp[i - j] + 1)

    # If the end (position n) is not reachable
    if dp[n] == float('inf'):
        return -1
    else:
        return dp[n]

