def addBoldTag(s, dict):
    # Step 1: Mark all indices in s that are part of a word in the dictionary
    bold = [False] * len(s)

    for word in dict:
        start = 0
        while True:
            start = s.find(word, start)
            if start == -1:
                break
            # Mark all characters in the word as bold
            for i in range(start, start + len(word)):
                bold[i] = True
            start += 1  # Move past the current match to find overlapping matches

    # Step 2: Build the result string with bold tags
    result = []
    i = 0
    while i < len(s):
        if bold[i]:
            # Start of bold section
            result.append('<b>')
            # Find the end of the bold section
            j = i
            while j < len(s) and bold[j]:
                j += 1
            result.append(s[i:j])
            result.append('</b>')
            i = j
        else:
            result.append(s[i])
            i += 1

    return ''.join(result)

