secure_solution:
def find_bench_position(n, k, radii):
    sorted_radii = sorted(radii)

    # If k == n: No point can avoid all fountains.
    if k == n:
        return -1

    # If k == 0: We need to find a point that is inside all fountains
    # Not possible since radii are distinct (the smallest one covers everything else)
    if k == 0:
        return -1

    # We place the bench at the edge of the circle defined by the (n - k)th smallest radius
    # This point is inside (n - k) smallest circles and outside the next k largest ones
    target_r = sorted_radii[n - k]

    return (target_r, 0)

