def knapsack(n, W, items):
    # Initialize a DP array where dp[w] represents the maximum value that can be achieved with weight w
    dp = [0] * (W + 1)

    for weight, value in items:
        # Traverse the dp array from back to front to avoid using the same item multiple times
        for w in range(W, weight - 1, -1):
            dp[w] = max(dp[w], dp[w - weight] + value)

    # The maximum value that can be carried within the weight limit W
    return dp[W]

