def longestZeroSumSubarray(arr):
    prefix_sum = 0
    sum_indices = {0: -1}  # To handle the case where subarray starts from index 0
    max_length = 0

    for i, num in enumerate(arr):
        prefix_sum += num

        if prefix_sum in sum_indices:
            # If this prefix sum was seen before, calculate the length of subarray
            max_length = max(max_length, i - sum_indices[prefix_sum])
        else:
            # Store the first occurrence of this prefix sum
            sum_indices[prefix_sum] = i

    return max_length

