def is_secure_id(id_number: str) -> bool:
    # Check that the ID has exactly 6 digits (though the problem states this is guaranteed)
    if len(id_number) != 6:
        return False

    # Iterate over adjacent pairs of digits
    for i in range(5):
        current_digit = int(id_number[i])
        next_digit = int(id_number[i + 1])

        # If the absolute difference is less than 2, the ID is not secure
        if abs(current_digit - next_digit) < 2:
            return False

    # All adjacent pairs differ by at least 2
    return True

