def find_pairs(nums, target):
    seen = set()
    result = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            # Ensure the pair is ordered with a <= b
            pair = tuple(sorted((num, complement)))
            result.add(pair)
        seen.add(num)

    # Convert the set to a sorted list of tuples
    return sorted(result)

