def can_get_exact_sugar(X, Z, A):
    # Create a set to store all possible sums
    possible_sums = set()
    possible_sums.add(0)  # Start with 0 (sum of no elements)

    for a in A:
        new_sums = set()
        for s in possible_sums:
            new_sum = s + a
            if new_sum <= Z:
                new_sums.add(new_sum)
        possible_sums.update(new_sums)

    return "YES" if Z in possible_sums else "NO"

