def longest_winning_streak(nums):
    if not nums:
        return 0

    max_streak = 0
    current_streak = 1  # At least one player, so minimum streak is 1 (if no increasing sequence)

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
