from collections import deque

def topologicalSort(edges, numNodes):
    # Step 1: Build the adjacency list and in-degree count
    graph = [[] for _ in range(numNodes)]
    in_degree = [0] * numNodes

    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    # Step 2: Initialize the queue with nodes having in-degree 0
    queue = deque()
    for i in range(numNodes):
        if in_degree[i] == 0:
            queue.append(i)

    # Step 3: Process the nodes
    result = []
    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Step 4: Check for cycles (if the result contains all nodes)
    if len(result) != numNodes:
        return []

    return result

