def canPartition(nums):
    total_sum = sum(nums)
    # If the total sum is odd, it's not possible to partition into two equal subsets
    if total_sum % 2 != 0:
        return False
    target = total_sum // 2

    # Using a set to keep track of all possible subset sums we can make
    possible_sums = {0}
    for num in nums:
        # We need to create a copy to avoid modifying the set while iterating
        current_sums = list(possible_sums)
        for s in current_sums:
            new_sum = s + num
            if new_sum == target:
                return True
            if new_sum < target:
                possible_sums.add(new_sum)
    return target in possible_sums

# Example usage
