def min_operations_to_one(n):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i):
        if i == 1:
            return 0
        res = 1 + dp(i - 1)  # Subtract 1
        if i % 2 == 0:
            res = min(res, 1 + dp(i // 2))  # Divide by 2
        if i % 3 == 0:
            res = min(res, 1 + dp(i // 3))  # Divide by 3
        return res

    return dp(n)

