def max_coins(mat):
    m, n = len(mat), len(mat[0])

    # Initialize DP table
    dp = [[0] * n for _ in range(m)]

    # Base case: starting from any cell in the first column
    for i in range(m):
        dp[i][0] = mat[i][0]

    # Fill DP table
    for j in range(1, n):
        for i in range(m):
            # Consider all possible previous positions to reach (i, j)
            max_prev = 0
            for di in [-1, 0, 1]:
                ni = i + di
                if 0 <= ni < m:
                    max_prev = max(max_prev, dp[ni][j - 1])
            dp[i][j] = max_prev + mat[i][j]

    # The answer is the maximum value in the last column
    return max(dp[i][n - 1] for i in range(m))

