import math

def is_power_of_any(num: int) -> bool:
    if num < 2:
        return False

    max_exponent = int(math.log(num, 2)) + 1  # Determine the upper bound for exponents

    for k in range(2, max_exponent + 1):  # Skip exponent 1 (since base > 1)
        # Calculate the base using the k-th root
        b = round(num ** (1.0 / k))

        # Check if b^k equals num
        if b ** k == num:
            return True

    return False

