def max_tasks_durations(tasks, hours):
    total_minutes = hours * 60
    tasks.sort()  # Sort the tasks by duration in ascending order
    count = 0
    total_time = 0

    for duration in tasks:
        if total_time + duration <= total_minutes:
            total_time += duration
            count += 1
        else:
            break

    return count

