from collections import Counter

def longest_palindrome(s):
    count = Counter(s)
    length = 0
    odd_found = False

    for freq in count.values():
        if freq % 2 == 0:
            length += freq
        else:
            length += freq - 1
            odd_found = True

    # If there is any character with an odd count, we can add 1 to the length for the center
    if odd_found:
        length += 1

    return length

