def count_firefly_pairs(n, target, durations):
    seen = {}
    count = 0
    for duration in durations:
        complement = target - duration
        # If the complement has been seen before, it means we have a valid pair
        if complement in seen:
            count += seen[complement]
        # Update the frequency of the current duration in the dictionary
        seen[duration] = seen.get(duration, 0) + 1
    return count

