def is_sequential(word):
    if len(word) == 1:
        return True  # A single character is trivially sequential

    for i in range(1, len(word)):
        prev_char = word[i - 1]
        current_char = word[i]

        # Calculate the difference between current and previous character
        diff = ord(current_char) - ord(prev_char)

        # If the difference is 1, it's a normal increment
        # If the difference is -25, it wraps around from 'z' to 'a'
        if diff != 1 and diff != -25:
            return False

    return True

