def is_feasible(W, H, circles):
    # Check if all circles fit within the canvas
    for x, y, r in circles:
        if x - r < 0 or x + r > W or y - r < 0 or y + r > H:
            return "Not Feasible"

    # Check for overlap between any two circles
    n = len(circles)
    for i in range(n):
        x1, y1, r1 = circles[i]
        for j in range(i + 1, n):
            x2, y2, r2 = circles[j]
            dx = x1 - x2
            dy = y1 - y2
            distance_sq = dx * dx + dy * dy
            min_distance_sq = (r1 + r2) ** 2
            if distance_sq < min_distance_sq:
                return "Not Feasible"

    return "Feasible"

