def findMinArrowShots(points):
    if not points:
        return 0

    # Sort the points based on their end coordinates
    points.sort(key=lambda x: x[1])

    arrows = 1
    last_end = points[0][1]

    for x_start, x_end in points[1:]:
        if x_start > last_end:
            arrows += 1
            last_end = x_end

    return arrows

