def max_consecutive_sum(numbers, k):
    if len(numbers) < k or k <= 0:
        return 0

    current_sum = sum(numbers[:k])
    max_sum = current_sum

    for i in range(k, len(numbers)):
        current_sum += numbers[i] - numbers[i - k]
        max_sum = max(max_sum, current_sum)

    return max_sum

