def longest_balanced_segment(n, A):
    prefix_sum = 0
    sum_indices = {0: -1}  # To handle the case where subarray starts from index 0
    max_length = -1

    for i in range(n):
        prefix_sum += A[i]

        if prefix_sum in sum_indices:
            # A subarray with sum 0 exists from index sum_indices[prefix_sum] + 1 to i
            max_length = max(max_length, i - sum_indices[prefix_sum])
        else:
            sum_indices[prefix_sum] = i

    return max_length if max_length != 0 else -1

