def max_eggs_value(n, egg_values):
    if n == 0:
        return 0
    if n == 1:
        return egg_values[0]

    # Initialize previous include and exclude values
    prev_include = egg_values[0]
    prev_exclude = 0

    for i in range(1, n):
        current_include = prev_exclude + egg_values[i]
        current_exclude = max(prev_include, prev_exclude)

        # Update previous values for next iteration
        prev_include, prev_exclude = current_include, current_exclude

    return max(prev_include, prev_exclude)

