def closest_pair(arr, x):
    n = len(arr)
    left = 0
    right = n - 1
    closest_sum = float('inf')
    result = []

    while left < right:
        current_sum = arr[left] + arr[right]

        # Update closest sum and result if current sum is closer to x
        if abs(current_sum - x) < abs(closest_sum - x):
            closest_sum = current_sum
            result = [arr[left], arr[right]]
        elif abs(current_sum - x) == abs(closest_sum - x):
            # If sums are equally close, choose the pair with the smallest first element
            if arr[left] < result[0] or (arr[left] == result[0] and arr[right] < result[1]):
                result = [arr[left], arr[right]]

        # Move the pointers
        if current_sum < x:
            left += 1
        else:
            right -= 1

    return result

from collections import deque

def min_moves(nums, start, end):
    if not nums or not nums[0]:
        return -1

    rows, cols = len(nums), len(nums[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    # Check if start or end is a wall
    if nums[start[0]][start[1]] == 1 or nums[end[0]][end[1]] == 1:
        return -1

    visited = [[False] * cols for _ in range(rows)]
    queue = deque()
    queue.append((start[0], start[1], 0))  # (row, col, moves)
    visited[start[0]][start[1]] = True

    while queue:
        r, c, moves = queue.popleft()

        if (r, c) == (end[0], end[1]):
            return moves

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and nums[nr][nc] == 0:
                visited[nr][nc] = True
                queue.append((nr, nc, moves + 1))

    return -1

