def max_tastiness(N, B, ingredients):
    # Create a DP array where dp[b] represents the maximum tastiness achievable with bitterness b
    dp = [-1] * (B + 1)
    dp[0] = 0  # Base case: zero bitterness yields zero tastiness

    for tastiness, bitterness in ingredients:
        # Traverse from high to low to avoid reusing the same item
        for b in range(B, bitterness - 1, -1):
            if dp[b - bitterness] != -1:
                dp[b] = max(dp[b], dp[b - bitterness] + tastiness)

    # The maximum tastiness is the highest value in the dp array
    return max(dp)

