def optimal_discount(cart, bulk_threshold, bulk_discount, percent_discount):
    # Calculate total price before any discount
    total_price = sum(item[1] * item[2] for item in cart)

    # Apply percentage discount to each item individually
    percent_discounted_total = 0
    for item in cart:
        name, price, quantity = item
        discounted_price = price * (1 - percent_discount / 100)
        percent_discounted_total += discounted_price * quantity

    # Apply bulk discount if applicable
    if total_price >= bulk_threshold:
        bulk_discounted_total = total_price - bulk_discount
    else:
        bulk_discounted_total = total_price

    # Choose the minimum of the two discount strategies
    return min(percent_discounted_total, bulk_discounted_total)

