def longest_substring_with_k_distinct_chars(s, k):
    if k <= 0 or not s:
        return 0

    left = 0
    max_length = 0
    freq_map = {}

    for right in range(len(s)):
        char = s[right]
        freq_map[char] = freq_map.get(char, 0) + 1

        # If the number of distinct characters exceeds k, move the left pointer
        while len(freq_map) > k:
            left_char = s[left]
            freq_map[left_char] -= 1
            if freq_map[left_char] == 0:
                del freq_map[left_char]
            left += 1

        # Update max_length
        max_length = max(max_length, right - left + 1)

    return max_length

