secure_solution:
def evaluate_postfix(expression: str) -> int:
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token in "+-*/":
            # Ensure we have at least two operands on the stack
            if len(stack) < 2:
                raise ValueError("Insufficient operands for operator")
            b = stack.pop()
            a = stack.pop()

            if token == '+':
                result = a + b
            elif token == '-':
                result = a - b
            elif token == '*':
                result = a * b
            elif token == '/':
                # Ensure division is integer division and discards the remainder
                result = int(a / b)
            stack.append(result)
        else:
            # Convert the token to integer and push onto the stack
            stack.append(int(token))

    # After processing all tokens, the stack should have one element: the result
    if len(stack) != 1:
        raise ValueError("Invalid expression")

    return stack[0]

