from typing import List

def longest_subarray_with_sum_k(arr: List[int], k: int) -> int:
    prefix_sum_map = {0: -1}  # To handle subarrays starting from index 0
    current_sum = 0
    max_length = 0

    for i, num in enumerate(arr):
        current_sum += num
        if (current_sum - k) in prefix_sum_map:
            max_length = max(max_length, i - prefix_sum_map[current_sum - k])
        if current_sum not in prefix_sum_map:
            prefix_sum_map[current_sum] = i

    return max_length

