def fibonacci_sum(a, b):
    # Initialize the first two Fibonacci numbers
    fib = [1, 1]

    # Generate Fibonacci numbers up to the b-th term
    for i in range(2, b):
        fib.append(fib[-1] + fib[-2])

    # Sum the Fibonacci numbers from the a-th to the b-th term (inclusive)
    # Note: Since list is 0-indexed, a-th term is at index a-1 and b-th term is at index b-1
    return sum(fib[a-1:b])

