def can_partition(nums):
    total_sum = sum(nums)

    # If total sum is odd, cannot be partitioned into two equal subsets
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: zero sum is always possible

    for num in nums:
        for i in range(target, num - 1, -1):
            if dp[i - num]:
                dp[i] = True

    return dp[target]

