from typing import List

def detect_anomaly(sequence: List[int]) -> int:
    if len(sequence) < 3:
        return -1  # Though the constraints say it will be at least 3, this is a fallback

    # Determine the common difference of the arithmetic progression
    # from the first 3 elements
    diff = sequence[2] - sequence[1]
    if sequence[1] - sequence[0] != diff:
        return 2  # First anomaly at index 2

    # Check the rest of the sequence
    for i in range(3, len(sequence)):
        expected = sequence[i - 1] + diff
        if sequence[i] != expected:
            return i

    return -1  # No anomalies found

