def longest_palindromic_subsequence(s: str) -> int:
    if not s:
        return 0

    n = len(s)
    s = s.lower()  # Make the string case-insensitive

    # Create a 2D DP table initialized with 0s
    dp = [[0] * n for _ in range(n)]

    # All substrings of length 1 are palindromes of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the DP table for substrings of length >= 2
    for length in range(2, n + 1):  # Length of the substring
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = 2 + dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]

