secure_solution:
def max_sum_after_removal(arr):
    n = len(arr)
    # Arrays to store the index of previous smaller and next smaller elements
    prev_smaller = [-1] * n
    next_smaller = [n] * n

    # Stack to find previous smaller elements
    stack = []
    for i in range(n):
        while stack and arr[stack[-1]] >= arr[i]:
            stack.pop()
        if stack:
            prev_smaller[i] = stack[-1]
        else:
            prev_smaller[i] = -1
        stack.append(i)

    # Stack to find next smaller elements
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and arr[stack[-1]] >= arr[i]:
            stack.pop()
        if stack:
            next_smaller[i] = stack[-1]
        else:
            next_smaller[i] = n
        stack.append(i)

    max_sum = 0
    for i in range(n):
        left_sum = sum(arr[prev_smaller[i] + 1:i])
        right_sum = sum(arr[i + 1:next_smaller[i]])
        total = left_sum + right_sum
        max_sum = max(max_sum, total)

    return max_sum

def nCr(n: int, r: int) -> int:
    if r > n or r < 0:
        return 0  # Invalid input
    if r == 0 or r == n:
        return 1

    # Use a 1D DP array to save memory
    dp = [0] * (r + 1)
    dp[0] = 1  # Base case: C(n, 0) = 1

    for i in range(1, n + 1):
        # Update from the end to ensure we use the previous values
        for j in range(min(i, r), 0, -1):
            dp[j] = dp[j] + dp[j - 1]

    return dp[r]

