def longest_palindrome(s):
    from collections import Counter

    char_counts = Counter(s)
    length = 0
    odd_found = False

    for count in char_counts.values():
        if count % 2 == 0:
            length += count
        else:
            length += count - 1
            odd_found = True

    # If there is any character with an odd count, we can add 1 to the length for the center
    if odd_found:
        length += 1

    return length

