import heapq

def minCostPath(grid):
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    # Priority queue: (cost, row, col)
    heap = [(grid[0][0], 0, 0)]
    # Visited matrix to keep track of minimum cost to reach each cell
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    visited[0][0] = True

    while heap:
        cost, row, col = heapq.heappop(heap)

        # Reached the bottom-right corner
        if row == rows - 1 and col == cols - 1:
            return cost

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols and not visited[new_row][new_col]:
                visited[new_row][new_col] = True
                heapq.heappush(heap, (cost + grid[new_row][new_col], new_row, new_col))

    return -1  # If no path found (should not happen with given constraints)

from typing import List
from collections import deque

def can_reach_all_empty_cells(grid: List[str]) -> str:
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # Find the starting position 'P'
    start = None
    total_empty = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'P':
                start = (i, j)
            elif grid[i][j] == '.':
                total_empty += 1

    if start is None:
        return "No"  # This should not happen based on the problem constraints

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    visited = [[False for _ in range(m)] for _ in range(n)]
    queue = deque()
    queue.append((start[0], start[1]))
    visited[start[0]][start[1]] = True
    reachable_empty = 0

    while queue:
        x, y = queue.popleft()
        if grid[x][y] == '.':
            reachable_empty += 1

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                if grid[nx][ny] != '#':
                    visited[nx][ny] = True
                    queue.append((nx, ny))

    # The player's starting point is not counted as an empty cell
    return "Yes" if reachable_empty == total_empty else "No"

