def can_form_arithmetic_progression(arr, K):
    if K == 1:
        return "YES"  # Any single element is trivially an arithmetic progression

    # Sort the array to make it easier to check for arithmetic progression
    arr.sort()

    # Try each possible starting pair (i, j) to see if we can form a K-length AP
    for i in range(len(arr) - K + 1):
        for j in range(i + 1, len(arr)):
            # Calculate the common difference
            d = arr[j] - arr[i]
            # Check if the next K-2 elements exist with this difference
            valid = True
            current = arr[j]
            count = 2  # Already have 2 elements (arr[i], arr[j])
            while count < K:
                current += d
                if current in arr:
                    count += 1
                else:
                    valid = False
                    break
            if valid:
                return "YES"

    return "NO"

