def min_coins(s, m):
    # Parse the string into a list of integers
    coins = list(map(int, s.split(',')))

    # Edge case: if the target amount is 0
    if m == 0:
        return 0

    # Initialize dp array
    dp = [float('inf')] * (m + 1)
    dp[0] = 0

    # Update dp array
    for amount in range(1, m + 1):
        for coin in coins:
            if coin <= amount:
                dp[amount] = min(dp[amount], dp[amount - coin] + 1)

    return dp[m] if dp[m] != float('inf') else -1

