def can_modules_be_reviewed(n, m, capacities, complexities):
    # Sort capacities in descending order (largest capacity first)
    capacities.sort(reverse=True)
    # Sort complexities in descending order (most complex first)
    complexities.sort(reverse=True)

    # Try to assign modules to engineers
    for complexity in complexities:
