from typing import List, Tuple

def find_pairs_with_sum(arr: List[int], k: int) -> List[Tuple[int, int]]:
    seen = set()
    result = set()

    for num in arr:
        complement = k - num
        if complement in seen:
            # Ensure a <= b
            pair = (min(num, complement), max(num, complement))
            result.add(pair)
        seen.add(num)

    return sorted(result)

