def trap_water(columns):
    if not columns or len(columns) < 3:
        return 0

    left, right = 0, len(columns) - 1
    left_max = right_max = 0
    trapped_water = 0

    while left < right:
        if columns[left] <= columns[right]:
            if columns[left] >= left_max:
                left_max = columns[left]
            else:
                trapped_water += left_max - columns[left]
            left += 1
        else:
            if columns[right] >= right_max:
                right_max = columns[right]
            else:
                trapped_water += right_max - columns[right]
            right -= 1

    return trapped_water

