MOD = 10**9 + 7

def find_paths(grid: List[List[int]]) -> int:
    n, m = len(grid), len(grid[0])
    dp = [[0] * m for _ in range(n)]

    # Initialize the top-left cell
    if grid[0][0] == 0:
        dp[0][0] = 1
    else:
        return 0  # As per the problem statement, this won't happen

    # Fill first row
    for j in range(1, m):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j - 1]
        else:
            dp[0][j] = 0

    # Fill first column
    for i in range(1, n):
        if grid[i][0] == 0:
            dp[i][0] = dp[i - 1][0]
        else:
            dp[i][0] = 0

