def enhanced_selection_sort(arr: list[int], simulation: bool = False) -> list[int]:
    n = len(arr)
    for i in range(n):
        # Check if the array is already sorted (early termination)
        is_sorted = True
        for j in range(i + 1, n):
            if arr[j] < arr[j - 1]:
                is_sorted = False
                break
        if is_sorted:
            if simulation:
                print(f"iteration {i} : {' '.join(map(str, arr))} (breaks early as the array is already sorted)")
            break

        # Find the minimum element in the remaining unsorted part
        min_index = i
        for j in range(i + 1, n):
            if arr[j] < arr[min_index]:
                min_index = j

        # Perform the swap only if needed
        if min_index != i:
            arr[i], arr[min_index] = arr[min_index], arr[i]
            if simulation:
                print(f"iteration {i} : {' '.join(map(str, arr))}")
        else:
            if simulation:
                print(f"iteration {i} : {' '.join(map(str, arr))} (no swap needed)")

    return arr

