def min_swaps_to_sort_books(n, thicknesses):
    # Create a copy of the list
    arr = thicknesses[:]
    swaps = 0

    # Perform Bubble Sort and count swaps
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                # Swap adjacent elements
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swaps += 1

    return swaps

