def daily_temperatures(n, temperatures):
    result = [0] * n
    stack = []

    for i in range(n - 1, -1, -1):
        # Pop from the stack while the top of the stack is less than or equal to current temperature
        while stack and temperatures[stack[-1]] <= temperatures[i]:
            stack.pop()
        # If stack is not empty, the top of the stack is the index of the next warmer day
        if stack:
            result[i] = stack[-1] - i
        else:
            result[i] = 0
        # Push current index to the stack
        stack.append(i)

    return result

def max_points_in_game(n, m, points):
    max_score = -1
    game_index = -1

    for game in range(m):
        current_max = max(points[i][game] for i in range(n))
        if current_max > max_score or (current_max == max_score and (game + 1) < game_index):
            max_score = current_max
            game_index = game + 1  # Convert to 1-based index

    return max_score, game_index

def max_height(n, W, books):
    # Initialize DP array with zeros
    dp = [0] * (W + 1)

    for width, height in books:
        # Traverse the DP array in reverse to avoid using the same book multiple times
