from typing import List

def longest_increasing_subsequence(sales: List[int]) -> List[int]:
    if not sales:
        return []

    max_len = 1
    current_len = 1
    start_idx = 0
    best_start = 0

    for i in range(1, len(sales)):
        if sales[i] > sales[i - 1]:
            current_len += 1
        else:
            if current_len > max_len:
                max_len = current_len
                best_start = start_idx
            current_len = 1
            start_idx = i

    # Check if the last sequence is the longest
    if current_len > max_len:
        max_len = current_len
        best_start = start_idx

    return sales[best_start:best_start + max_len]

