from typing import List

def can_return_books(borrowed: List[str], permissible: List[str]) -> bool:
    # We are checking if permissible is a valid "return order"
    # So, we match from the end of both lists
    i, j = len(borrowed) - 1, len(permissible) - 1

    while i >= 0 and j >= 0:
        if borrowed[i] == permissible[j]:
            j -= 1
        i -= 1

    return j == -1

