def longest_bitonic_subsequence(arr):
    n = len(arr)

    # Step 1: Compute LIS from left to right
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if arr[i] > arr[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Step 2: Compute LDS from right to left
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Step 3: Find the maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        max_bitonic = max(max_bitonic, lis[i] + lds[i] - 1)

    return max_bitonic

