def subset_sum(item_values: list, target_value: int) -> bool:
    # Edge cases
    if target_value == 0:
        return True
    if not item_values:
        return False

    # Initialize a boolean DP array of size target_value + 1
    dp = [False] * (target_value + 1)
    dp[0] = True  # A subset with sum 0 is always possible (empty subset)

    # Iterate through each item
    for value in item_values:
        # Update the dp array from target_value down to value to avoid using the same item multiple times
        for i in range(target_value, value - 1, -1):
            if dp[i - value]:
                dp[i] = True

    return dp[target_value]

