def robot_final_position(movements: str) -> tuple:
    """
    Calculate the final position of the robot on a 2D plane after a series of movements.

    Args:
        movements (str): A string representing a sequence of movements.

    Returns:
        tuple: Final position of the robot as (x, y).
    """
    # Initialize starting position at the origin
    x, y = 0, 0

    # Iterate over each movement in the input string
    for move in movements:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
        else:
            raise ValueError("Invalid movement character in the input string.")

    return (x, y)

