def int_to_roman(num: int) -> str:
    if not (1 <= num <= 3999):
        raise ValueError("int_to_roman() requires a positive integer between 1 and 3999")

    # Mapping of integer values to Roman numerals
    val_to_roman = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    roman = ''
    for value, symbol in val_to_roman:
        while num >= value:
            roman += symbol
            num -= value

    return roman

