secure_solution:
def caesar_cipher_optimized(s: str, k: int) -> str:
    result = []
    k = k % 26  # Reduce k to the range [0, 25] since shifting by 26 is a full cycle

    for char in s:
        if 'a' <= char <= 'z':
            # Shift lowercase letters
            shifted = chr((ord(char) - ord('a') + k) % 26 + ord('a'))
            result.append(shifted)
        elif 'A' <= char <= 'Z':
            # Shift uppercase letters
            shifted = chr((ord(char) - ord('A') + k) % 26 + ord('A'))
            result.append(shifted)
        else:
            # Non-alphabetic characters remain unchanged
            result.append(char)

    return ''.join(result)

