def longest_substring_distinct(s: str) -> str:
    if not s:
        return ""

    char_set = set()
    start = 0
    max_length = 0
    max_start = 0

    for end in range(len(s)):
        while s[end] in char_set:
            char_set.remove(s[start])
            start += 1

        char_set.add(s[end])

        if end - start + 1 > max_length:
            max_length = end - start + 1
            max_start = start

    return s[max_start:max_start + max_length]

