def modify_array(nums):
    n = len(nums)
    modified_nums = [-1] * n
    stack = []  # stores tuples of (value, index)

    for i in range(n - 1, -1, -1):
        # Pop elements from stack which are <= current element
        while stack and stack[-1][0] <= nums[i]:
            stack.pop()

        # If stack is not empty, the next greater element is at the top
        if stack:
            modified_nums[i] = stack[-1][0]
        else:
            modified_nums[i] = -1

        # Push current element to stack
        stack.append((nums[i], i))

    return modified_nums

