def count_ways_to_make_amount(amount, coins):
    # Initialize a dp array where dp[i] is the number of ways to make amount i
    dp = [0] * (amount + 1)
    dp[0] = 1  # There's 1 way to make amount 0: use no coins

    # Iterate through each coin
    for coin in coins:
        # Update dp array for all amounts from coin to amount
        for i in range(coin, amount + 1):
            dp[i] += dp[i - coin]

    return dp[amount]

