def apply_operations(grid, row_operations, column_operations):
    # Create a copy of the grid to avoid modifying the original
    m = len(grid)
    n = len(grid[0]) if m > 0 else 0

    # Initialize the result matrix with the same values as grid
    result = [row[:] for row in grid]

    # Apply row operations
    for row_idx, increment in row_operations:
        if 0 <= row_idx < m:
            for col in range(n):
                result[row_idx][col] += increment

    # Apply column operations
    for col_idx, increment in column_operations:
        if 0 <= col_idx < n:
            for row in range(m):
                result[row][col_idx] += increment

    # Calculate the sum of all elements in the result matrix
    return sum(sum(row) for row in result)

