def max_packages(W, N, weights):
    # Sort the weights in ascending order
    weights.sort()

    count = 0
    total_weight = 0

    for weight in weights:
        if total_weight + weight <= W:
            total_weight += weight
            count += 1
        else:
            break  # Cannot add more packages without exceeding the limit

    return count

