secure_solution:
def decompress_string(s: str) -> str:
    result = ""
    i = 0
    while i < len(s):
        # Check if current character is a letter
        if s[i].isalpha():
            letter = s[i]
            # Check if next character is a digit
            if i + 1 < len(s) and s[i + 1].isdigit():
                repeat = int(s[i + 1])
                i += 2  # Skip the letter and the digit
            else:
                repeat = 1
                i += 1  # Just skip the letter
            result += letter * repeat
        else:
            # According to constraints, this case shouldn't occur
            i += 1
    return result

