def max_value_of_books(n, T, thicknesses, values):
    # Initialize a DP array where dp[i] represents the maximum value with thickness i
    dp = [0] * (T + 1)

    for i in range(n):
        t = thicknesses[i]
        v = values[i]
        # Traverse from T down to t to avoid using the same book multiple times
        for j in range(T, t - 1, -1):
            dp[j] = max(dp[j], dp[j - t] + v)

    return max(dp)

