secure_solution:
def min_containers(total_food, containers):
    # Sort containers in descending order
    containers.sort(reverse=True)
    count = 0
    remaining_food = total_food

    for container in containers:
        if remaining_food <= 0:
            break
        if container <= remaining_food:
            remaining_food -= container
            count += 1

    return count if remaining_food == 0 else -1

