secure_solution:
def is_wildcard_balanced(s: str) -> bool:
    # First pass: Treat '*' as '(' and check for potential imbalance
    left = 0
    for char in s:
        if char == '(':
            left += 1
        elif char == ')':
            left -= 1
        elif char == '*':
            left += 1  # Treat '*' as '('
        # If at any point, we have more closing than opening
        if left < 0:
            return False
    # Second pass: Treat '*' as ')' and check for potential imbalance
    right = 0
    for char in reversed(s):
        if char == ')':
            right += 1
        elif char == '(':
            right -= 1
        elif char == '*':
            right += 1  # Treat '*' as ')'
        # If at any point, we have more opening than closing
        if right < 0:
            return False
    return True

