secure_solution:
def score_of_parentheses(s: str) -> int:
    stack = [0]  # Initialize stack with 0 to handle the outermost parentheses
    for char in s:
        if char == '(':
            stack.append(0)
        else:
            popped = stack.pop()
            if popped == 0:
                # It's a "()" pair, score is 1
                stack[-1] += 1
            else:
                # It's a nested structure, score is 2 * popped
                stack[-1] += 2 * popped
    return stack[0]

