def count_subsets_with_target_sum(N, factors, T):
    MOD = 10**9 + 7

    # Initialize a dp array with size T + 1
    dp = [0] * (T + 1)
    dp[0] = 1  # One subset (empty subset) sums to 0

    for factor in factors:
        for j in range(T, factor - 1, -1):
            dp[j] = (dp[j] + dp[j - factor]) % MOD

    return dp[T]

