def max_trade_value(n, B, items):
    # Initialize a DP array of size B+1 with all values set to 0
    dp = [0] * (B + 1)

    # Iterate over each item
    for s, v in items:
        # Iterate backwards to prevent reusing the same item
        for b in range(B, v - 1, -1):
            dp[b] = max(dp[b], dp[b - v] + v)

    # The maximum possible value within the budget is in dp[B]
    return dp[B]

