def find_triplet(n, arr, x):
    # Check if the array has at least 3 elements
    if n < 3:
        return False

    # Sort the array
    arr.sort()

    # Iterate through each element as the first element of the triplet
    for i in range(n - 2):
        left = i + 1
        right = n - 1

        # Use two pointers to find the other two elements
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]

            if current_sum == x:
                return True
            elif current_sum < x:
                left += 1
            else:
                right -= 1

    return False

