    # Binary search to find the position where the target would be inserted
    while left <= right:
        mid = (left + right) // 2
        if array[mid] == target:
            return target  # Target found
        elif array[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    # At this point, left is the index where the target would be inserted
    # So, the closest element is either at left - 1 or left
