    if left == 0:
        return array[0]
    elif left == len(array):
        return array[-1]
    else:
        # Check the closest between array[left - 1] and array[left]
        if (array[left] - target) <= (target - array[left - 1]):
            return array[left]
        else:
            return array[left - 1]

