def efficient_combination(n: int, r: int) -> int:
    # Edge cases
    if r == 0 or r == n:
        return 1

    # Create a 2D DP table with (n+1) rows and (r+1) columns
    dp = [[0] * (r + 1) for _ in range(n + 1)]

    # Base case: C(n, 0) = 1 for all n
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, min(i, r) + 1):
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]

    return dp[n][r]

