def can_split_into_k_subarrays(arr, k):
    total_sum = sum(arr)
    if total_sum % k != 0:
        return False

    target = total_sum // k
    current_sum = 0
    count = 0

    for num in arr:
        current_sum += num
        if current_sum == target:
            count += 1
            current_sum = 0
            if count == k:
                return True

    return False

