def minimize_candies(n, ratings):
    if n == 0:
        return 0

    # Initialize an array of 1s since each child gets at least one candy
    candies = [1] * n

    # Left to right pass
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            candies[i] = candies[i - 1] + 1

    # Right to left pass
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            candies[i] = max(candies[i], candies[i + 1] + 1)

    # Sum up all the candies
    return sum(candies)

