def two_sum_pairs(nums, target):
    seen = set()
    result = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            # Ensure the pair is stored in sorted order to avoid duplicates
            result.add(tuple(sorted((num, complement))))
        seen.add(num)

    return [list(pair) for pair in result]

