def can_be_sorted_by_reversing(nums):
    # Identify the indices where the array is not in non-decreasing order
    n = len(nums)
    left = 0
    while left < n - 1 and nums[left] <= nums[left + 1]:
        left += 1

    # If the array is already sorted, return True
    if left == n - 1:
        return True

    # Find the rightmost index where the array is not in order
    right = n - 1
    while right > 0 and nums[right] >= nums[right - 1]:
        right -= 1

    # Reverse the subarray from left to right
    nums[left:right+1] = nums[left:right+1][::-1]

    # Check if the array is now sorted
    for i in range(n - 1):
        if nums[i] > nums[i + 1]:
            return False

    return True

