    # Initialize a 2D list to store the number of paths to each cell
    dp = [[0] * n for _ in range(n)]

    # If the starting cell is an obstacle, no path is possible
    if grid[0][0] == 'O':
        return 0

    # Base case: starting cell
    dp[0][0] = 1

    # Fill the first row
    for j in range(1, n):
        if grid[0][j] == 'E':
            dp[0][j] = dp[0][j - 1]
        else:
            dp[0][j] = 0  # Obstacle, no path can go through this

    # Fill the first column
