        if grid[i][0] == 'E':
            dp[i][0] = dp[i - 1][0]
        else:
            dp[i][0] = 0  # Obstacle, no path can go through this

    # Fill the rest of the dp table
    for i in range(1, n):
        for j in range(1, n):
            if grid[i][j] == 'E':
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
            else:
                dp[i][j] = 0  # Obstacle, no path can go through this

