def min_diff_fruit_pairs(n, t, powers):
    powers.sort()
    min_diff = float('inf')
    left = 0
    right = n - 1

    while left < right:
        current_sum = powers[left] + powers[right]
        diff = abs(current_sum - t)
        if diff < min_diff:
            min_diff = diff
        if current_sum < t:
            left += 1
        else:
            right -= 1

    return min_diff

