def enhanced_selection_sort(arr: List[int], simulation: bool = False) -> List[int]:
    n = len(arr)

    # Handle edge cases: empty array or one element
    if n <= 1:
        if simulation:
            print(f"iteration 0: {arr}")
        return arr

    # Flag to detect if the array is already sorted
    already_sorted = False

    for i in range(n):
        # Assume the minimum is at the current position
        min_index = i

        # Find the minimum element in the remaining unsorted array
        for j in range(i + 1, n):
            if arr[j] < arr[min_index]:
                min_index = j

        # If the minimum element is not at the current position, perform the swap
        if min_index != i:
            arr[i], arr[min_index] = arr[min_index], arr[i]
            already_sorted = False
        else:
            already_sorted = True

        # Print the array if simulation is enabled
        if simulation:
            print(f"iteration {i}: {arr}")

        # If the array is already sorted, break to optimize
        if already_sorted:
            break

    return arr

