def integer_decompositions(n: int) -> int:
    # dp[i][j]: number of ways to partition i using integers up to j
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Initialize base case: only 1 way to partition 0 (empty set)
    for j in range(n + 1):
        dp[0][j] = 1

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if j > i:
                dp[i][j] = dp[i][i]
            elif j == 1:
                dp[i][j] = 1
            else:
                dp[i][j] = dp[i][j - 1] + dp[i - j][j]

