def max_subgrid_sum(n: int, grid: List[List[int]], k: int) -> int:
    # Create a prefix sum matrix of size (n+1) x (n+1)
    prefix = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill the prefix sum matrix
    for i in range(n):
        for j in range(n):
            prefix[i+1][j+1] = grid[i][j] + prefix[i][j+1] + prefix[i+1][j] - prefix[i][j]

    max_sum = float('-inf')

    # Iterate over all possible top-left corners of k x k subgrids
    for i in range(n - k + 1):
        for j in range(n - k + 1):
            # Calculate the sum using the prefix sum matrix
            subgrid_sum = prefix[i+k][j+k] - prefix[i][j+k] - prefix[i+k][j] + prefix[i][j]
            if subgrid_sum > max_sum:
                max_sum = subgrid_sum

    return max_sum

