def num_decodings(s):
    if not s:
        return 0
    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1  # base case: empty string has one way to decode
    dp[1] = 1 if s[0] != '0' else 0  # first character can't be '0'

    for i in range(2, n + 1):
        # Check if the current single digit is valid (non-zero)
        if s[i - 1] != '0':
            dp[i] += dp[i - 1]
        # Check if the previous two digits form a valid number between 10 and 26
        if 10 <= int(s[i - 2:i]) <= 26:
            dp[i] += dp[i - 2]

    return dp[n]

