def fibonacci_memo(n, memo={}):
    # Base cases
    if n == 0:
        return 0
    elif n == 1:
        return 1

    # Check if we've already computed this value
    if n in memo:
        return memo[n]

    # Compute the Fibonacci number iteratively to avoid recursion depth issues
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b

    # Store the result in memo before returning
    memo[n] = b
    return b

