def max_product(arr: list) -> int:
    if len(arr) < 2:
        raise ValueError("The input array must contain at least two elements")

    # Initialize the two largest and two smallest numbers
    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')

    for num in arr:
        # Update the two largest numbers
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update the two smallest numbers
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # The maximum product is the max of the two candidates
    return max(max1 * max2, min1 * min2)

