def count_binary_strings(n):
    if n == 1:
        return 2
    dp0, dp1 = 1, 1  # dp[1][0], dp[1][1]
    for _ in range(2, n + 1):
        new_dp0 = dp0 + dp1
        new_dp1 = dp0
        dp0, dp1 = new_dp0, new_dp1
    return dp0 + dp1

def maximum_score_path(n, m, grid):
    # We'll modify the grid in place to use it as our DP table
    for i in range(1, n):
        for j in range(m):
            # From (i-1, j-1), (i-1, j), (i-1, j+1), if they are valid indices
            max_prev = 0
            for dj in [-1, 0, 1]:
                prev_j = j + dj
                if 0 <= prev_j < m:
                    max_prev = max(max_prev, grid[i - 1][prev_j])
            grid[i][j] += max_prev

    # The last row contains the maximum score sum for each column
    return max(grid[-1])

