def longest_repeated_subsequence(s):
    n = len(s)
    # Create a 2D DP array with (n+1) x (n+1) dimensions
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            # If characters at positions i-1 and j-1 match and i != j
            if s[i - 1] == s[j - 1] and i != j:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                # Take the maximum of the previous values
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n][n]

