def plant_flowers(n, m, k):
    occupied = [False] * (n + 1)  # Using 1-based indexing
    result = []

    for i in range(m):
        ki = k[i]
        found = False
        start = 1

        while start <= n - ki + 1:
            # Check if the block [start, start+ki-1] is completely unoccupied
            is_free = True
            for j in range(start, start + ki):
                if occupied[j]:
                    is_free = False
                    break
            if is_free:
                # Mark the block as occupied
                for j in range(start, start + ki):
                    occupied[j] = True
                result.append(start)
                found = True
                break
            else:
                start += 1  # Move to the right and try again

        if not found:
            print(-1)
            return -1

    print(' '.join(map(str, result)))
    return result

