def largest_open_square(grid):
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # Initialize dp table with the same size as grid
    dp = [[0 for _ in range(m)] for _ in range(n)]
    max_square_size = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_square_size = max(max_square_size, dp[i][j])
            else:
                dp[i][j] = 0

    return max_square_size

