def min_magic_energy(n, positions):
    import sys
    sys.setrecursionlimit(10000)

    # Precompute distance matrix
    dist = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            dist[i][j] = abs(positions[i] - positions[j])

    # Initialize DP table (dp[mask][i] = min energy to reach i with mask)
    dp = [[float('inf')] * n for _ in range(1 << n)]
    for i in range(n):
        dp[1 << i][i] = 0  # Starting at i with only that orb visited

    # Fill DP table
    for mask in range(1 << n):
        for u in range(n):
            if not (mask & (1 << u)):
                continue  # u is not in the current mask, skip
            for v in range(n):
                if mask & (1 << v):
                    continue  # v is already in the mask
                new_mask = mask | (1 << v)
                dp[new_mask][v] = min(dp[new_mask][v], dp[mask][u] + dist[u][v])

    # All orbs visited (full_mask)
    full_mask = (1 << n) - 1
    return min(dp[full_mask][i] for i in range(n))

# Example usage:
# n = 4
# positions = [1, 4, 7, 10]
# print(min_magic_energy(n, positions))  # Output: 9

