from typing import List

def optimized_bubble_sort(arr: List[int], simulate: bool = False) -> List[int]:
    n = len(arr)
    for i in range(n):
        # Flag to check if any swap was done in this pass
        swapped = False

        # Last i elements are already in place
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                # Swap the elements
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True

        # If no swaps were done in this pass, the array is sorted
        if not swapped:
            break

        # Print the array after this pass if simulation is enabled
        if simulate:
            print(f"iteration {i + 1}: {arr}")

    return arr

def closest_playlist(durations, target):
    # Create a DP array where dp[i] represents the maximum sum we can get <= i
    dp = [0] * (target + 1)

    # For each duration, update the dp array
    for duration in durations:
        for i in range(target, duration - 1, -1):
            if dp[i - duration] + duration > dp[i]:
                dp[i] = dp[i - duration] + duration

    # Find the maximum total duration <= target
    max_duration = dp[target]

    # If no duration selected (i.e., max_duration is 0), return empty list
    if max_duration == 0:
        return []

    # Reconstruct the playlist
    playlist = []
    remaining = target
    for duration in reversed(durations):
        if remaining >= duration and dp[remaining] == dp[remaining - duration] + duration:
            playlist.append(duration)
            remaining -= duration

    return playlist

