def longest_subarray_divisible_by_k(t, test_cases):
    results = []

    for case in test_cases:
        N, K, arr = case
        prefix_mod = {0: -1}  # Map: remainder -> index
        max_len = 0
        current_sum = 0

        for i in range(N):
            current_sum += arr[i]
            mod = current_sum % K

            # If this remainder has been seen before
            if mod in prefix_mod:
                length = i - prefix_mod[mod]
                if length > max_len:
                    max_len = length
            else:
                # Store the first occurrence of this remainder
                prefix_mod[mod] = i

        results.append(max_len)

    return results

def count_perfect_squares(start, end):
    # Find the smallest integer whose square is >= start
    lower = int(start ** 0.5)
    if lower * lower < start:
        lower += 1

    # Find the largest integer whose square is <= end
    upper = int(end ** 0.5)

    # Count the number of perfect squares between lower and upper (inclusive)
    return max(0, upper - lower + 1)

