def smallest_string_after_removal(s: str, n: int) -> str:
    stack = []
    for char in s:
        while n > 0 and stack and stack[-1] > char:
            stack.pop()
            n -= 1
        stack.append(char)

    # If any removals are left, remove from the end
    if n > 0:
        stack = stack[:-n]

    return ''.join(stack)

