from typing import List

def shortestPath(matrix: List[List[int]]) -> int:
    if not matrix or matrix[0][0] == 1 or matrix[-1][-1] == 1:
        return -1

    m, n = len(matrix), len(matrix[0])
    visited = [[[False] * 2 for _ in range(n)] for _ in range(m)]
    queue = deque()
    queue.append((0, 0, 0, 0))  # (row, col, walls_broken, distance)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, walls_broken, dist = queue.popleft()

        if r == m - 1 and c == n - 1:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n:
                if matrix[nr][nc] == 0 and not visited[nr][nc][walls_broken]:
                    visited[nr][nc][walls_broken] = True
                    queue.append((nr, nc, walls_broken, dist + 1))
                elif matrix[nr][nc] == 1 and walls_broken == 0 and not visited[nr][nc][1]:
                    visited[nr][nc][1] = True
                    queue.append((nr, nc, 1, dist + 1))

    return -1

