def match_pattern(pattern: str, s: str) -> bool:
    words = s.split()

    # Check if the number of words matches the number of characters in the pattern
    if len(pattern) != len(words):
        return False

    # Dictionaries to map pattern to word and word to pattern
    pattern_to_word = {}
    word_to_pattern = {}

    for char, word in zip(pattern, words):
        # Check if the pattern character already maps to a different word
        if char in pattern_to_word:
            if pattern_to_word[char] != word:
                return False
        else:
            # Check if the word is already mapped to a different pattern character
            if word in word_to_pattern:
                return False
            pattern_to_word[char] = word
            word_to_pattern[word] = char

    return True

