def min_storage_units(n, weights, capacity):
    # Sort the weights in descending order
    weights.sort(reverse=True)

    # Initialize the list of storage units' remaining capacities
    storage_remaining = []

    for weight in weights:
        placed = False
        # Try to place the current product in an existing storage unit
        for i in range(len(storage_remaining)):
            if storage_remaining[i] >= weight:
                storage_remaining[i] -= weight
                placed = True
                break
        # If not placed, create a new storage unit
        if not placed:
            storage_remaining.append(capacity - weight)

    return len(storage_remaining)

