def num_paths(n, m, grid):
    # Initialize a 2D dp array with zeros
    dp = [[0] * m for _ in range(n)]

    # Starting point
    if grid[0][0] == '#':
        return 0  # Starting cell is a wall
    dp[0][0] = 1

    # Fill first row
    for j in range(1, m):
        if grid[0][j] == '#':
            break
        dp[0][j] = dp[0][j - 1]

    # Fill first column
    for i in range(1, n):
        if grid[i][0] == '#':
            break
        dp[i][0] = dp[i - 1][0]

    # Fill the rest of the dp table
    for i in range(1, n):
        for j in range(1, m):
