def max_candies(arr):
    from functools import lru_cache

    @lru_cache(None)
    def dp(i):
        if i >= len(arr):
            return 0
        # Option 1: Eat current box and skip next
        take = arr[i] + dp(i + 2)
        # Option 2: Skip current box
        skip = dp(i + 1)
        return max(take, skip)

    return dp(0)

