    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # If the start or end is a wall, no paths exist
    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return 0

    # Initialize DP table
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    # Fill the first row
    for j in range(1, m):
        if grid[0][j] == '.':
            dp[0][j] = dp[0][j-1]
        else:
            break  # Wall encountered, no further paths in this row

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == '.':
            dp[i][0] = dp[i-1][0]
        else:
            break  # Wall encountered, no further paths in this column

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == '.':
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Wall, no paths through this cell

    return dp[n-1][m-1]

