def longest_consecutive_subsequence_length(n, arr):
    if n == 0:
        return 0

    # Sort the array to check for consecutive numbers
    arr.sort()

    max_length = 1
    current_length = 1

    # Traverse the sorted array and find the longest consecutive sequence
    for i in range(1, n):
        if arr[i] == arr[i - 1] + 1:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
