def largest_mountain(arr: List[int]) -> int:
    n = len(arr)
    up = [0] * n  # up[i] is the length of increasing sequence ending at i
    down = [0] * n  # down[i] is the length of decreasing sequence starting at i

    # First pass: increasing
    for i in range(1, n):
        if arr[i] > arr[i - 1]:
            up[i] = up[i - 1] + 1
        else:
            up[i] = 0

    # Second pass: decreasing
    for i in range(n - 2, -1, -1):
        if arr[i] > arr[i + 1]:
            down[i] = down[i + 1] + 1
        else:
            down[i] = 0

    # Find the maximum mountain length
    max_mountain = 0
    for i in range(n):
        if up[i] > 0 and down[i] > 0:
            max_mountain = max(max_mountain, up[i] + down[i] + 1)

