def find_cold_days(temperature, k):
    n = len(temperature)
    if n < 2 * k + 1:
        return []  # Not enough days to form a cold day

    # Track indices of strictly decreasing sequence from left to right
    decreasing_stack = []
    is_decreasing = [False] * n

    for i in range(n):
        while decreasing_stack and temperature[decreasing_stack[-1]] <= temperature[i]:
            decreasing_stack.pop()
        if decreasing_stack:
            is_decreasing[i] = True
        decreasing_stack.append(i)

    # Track indices of strictly increasing sequence from right to left
    increasing_stack = []
    is_increasing = [False] * n

    for i in range(n - 1, -1, -1):
        while increasing_stack and temperature[increasing_stack[-1]] <= temperature[i]:
            increasing_stack.pop()
        if increasing_stack:
            is_increasing[i] = True
        increasing_stack.append(i)

    # Find all cold days
    cold_days = []
    for i in range(k, n - k):
        # Check if the previous k elements are strictly decreasing
        if all(temperature[j] > temperature[j + 1] for j in range(i - k, i)):
            # Check if the next k elements are strictly increasing
            if all(temperature[j] < temperature[j + 1] for j in range(i, i + k)):
                cold_days.append(i)

    return cold_days

