def count_ways_to_tile(n):
    MOD = 10**9 + 7

    # Base cases
    if n == 0:
        return 1  # 1 way to tile a 2x0 grid (do nothing)
    if n == 1:
        return 1

    # Initialize dp array
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1

    # Fill dp array using the recurrence relation
    for i in range(2, n + 1):
        dp[i] = (dp[i - 1] + dp[i - 2]) % MOD

    return dp[n]

def max_sum_contiguous_subarray_of_size_k(n, k, arr):
    if k > n or k <= 0:
        return 0

    current_sum = sum(arr[:k])
    max_sum = current_sum

    for i in range(k, n):
        current_sum += arr[i] - arr[i - k]
        max_sum = max(max_sum, current_sum)

    return max_sum

