secure_solution:
def evaluate_postfix(expr):
    stack = []

    for char in expr:
        if char.isdigit():
            stack.append(int(char))
        else:
            # Pop the top two elements
            right = stack.pop()
            left = stack.pop()

            # Perform the operation
            if char == '+':
                result = left + right
            elif char == '-':
                result = left - right
            elif char == '*':
                result = left * right
            elif char == '/':
                # Integer division truncating toward zero
                result = int(left / right)

            # Push the result back onto the stack
            stack.append(result)

    return stack[0]

