secure_solution:
def min_energy(heights):
    n = len(heights)
    dp = [float('inf')] * n
    dp[0] = 0  # Starting at position 0, energy cost is 0

    for i in range(n):
        # Move to i+1
        if i + 1 < n:
            dp[i + 1] = min(dp[i + 1], dp[i] + abs(heights[i + 1] - heights[i]))
        # Stay at i (no cost)
        # Jump j steps
        for j in range(1, 4):
            if i + j < n:
                cost = abs(heights[i + j] - heights[i]) * j
                dp[i + j] = min(dp[i + j], dp[i] + cost)

    return dp[-1]

def find_winner(n, k, votes):
    from collections import defaultdict

    # Count total votes for each candidate
    vote_counts = defaultdict(int)
    total_votes = 0

    # Aggregate votes from all stations
    for station in votes:
        for vote in station:
            vote_counts[vote] += 1
            total_votes += 1

    # Determine the winner
    for candidate in range(1, k + 1):
        if vote_counts.get(candidate, 0) > total_votes // 2:
            return candidate

    return "Tie"

