def max_compatible_meetings(meetings):
    # Sort meetings by their end times
    meetings.sort(key=lambda x: x[1])

    count = 0
    last_end = -1  # Initialize with a value that ensures the first meeting is considered

    for start, end in meetings:
        if start >= last_end:
            count += 1
            last_end = end

    return count

